  quests = {
    [2] = {ot = "Bringt die Klaue von Scharfkralle zu Senani Thunderheart im Splintertreeposten in Ashenvale.", st = "Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg. Senani Thunderheart im Splintertreeposten wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.", t = "Klaue von Scharfkralle"},
    [5] = {ot = "Sprecht mit Küchenchef Grual.", st = "Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.$B$BBringt mir ein Festessen, und ich bezahle Euch gut dafür.$B$BIch habe gehört, dass Küchenchef Grual aus der Taverne Zum roten Raben in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...", t = "Jitters' knurrender Magen"},
    [6] = {ot = "Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", st = "Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!$B$BDoch seht Euch vor, $n. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", t = "Kopfgeld auf Garrick Padfoot"},
    [7] = {ot = "Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", st = "Eure erste Aufgabe ist eine Säuberung, $n. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", t = "Säuberung im Koboldlager"},
    [8] = {ot = "Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab.", st = "Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?$B$BIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.$B$BNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.", t = "Ein Schurkenhandel"},
    [9] = {ot = "Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", st = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breit gemacht.$b$bWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.", t = "Tod auf den Feldern"},
    [11] = {ot = "Bringt Deputy Rainer in der Kaserne 8 bemalte Gnoll-Armbinden.", st = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.$B$BDie Armee von Stormwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnoll-Armbinden als Beweis für Eure Tat.", t = "Kopfgeld auf die Flusspfotengnolle"},
    [12] = {ot = "Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", st = "Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. $b$bEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Furlbrows Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.", t = "Die Volksmiliz"},
    [13] = {ot = "Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", st = "Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Moonbrook und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, $N, und zeigt, dass das Licht in Westfall zugegen ist.$b$bDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.", t = "Die Volksmiliz"},
    [14] = {ot = "Gryan Stoutmantle möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", st = "Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.", t = "Die Volksmiliz"},
    [15] = {ot = "Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", st = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, $n. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.$B$BBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 10 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", t = "Überprüfung der Echokammmine"},
    [18] = {ot = "Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", st = "Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.$B$BIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", t = "Bruderschaft der Diebe"},
    [19] = {ot = "Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris.", st = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten der Blackrock ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!", t = "Tharil'zun"},
    [20] = {ot = "Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris.", st = "Die Orcs des Blackrockklans haben die brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.$B$BHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs der Blackrock und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.$B$BUnd obwohl die Blackrocks uns vor allem aus dem Norden bedrohen, haben wir auch gehört, dass sich noch weitere in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.", t = "Bedrohung durch die Blackrock"},
    [21] = {ot = "Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück.", st = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.$B$BIhr dürft keine Zeit verlieren, $n. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.", t = "Scharmützel in der Echokammmine"},
    [22] = {ot = "Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber.", st = "Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!", t = "Pastete aus Geiferzahnleber"},
    [23] = {ot = "Bringt Ursangus' Tatze zu Senani Thunderheart im Splintertreeposten in Ashenvale.", st = "<Die Tatze des mächtigen Bären Ursangus stellt die Trophäe für diesen Teil der Jagd in Ashenvale dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis.$B$BDie Tatze soll zu Senani Thunderheart im Splintertreeposten gebracht werden, um zu beweisen, dass Ihr das mächtige Tier besiegt und diesen Teil der Jagd abgeschlossen habt.>", t = "Ursangus' Tatze"},
    [24] = {ot = "Bringt Schattumbras Kopf zu Senani Thunderheart im Splintertreeposten in Ashenvale.", st = "Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer. Der Kopf des erschlagenen Nachtsäblers ist eine passende Trophäe für diesen Kampf. Senani Thunderheart im Splintertreeposten wird eine solche Trophäe sehen wollen, um Euch den Erfolg in diesem Teil der Jagd in Ashenvale anzurechnen.", t = "Schattumbras Kopf"},
    [25] = {ot = "Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.$B$BErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.$B$BKehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück.", st = "Wenn Ihr Euch nützlich machen wollt, warum unternehmt Ihr dann nicht etwas wegen der Situation am Steinkrallenpfad?$B$BDer Güterverkehr zwischen Ashenvale und dem Steinkrallengebirge steht still, weil der See zum Leben erwacht ist und alles angreift, was ihm zu nahe kommt... und das bedeutet, jeden auf dem Pfad. Noch weitaus nützlicher als einfach nur die Wasserelementare zu unterjochen, wäre es, wenn jemand den Pavillon auf dem Mystralsee auskundschaften würde... der, von dem aus man einen guten Blick auf den dortigen Außenposten der Allianz hat.$B$BNa, wollt Ihr Euch nützlich machen?", t = "Stillstand am Steinkrallenpfad"},
    [26] = {ot = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", st = "$n, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.$B$BEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", t = "Eine wertvolle Lektion"},
    [27] = {ot = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", st = "$n, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.$B$BEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", t = "Eine wertvolle Lektion"},
    [28] = {ot = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", st = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.$B$BIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.$B$BViel Glück, $n.", t = "Prüfung des Sees"},
    [29] = {ot = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.$B$BIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", st = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.$B$BIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.$B$BViel Glück, $n.", t = "Prüfung des Sees"},
    [30] = {ot = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.$B$BFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.$B$BBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", st = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.$B$BSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", t = "Prüfung des Seelöwen"},
    [31] = {ot = "Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen.", st = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runetotem nach Thunder Bluff zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.$B$BAuf Wiedersehen. Wir werden uns wieder sprechen.", t = "Wassergestalt"},
    [33] = {ot = "Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", st = "Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.$B$BZähes Wolfsfleisch bekommt Ihr, wenn Ihr die Waldwölfe und jungen Wölfe jagt, die in Nordhain durch das Land streifen.", t = "Wölfe an der Grenze"},
    [34] = {ot = "Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", st = "Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marshal Marris seit einer Weile immer \"Stopfwanst\" nennt.$b$bJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen diesem einen gefährlichen Eber. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.", t = "Ein ungebetener Gast"},
    [35] = {ot = "Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht.", st = "Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Elwynn-Brücke und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.$B$BBringt mir seinen Bericht.", t = "Weitere Sorgen"},
    [36] = {ot = "Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert.", st = "Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Furlbrow den Wagen repariert hat, machen wir uns auf den Weg. $b $bKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfall-Eintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.", t = "Westfall-Eintopf"},
    [37] = {ot = "Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.", st = "Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.$B$BSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste...", t = "Suche nach den vermissten Wachen"},
    [38] = {ot = "Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten.", st = "Wollt Ihr mir dabei helfen, Westfall-Eintopf zu kochen? Dann bringt mir die folgenden Zutaten: $b $b 3 Stücke sehniges Geierfleisch $b 3 Geiferzahnschnauzen $b 3 Murlocaugen $b 3 Okraschoten", t = "Westfall-Eintopf"},
    [39] = {ot = "Erstattet Marshal Dughan in Goldhain Bericht.", st = "Berichtet Marshal Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.$B$BIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.", t = "Zustellung von Thomas' Bericht"},
    [40] = {ot = "Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marshal Dughan sprecht.", st = "Eine neue Gefahr bedroht den Wald von Elwynn, $n! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!$B$BIch habe Marshal Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.$B$BBitte sprecht mit Dughan, $n, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!", t = "Gefahr aus dem Wasser"},
    [45] = {ot = "Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod.", st = "Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.$B$BVielleicht fand Rolfs Leben dort sein Ende...", t = "Rolfs Schicksal"},
    [46] = {ot = "Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Elwynn-Brücke findet.", st = "Die Armee von Stormwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Stormwind Euch ansehnlich belohnen$B$BDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.", t = "Kopfgeld auf die Murlocs"},
    [47] = {ot = "Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", st = "Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!$B$BDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.", t = "Tauschhandel mit Goldstaub"},
    [52] = {ot = "Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Elwynn-Brücke zurück.", st = "Seid gegrüßt, $n. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.$B$BWir könnten hier draußen wirklich Eure Hilfe gebrauchen.", t = "Grenzschutz"},
    [54] = {ot = "Liefert Marshal McBrides Unterlagen bei Marshal Dughan in Goldhain ab.", st = "$n, Ihr habt bewiesen, dass Ihr Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.$B$BWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marschall Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.", t = "Meldung in Goldhain"},
    [56] = {ot = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", st = "Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Stormwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.$b$bWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof \"Stille Gärten\", der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!", t = "Die Nachtwache"},
    [57] = {ot = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 15 Skelettsatanskreaturen und 15 Skelettschrecken tötet.", st = "Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, $n. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettsatanskreaturen und 15 Skelettschrecken. Außerdem sollen im Friedhof \"Stille Gärten\", der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!", t = "Die Nachtwache"},
    [59] = {ot = "Gebt Sara Timberlain den Rüstungsgutschein der Armee von Stormwind.", st = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Timberlain. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, $n.$B$BIhr findet das Holzfällerlager des Osttals im Osten jenseits von Wache Thomas' Posten.", t = "Rüstung aus Tuch und aus Leder"},
    [60] = {ot = "Bringt 8 große Kerzen nach Goldhain zu William Pestle.", st = "Guten Tag, $gwerter Herr:werte Dame;! Hättet Ihr einen Moment Zeit für mich?$B$BMein Bruder und ich führen in Stormwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?$B$BGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.", t = "Koboldkerzen"},
    [61] = {ot = "Bringt Williams Lieferung in den Handelsdistrikt von Stormwind zu Morgan Pestle.", st = "In Stormwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.$B$BIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Stormwind. Es heißt Pestles Apotheke.", t = "Lieferung nach Stormwind"},
    [62] = {ot = "Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marshal Dughan zurück.", st = "Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.$B$BErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Stonefields und der Maclures.", t = "Die Tiefenschachtmine"},
    [63] = {ot = "Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Everfount.", st = "An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.$B$BNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.$B$BBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.", t = "Ruf des Wassers"},
    [64] = {ot = "Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", st = "Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.", t = "Das vergessene Erbstück"},
    [65] = {ot = "Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht.", st = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.$b$bBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.", t = "Die Bruderschaft der Defias"},
    [66] = {ot = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", st = "Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.$b$bIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.$b$bSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.", t = "Die Legende von Stalvan"},
    [67] = {ot = "Begebt Euch zur Schule in Moonbrook und bringt Amtmann Daltry alle neuen Informationen über Stalvan Mistmantle.", st = "Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.$b$bStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Mistmantle. Die letzte bekannte Adresse ist die Schule in Moonbrook. Liebe Güte, das nenne ich veraltet!$b$bWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Moonbrook kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.", t = "Die Legende von Stalvan"},
    [68] = {ot = "Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief.", st = "In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.", t = "Die Legende von Stalvan"},
    [69] = {ot = "Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat.", st = "Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus Zur Höhle des Löwen drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, $n.", t = "Die Legende von Stalvan"},
    [70] = {ot = "Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Stormwind ab.", st = "Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.$b$bVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.$b$bIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Stormwind. Ihr dürft ihn gern haben.", t = "Die Legende von Stalvan"},
    [71] = {ot = "Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Elwynn-Brücke.", st = "Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.", t = "Meldung an Thomas"},
    [72] = {ot = "Durchsucht die verpackten Besitztümer nach Hinweisen.", st = "Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.$b$bDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.", t = "Die Legende von Stalvan"},
    [76] = {ot = "Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marshal Dughan zurück, um ihm Bericht zu erstatten.", st = "Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.$B$BErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.", t = "Die Jaspismine"},
    [83] = {ot = "Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Timberlain.", st = "Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.$B$BBringt mir rote Leinenkopftücher, dann stelle ich daraus etwas für Euch her.$B$BDie Mitglieder der Defias haben Lager, die sich über ganz Elwynn verteilen.", t = "Rote Leinenwaren"},
    [84] = {ot = "Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures.", st = "Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!", t = "Zurück zu Billy"},
    [85] = {ot = "Sprecht mit Billy Maclure.", st = "Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. $B$BBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.", t = "Die verlorene Halskette"},
    [86] = {ot = "Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Stonefield auf den Hof der Stonefields.", st = "Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. $B$BWenn Ihr ihr ein paar Brocken Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.", t = "Pastete für Billy"},
    [87] = {ot = "Bringt Berenices Halskette auf den Hof der Stonefields zu \"Tantchen\" Berenice Stonefield.", st = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!$B$BNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist in die Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!", t = "Goldzahn"},
    [88] = {ot = "Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Stonefield auf den Hof der Stonefields.", st = "Die Brackwells haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!$B$BUnd deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht! Bringt mir ihr Halsband zum Beweis, dass Ihr die Sau abgestochen habt, dann gebe ich Euch etwas, das Euch für Euren Aufwand entschädigt.$B$BIhr findet Prinzessin normalerweise bei Brackwells Kürbisbeet, noch hinter dem Hof der Maclures und von dort aus im Osten gesehen. Ich hoffe, Ihr erwischt die Sau, bevor sie wieder hungrig wird und hierher kommt!", t = "Prinzessin muss sterben!"},
    [89] = {ot = "Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow.", st = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Stormwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.$b$bJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, $n, dann sollt Ihr dafür belohnt werden. $b$bUnd jetzt an die Arbeit!", t = "Die Immerruhbrücke"},
    [90] = {ot = "Beschafft 10 magere Wolfflanken und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück.", st = "Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr gewiss kein Problem haben, an die Wolfflanken zu kommen. Glücklicherweise habe ich gerade meine jüngste Lieferung von Würzkräutern aus Stormwind erhalten, sodass ich nur noch die Flanken brauche, um loszulegen.", t = "Gewürzter Wolfskebab"},
    [91] = {ot = "Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher.", st = "Ein Feind Stormwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.$b$bMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.$b$bDiese abscheulichen Gnolle verdienen den Tod!$b$bGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", t = "Das Gesetz des Solomon"},
    [92] = {ot = "Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", st = "Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Stormwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.$b$bBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", t = "Rotkammgulasch"},
    [93] = {ot = "Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual.", st = "Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich euch ein paar.$B$BIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.", t = "Schwärzliche Krebsküchlein"},
    [94] = {ot = "Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge.", st = "Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.$B$BDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.$B$BWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.$B$BSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.", t = "Ein wachsames Auge"},
    [95] = {ot = "Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde.", st = "Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.$B$BAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Er floh, ehe ich ihn erreichen konnte, und ich hatte keine Zeit, mich mit ihm aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.$B$BWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.", t = "Svens Rache"},
    [99] = {ot = "Bringt Dalar Dawnweaver 6 Pyrewood-Fesseln zum Grabmal.", st = "Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.$b$bMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Pyrewood verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Moonrage-Worgs.$b$bIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Pyrewood-Fesseln, $n.", t = "Arugals Torheit"},
    [101] = {ot = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva.", st = "Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, $n. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.$b$bAuch ein tapferer $C wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", t = "Das Totem des Gegenschlages"},
    [102] = {ot = "Bringt 8 Gnolltatzen auf die Späherkuppe zu Captain Danuvin.", st = "Stormwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.$b$bEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.", t = "Auf Patrouille durch Westfall"},
    [103] = {ot = "Bringt 5 Fläschchen Öl zu Captain Grayson beim Leuchtturm von Westfall.", st = "Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Old Murk-Eye den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.$b$bHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.", t = "Bewahrer der Flamme"},
    [104] = {ot = "Bringt Captain Grayson am Leuchtturm von Westfall eine Schuppe von Old Murk-Eye.", st = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Old Murk-Eye die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Old Murk-Eye brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.$b$bTötet Old Murk-Eye, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", t = "Bedrohung an der Küste"},
    [106] = {ot = "Gebt Tommy Joe Stonefield Maybells Liebesbrief.", st = "Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Stonefield, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!$B$BBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Stonefields auf, das ist auch von hier aus genau westlich.", t = "Junge Liebende"},
    [107] = {ot = "Bringt Oma Stonefields Nachricht zu William Pestle.", st = "Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.$B$BHier, bringt William diese Nachricht. Er wohnt im Gasthaus Zur Höhle des Löwen in Goldhain.", t = "Nachricht an William"},
    [109] = {ot = "Sprecht mit Gryan Stoutmantle. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", st = "Es scheint mir, $C, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Stoutmantle melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", t = "Meldung bei Gryan Stoutmantle"},
    [111] = {ot = "Sprecht mit Oma Stonefield.", st = "Bitte sprecht mit meiner Großmutter, $n. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.$B$BIhr findet sie in unserem Haus, östlich von hier.", t = "Gespräch mit Oma"},
    [112] = {ot = "Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle.", st = "Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.$B$BDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.", t = "Die Suche nach dem Tang"},
    [114] = {ot = "Bringt Maybell Maclure den Unsichtbarkeitsschnaps.", st = "Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.", t = "Die Flucht"},
    [115] = {ot = "Bringt 3 Mitternachtskugeln nach Seenhain zu Marshal Marris.", st = "Von den Orcs des Blackrockklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.$B$BDurchsucht erschlagene Schattenzauberer der Blackrock nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.", t = "Schattenmagie"},
    [118] = {ot = "Bringt Verners Nachricht zu Schmied Argus nach Goldhain.", st = "Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Stormwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!$B$BBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.", t = "Der Preis für Hufeisen"},
    [119] = {ot = "Kehrt zu Verner Osgood ins Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen.", st = "Gut, er soll seine 50 Hufeisen haben.$B$BHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!", t = "Zurück zu Verner"},
    [120] = {ot = "Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Stormwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt.", st = "Wir leben in schwierigen Zeiten, $C. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Stormwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. $b$bDoch nun eilt!", t = "Botschaft nach Stormwind"},
    [121] = {ot = "Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon.", st = "Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. $b$bWeggetreten, $C!", t = "Botschaft nach Stormwind"},
    [122] = {ot = "Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Osgood.", st = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.$B$BSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.", t = "Bauchschuppen"},
    [123] = {ot = "Begebt Euch zu Marshal Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers.", st = "Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.$B$BAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe vom Brackwell-Kürbisbeet in Ost-Elwynn aufhält.$B$BDas klingt, als sei es wichtig. Ihr solltet Marshal Dughan in Goldhain davon berichten.", t = "Der Sammler"},
    [124] = {ot = "Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Osgood zurück.", st = "Als ob Orc-Angriffe nicht genug wären! Jetzt schleichen auch noch Gnoll-Schläger und Gnoll-Mystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...$B$BWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.", t = "Das Bellen der Gnolle"},
    [125] = {ot = "Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt.", st = "Ich könnte hier wirklich etwas Hilfe gebrauchen, $n. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.$b$bWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, $n, dann soll es Euer Schaden nicht sein.", t = "Die verlorenen Werkzeuge"},
    [126] = {ot = "Bringt Jaulers Tatze nach Seenhain zu Verner Osgood.", st = "Die Gnolle sind immer noch da draußen, $n. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.$B$BTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.$B$BAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...", t = "Geheul in den Hügeln"},
    [127] = {ot = "Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren.", st = "Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!$B$BBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!", t = "Fischhandel"},
    [128] = {ot = "Tötet 15 Helden der Blackrock, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung.", st = "Der Blackrockklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Stormwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan \"Helden\" genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die brennende Steppe führt.$b$bMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden der Blackrock und kehrt zu mir zurück.", t = "Kopfgeld auf die Blackrocks"},
    [129] = {ot = "Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille.", st = "Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Stormwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!$B$BWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.", t = "Ein geschenktes Mittagessen"},
    [130] = {ot = "Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose.", st = "Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.$B$BAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?", t = "Besuch im Kräuterladen"},
    [131] = {ot = "Gebt Darcy den Narzissenstrauß.", st = "Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.", t = "Narzissen für eine Dame"},
    [132] = {ot = "Bringt Wileys Nachricht nach Westfall zu Gryan Stoutmantle.", st = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.$b$bBringt Stoutmantle diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.", t = "Die Bruderschaft der Defias"},
    [135] = {ot = "Bringt Wileys Nachricht nach Stormwind zu Mathias Shaw.", st = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.", t = "Die Bruderschaft der Defias"},
    [136] = {ot = "Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.", st = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sander in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. $b$bErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", t = "Käpt'n Sanders Versteckter Schatz"},
    [138] = {ot = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.", st = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin.", t = "Käpt'n Sanders versteckter Schatz"},
    [139] = {ot = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.", st = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", t = "Käpt'n Sanders Versteckter Schatz"},
    [140] = {ot = "Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung.", st = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", t = "Käpt'n Sanders Versteckter Schatz"},
    [141] = {ot = "Bringt Shaws Bericht nach Westfall zu Gryan Stoutmantle.", st = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Stormwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.$b$bIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!", t = "Die Bruderschaft der Defias"},
    [142] = {ot = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle.", st = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. $n, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", t = "Die Bruderschaft der Defias"},
    [143] = {ot = "Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Stoutmantle bringt.", st = "Irgendetwas stimmt mit der Armee von Stormwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.$b$bBringt dieses Hilfegesuch ihrem Anführer, Gryan Stoutmantle. Vielleicht können Stoutmantles Männer uns hier unterstützen, bis der König Verstärkung schickt.", t = "Botschaft nach Westfall"},
    [144] = {ot = "Kehrt mit Gryan Stoutmantles Antwort zu Magistrat Solomon zurück.", st = "Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Stormwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.$b$bBringt Eurem Herrn im Rotkammgebirge diese Antwort, $C. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.", t = "Botschaft nach Westfall"},
    [145] = {ot = "Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Ebonlocke nach Dunkelhain bringt.", st = "Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Ebonlocke geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Ebonlocke ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.", t = "Botschaft nach Dunkelhain"},
    [146] = {ot = "Kehrt mit Lord Ebonlockes Antwortschreiben zu Magistrat Solomon zurück.", st = "Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Stormwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Stormwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.$b$bBringt Eurem Meister in Seenhain dieses Antwortschreiben.", t = "Botschaft nach Dunkelhain"},
    [147] = {ot = "Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marshal Dughan zurück.", st = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.$B$BIm Abholplan steht, dass der Sammler sich am Brackwell-Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.", t = "Menschenjagd"},
    [148] = {ot = "Sprecht mit Madame Eva.", st = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.$B$BKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", t = "Lieferung aus Dunkelhain"},
    [149] = {ot = "Bringt der blinden Mary den spektralen Kamm.", st = "Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.$B$BHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.$B$BUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...", t = "Geisterhaarfaden"},
    [150] = {ot = "Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren.", st = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.$B$BGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...", t = "Murlocwilderer"},
    [151] = {ot = "Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", st = "Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.$B$BIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.", t = "Die arme Graumähne"},
    [152] = {ot = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Captain Grayson beim Leuchtturm von Westfall zurück.", st = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.$b$bTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", t = "Ärger an der Küste"},
    [153] = {ot = "Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan.", st = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.$b$bBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", t = "Rote Lederkopftücher"},
    [154] = {ot = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", st = "NEIN!!!!!$B$BNehmt ihn weg, nehmt diesen Kamm weg!$B$BIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", t = "Rückkehr mit dem Kamm"},
    [155] = {ot = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Stoutmantle zurück.", st = "Stoutmantle denkt also wirklich, ein $R wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. $b$bIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.$b$bSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", t = "Die Bruderschaft der Defias"},
    [156] = {ot = "Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts.", st = "Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.$B$BFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettsatanskreaturen - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!$B$BDer Friedhof von Rabenflucht und die stillen Gärten sind voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.", t = "Das Sammeln von Faulblüten"},
    [157] = {ot = "Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht.", st = "Hier ist Euer Faden, $n. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.", t = "Abliefern des Fadens"},
    [158] = {ot = "Sprecht mit Schankwart Smitts.", st = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne Zum roten Raben in Dunkelhain sollte welchen haben.$B$BUnd bitte sputet Euch, $n. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", t = "Zombiesaft"},
    [159] = {ot = "Bringt Calvinius den Zombiesaft in seine Hütte.", st = "Hier habt Ihr Euren Zombiesaft...$B$B... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", t = "Saftlieferung"},
    [161] = {ot = "Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver nach Dun Modr zu Ashlan Stonesmirk, dem Sprengstoffexperten, bringt.", st = "Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, mit was wir es hier zu tun haben. Ashlan Stonesmirk wurde dem Regiment zugeteilt, das Dun Modr und den Thandol-Übergang bewachen soll. Ihr müsst für mich eine schwierige und gefahrvolle Reise auf Euch nehmen, $n.$b$bReist durch das Algaz-Tor, folgt der Straße durch das Sumpfland und sucht Stonesmirk in Dun Modr auf. Folgt meinem Rat: Bleibt auf den Straßen und lasst Euch nicht zum Anhalten bewegen!", t = "Eine dunkle Bedrohung"},
    [163] = {ot = "Findet heraus, was in Rabenflucht umgeht.", st = "Irgendetwas stimmt nicht in Rabenflucht, $N. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.$b$bWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.", t = "Rabenflucht"},
    [164] = {ot = "Liefert die Vorräte an Sven.", st = "Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.$b$bLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?", t = "Lieferung an Sven"},
    [165] = {ot = "Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte.", st = "Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.", t = "Der Einsiedler"},
    [166] = {ot = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Stoutmantle.", st = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", t = "Die Bruderschaft der Defias"},
    [167] = {ot = "Bringt Großknecht Thistlenettles Forscherliga-Abzeichen nach Stormwind zu Wilder Thistlenettle.", st = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen ... na ja ... von den anderen hat seither niemand mehr etwas gehört.$b$bIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", t = "Oh Bruder..."},
    [168] = {ot = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Stormwind zu Wilder Thistlenettle.", st = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", t = "Die Suche nach Andenken"},
    [169] = {ot = "Erledigt Gath'llzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten.", st = "Gesucht! Gath'llzogg, Rädelsführer hinter den Angriffen der Blackrock auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. $b$bGath'llzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Blackrockklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.", t = "GESUCHT: Gath'Ilzogg"},
    [170] = {ot = "Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet.", st = "Ich hoffe, Ihr seid hier, um uns zu helfen, $C. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.$b$bIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Coldridge-Tal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.$b$bUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! $b$bWir haben hier zu wenig Leute, $gJungchen:Mädel;, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.", t = "Eine neue Bedrohung"},
    [174] = {ot = "Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt.", st = "Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.$b$bBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.", t = "Der Blick zu den Sternen"},
    [175] = {ot = "Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.", st = "Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...", t = "Der Blick zu den Sternen"},
    [176] = {ot = "Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan.", st = "Gesucht: Hogger$B$BEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.$B$BDie Armee von Stormwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marshal Dughan in Goldhain vorlegen.", t = "GESUCHT: \"Hogger\""},
    [177] = {ot = "Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain.", st = "Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof \"Stille Gärten\".", t = "Der Blick zu den Sternen"},
    [179] = {ot = "Sten Stoutarm hätte gern 8 Stücke zähes Wolfsfleisch.", st = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?$b$bIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.$b$bIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?", t = "Zwergenausstatter"},
    [180] = {ot = "Tötet Lieutenant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück.", st = "Gesucht: Lieutenant Fangor$b$bBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Stormwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.", t = "GESUCHT: Leutnant Fangor"},
    [182] = {ot = "Grelin Whitebeard möchte, dass Ihr 14 Trollwelpen der Frostmane tötet.", st = "Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.$b$bNach allem, was ich gesehen habe, ist die Position der Trolle hier im Coldridgetal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Ich würde sagen, die Armee brauchen wir nicht. Einige starke Arme sollten mehr als ausreichend sein.$b$bMöchtet Ihr vielleicht mithelfen? Ich bin ermächtigt, Euch für Eure Dienste eine Entschädigung anzubieten.", t = "Die Trollhöhle"},
    [183] = {ot = "Talin Keeneye möchte, dass Ihr 12 kleine Klippeneber tötet.", st = "Es geht doch nichts über einen Tag auf der Eberjagd, wie?$b$bNa ja, hier im Coldridgetal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.$b$bIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.", t = "Der Eberjäger"},
    [184] = {ot = "Bringt Furlbrows Besitzurkunde zu Bauer Furlbrow.", st = "Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Furlbrow und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:$B$B\"Wir haben Furlbrow etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.$B$BUm die Furlbrows müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"$B$BIhr denkt, die Furlbrows hätten ihre Besitzurkunde vielleicht gern zurück ...", t = "Furlbrows Urkunde"},
    [199] = {ot = "Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt.", st = "Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.", t = "Eine dunkle Bedrohung"},
    [214] = {ot = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", st = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.$b$bJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, $n.", t = "Rote Seidenkopftücher"},
    [216] = {ot = "Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück.", st = "Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle östlich von uns blockiert den Weg zwischen uns hier und dem Splintertreeposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.$B$B$n, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!$B$BBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.", t = "Hart auf hart"},
    [217] = {ot = "Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht.", st = "$n, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.$b$bWenn Ihr Euch dem gewachsen fühlt, $n, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger anführt. Wenn die Führungsriege der Troggs tot ist, dann haben wir vielleicht eine Chance, diese Bestien wieder unter die Erde zu treiben.", t = "Verteidigung der Länder des Königs"},
    [218] = {ot = "Grelin Whitebeard möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft.", st = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen.$b$bIhr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?", t = "Das gestohlene Tagebuch"},
    [219] = {ot = "Beschützt Corporal Keeshan auf dem Rückweg ins Rotkammgebirge.", st = "Freunde der Allianz! Endlich!$b$bHelft... bitte... $b$bDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.$b$bIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...", t = "Vermisst"},
    [220] = {ot = "Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer.", st = "Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.$B$BGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.", t = "Ruf des Wassers"},
    [224] = {ot = "Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet.", st = "Wir müssen den Loch beschützen, $n! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Trogg-Plage stellt für Ironforge die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.$b$bIhr, $gtapferer Abenteurer:tapfere Abenteurerin;, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher und erstattet dann wieder Bericht.", t = "Verteidigung der Länder des Königs"},
    [226] = {ot = "Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", st = "Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!$B$BAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.", t = "Wölfe auf den Fersen"},
    [230] = {ot = "Bringt das Buch von Svens Hof zu Sven.", st = "Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.$B$BDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.", t = "Svens Lager"},
    [233] = {ot = "Liefert den Stapel Briefe bei Talin Keeneye ab.", st = "Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, $gJungchen:Mädchen;? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.$b$bSie sind alle an Talin Keeneye adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.$b$bWas meint Ihr?", t = "Postbeförderung im Coldridgetal"},
    [234] = {ot = "Liefert den Brief bei Grelin Whitebeard ab.", st = "Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.", t = "Postbeförderung im Coldridgetal"},
    [237] = {ot = "Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet.", st = "Gebirgsjäger Cobbleflint hat nur Gutes über Euch zu berichten gehabt, $R. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Trogg-Streitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.$b$bBegebt Euch in die südlichen Hügel und tötet 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.", t = "Verteidigung der Länder des Königs"},
    [239] = {ot = "Begebt Euch zur Weststromgarnison und sprecht mit Deputy Rainer.", st = "Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Stormwind... aber wir können einfach keine entbehren!$B$BWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Deputy Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.$B$BDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.", t = "Hilfe für die Weststromgarnison"},
    [240] = {ot = "Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück.", st = "Und voilà - \"Krebs\"-Küchlein à la Grual!", t = "Rückkehr zu Jitters"},
    [244] = {ot = "Erstattet Deputy Feldon Bericht.", st = "Seid gegrüßt, $C. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.$B$BSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Deputy Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.$B$BGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.", t = "Eindringende Gnolle"},
    [245] = {ot = "Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", st = "Seid gegrüßt, $C. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.$b$bIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertig werden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.$b$bAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.", t = "Gefahr auf acht Beinen"},
    [246] = {ot = "Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain.", st = "Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.$B$BSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.$B$BTut dies für die Armee von Stormwind, $n, und Ihr erhaltet eine Belohnung.", t = "Einschätzung der Gefahr"},
    [247] = {t = "Die Jagd ist abgeschlossen"},
    [248] = {ot = "Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.$B$BFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab.", st = "Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.$B$BNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.$B$BFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.", t = "Weitere Beobachtungen"},
    [250] = {ot = "Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben.", st = "Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandol-Übergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.$b$bUnd deswegen brauche ich Euch, $n. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.", t = "Eine dunkle Bedrohung"},
    [255] = {ot = "Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten.", st = "Zwei Monate! Zwei Monate, nur um dann aus Ironforge zu hören zu bekommen, dass eine Handvoll Soldaten zu unserer Verteidigung abgestellt wird, und zwei weitere Monate, bis sie ankommen! Schlimm genug, dass unsere Stadt ohne Schutz ist, aber die Ausgrabung und der Damm - der Damm! - sind ebenfalls allen Angriffen schutzlos ausgesetzt.$b$bIch habe also keine Wahl, scheint mir. Ich brauche gedungene Kämpfer.$b$bWie steht es mit Euch? Ihr seht mir tüchtig aus, $C. Eine Gruppe Oger hat im Nordosten des Sees ihr Lager aufgeschlagen. Vielleicht könntet Ihr ein paar weitere Kämpfer rekrutieren und uns dabei helfen, die Bedrohung für unsere Stadt zu beseitigen?", t = "Söldner"},
    [257] = {ot = "Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", st = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertig werdet.$b$bEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt und es Euch in 15 Minuten gelingt, dann gebe ich Euch meinen Bogen oder mein Gewehr.$b$b<Er mustert Euch abschätzig.>$b$bScheint ja nicht, als ob Ihr viel zu verlieren hättet.", t = "Das Prahlen eines Jägers"},
    [258] = {ot = "Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", st = "$nath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.$b$bIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Coldridgetal, also solltet Ihr Euch vorsehen. Diesmal gebe ich Euch nur 12 Minuten.$b$bSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch das Hemd geben, das ich am Leibe trage, wenn Ihr es schaffen würdet!$b$bHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...", t = "Die Herausforderung eines Jägers"},
    [262] = {ot = "Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain.", st = "Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.$B$BBitte, $n, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!$B$BIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.", t = "Die Schattengestalt"},
    [263] = {ot = "Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet.", st = "Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, $n. Ein $R wie Ihr wird hier draußen gebraucht. Wir bekommen das Trogg-Problem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, ein erfahrener $C, also wollen wir doch mal sehen, was Ihr ausrichten könnt.$b$bZieht los und tötet 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, $gTrogg-Töter:Trogg-Töterin;.", t = "Verteidigung der Länder des Königs"},
    [264] = {ot = "Legt Clarices Anhänger auf Yurivs Grab in Silberwald.", st = "Dreckiger Abschaum! Lässt mich wegen seines verdammten Kreuzzugs hier sitzen. Nur, weil \"das Licht das Wichtigste ist, was wir gegen die Bedrohung durch die Untoten besitzen\".$B$BUnd was ist mit seinen Kindern?! Was ist mit MIR?! Nacht für Nacht hab ich hier gesessen und geduldig auf ihn gewartet... hab immer den zweiten Platz hinter seiner verfluchten Pflicht eingenommen!$B$BTja, hier könnt Ihr sehen, was Euch Gerechtigkeit einbringt, $n! Er ist tot und ich ertrage genau das, was er aufzuhalten versuchte!$B$BNehmt diesen Plunder und legt ihn auf seine Gruft im Grabmal. Ich will nichts mehr damit zu tun haben... oder mit ihm!", t = "Bis dass der Tod uns scheidet"},
    [265] = {ot = "Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben.", st = "Hier habt Ihr Euer Buch zurück, $n, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.$B$BIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.", t = "Die Schattensuche geht weiter"},
    [266] = {ot = "Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt.", st = "Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.$B$BVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.", t = "Nachforschungen im Gasthaus"},
    [267] = {ot = "Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne.", st = "$C, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Ironforge zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.$b$bEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Trogg-Steinzähne als Beweis.", t = "Die Bedrohung durch die Troggs"},
    [268] = {ot = "Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück.", st = "Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... $B$BHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.$B$BObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.", t = "Rückkehr zu Sven"},
    [269] = {ot = "Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch.", st = "Geht nach Stormwind und sprecht dort mit Bischof Farthing in der Kathedrale des Lichts. Gebt ihm Jitters' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Fel zu stellen.$B$BAuch wenn Stormwind Dunkelhain aufgegeben hat, ist Farthing doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.$B$BEure Mission ist gefahrvoll, aber beeilt Euch dennoch, $n. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.", t = "Auf der Suche nach Weisheit"},
    [271] = {ot = "Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk.", st = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.$b$bVor einem Jahr war ein großer Bär das Ziel der Weitschreiter-Lodge, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.$b$bErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.$b$bDer Bär, Old Sooty, hält sich irgendwo in der Nähe seines Baus in den Hügeln über Thelsamar auf.", t = "Vyrins Rache"},
    [272] = {ot = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.$B$BFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.$B$BBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", st = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.$B$BSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", t = "Prüfung des Seelöwen"},
    [273] = {ot = "Sprecht mit Huldar.", st = "Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.$b$bSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.$b$bIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.", t = "Nachschub für die Ausgrabungsstätte"},
    [275] = {ot = "Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", st = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.$B$BDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.", t = "Schwärendes Land"},
    [276] = {ot = "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", st = "Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.$B$BSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.$B$BTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.", t = "Stapfende Pfoten"},
    [277] = {ot = "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", st = "Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!$B$BEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.", t = "Feuer-Tabu"},
    [279] = {ot = "Tötet 12 Murlocs der Blaukiemen.$B$BErschlagt Gobbler und nehmt Euch seinen Kopf.$B$BBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil", st = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.$B$BEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.$B$BGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", t = "Klauen aus der Tiefe"},
    [281] = {ot = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", st = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blind Princess, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.$B$BDurchsucht die Hütten der Murloc an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Menethil-Statuette und bringt sie mir wieder.", t = "Waren-Wiederbeschaffung"},
    [282] = {ot = "Sprecht mit Gebirgsjäger Thalos.", st = "Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?$b$bHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.$b$bSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.$b$bFolgt der Straße zurück nach Anvilmar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.", t = "Senirs Beobachtungen"},
    [284] = {ot = "Sucht nach der Menethil-Statuette.", st = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur von der Menethil-Statuette.$B$BVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", t = "Die Suche geht weiter"},
    [285] = {ot = "Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette.", st = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.$B$B... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.$B$BEine der Hütten nördlich von hier muss die Menethil-Statuette enthalten!", t = "Suche in weiteren Hütten"},
    [286] = {ot = "Bringt Karl Boran die Menethil-Statuette.", st = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.$B$BDies kann nur die Menethil-Statuette sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", t = "Rückgabe der Statuette"},
    [287] = {ot = "Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos.", st = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, $n. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.$b$bWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.$b$bNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.", t = "Höhle der Frostmane"},
    [288] = {ot = "Spendiert dem ersten Maat Fitzsimmons einen Krug Met.", st = "Ich war einst erster Maat auf der HERRIN DER MEERE, einem Linienschiff der dritten Flotte von Kul Tiras, der verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!$B$BWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.$B$B... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.", t = "Die Dritte Flotte"},
    [291] = {ot = "Überbringt Senator Barin Redstone in Ironforge Senirs Bericht.", st = "Wunderbar! Überbringt Senator Barin Redstone meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Ironforge, in der Halle, in der König Magni Hof hält.$b$bIhr kennt den Weg nach Ironforge nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.$b$bAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?", t = "Die Berichte"},
    [294] = {ot = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", st = "Die Lage ist ernst, soviel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.$b$bHelft mit, das Sumpfland von diesen Raptoren zu säubern, $n. Scheckige Raptoren und Scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.$b$bDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.", t = "Ormers Rache"},
    [297] = {ot = "Bringt Magmar Fellhew 8 verzierte Steingötzen.", st = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!$B$BBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", t = "Götzen sammeln"},
    [298] = {ot = "Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar.", st = "Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.$B$BKeine schwierige Aufgabe, aber sie muss erledigt werden.", t = "Bericht über den Fortschritt der Ausgrabungen"},
    [301] = {ot = "Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike.", st = "Wir werden eine Bewilligung brauchen, um Ironband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Ironforge bringen.$B$BHier ist der Bericht. Gebt ihn Ausgrabungsleiter Stormpike und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Stormpike ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Ironbands langsamem Vorankommen an der Ausgrabungsstätte hört.$B$BIhr findet Stormpike in der Versammlungshalle der Forscher.", t = "Meldung in Ironforge"},
    [302] = {ot = "Sprecht in Thelsamar mit Jern Hornhelm.", st = "Wenn Ironband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Ironband bereitstellen.$B$BAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.", t = "Pulver für Ironband"},
    [303] = {ot = "Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", st = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.$b$bIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.$b$bUnd jetzt beeilt Euch!", t = "Der Dunkeleisenkrieg"},
    [305] = {ot = "Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt.", st = "Ihr könnt Euch nicht vorstellen, wie besorgt ich war.$b$bMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zum Whelgar-Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schiefgelaufen!$b$bLongbraid versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, $n. Findet Merrin in der Ausgrabungsstätte im Osten!", t = "Auf der Suche nach dem Ausgrabungstrupp"},
    [306] = {ot = "Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück.", st = "Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.$b$bBevor wir wussten, wie uns geschah, überrannten diese Scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.$b$bOrmer hier rettete, ganz tapfer, den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.$b$bHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.", t = "Auf der Suche nach dem Ausgrabungstrupp"},
    [307] = {ot = "Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.$B$BKehrt dann zu Gebirgsjäger Stormpike zurück.", st = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!$B$BWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.$B$BDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", t = "Schmutzige Pfoten"},
    [308] = {t = "Jarvens Ablenkung"},
    [309] = {ot = "Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis.", st = "Bereit zum Aufbruch, $N?$b$bAls Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?$b$bIch werde mich viel besser fühlen, wenn Ihr mitkommt.", t = "Beschützen der Fracht"},
    [310] = {ot = "Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu.", st = "Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...$B$BHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbier. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!$B$BAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...", t = "Bittere Rivalen"},
    [311] = {ot = "Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier.", st = "Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbier...", t = "Rückkehr zu Marleth"},
    [312] = {ot = "Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten.", st = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.$b$bIhr seht verstohlener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.", t = "Tundra MacGranns gestohlene Vorräte"},
    [313] = {ot = "Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", st = "Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?$B$BWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!", t = "Der altgediente Bau"},
    [314] = {ot = "Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", st = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.$b$bVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen Fangzahn der Bestie, und ich werde Euch belohnen. Vagash lauert direkt oberhalb der Ranch hier, aber seid gewarnt, die Bestie ist tödlich.", t = "Die Herde beschützen"},
    [315] = {ot = "Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter.", st = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...$B$BWeit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.$B$BBesorgt mir etwas Schimmerkraut von den Sehern der Frostmane oder klaut es aus den Schimmerkrautkörben der Trolle.", t = "Das Perfekte Starkbier"},
    [317] = {ot = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", st = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?$B$BIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.", t = "Vorräte für Jetsteam"},
    [318] = {ot = "Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer.", st = "Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.$B$BEr lebt in Brewnall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.$B$BAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Jetsteams Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.", t = "Immerschimmer"},
    [319] = {ot = "Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück.", st = "Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Brewnall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.$B$BWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.", t = "Ein Gefallen für etwas Immerschimmer"},
    [320] = {ot = "Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer.", st = "Hier habt Ihr Euer Fässlein mit Immerschimmer, $n. Und wie gesagt, vielen Dank für die Jagd kürzlich.", t = "Rückkehr zu Bellowfiz"},
    [323] = {ot = "Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", st = "Morbent Fel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Fel entgegenzustellen, aber ich werde Euch erst gegen diese widerwärtige Satanskreatur kämpfen lassen, wenn ich Eure wahre Stärke kenne.$B$BIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.", t = "Bewährungsprobe"},
    [337] = {ot = "Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück.", st = "Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Stormwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Stormwind erkennen, das deutlich auf der ersten Seite prangt.$B$BEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.", t = "Ein altes Geschichtsbuch"},
    [343] = {ot = "Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt.", st = "Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der königlichen Bibliothek der Burg Stormwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!$B$BDie königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Sheaf, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.", t = "Reden über Kraft"},
    [344] = {ot = "Sprecht mit Bruder Paxton in der Abtei von Nordhain.", st = "Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!$B$BAber wo war ich doch gleich? Ach ja, die \"Belastbarkeit von Eisen\"! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.$B$BDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...", t = "Bruder Paxton"},
    [345] = {ot = "Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz.", st = "Ich will meine Abschrift von \"Belastbarkeit von Eisen\" schon länger fertig stellen, aber... $B$BNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!$B$BUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.", t = "Tinten-Zutaten"},
    [346] = {ot = "Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\".", st = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.", t = "Rückkehr zu Kristoff"},
    [347] = {ot = "Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain.", st = "Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.$B$BWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.$B$BWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.", t = "Rethbanerz"},
    [350] = {ot = "Sprecht mit Elling Trias in Stormwind.", st = "Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... $B$BDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.$B$BWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.", t = "Auf einen alten Freund verlassen"},
    [353] = {ot = "Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan.", st = "Die Stormpikes sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Stormpike, ein Gebirgsjäger aus Ironforge, mich beauftragte, ihm eine Waffe zu schmieden.$B$BDie Waffe ist fertig, aber... Gebirgsjäger Stormpike ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?$B$BMeine letzte Nachricht von Gebirgsjäger Stormpike besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.", t = "Stormpikes Lieferung"},
    [354] = {ot = "Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste.", st = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.$B$BAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.$B$BDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!$B$BDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", t = "Todesfälle in der Familie"},
    [355] = {ot = "Sprecht mit Magistrat Sevren in Brill.", st = "Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.$B$BIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.", t = "Gespräch mit Sevren"},
    [356] = {ot = "Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager.", st = "Die Verteidiger auf dem Bollwerk, die Tirisfal vor den Pestländern schützen, sind immer wachsam. Aber manchmal schafft es die Geißel, an ihnen vorbeizuschlüpfen.$B$BUnser Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht... wir dürfen keinen Angriff von hinten zulassen, und noch weniger dürfen wir zulassen, dass die Versorgungslinie unserer Verteidiger unterbrochen wird.$B$BUnterstützt das Bollwerk. Patrouilliert ostwärts und erschlagt alle Untoten, die Ihr findet. Seid auf Balnirs Bauernhof im Osten besonders gründlich. Er hat sich zu einem Zufluchtsort für eindringende Untote entwickelt.", t = "Patrouille zur Rückendeckung"},
    [357] = {ot = "Bringt das Zauberbuch des Lichs zu Bethor Iceshard in Undercity.", st = "Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.$B$BAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.$B$BUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.", t = "Die Identität des Lichs"},
    [358] = {ot = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. $B$BBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete.", st = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. $B$BDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!$B$BIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.", t = "Grabräuber"},
    [359] = {ot = "Sprecht mit Todeswache Linnea.", st = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.$B$BIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!$B$BReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", t = "Verlassenen-Pflichten"},
    [360] = {ot = "Kehrt zu Magistrat Sevren nach Brill zurück.", st = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.$B$BUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.", t = "Rückkehr zum Magistrat"},
    [361] = {ot = "Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand.", st = "Dies ist ein Brief, der von Thurman, dem ältesten Sohn von Gregor Agamand, geschrieben wurde. Er ist an Yvette Farthing adressiert, aber er scheint nicht bei ihr angekommen zu sein...", t = "Ein nie zugestellter Brief"},
    [362] = {ot = "Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill.", st = "Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.$B$BAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.$B$BIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.", t = "Die Spuk-Mühle"},
    [363] = {ot = "Sprecht mit Schattenpriester Sarvis.", st = "Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.$b$bIch bin Mordo, der Verwalter der Deathknell-Gruft. Und Ihr seid kein Sklave des Lichkönigs mehr.$b$bSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.", t = "Unsanftes Erwachen"},
    [364] = {ot = "Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet.", st = "Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.$b$bDer nördliche Teil des Dorfes wurde von den Hirnlosen überrannt, und diese müssen vernichtet werden. Vernichtet sie, zeigt ihnen keine Gnade, auch wenn sie unsere früheren Brüder und Schwestern gewesen sein mögen. Die Gefallenen sind nichts als Sklaven des Lichkönigs.", t = "Die Hirnlosen"},
    [365] = {ot = "Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill.", st = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, $C. Wenn Ihr darauf hofft, Euch der dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.$b$bIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.$b$bSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.", t = "Felder des Kummers"},
    [366] = {ot = "Bringt Gunthers Zauberbuch zu ihm auf die \"Gunthers Zufluchtsort\" genannte Insel zurück.", st = "Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.$B$BGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.$B$BWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.", t = "Rückgabe des Buches"},
    [367] = {ot = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.", st = "Lady Sylvanas hat sich an die Königliche Apothekervereinigung gewandt. Die dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.$b$bMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.", t = "Eine neue Seuche"},
    [368] = {ot = "Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal.", st = "Während Ihr unterwegs wart und Proben für mich gesammelt habt, haben meine Experimente ergeben, dass noch weitere Reagenzien benötigt werden, wenn sich diese Krankheit ordentlich ausbreiten soll. Ein paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit. Eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter.$b$bIch werde 5 Finsterflossenschuppen von den Murlocs in der Umgebung brauchen. Ihr findet die Kreaturen entlang der Küste im Norden oder Westen von hier.", t = "Eine neue Seuche"},
    [369] = {ot = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt.", st = "Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.$b$bBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.", t = "Eine neue Seuche"},
    [370] = {ot = "Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet.", st = "Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Captain Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.$b$bTötet Perrine, sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.", t = "Im Krieg mit dem Scharlachroten Kreuzzug"},
    [371] = {ot = "Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen.", st = "Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Captain Vachon ausgeführt haben.$b$bTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!", t = "Krieg mit dem Scharlachroten Kreuzzug"},
    [372] = {ot = "Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet.", st = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.$b$bIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der dunklen Fürstin.", t = "Krieg mit dem Scharlachroten Kreuzzug"},
    [373] = {ot = "Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston.", st = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".$B$BEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein.", t = "Der nie verschickte Brief"},
    [374] = {ot = "Bringt Todeswache Burgess in Brill 10 scharlachrote Insignienringe.", st = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.$b$bVarimathras, Offizier der dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.$b$bBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, $C. Bringt mir 10 scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der dunklen Fürstin gegenüber.", t = "Beweise des Ablebens"},
    [375] = {ot = "Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden.", st = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.$b$bJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, $n, auf dass ich der Sache weiter dienen kann.", t = "Die Kälte des Todes"},
    [376] = {ot = "Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel.", st = "Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.$b$bEs sieht so aus, als würdet Ihr ebenfalls in seine Dienste aufgenommen... wahrscheinlich um die Hirnlosen zu jagen, wie ich ihn kenne. Tja, wenn Ihr dabei in einem Stück bleiben wollt - und ich bezweifle nicht, dass Ihr das wollt -, dann kann ich Euch vielleicht helfen. Mir gehen die Tatzen und Flügel aus, und wenn Ihr mir einige davon bringt, besorge ich Euch eine Rüstung. Ihr werdet im Norden eine Menge Wölfe und Fledermäuse finden.", t = "Die Verdammten"},
    [377] = {ot = "Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", st = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.$b$bWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.$b$bErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.", t = "Verbrechen und Strafe"},
    [378] = {ot = "Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", st = "Ihr habt Eure Loyalität zu König Magni bewiesen, $C. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.$b$bEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.$b$bDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, $n. Für Longbraid! Bringt mir seinen Kopf!", t = "Tief empfundener Zorn"},
    [380] = {ot = "Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet.", st = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.$b$bEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.$B$BBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, $N.", t = "Nachtweber"},
    [381] = {ot = "Bringt Exekutor Arren insgesamt 12 scharlachrote Armbinden von scharlachroten Konvertiten und scharlachroten Initianden.", st = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.$b$bMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!$b$bSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.", t = "Der Scharlachrote Kreuzzug"},
    [382] = {ot = "Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück.", st = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!$b$bIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, $n. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.", t = "Der Rote Bote"},
    [383] = {ot = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill.", st = "Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Deathknell nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. $b$bNehmt die Straße nach Norden, hinaus aus Deathknell. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Coldhearth-Anwesen vorbeikommen.", t = "Entscheidende Informationen"},
    [384] = {ot = "Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", st = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. $b$bVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", t = "Eberrippchen in Biersauce"},
    [385] = {ot = "Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge.", st = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.$b$bWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.$b$bAch ja, das eine Mal damals...", t = "Krokiliskenjagd"},
    [386] = {ot = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", st = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.$b$bMacht Targorr dem Schrecklichen ein Ende, $n. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", t = "Verbrechen lohnt sich nicht"},
    [387] = {ot = "Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", st = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.$b$bDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", t = "Niederschlagung des Aufstandes"},
    [388] = {ot = "Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", st = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.$b$bIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", t = "Die Farbe von Blut"},
    [389] = {ot = "Sprecht mit Aufseher Thelwater im Verlies.", st = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.$B$BAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.$b$bSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.", t = "Bazil Thredd"},
    [391] = {ot = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", st = "Lasst uns eine Sache klarstellen, $n: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.$B$BAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", t = "Aufstand im Verlies"},
    [392] = {ot = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston.", st = "In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.$B$BAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch ... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.$B$BLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.", t = "Der seltsame Besucher"},
    [393] = {ot = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw.", st = "Ich habe wirklich keine Ahnung, $n. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.$B$BWenn also jemand etwas weiß, dann er.", t = "Schatten der Vergangenheit"},
    [394] = {ot = "Sprecht mit Mathias Shaw in Stormwind.", st = "Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Stormwinds zu haben.$B$BEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, $n. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.", t = "Der Kopf des Ganzen"},
    [395] = {ot = "Sprecht mit Baros Alexston in Stormwind.", st = "Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.$B$BEin kleiner Rat, $n: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.$B$BUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.", t = "Das Ende der Bruderschaft"},
    [396] = {ot = "Liefert Baros Alexstons Bericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab.", st = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.$B$BEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Stormwind.", t = "Eine Audienz beim König"},
    [398] = {ot = "Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten.", st = "Gesucht: Madenauge!$b$bDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.$b$bDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.$b$bGnade ist etwas für die Schwachen.", t = "GESUCHT: Madenauge"},
    [399] = {ot = "Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Stormwind.", st = "Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.$b$bIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.$b$bIhr findet den Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?", t = "Ein bescheidener Anfang"},
    [400] = {ot = "Liefert Beldin Steelgrill seine Werkzeuge.", st = "Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!$B$BWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.$B$BSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", t = "Werkzeuge für Steelgrill"},
    [404] = {ot = "Bringt Todeswache Dillinger in Brill 7 eitrige Klauen.", st = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen die Gegend westlich von Brill heim, nahe der alten Brücke.$B$BGeht dorthin und schlagt die Faulenden Toten und Verheerten Kadaver zurück, die Ihr dort vorfindet. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", t = "Eine eitrige Aufgabe"},
    [405] = {ot = "Zeigt Bethor Iceshard in Undercity Sevrens Befehle.", st = "Bethor Iceshard, ein hochrangiger und mächtiger Magier aus Undercity im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, $n, werdet dieser Agent sein.$B$BZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.$B$BAlso macht Euch bereit, $C. Ihr dürft nicht scheitern.$B$BIhr dürftet Bethor im Magieviertel von Undercity finden.", t = "Der abtrünnige Lich"},
    [407] = {ot = "Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird.", st = "Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.$b$bMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.$b$bEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.", t = "Felder des Kummers"},
    [408] = {ot = "Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.$B$BTötet Captain Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill.", st = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.$B$BDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.$B$BUnd bringt mir den Schädel von Captain Dargol.", t = "Die Familiengruft"},
    [409] = {ot = "Beschafft Euch eine Kerze des Heranlockens.$B$BBeschwört Lillith Nefara und tötet sie.$B$BKehrt zu Gunther auf seiner Insel zurück.", st = "Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.$B$BEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.$B$BNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.", t = "Treuebeweis"},
    [411] = {ot = "Bringt den Netheredelstein zu Bethor Iceshard nach Undercity.", st = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.", t = "Die Rückkehr des abtrünnigen Lichs"},
    [412] = {ot = "Bringt Razzle Sprysprocket in Kharanos 8 Restabilisationszahnräder und 8 gyromechanische Getriebeteile.", st = "Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.$b$bOzzie und ich haben vor, den schrecklichen Lepraeffekt mit unserer jüngsten Erfindung wieder rückgängig zu machen: der Rekombobulator. Die Maschine ist beinahe fertig, aber wir brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile. Besorgt uns ein paar davon bei den Lepragnomen drüben in Gnomeregan.", t = "Operation Rekombobulationsgerät"},
    [413] = {ot = "Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu.", st = "Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.$B$BEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.$B$BKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?", t = "Schimmerstarkbier"},
    [414] = {ot = "Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell.", st = "Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.$B$BUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.$B$BGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!", t = "Starkbier für Kadrell"},
    [416] = {ot = "Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.", st = "Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!$B$BWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.$B$BIhr findet die Kobolde der Tunnelratten und ihre Baue westlich von Thelsamar überall über den Berghang verteilt.", t = "Rattenfang"},
    [417] = {ot = "Tötet Marterklaue.$B$BBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch.", st = "Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.$B$BWenn man sich den Zustand von Hildelves Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.$B$BJedenfalls schrieb Hildelve in sein Tagebuch einen letzten Wunsch:$B$BRache an Marterklaue.", t = "Pilotenrache"},
    [418] = {ot = "Bringt Vidra Hearthstove in Thelsamar 3 Stück Bärenfleisch, 3 Portionen Ebergedärme und 3 Portionen Spinnensekret.", st = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?$b$bNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr ein toller $C seid.$b$bIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!", t = "Thelsamar-Blutwurst"},
    [419] = {ot = "Findet Pilot Hildelve.", st = "Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!$B$BImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.$B$BDas ist jetzt mehrere Tage her, und ich habe in den Hügeln des Nachts das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.$B$BBitte, $n. Sucht ihn.", t = "Der vermisste Pilot"},
    [420] = {ot = "Überbringt Senir Whitebeard in Kharanos Grelins Bericht.", st = "Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.$b$bEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.$b$bArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.", t = "Senirs Beobachtungen"},
    [421] = {ot = "Dalar Dawnweaver auf dem Grabmal will, dass Ihr 5 Moonrage-Weißskalps tötet.", st = "Lady Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.$b$bAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Shadowfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.$b$bIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Moonrage-Weißskalps tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.", t = "Wertbeweis"},
    [422] = {ot = "Beschafft Dalar Dawnweaver auf dem Grabmal die Arznei des Arugal.", st = "Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.$b$bAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die dunkle Fürstin einnehmen kann.$b$bArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.", t = "Arugals Torheit"},
    [423] = {ot = "Bringt Dalar Dawnweaver am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln.", st = "Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!$b$bArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.", t = "Arugals Torheit"},
    [424] = {ot = "Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Dawnweaver auf das Grabmal.", st = "Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.$b$bIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.$b$bDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.$b$bIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.", t = "Arugals Torheit"},
    [425] = {ot = "Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivar-Feld.", st = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.$B$BWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.$B$BTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.", t = "Ivar der Verfaulte"},
    [426] = {ot = "Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück.", st = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.$B$BEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.$B$BGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.$B$BUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.", t = "Die überrannte Mühle"},
    [427] = {ot = "Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet.", st = "Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.$b$bAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.$b$bBeweist mir, dass Ihr der dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.", t = "Im Krieg mit dem Scharlachroten Kreuzzug"},
    [429] = {ot = "Sammelt 3 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel am Grabmal.", st = "Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne alchemistische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.$B$BSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.$B$BZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.", t = "Wilde Herzen"},
    [430] = {ot = "Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank.", st = "Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.$B$BWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...", t = "Rückkehr zu Quinn"},
    [432] = {ot = "Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer.", st = "Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.$b$bOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!$b$bDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!$b$bIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!", t = "Diese verfluchten Troggs!"},
    [433] = {ot = "Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer.", st = "Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, mich um den Teil der Trogg-Plage zu kümmern, die unser Land heimsucht.$b$bSie haben den Gol'Bolar Steinbruch wirklich ziemlich verwüstet, und das ohne erkennbaren Grund. Als wir tiefer in die Erde hineingruben, strömten sie heraus, zerstörten unsere Ausrüstung und verjagten die Minenarbeiter. Wir können nicht viel mehr tun, als das ganze Pack auszulöschen, alles wieder aufzubauen und dann wieder an die Arbeit zu gehen.$b$bWenn Ihr mir mit den Troggs helft, werde ich Euch gern für Eure Zeit, die Ihr dafür opfert, entschädigen.", t = "Im Dienste des Volkes"},
    [434] = {ot = "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt.", st = "Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.$B$BWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.$B$BLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?$B$BWenn Ihr das erledigt habt, sprecht Ihr mit Trias.", t = "Der Angriff!"},
    [435] = {ot = "Begleitet Erland durch die Wölfe hindurch zu Rane Yorick.", st = "Die Wölfe da draußen wollen nicht abhauen, und jedesmal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.$B$BIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.$B$BBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...", t = "Eskorte für Erland"},
    [436] = {ot = "Sprecht mit Forscher Fellhew.", st = "Ausgrabungsleiter Ironband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.$B$BIronband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.$B$BGeht zu Ironbands Ausgrabungsstätte und sprecht mit Magmar Fellhew. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.$B$BUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.", t = "Ironbands Ausgrabungsstätte"},
    [437] = {ot = "Tötet Gnolle der Moderfelle auf dem Todesfeld.$B$BSobald Nachtseele auftaucht, tötet sie ebenfalls.$B$BBringt Nachtseeles Essenz zu Hochexekutor Hadrec auf das Grabmal.", st = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedesmal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.$B$BWir wollen Nachtseele vernichtet sehen.$B$BGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.$B$BIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.", t = "Das Todesfeld"},
    [438] = {ot = "Geht zur verfallenen Fähre.$B$BSucht nach dem Grund, warum die Geißel dort ist.", st = "$n, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.$B$BEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.", t = "Die verfallene Fähre"},
    [439] = {ot = "Bringt Deliahs Ring zu Hochexekutor Hadrec auf das Grabmal.", st = "Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. $B$BAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:$B$B\"Für Deliah\".", t = "Auf den Spuren der Moderfelle"},
    [440] = {ot = "Bringt Deliahs Ring zu Magistrat Sevren nach Brill.", st = "Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.$B$BAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.", t = "Der gravierte Ring"},
    [441] = {ot = "Bringt Deliahs Ring zu Raleigh.", st = "Deliah hatte einen Ehemann, Raleigh, der nun in Undercity sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.$B$BRaleigh ist im Handwerksviertel von Undercity.", t = "Raleigh und Undercity"},
    [442] = {ot = "Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf.", st = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.$B$BIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!$B$BDiese Mission ist so gefahrvoll, wie sie entscheidend ist, $n. Ihr dürft nicht scheitern.", t = "Sturm auf die Insel Fenris"},
    [443] = {ot = "Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel auf das Grabmal.", st = "Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.$B$BGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.", t = "Moderfellsekret"},
    [444] = {ot = "Bringt die Sekretprobe zu Bethor Iceshard nach Undercity.", st = "Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.$B$BWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Iceshard nach Undercity bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.$B$BGeht. Ihr dürftet Bethor im Magieviertel von Undercity finden.", t = "Die Ursprünge der Moderfelle"},
    [445] = {ot = "Bringt Apotheker Johaans Erkenntnisse zu Apotheker Renferrel im Silberwald.", st = "Zeit ist ein Luxus, den sich diejenigen, die für Lady Sylvanas arbeiten, nicht leisten können. Aber das wisst Ihr inzwischen sicher selbst.$b$bAls Mitglied der königlichen Apothekervereinigung ist es meine Pflicht, mein Wissen mit meinen Kollegen zu teilen, auf dass unsere gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt.$b$bBringt diese Erkenntnisse zu Apotheker Renferrel, der beim Grabmal im Silberwald stationiert ist. Folgt der Straße von Brill aus nach Süden. Geht dann nach Undercity südwestwärts.", t = "Lieferung in den Silberwald"},
    [446] = {ot = "Bringt Bethors Spruchrolle zu Apotheker Renferrel auf das Silberwald-Grabmal.", st = "Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.$B$BIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.$B$BIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.", t = "Thule Rabenklaue"},
    [447] = {ot = "Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Meisterapotheker Faranell nach Undercity.", st = "Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.$b$bMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Meisterapotheker Faranell von der königlichen Apothekervereinigung in Undercity.", t = "Rezept für den Tod"},
    [448] = {ot = "Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal.", st = "Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.", t = "Meldung bei Hadrec"},
    [449] = {ot = "Bringt den Todespirscherbericht zu Hochexekutor Hadrec auf das Grabmal.", st = "Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.", t = "Der Bericht der Todespirscher"},
    [450] = {ot = "Bergt Apotheker Berards Tagebuch aus Pyrewood und bringt es zu Apotheker Renferrel auf das Grabmal.", st = "Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, $n.$b$bAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer viel versprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.$b$bBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Pyrewood und bringt es zu Apotheker Renferrel.", t = "Rezept für den Tod"},
    [451] = {ot = "Bringt 6 Proben Seeschleicher-Moos, 6 Proben Seekrabbler-Moos und einen verhärteten Tumor zu Meisterapotheker Faranell nach Undercity.", st = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.$b$bEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.$b$bSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Meisterapotheker Faranell nach Undercity.", t = "Rezept für den Tod"},
    [452] = {ot = "Helft Todespirscher Faerleia, den Rat von Pyrewood zu töten.", st = "Ihr kommt gerade rechtzeitig, $n!$b$bDer Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Pyrewood gegen ihren Meister stellen werden.$b$bIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Lady Sylvanas zerschlagen.", t = "Der Pyrewood-Überfall"},
    [453] = {ot = "Findet die Schattengestalt. Eure Hinweise:$B$BEr stammt nicht aus Dunkelhain.$B$BEr ist eine nervöse, hektische Person.$B$BEr verließ Dunkelhain und ging nach Westen.", st = "Viel Glück, $n. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.$B$BWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.", t = "Auf der Suche nach der Schattengestalt"},
    [454] = {ot = "Sprecht mit Miran.", st = "Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.$b$bIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?", t = "Nach dem Hinterhalt"},
    [456] = {ot = "Tötet 7 junge Nachtsäbler sowie 4 junge Disteleber und kehrt dann zu Konservator Ilthalaine zurück.", st = "Seid gegrüßt, $n. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.$b$bDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.$b$bUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Shadowglen kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, $C, und dünnt die Eber- und die Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.", t = "Das Gleichgewicht der Natur"},
    [457] = {ot = "Konservator Ilthalaine verlangt von Euch, 7 räudige Nachtsäbler und 7 Disteleber zu töten.", st = "Die Jungbestände einiger Kreaturen hier im Shadowglen auszudünnen, war ein guter Anfang, $n, aber es gibt immer noch etwas zu tun.$b$bDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Wald und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.", t = "Das Gleichgewicht der Natur"},
    [458] = {ot = "Sucht die Dryade, die als Tarindrella bekannt ist.", st = "Was ein Glück, dass Ihr hier seid, $C. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.$b$bDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist nach Shadowglen zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.$b$bSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.", t = "Die Beschützerin des Waldlandes"},
    [459] = {ot = "Sammelt 8 Stücke Teufelsmoos und bringt sie zu Tarindrella.", st = "Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.$b$bNur die Verderbtheit des bösartigen Teufelsmooses könnte eine solche Wandlung geschehen lassen. Die Grells und Grellkin suchen die Gegend heim und bedrohen die Einwohner von Shadowglen. $b$bSpürt diese Grells und Grellkins auf, $n, und überzeugt Euch, ob sie wirklich unter dem Einfluss des bösartigen Teufelsmooses stehen.", t = "Die Beschützerin des Waldlandes"},
    [460] = {ot = "Bringt Alarics Kopf zu seinem Grab.", st = "Ihr seht nicht aus wie ein Moderfell. Gut. Ich hatte die Hoffnung schon aufgegeben...$B$BMein Name ist Alaric und ich war einst Thules oberster Diener und Leibwächter. Er nutzte seine Magie, um mich vor der Pest des Untodes zu \"schützen\", ein schöner Schutz... denn sein Zauber bürdete mir ein Unleben auf, dem ich nicht entrinnen kann. Und nachdem er diese verfluchten  der Moderfellgnolle erschaffen hatte, hat Thule mich geköpft... und meinen Kopf den Gnollen zum Spielen gegeben!$B$BBitte, bringt mich zu meinem Körper. Ich glaube, die Gnolle haben ihn hier in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt.", t = "In Stücken begraben"},
    [461] = {ot = "Bringt Alaric zur versteckten Nische.", st = "Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!$B$BDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.$B$BNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.", t = "Die versteckte Nische"},
    [463] = {ot = "Findet den Sumpfhüter.", st = "Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich $geinen Narren:eine Närrin; davon abhalte, in den Tod zu gehen?$B$BFalls Ihr ihn sucht... Hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Kroks und Schlimmerem herum!$B$BAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... Und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.", t = "Der Sumpfhüter"},
    [470] = {ot = "Einer der Brühschlammer bei Ironbeards Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil.", st = "Bei meinem wöchentlichen Besuch an Ironbeards Grabmal wurde ich von grässlichen, triefenden Brühschlammern angegriffen! Natürlich geriet ich in Panik.$b$bIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Brühschlammer saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.$b$bDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!$b$bIch weiß nicht, nach welchem Brühschlammer ich meine Tasche geworfen habe; sie sehen alle gleich aus! Ironbeards Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!", t = "Stochern im Brühschlamm"},
    [471] = {ot = "Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil.", st = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.$b$bDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!$b$bUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Kroks, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.", t = "Lehrlingspflichten"},
    [475] = {ot = "Sucht Gaerolas Talvethren im Dorf Starbreeze auf.", st = "Ein beunruhigender Wind weht durch den Wald.$b$bGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.$b$bAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Starbreeze, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder sicher schlummern.", t = "Ein beunruhigender Wind"},
    [476] = {ot = "Kehrt zu Athridas Bearmantle nach Dolanaar zurück.", st = "Der Knarzklauenstamm ist verderbt worden!$b$bDie einstmals friedliebenden Furbolgs haben sich gegen die Beschützer des Waldes gewandt. Sie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Starbreeze zu plündern. Ursal der Raufer, ihr Häuptling, benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.$b$bMeine Wunden sind zu schwer, ich kann nicht zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen. Junger $C, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil vorgedrungen sind!", t = "Die Verderbnis der Knarzklauen"},
    [477] = {ot = "Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Pyrewood im Süden.", st = "Wie Ihr vielleicht bereits wisst, die Stadt Ambermill ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.$b$bIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldler-Dorf wie Ambermill zeigt mir, dass es von größerer Bedeutung sein muss.$b$bVon Hillsbrad aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Pyrewood gebracht. Bringt mir den Inhalt einer dieser Kisten.", t = "Grenzübergänge"},
    [478] = {ot = "Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal.", st = "<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>", t = "Karten und Runen"},
    [479] = {ot = "Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal.", st = "Dalar versucht die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...$b$bAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.$b$bFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Ambermill.", t = "Ambermill-Nachforschungen"},
    [480] = {ot = "Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal.", st = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.$b$bIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.", t = "Der Wirker"},
    [481] = {ot = "Bringt den mit Runen gravierten Anhänger zu Dalar Dawnweaver in dem Grabmal.", st = "Bringt den Anhänger zu Dalar Dawnweaver, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.", t = "Dalars Analyse"},
    [482] = {ot = "Sprecht mit dem Schattenpriester Allister in dem Grabmal.", st = "Natürlich! Wie konnte ich das vergessen?$b$bAmbermill war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.$b$bDas dürfen wir nicht zulassen...$b$bUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.$b$bBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.", t = "Dalaran Absichten"},
    [483] = {ot = "Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar.", st = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.$b$bWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.$b$bReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.", t = "Die Relikte des Erwachens"},
    [484] = {ot = "Besorgt $1oa Häute junger Krokilisken für James Halloran im Hafen von Menethil.", st = "Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.$b$bHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.$b$bMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.$b$bDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Kroks im Wasser gleich außerhalb der Stadt finden.", t = "Häute junger Krokilisken"},
    [486] = {ot = "Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück.", st = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. $n, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.$b$bIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.$b$bEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.", t = "Ursal der Raufer"},
    [487] = {ot = "Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück.", st = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.$b$bJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.$b$b$C, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.", t = "Die Straße nach Darnassus"},
    [488] = {ot = "Bringt Zenn Foulhoof außerhalb von Dolanaar 3 Nachtsäblerfangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.", st = "Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, ein junger $C wäre hier, der mir zur Hand geht.$b$bIhr seht, $n , ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.$b$bMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir 3 Nachtsäbler-Fangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.$b$bDas soll unser kleines Geheimnis bleiben, $R.", t = "Zenns Aufträge"},
    [489] = {ot = "Sammelt 3 Teufelszapfen und gebt sie Zenn Foulhoof außerhalb von Dolanaar.", st = "Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Foulhoof behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als $R müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.$b$bIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin ein Freund von Teldrassil bleiben wollt.$b$bErteilt Foulhoof eine Lektion, dann habt ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.$b$bGebt Foulhoof einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.", t = "Sucht Befreiung!"},
    [490] = {ot = "Shayla Nightbreeze auf der Straße außerhalb von Darnassus möchte, dass Ihr ihr $1oa Knarzklauenfangzähne bringt.", st = "Laut der strikten Befehle der Schildwachen setze ich hiermit ein Kopfgeld auf den Knarzklauenstamm aus. Sie sind nicht länger Freunde des Waldes. Ihre Verderbtheit hat sie zu hirnlosen Wesen werden lassen, die eine Bedrohung für unser Volk und der Lebewesen des Moores darstellen\n\nAufgrund dieser Entscheidung werdet Ihr für die Beseitigung der Bedrohung durch die Furbolgs, der Teldrassil ausgesetzt ist, belohnt werden. Bringt mir ihre Fangzähne als Beweis Eures Tuns.\n\nAnsammlungen von Furbolgs findet Ihr auf dem Ban'ethil Hollow westlich von Dolanaar und südlich der Straße sowie im Dorf Starbreeze im Osten.", t = "Kopfgeld: Knarzklauenfurbolg"},
    [492] = {ot = "Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger.", st = "Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergen-Gebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.$b$bWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die dunkle Fürstin für den Rest von Azeroth geplant hat.", t = "Eine neue Seuche"},
    [493] = {ot = "Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge von Hillsbrad.", st = "Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.$b$bAus diesem Grunde möchte ich, dass Ihr meine letzten Funde an Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge von Hillsbrad befindet. Die Reise wird sehr lange dauern.$b$bBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!", t = "Reise in das Vorgebirge von Hillsbrad"},
    [494] = {ot = "Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesh an Hochexekutorin Darthalia zu überbringen.", st = "Schweigt und passt auf, $C.$b$bIch wurde an diesen Ort geschickt, um die Stadt Hillsbrad zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesh, lasse ihr folgende Nachricht ausrichten:$b$b\"Der Schrei des Raben locket vom Westen her.\"$b$bFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!", t = "Zeit zum Zuschlagen"},
    [496] = {ot = "Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret.", st = "Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, $n.$b$bJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.$b$bWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.", t = "Elixier des Leidens"},
    [498] = {ot = "Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien.", st = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.$b$bAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.$b$bDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.", t = "Die Rettung"},
    [499] = {ot = "Gebt Umpi das Elixier des Leidens", st = "Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.$b$bDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.$b$bLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.$b$bGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.", t = "Elixier des Leidens"},
    [501] = {ot = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.", st = "Oh, $n..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.$b$bSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.", t = "Elixier der Schmerzen"},
    [502] = {ot = "Füttert Stanley mit dem Elixier der Schmerzen.", st = "Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!$b$bDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady Sylvanas sein. Aber wir müssen erst mal einen Testlauf machen.$b$bBringt dieses Elixier zum nördlichen Hof in den Feldern von Hillsbrad im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.", t = "Elixier der Schmerzen"},
    [516] = {ot = "Findet zuerst Beren's Peril, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück.", st = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.$b$bLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Beren's Peril bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.$b$bIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.", t = "Beren's Peril"},
    [527] = {ot = "Tötet 6 Landarbeiter von Hillsbrad, 6 Bauern von Hillsbrad, Bauer Ray und Bauer Getz und meldet Euch dann wieder bei Darthalia in Tarrens Mühle.", st = "Steht gefälligst stramm, wenn Ihr mit mir sprecht, $C.$b$bIch stehe unter direktem Kommando von Varimathras. Wir sollen der menschlichen Plage Einhalt gebieten, bis unsere Apotheker eine neue Pest entwickeln können.$b$bUnseren Informationen zufolge bietet Hillsbrad einen guten Angriffspunkt. Eure erste Aufgabe ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen.$b$bBegebt Euch nach Westen. Überfallt die nördlichsten Höfe der Felder von Hillsbrad. Und stellt sicher, dass die Landeigner, Bauer Ray und Bauer Getz, ebenfalls exekutiert werden.", t = "Kampf um Hillsbrad"},
    [528] = {ot = "Tötet 15 Arbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle.", st = "Die Berichte vom Angriff auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Vorzüglich.$b$bUnsere Todespirscher melden, dass Arbeiter in die Felder ins südliche Hillsbrad flüchten. Diese Narren glauben doch tatsächlich, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können.$b$bBeweist ihnen das Gegenteil, $n. Kehrt zu den Feldern von Hillsbrad zurück und macht die feigen Arbeiter ausfindig. Vernichtet sie im Namen der dunklen Fürstin.$b$bWeggetreten!", t = "Kampf um Hillsbrad"},
    [530] = {ot = "Tötet Valdred Moray.$B$BBringt seine Hände zu Raleigh Andrean nach Undercity.", st = "Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.$B$BDas Letzte, was ich hörte, war, dass er sich im südlichen Silberwald beim Greymane-Wall aufhält und in das Königreich von Gilneas flüchten will.", t = "Rache eines Ehemanns"},
    [531] = {ot = "Bringt Old Sootys Kopf zu Vyrin Swiftwind in die Weitschreiter-Lodge.", st = "Licht! Bringt solche Dinge nicht in die Lodge... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!$b$bBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, nu wirklich nicht!", t = "Vyrins Rache"},
    [544] = {ot = "Findet diese Verräter, sammelt ihre Artefakte ein und kehrt dann zu mir zurück, $n.", st = "Eigentlich kam ich zu Forschungszwecken nach Tarrens Mühle, aber jetzt muss ich eine Krise verhindern. Wisst Ihr, vier Verlassene sind vor einigen Monaten aus Undercity geflohen. Sie haben ihren Brüdern den Rücken zugekehrt, aber was viel schlimmer ist... sie haben die dunkle Fürstin bestohlen.\n\nDiese Diebe sind in ein gesichertes Gewölbe eingebrochen und haben vier Artefakte gestohlen; Gegenstände, die unsere Apotheker für bestimmte Studien benötigen. Sylvanas will, dass diese Artefakte zurückgebracht werden.\n\nDie Diebe sind aus Undercity nach Dalaran geflohen und diese Hexer haben sie in Quarantäne in das Lordamere-Internierungslager gesteckt.", t = "Gefängnis-Einbruch"},
    [545] = {ot = "Tötet 6 Beschwörer von Dalaran sowie 12 Elementarsklaven und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück.", st = "Es gab eine riesige magische Barriere um die neu errichtete Stadt Dalaran, bevor sie auf mysteriöse Weise verschwand. Es ist mir völlig egal, warum dieses magische Wunder plötzlich den Geist aufgab, aber es ist mir nicht egal, dass die nun freigelegten Vororte ihrer Stadt wertvolle magische Schätze verbergen könnten. Überreste der Ruinen, auf denen die neue Stadt erbaut wurde.$B$BAber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert.$B$BAlso jagt sie und kehrt erst zurück, wenn ihre Anzahl einigermaßen reduziert worden ist.", t = "Patrouillen von Dalaran"},
    [546] = {ot = "Todeswache Samsa aus Tarrens Mühle will 30 menschliche Schädel aus Hillsbrad.", st = "Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin ganz grün vor Neid...$b$bIhr habt den ganzen Spaß... Menschen erschlagen, die Stadt plündern, Unschuldige terrorisieren..., und ich stecke hier fest und darf in Tarrens Mühle Wache schieben.$b$bVielleicht habt Ihr ja etwas Mitleid mit einer alten Todeswache wie mir? Wisst Ihr, ich sammle nämlich menschliche Schädel. Und Ihr werdet eine recht lange Zeit gegen Menschen kämpfen. Bringt mir im Verlauf Eures langen Kampfes 30 Schädel, und ich werde Euch für Eure Mühe entlohnen.", t = "Andenken des Todes"},
    [549] = {ot = "Tötet 10 Schurken des Syndikats und 10 Wachmänner des Syndikats. Kehrt danach zu Hochexekutorin Darthalia nach Tarrens Mühle zurück.", st = "In Lady Sylvanas Namen sollen alle Mitglieder der Organisation, die sich das Syndikat nennt, getötet werden. Diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. Wir wissen, dass sie sich im Moment in den Ruinen der Burg Durnholde im Südosten von Tarrens Mühle sammeln.$b$bFür alle diejenigen, die Beweise ihrer Taten zu Hochexekutorin Darthalia bringen, ist eine reiche Belohnung ausgesetzt.", t = "GESUCHT: Syndikatspersonal"},
    [556] = {ot = "Bringt 10 abgenutzte Steinmarken zu Bewahrer Bel'varil nach Tarrens Mühle.", st = "Ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren: mächtige Kreaturen aus anderen Dimensionen. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren. Magus Voidglare hätte gern einige dieser Marken, damit er sie studieren kann.$B$BBegebt Euch auf das Gebiet der Hexer von Dalaran, westlich von Hillsbrad, und sammelt die Marken ein.$B$BJeder Einwohner von Dalaran hat solche Marken, aber ich schlage vor, dass Ihr im Internierungslager auf die Suche geht. Dort ist es sicherer als in Dalaran selbst.", t = "Steinmarken"},
    [557] = {ot = "Bringt 4 Armschienen der Erdbindung zu Bewahrer Bel'varil nach Tarrens Mühle.", st = "Der Magus wird die Steinmarken, die Ihr gesammelt habt, einige Zeit lang intensiv untersuchen, aber ich weiß, dass er später mit Bestimmtheit auch Exemplare ihrer Gegenstücke haben will: Armschienen der Bindung. Diese befinden sich an den Handgelenken von echten Elementaren und binden sie in die Dienste der Magier.$B$BMacht Jagd auf Elementare in den Ruinen von Dalaran und sammelt ihre Armschienen der Erdbindung, und der Magus wird sehr erfreut sein.", t = "Armschienen der Bindung"},
    [590] = {ot = "Besiegt Calvin Montague in Deathknell.", st = "Was?$B$BWas?!$B$BIhr wollt Geld? Ich schulde Euch kein Geld.$B$BBrief? Was für ein Brief? Oh, Ihr wollt also kämpfen? Nun, gut Kumpel... dann lasst uns anfangen! Schulde Euch Geld...", t = "Ein Schurkenhandel"},
    [729] = {ot = "Reist nach Süden und seht nach Ausgrabungsleiter Remtravel.", st = "Was war es doch für eine Ehre, als Meister Greywhisker mir auftrug, unter der Führung des großen Ausgrabungsleiters Remtravel zu arbeiten. Jeder an der Akademie in Ironforge kannte Remtravels großartige Entdeckungen.$b$bAber der Ausgrabungsleiter ist sich nicht so recht ... ähm ... bewusst ... was um ihn herum so vor sich geht.$b$bWir hatten Hinweise auf eine große Kultur entdeckt. Schreckliche Golems brachen aus dem Boden hervor und überrannten die Grabungsstätte. Remtravel schien gar nichts bemerkt zu haben. Ich rannte nach Auberdine, um Hilfe zu holen.$b$bBitte reist nach Süden und seht nach, ob es dem Ausgrabungsleiter gut geht!", t = "Der geistesabwesende Ausgrabungsleiter"},
    [730] = {ot = "Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam.", st = "Wie schön, ein $C, der an den großartigen archäologischen Wundern unserer Welt interessiert ist.$b$bOftmals wird unser Wirken von unseren Freunden der Allianz nur als reines Hobby abgetan. Aber was viele nicht einsehen wollen ist, dass die jüngsten Entdeckungen in Khaz Modan bewiesen haben, dass eine große und mächtige Kraft ganz Azeroth bedroht, von Lordaeron bis nach Kalimdor.$b$bIch bin höchst besorgt um meine Mannschaft, die ich nach Dunkelküste geschickt habe. Meine Leute haben seit Wochen nichts mehr von sich hören lassen.$b$bReist nach Auberdine und sucht nach Hinweisen auf ihren Aufenthaltsort.", t = "Ärger in Dunkelküste?"},
    [731] = {ot = "Beschützt Ausgrabungsleiter Remtravel, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück.", st = "Also dann, Hollee... ach ja, richtig, Ihr seid ja gar nicht Hollee. Wo ist Hollee?$b$bPah, das ist ja jetzt auch nebensächlich. Wir müssen diesen Handfeger finden... Ich meine, das rätselhafte Fossil! Wir müssen dieses Fossil finden. Die Forscherliga in Darnassus wird ein paar Hinweise darauf haben wollen, was ich hier die ganze Zeit getrieben habe.$b$bLasst es mich wissen, wenn Ihr bereit seid, dann machen wir uns auf die Jagd nach diesem Feger... Ich meine, Fossil! Wir sollten irgendeine Niederschrift finden, damit die Liga zufrieden ist.$b$bAlso, seid Ihr so weit?", t = "Der geistesabwesende Ausgrabungsleiter"},
    [741] = {ot = "Bringt dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", st = "Der Ausgrabungsleiter will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Es schmeckt mir gar nicht, Dunkelküste ohne ihn zu verlassen.$b$bHier, $N, bringt Ihr dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", t = "Der geistesabwesende Ausgrabungsleiter"},
    [743] = {ot = "Bringt Ruul Eagletalon in Bloodhoof 8 Windfurienkrallen.", st = "Danke, dass Ihr Euch die Zeit genommen habt, mit mir zu sprechen, $n. Ich bin Ruul, Krieger und Lehrer.$B$BIhr habt offensichtlich ein Alter erreicht, in dem Ihr Euch auf Eure Aufgaben vorbereiten müsst, wenn Ihr auf Abenteuer weit außerhalb von Mulgore aus seid.$B$BWenn Ihr Eure Kraft erproben möchtet, versucht Euch zuerst an den Windfurienharpyien im Südosten. Sie treiben sich an den Bergrändern fernab der Straße herum.$B$BSie gehören mit zu unseren natürlichen Feinden hier in Mulgore und sind gut geeignet, um Eure Fertigkeiten einzuschätzen.", t = "Windfuriengefahr"},
    [744] = {ot = "Sammelt 6 azurblaue und 6 bronzene Federn und bringt sie Eyahn Eagletalon in Thunder Bluff.", st = "$n, mein Bruder wird schon bald vor Häuptling Bluthuf treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen.$B$BIch möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe. Ich habe keine Zeit mehr, um genügend Federn zu suchen, und ich habe mich gefragt, ob Ihr wohl noch ein paar für mich sammeln würdet?$B$BIhr könnt Federn in der richtigen Größe bei den Harpyien finden, die ganz weit im Norden und nordwestlich von Donnerfels leben. Ich brauche nur 6 azurblaue und 6 bronzene Federn, um die Ausführung zu vervollständigen.", t = "Vorbereitungen auf die Zeremonie"},
    [745] = {ot = "Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bloodhoof in Bloodhoof zurück.", st = "Viele Konflikte verwunden dieses Land, $n. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.$B$BBleichmähnengnolle haben sich südlich von Bloodhoof in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.$B$BWorte allein genügen nicht mehr als Antwort.", t = "Gemeinsame Nutzung des Landes"},
    [746] = {ot = "Sammelt 5 Ausgrabungsleiterhacken ein.$B$BZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.$B$BBringt Baine Bloodhoof in Bloodhoof 5 zerbrochene Werkzeuge.", st = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.$B$BSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.$B$BIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Thunder Bluff, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", t = "Zwergen-Buddelei"},
    [747] = {ot = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt.", st = "Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Thunder Bluff willkommen heißen. Bevor das jedoch möglich ist, müsst Ihr Euch meinem Vater, Häuptling Hawkwind, beweisen.$b$bWir hier oben auf der Red Cloud Mesa sind stolz auf unsere hervorragenden Jagdfertigkeiten. Tauren jagen aus Notwendigkeit und als sportlichen Wettkampf. Unsere Fleischvorräte gehen zur Neige und wir brauchen Federn, um Kleidung herzustellen. Jagt die in der Nähe herumwandernden Ebenenschreiter und beweist Euch, indem Ihr für Nachschub für das Dorf sorgt.", t = "Die Jagd beginnt"},
    [748] = {ot = "Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", st = "Goblins und ihre Gefolgsleute haben unsere heiligen Wasserbrunnen besudelt! Das dürfen wir nicht zulassen.$B$BUm alle Brunnen zu säubern, muss ich ein Säuberungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.$B$BZuerst werden wir ein Säuberungstotem für den Wasserbrunnen von Winterhoof herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und erwachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.$B$BKehrt mit den Tatzen und Krallen zu mir zurück, $n.", t = "Vergiftetes Wasser"},
    [749] = {ot = "Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht.", st = "Vor ein paar Tagen haben wir am Nordufer des Stonebullsees eine bewachte Karawane der Venture Company entdeckt. Wir haben bei früheren Kämpfen mit ihnen zwei unserer Leute verloren, deshalb haben wir mit der Karawane kurzen Prozess gemacht.$b$bWir haben ihre Nachschubkisten zurückgelassen, weil wir dachten, unsere Fackeln würden alles Wertvolle zerstören, aber da man in der Nähe der ausgebrannten Wagen Bergungstrupps der Venture Company gesichtet hat, haben wir uns wohl geirrt.$b$bWürdet Ihr zur Karawane gehen und den Inhalt der Kisten untersuchen?", t = "Die überfallene Karawane"},
    [750] = {ot = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt.", st = "Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen. Ihr würdet die Ältesten ziemlich beeindrucken, wenn Ihr ein paar hochgeschätzte Bergpumapelze erjagen würdet. Ihr findet die Wildtiere in den Hügeln im Süden.$b$bUnsere Kinder brauchen Kleidung und unsere Zelte müssen repariert werden.", t = "Die Jagd geht weiter"},
    [751] = {ot = "Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente der Venture Company.", st = "Als Ihr den Deckel der Kiste aufstemmt, findet Ihr sie vollgestopft mit einem Sortiment aus Erzen und Mineralien, weitere Beweise für den Bergbau der Venture Company in Mulgore. Oben auf dem Erz und den Mineralien liegt ein fest verschnürtes Bündel Papiere, das Ihr an Euch nehmt.$b$bVom Vorgebirge im Osten her könnt Ihr schwach Arbeitsgeräusche hören und Ihr seht Rauch von einem großen Feuer aufsteigen.", t = "Die überfallene Karawane"},
    [752] = {ot = "Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht.", st = "Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.$b$bMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.$b$bMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?", t = "Eine bescheidene Bitte"},
    [753] = {ot = "Holt eine Wasserkanne vom Wasserbrunnen.$b$bBringt die Kanne Häuptling Hawkwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt.", st = "Ich habe in meinem Leben so viele Pfade beschritten und meinen alten Beinen mangelt es an der Energie, die sie einst hatten. Ich kann aber immer noch meine Pflichten innerhalb des Stammes erfüllen. Manchmal braucht eine alte Frau eben nur etwas länger dafür.$b$bAber Ihr scheint mir ein eifriger $C zu sein. Wir sollten Eure jugendliche Vitalität auf die Probe stellen. Holt eine Wasserkanne vom Brunnen und bringt sie meinem Sohn, dem Häuptling im Camp Narache.$b$bVergesst nicht, dass selbst die bescheidenste Tat die Anerkennung der Ahnen finden kann.", t = "Eine bescheidene Bitte"},
    [754] = {ot = "Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück.", st = "Ich habe das Totem angefertigt, um den Wasserbrunnen von Winterhoof zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet ihn im Südosten, bewacht von elenden Goblins!$B$BDas wird keine leichte Aufgabe, aber Ihr müsst es tun, wenn wir jemals wieder sein Wasser trinken sollen.$B$BViel Glück, $n.", t = "Säuberung von Winterhoof"},
    [755] = {ot = "Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt.", st = "Eure Bereitschaft, für die Tauren von Narache eine bescheidene Bitte zu erfüllen, und Euer Eifer zu lernen sind edle Charakterzüge, $n. Ich weiß, eines Tages wird man in Thunder Bluff von Euch als einer bedeutenden Person sprechen, $C.$b$bBevor es so weit ist, müsst Ihr jedoch die Riten der Erdenmutter bestehen, derer es drei gibt.$b$bDie erste Prüfung ist der Ritus der Kraft. Begebt Euch zu Seher Graytongue und sagt ihm, dass Häuptling Hawkwind Euch schickt.$b$bIhr findet die Behausung des Sehers direkt südlich des Lagers Narache in den Hügeln verborgen.", t = "Riten der Erdenmutter"},
    [756] = {ot = "Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen.", st = "Um das Säuberungstotem von Thunderhorn zu schaffen, benötigt Ihr die Klauen der Raubtiere der Mulgoreebene. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.$B$BIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", t = "Thunderhorn-Totem"},
    [757] = {ot = "Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken.", st = "Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Thunder Bluff Respekt zu verschaffen.$b$bIhr müsst zuerst den Ritus der Kraft bestehen. Bei dieser Prüfung müsst Ihr Euren Mut beweisen, indem Ihr Feinde des Stammes tötet.$b$bDer Borstennackenstamm aus der Dornrankenklamm im Osten ist in unser Stammesterritorium eingedrungen. Sie überfallen unsere Jägergruppen und rauben in der Dunkelheit unsere Dörfer aus.$b$bZeigt Euren Wagemut, indem Ihr diese Bösewichte zur Strecke bringt und dem Häuptling des Lagers Narache ihre Gürtel zum Beweis Eurer Taten vorlegt.", t = "Ritus der Kraft"},
    [758] = {ot = "Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück.", st = "Das Totem ist bereit, $n. Und wiederum ist es Eure Aufgabe, das Ritual der Säuberung durchzuführen.$B$BGeht zum Wasserbrunnen von Thunderhorn nördlich des Dorfes und benutzt das Säuberungstotem von Thunderhorn bei Eurem Ritual. Kehrt danach zu mir zurück.$B$BMögen Euch die Geister leiten.", t = "Säuberung von Thunderhorn"},
    [759] = {ot = "Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne.", st = "Es gibt nur noch einen Wasserbrunnen, der gesäubert werden muss; er trägt den Namen des Wildmaneklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.$B$BAlphatiere streifen oft am Fuße unserer mächtigen Stadt Thunder Bluff umher.", t = "Wildmane-Totem"},
    [760] = {ot = "Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück.", st = "Die Geister sprechen von Eurer Säuberung der Wasserbrunnen von Winterhoof und Thunderhorn, $n. Das Totem von Wildmane ist fertig und die letzte Aufgabe erwartet Euch.$B$BDer Wasserbrunnen von Wildmane liegt nördlich von Thunder Bluff. Führt das Ritual durch! Heilt das Land vom Gift der Goblins! Lasst das Wasser wieder klar und rein fließen!", t = "Säuberung von Wildmane"},
    [761] = {ot = "Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele.", st = "Der Sturzflieger ist ein gewitzter Vogel, der schwer zu finden und zu jagen ist. Eine Sammlung Sturzfliegerkiele ist ein Zeichen der Geschicklichkeit und Entschlossenheit eines Jägers.$B$BWenn Ihr gewillt seid, diese Aufgabe anzunehmen, zieht in die Ebene hinaus und jagt die Sturzflieger.$B$BBringt mir ihre Kiele und macht Eurem Klan Ehre.$B$BSturzflieger findet man überall in Mulgore, aber Ihr müsst sehr scharfe Augen haben, um sie zu entdecken, und Ihr braucht flinke Hufe, um sie zu fangen.", t = "Sturzfliegerjagd"},
    [763] = {ot = "Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", st = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, $n.$b$bReist nach Bloodhoof und sprecht mit Häuptling Baine Bloodhoof, dem Sohn von Cairne. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Thunder Bluff verdienen.$b$bBringt Baine dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.$b$bFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr  könntet Euch sonst verirren.", t = "Riten der Erdenmutter"},
    [764] = {ot = "Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co.", st = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.$b$bGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der überfallenen Karawane und schickt ihnen eine Nachricht.", t = "Die Venture Company"},
    [765] = {ot = "Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett.", st = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.$b$bIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Fizsprocket, Ihr findet ihn in der Mine der Venture Co. östlich der überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", t = "Vorsteher Fizsprocket"},
    [766] = {ot = "Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.", st = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.$b$bWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich werde ein paar nur sehr schwer zu findende Körperteile von Tieren benötigen, um die Infektion durch seinen Biss zu säubern: ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.$b$bSchnell, Zeit ist hier entscheidend.", t = "Mazzranache"},
    [767] = {ot = "Sprecht in Bloodhoof mit Zarlman Two-Moons.", st = "Der Ritus der Sicht, einer der Riten der Erdenmutter, wird Euch helfen, den Respekt der Ältesten von Thunder Bluff zu erlangen.$b$bUnser Volk hat gelernt, dass das Land unser allerheiligster Versorger ist. Um am Ritus der Sicht teilzunehmen, müsst Ihr mit dem geistigen Anführer des Dorfes sprechen, Zarlman Two-Moons.", t = "Ritus der Sicht"},
    [768] = {ot = "Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder.", st = "Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!$B$BIch arbeite mit den Häuten von Wildtieren und fertige daraus Kleidung und Rüstung für die Leute von Thunder Bluff.$B$BWenn Ihr Wildtiere jagt und mir ihre Häute bringt, fertige ich Euch etwas daraus.", t = "Leder sammeln"},
    [769] = {ot = "Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden.", st = "Die Kodowildtiere von Mulgore sind stark und robust - Charaktereigenschaften, die wir sehr schätzen. Wenn Ihr in der Lederverarbeitung bewandert seid und wissen möchtet, wie man eine Kodobalgtasche fertigt, bringt mir die Materialien, die ich für mein Handwerk brauche.$B$BDann teile ich mein Wissen mit Euch.", t = "Kodobalgtasche"},
    [770] = {ot = "Sucht jemanden, der etwas über Geistheuler weiß.", st = "Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat.$B$BVielleicht weiß jemand in Bloodhoof, wie Geistheuler starb...", t = "Der Dämonennarbenumhang"},
    [771] = {ot = "Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof.", st = "Um den Ritus der Sicht zu bestehen, müsst Ihr die Zutaten sammeln, die für das Wasser der Seher benötigt werden:$b$bIch brauche Quellsteine, die man in der Nähe von Wasserbrunnen in Mulgore findet. Diese kombiniere ich mit Bernsteinkorn, das von den mächtigen Bäumen in unserem Land fällt.$b$bDiese Reagenzien enthalten magische Elemente, und wenn sie erhitzt und vor dem Stammesfeuer verzehrt werden, bekommt man eine Vision. Folgt ihr, dann wird sie Euch zum nächsten Schritt dieser heiligen Suche führen.", t = "Ritus der Sicht"},
    [772] = {ot = "Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint.", st = "Hier ist es nun, das Wasser der Seher.$b$bWenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.$b$bDann liegt es bei Euch, ihr zu Eurer Bestimmung zu folgen ...", t = "Ritus der Sicht"},
    [773] = {ot = "Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist.", st = "Um die Anerkennung der Ältesten von Thunder Bluff zu verdienen, müsst Ihr als Nächstes den Ritus der Weisheit absolvieren.$b$bJetzt, da Ihr den Ritus der Sicht bestanden habt, geben Euch die Vorfahrengeister der Teufelsfelsen den Segen unserer Vorfahren. Nur jene, die von dem Wasser der Seher getrunken haben, können diesen Segen erhalten.$b$bReist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist, $N.", t = "Ritus der Weisheit"},
    [775] = {ot = "Sprecht in Thunder Bluff mit Cairne Bloodhoof.", st = "Jetzt wird man Euch in unserer großen Stadt verehren. Ein $R, der würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.$b$bFür Eure letzte Aufgabe sucht unseren edlen Anführer Cairne Bloodhoof auf, der auf der höchsten Mesa in Thunder Bluff residiert.", t = "Reise nach Thunder Bluff"},
    [776] = {ot = "Cairne Bloodhoof in Thunder Bluff möchte, dass Ihr ihm das Horn von Arra'chea bringt.", st = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Thunder Bluff verdient.$b$bUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.$b$bWir sind Jäger, $n. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", t = "Riten der Erdenmutter"},
    [780] = {ot = "Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt.", st = "Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.$b$bTötet diese elenden Kreaturen und bringt mir ein paar ihrer Schnauzen und Flanken, damit wir daraus einen Eintopf für unsere Jungen zubereiten können.", t = "Die Kampfeber"},
    [781] = {ot = "Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken.", st = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Eure Entdeckung die geheimen Pläne des Grimmhauer-Kriegshäuptlings für eine ausgedehnte Belagerung des Lagers Narache sind.$b$bHäuptling Hawkwind wird diese Informationen sicherlich gut gebrauchen können!", t = "Angriff auf Camp Narache"},
    [783] = {ot = "Sprecht mit Marshal McBride.", st = "Ich hoffe, Ihr habt Euren Gürtel festgezurrt, $C, denn es gibt hier in Nordhain viel Arbeit.$B$BUnd ich meine damit nicht Landarbeit.$B$BDie Wachen von Stormwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.$B$BFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marshal McBride. Er ist in der Abtei hinter mir.", t = "Die Bedrohung von innen"},
    [784] = {ot = "Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück.", st = "Angeführt von Admiral Proudmoore drangen die Menschen von Kul Tiras nach Durotar vor und brachen damit den Pakt, den der Kriegshäuptling vor Jahren mit Jaina Proudmoore geschlossen hatte, um Archimonde zu besiegen.$b$bDie Menschen-Aggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. Kürzlich jedoch hat die Reserve des Admirals unter der Führung von Lieutenant Benedict die Burg zurückerobert und stellt erneut eine Bedrohung für unser Heimatland dar. Diese Menschen haben keinen Respekt vor Diplomatie.$b$bBeweist Eure Ehre und reist gen Süden zur Burg Tiragarde, um die Menschen-Eindringlinge zu eliminieren.", t = "Vernichtet die Verräter"},
    [786] = {ot = "Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden.", st = "Sprecht leiser, $C. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.$b$bWährend ihres Angriffs letzte Nacht schlich ich mich in ihr Dorf und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten.$b$bIhre Invasion muss verhindert werden. Vielleicht könnt Ihr die Streitmacht zusammenziehen, die nötig ist, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten.$b$bZuletzt sah ich, dass Sie sich auf drei ihrer Anführer verteilten.", t = "Vereitelung der Kolkaraggression"},
    [788] = {ot = "Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück.", st = "Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.$b$bIch glaube, die scheckigen Eber nördlich von hier wären genau das Richtige für Euch.", t = "Scharfe Zähne"},
    [789] = {ot = "Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau.", st = "Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpiden zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpiden. Bringt mir 10 ihrer Schwänze als Beweis für Eure Leistungsfähigkeit im Kampf.$b$bDas Gegengift für ihren Stich wird aus genau dem Gift, das aus ihren Stacheln extrahiert wurde, gewonnen. Wir haben immer einen großen Vorrat an Gegengift für dieses Skorpidgift, um Grünschnäbel wie Euch damit zu heilen...$b$bAber Ihr werdet das doch bestimmt nicht brauchen, oder?", t = "Stich des Skorpiden"},
    [790] = {ot = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", st = "$C! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.$b$bIch hatte jedoch nicht mit seinem Stecher gerechnet, den er tief in meine Brust trieb, mit dem er mein Fleisch zerschnitt und mir einen großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", t = "Sarkoth"},
    [791] = {ot = "Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben.", st = "Das Alter hat mich nutzlos für die Schlacht gemacht. Jetzt mache ich mich eben auf andere Weise nützlich.$b$bVon diesem Aussichtspunkt aus achte ich auf Eindringlinge. Während unsere Kraft hier zunimmt, muss ich mein Signalhorn immer seltener benutzen.$b$bUm mir die Zeit zu vertreiben, fertige ich Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung unserer Heimat helfen können.$b$bFür Euch könnte ich eine Tasche für Eure Habseligkeiten anfertigen. Falls ein solcher Gegenstand Euch nützlich sein könnte, bringt mir etwas Segeltuch, ein Material, das unter Menschen und Zentauren verbreitet ist.", t = "Akzeptiert Euer Schicksal"},
    [792] = {ot = "Tötet 12 üble Familiare.$B$BKehrt dann zu Zureetha Fargaze beim Höhlenbau zurück.", st = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, $C.$B$BMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...$B$BEine Gruppe, die sich die 'Burning Blade' nennt, hat hier im Tal der Prüfungen einen Koven für ihre Mitglieder. Sie lungern im Nordosten in einer Höhle herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten.$B$BAls erste Aktion gegen die Burning Blade bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt, und falls Ihr überlebt, kehrt zu mir zurück.", t = "Üble Familiare"},
    [794] = {ot = "Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", st = "Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Burning Blade ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird.$B$BEr wird das Medaillon der Burning Blade genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.$B$BSeid jedoch vorsichtig, denn das Medaillon könnte im Besitz eines Agenten der Burning Blade sein, und falls dem so ist, ist die Macht dieses Agenten weitaus stärker als die der Familiare, auf die Ihr bereits gestoßen seid.$B$BGeht, $n. Ihr findet den Koven in einer Höhle im Norden und Westen.", t = "Medaillon der Burning Blade"},
    [804] = {ot = "Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", st = "Was Ihr für mich getan habt, gibt mir Zuversicht. Ich darf nicht einfach so gehen! Ich muss durchhalten!$b$bOhne Hilfe schaffe ich jedoch den Weg zurück zum Höhlenbau nicht. Bitte, $n, kehrt zum Höhlenbau zurück und berichtet Gornek von meiner Lage. Vielleicht kann er mir helfen.", t = "Sarkoth"},
    [805] = {ot = "Sprecht mit Meister Gadrin in Sen'jin.", st = "Eure Prüfungen durch die Burning Blade sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.$B$BBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.$B$BBerichtet Gadrin von den Burning Blade und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.$B$BGeht, $n, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Burning Blade entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", t = "Bericht erstatten in Sen'jin"},
    [806] = {ot = "Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel.", st = "Wir können den Burning Blade nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!$B$BIch habe selbst Nachforschungen unternommen und herausgefunden, dass ein Hexenmeister der Burning Blade, der Goblin Fizzle Dunkelsturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos.$B$BSucht und besiegt Fizzle und bringt mir seine Klaue!", t = "Dunkle Stürme"},
    [808] = {ot = "Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.$B$BBringt ihn Meister Gadrin in Sen'jin.", st = "Ich höre die Stimme meines Bruders Minshina, der in meinen Träumen zu mir spricht.$B$BEr wurde von Zalazane, dem Hexenmeister auf den Echoinseln im Osten, gefangen genommen. Und er ist tot.$B$BAber der Tod bedeutet nicht Freiheit für meinen Bruder. Minshinas Geist ist durch Zalazanes Magie in seinem eigenen Schädel gefangen. In meinen Träumen sehe ich ihn zusammen mit weiteren Schädeln in einem Kreis der Macht auf der Größten der Echoinseln. Solange er dort bleibt, ist die Seele meines Bruders verdammt.$B$BBitte, $n. Sucht den Kreis und bringt Minshinas Schädel zurück. Bringt ihn mir.$B$BBefreit ihn!", t = "Minshinas Schädel"},
    [809] = {ot = "Sprecht im Brachland mit Ak'Zeloth.", st = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der Orc-Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.$B$BEs gehört den Burning Blade, einem Kult, der sich um einen Gegenstand dämonischer Macht schart. Er wird 'Dämonensaat' genannt und im Brachland hoch über dem Glutnebelgipfel aufbewahrt. Er muss zerstört werden!$B$BGeht zum Farwatch-Posten an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Er wird Euch weitere Anweisungen geben.", t = "Ak'Zeloth"},
    [812] = {ot = "Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar.", st = "$n, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann.$B$BWährend eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt. Bei dieser Geschwindigkeit bleibt mir vielleicht noch eine Stunde zu leben. Aber selbst dazu brauche ich Eure Hilfe...$B$BKor'ghan in Orgrimmar weiß, wie man das Gegengift herstellt. Sucht ihn... und zwar schnell, $n. Ich werde nicht mehr lange durchhalten. Er sollte sich in der Kluft der Schatten befinden.", t = "Heilmittel benötigt"},
    [813] = {ot = "Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden.", st = "Siechstachelskorpide sind eine der tödlichsten Skorpidarten in ganz Durotar. Es war dumm von Rhinag, sie zu jagen, ohne etwas von dem Gegengift mit sich zu führen, aber momentan ist eine ordentliche Standpauke das Letzte, was er benötigt.$B$BBringt mir ein paar Giftbeutel von den Siechstachelskorpiden in der Nähe des Eingangs nach Orgrimmar, dann stelle ich ein Gegengift für ihn her.$B$BBeeilt Euch, $n. Einer der Unseren braucht Eure Hilfe.", t = "Suche nach dem Gegengift"},
    [815] = {ot = "Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier.", st = "Pah! Jetzt hätte ich doch beinahe vergessen, Frühstück zu machen.$B$B$n, setzt Euch in Bewegung und bringt mir ein paar Schwanzpeitschereier. Ich brauche mindestens drei davon, wenn ich genug für die morgige Mahlzeit haben möchte.$B$BDie Blutkrallenschwanzpeitscher können ganz schön wild sein und beschützen ihre Eier bis in den Tod. Manchmal vergraben sie ihre Eier allerdings zu tief in der Erde, um sie sicher ausgraben zu können, aber reist doch zu den Echoinseln südöstlich von Sen'jin, dort findet man sie gewöhnlich überall auf den Inseln verteilt.", t = "Zerbrecht ein paar Eier"},
    [816] = {ot = "Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", st = "$n, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen. Ich fürchte das Schlimmste.$B$BSo stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Ich habe ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.$B$BFalls Ihr ihn nicht finden könnt, so bringt mir doch wenigstens einen Hinweis darauf, was aus ihm geworden ist ... und wenn Ihr dazu jedem einzelnen Krokilisken an den Ufern des Südstroms den Bauch aufschlitzen müsst.", t = "Verloren, aber nicht vergessen"},
    [817] = {ot = "Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle.", st = "Viele der Bälge, die wir benutzen, stammen von den Durotar-Tigern, $n. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum wir Jagd auf die Wildtiere machen, und ebenso viele Gründe, warum wir sie leben lassen.$B$BDie Zeit ist gekommen, dass wir den Bestand dezimieren. Wir werden immer mehr, und unser Bedarf übersteigt bald unsere Bestände. Ich brauche mehr Bälge, wenn ich geeignete Dinge für unser Volk anfertigen möchte.$B$BBringt mir 4 Durotar-Tigerfelle, dann werde ich Euch belohnen. Ihr findet sie auf den Inseln südlich von hier.", t = "Praktische Beute"},
    [818] = {ot = "Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret.", st = "Meine Augen sind zwar nicht mehr so scharf, aber ich kann immer noch gut genug sehen. Immer öfter muss ich mich auf meine Alchimie-Fertigkeiten verlassen, um mir bei Dingen, die mir früher leicht fielen, nun mit Magie zu helfen. Ich weigere mich jedoch, einen Lehrling einzustellen - bislang ist mir noch kein Troll oder Orc begegnet, der sich als würdig genug erwiesen hätte.$B$BSeid Ihr dessen würdig? Ja, natürlich seid Ihr das... natürlich glaubt Ihr, dass Ihr es seid.$B$BIch brauche ein paar Dinge. Würdet Ihr sie für mich besorgen?$B$BIch brauche intakte Makruraaugen und Phiolen mit Kriechersekret. Ihr findet das überall in Durotar, wo es Makruras oder Kriecher gibt. Wir sehen uns bald wieder.", t = "Ein geistvolles Getränk"},
    [819] = {ot = "Sucht jemanden, der etwas über Chens leeres Fässchen weiß.", st = "Auf einem kleinen Schild an einem Ende des Fässchens steht:$B$B\"Chen Stormstout -$B$BMöge es Euren Geist erheben und Euch Mut machen.\"", t = "Chens leeres Fässchen"},
    [821] = {ot = "Bringt Braumeister Drohn in Ratchet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn.", st = "Möchtet Ihr eine Kostprobe von Chens Namensvetter? Ahh, das Stormstout ist ein gehaltvolles Gebräu. Chen gab das Rezept an meinen Mentor weiter und mein Mentor gab es mir. Ich möchte, dass Ihr mir ein paar Dinge besorgt, aber eins möchte ich Euch sagen: Der Kick ist es wert.$B$BBringt mir 5 Savannenlöwenhauer von beliebigen Savannenlöwen, 5 Ebenenschreiternieren von beliebigen Ebenenschreitern und 1 Donnerechsenhorn von einer Sturmschnauze. Das sollte bestens funktionieren.$B$BIhr findet diese Zutaten überall im Brachland.", t = "Chens leeres Fässchen"},
    [822] = {ot = "Bringt Braumeister Drohn in Ratchet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber.", st = "Gutes Zeug, dieses Stormstout, was?$B$BIch habe noch ein Rezept, das ich von Chen gelernt habe. Hättet Ihr Interesse? Die Herstellung dauert nicht lange und es könnte Euch nützlich sein, wenn Ihr Eure Abenteuer fortsetzen wollt.$B$BBringt mir 5 Blitzschlagdrüsen einer beliebigen Sturmechse, 1 Donnerfalkenspeicheldrüse von großen Donnerfalken und eine Kodoleber einer beliebigen Kodoart des Brachlandes.$B$BWie ich sagte, das Zeug hat es in sich; das ist das Troggbräu, das ich kürzlich erwähnte.", t = "Chens leeres Fässchen"},
    [823] = {ot = "Sprecht mit Orgnil Soulscar in Klingenhügel.", st = "Auch wir in Sen'jin sind nicht ohne eigene Probleme und wir danken Euch für Eure Hilfe. Aber die Neuigkeiten, die Ihr über die Burning Blade bringt, können Probleme für jedermann bedeuten.$B$BIn Klingenhügel ist ein Orc stationiert, Orgnil Soulscar, der Durotar vor solch Bösem wie den Burning Blade bewacht! Geht zu Orgnil und berichtet ihm von unserer Not sowie von Euren Neuigkeiten über das Tal der Prüfungen. Er wird diese Dinge wissen wollen.$B$BKlingenhügel liegt im Norden.", t = "Bericht an Orgnil"},
    [824] = {ot = "Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", st = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.$B$BZu Eurem Glück kenne ich jemanden hier in Ashenvale, der Mitglied des Irdenen Rings ist. Geht hinüber zum Zoram'gar-Außenposten an der Küste des Zoramstrandes; zeigt Je'neu Sancrea, was Ihr gefunden habt. Wenn überhaupt jemand die Bedeutung dieser Kugel herausfinden kann, dann er.", t = "Je'neu vom Irdenen Ring"},
    [825] = {ot = "Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt.", st = "Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Proudmoores Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.$b$bEs ist kein Geheimnis, dass die Menschen, die sich mit diesen elenden kleinen, als Gnome bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen. Wir müssen so viel wie möglich über unsere potenziellen Feinde in Erfahrung bringen. Dann kann unser Volk von diesem neuen Wissen profitieren.$b$bSchwimmt durch die Wrackteile, $n, und bringt mir die Werkzeuge der Allianz.", t = "Aus den Wrackteilen geborgen..."},
    [826] = {ot = "Besiegt Zalazane.$B$BTötet 8 Voodootrolle und 8 verhexte Trolle.$B$BBringt Gadrin Zalazanes Kopf.", st = "Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten.$B$BVon dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.$B$BEr muss aufgehalten werden.$B$BBesiegt Zalazane und seine Diener - ehemalige Trolle der Darkspear, die jetzt nicht mehr zu uns gehören. Bringt mir seinen Kopf, dann weiß ich, dass seine Schreckensherrschaft vorbei ist.", t = "Zalazane"},
    [827] = {ot = "Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.$B$BBringt sie Margoz in seinem Lager.", st = "$n. Die Burning Blade haben die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.$B$BIch glaube, indem sie diese Halsbänder tragen, bringen die Kultisten sich im Einklang mit dämonischen Mächten. Um das zu bestätigen, benötige ich jedoch ein paar dieser Halsbänder, um sie zu studieren.$B$BGeht zur Knochenhöhle und besorgt ein paar Senghalsbänder von den Kultisten, die Ihr dort findet. Bringt sie mir, dann werde ich ihre Geheimnisse enthüllen.", t = "Die Knochenhöhle"},
    [828] = {ot = "Sprecht mit Margoz.", st = "Margoz, einer unserer Schamanen, weiß mehr über die Verderbnis der Burning Blade. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Burning Blade eingenistet haben.$B$BBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.$B$BEr lagert im Nordosten zwischen der Küste und der Staubwindklamm.$B$BFolgt seinem Rat, aber was immer Margoz auch sagt, $n, ich möchte, dass Ihr diese Kultisten vernichtet!", t = "Margoz"},
    [829] = {ot = "Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", st = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.$B$BBringt ein Senghalsband zu Neeru Fireblade. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.$B$BIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", t = "Neeru Fireblade"},
    [830] = {ot = "Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle.", st = "Ihr öffnet den alten, verwitterten Umschlag und findet darin ein offiziell aussehendes Dokument. Ihr erkennt das Siegel Admiral Proudmoores.$b$bEs sieht wichtig aus. Vielleicht wäre Gar'Thok, Kommandant von Klingenhügel, an diesen Informationen interessiert.", t = "Die Befehle des Admirals"},
    [831] = {ot = "Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle.", st = "Menschen kann man nicht trauen. Wir haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil wir wussten, dass sie uns eines Tages verraten würden.$b$bLeider war Admiral Proudmoores Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant.$b$bSeine Herrschaft würde, wie es scheint, nicht einmal mit Benedict enden. Wer weiß, wann die nächste Welle von Proudmoores Männern an unseren Küsten landen wird.$b$bWir müssen diese Befehle sofort zu Nazgrel in Orgrimmar bringen! Man findet ihn in Thralls Kammer.", t = "Die Befehle des Admirals"},
    [832] = {ot = "Bringt Neeru Fireblade dieses Auge.", st = "<Die Stimme aus dem Anhänger erreicht direkt Euren Verstand.>$B$BGazz'uz?$B$BGazz'uz... Bericht!$B$BMan hat von Eurer Entdeckung in der Knochenhöhle gehört. Ihr müsst Euch auf einen Angriff vorbereiten!$B$BGazz'uz, ich befehle Euch, mir zu antworten! Sagt etwas, sonst werde ich dafür sorgen, dass Neeru Fireblade von Eurer Anwesenheit erfährt, dann wird es Euch schlecht ergehen.$B$BVersucht nicht, Eure Fertigkeiten mit denen Neerus zu messen...$B$B... Gazz'uz, seid Ihr da...?", t = "Brennende Schatten"},
    [833] = {ot = "Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet.", st = "Nur die tapfersten Tauren werden bei den Teufelsfelsen, unserer heiligen Begräbnisstätte, bestattet. Es ist eine Ehre, die jenen großen Kriegern zuteil wird, die dazu beitrugen, Thunder Bluff zu gründen und zu verteidigen, und jenen, die ihr Leben für das Wohl ihres Stammes und ihrer Häuptlinge gegeben haben.$b$bNun sieht es jedoch so aus, als wäre es einer üblen Bedrohung gelungen, in unser heiliges Land einzudringen. Eine Gruppe Borstennacken-Eindringlinge verheert das Grabmal und ich bin zu alt und gebrechlich, um sie selbst zu vertreiben.$b$bSie müssen mit Gewalt von dort verjagt werden, $N.", t = "Eine heilige Bestattung"},
    [834] = {ot = "Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar.", st = "Ich bin Rezlak, einer von Gazlowes Jungs. Boss hat mich geschickt, den Orcs hier in Durotar unter die Arme zu greifen. Soweit läuft alles klar, abgesehen von den Karawanen. Ich schaff's einfach nicht, sie zu sichern! Das erschwert mir meinen Job ganz schön, wisst Ihr?$b$bDie letzte Lieferung, meine Güte, die hatten garantiert, dass sie durchkommt! Aber sie wurde von den Staubschwingenharpyien von... wo war das noch... in der Klingenschlucht geklaut.$b$bIch muss dieses Zeug zurückhaben, sonst kriege ich hier nie mehr was zu tun! Folgt dem großen Canyon nach Süden, dort findet Ihr eine Klamm direkt westlich und östlich der Wände.", t = "Wind in der Wüste"},
    [835] = {ot = "Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen.", st = "Gazlowe sagte mal zu mir: \"Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\"$b$bIch kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen. Die Staubwindklamm liegt hinter dem Ostteil der Klingenschlucht. Wenn wir alle Harpyien dort töten, ist die Route wieder sicher.$b$bNatürlich gab's da noch was, das Gazlowe mir beigebracht hat, und das ist: \"Wenn die Kohle stimmt, kriegt man alles.\" Also, werdet Ihr mir helfen, $n?", t = "Sicherung der Linien"},
    [837] = {ot = "Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer.", st = "Als wir hier ankamen, war ein Großteil des Landes im Besitz der Grimmhauerstacheleber, die sich als ein ziemlicher Dorn im Auge erwiesen. Durch unsere Anstrengungen konnten wir einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.$b$bDas geht jetzt jedoch schon viel zu lange so. Zu unserer eigenen Sicherheit dürfen wir nicht zulassen, dass sich die Grimmhauer in unserem Land festsetzen. Ihre Lager befinden sich westlich von hier. Sucht nach dem Dornengestrüpp, dann findet Ihr sie. Heute vertreiben wir sie aus Durotar, morgen vielleicht schon aus Kalimdor.", t = "Übergriff"},
    [840] = {ot = "Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.$B$BMacht bei dem Außenposten der Orcs auf der anderen Seite Halt.$B$BGebt Kargal Battlescar im Brachlandaußenposten Euren Anwerbungsbrief.", st = "Hmmm, Ihr seht mir recht stark aus.$B$BHört mal, mein guter Freund Kargal braucht ein paar neue Rekruten für den Dienst im Brachland. Ich weiß, dass Ihr immer nur das Richtige für die Horde tun wollt. Das ist jetzt Eure Chance.$B$BBringt Kargal diesen Anwerbungsbrief und seht, ob er ihn unterzeichnet.", t = "Freiwilliger der Horde"},
    [842] = {ot = "Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen.$B$BWendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung. $B$BSucht Sergra Darkthorn an der Kreuzung zweier Straßen in Crossroads auf.", st = "Bringt diesen unterzeichneten Anwerbungsbrief nach Crossroads.$B$BSergra Darkthorn, verflucht sei sie, hat dort das Kommando. Sie ist eine grässliche Schamanin, die Euch erst schwindelig redet, bevor Sie Euch etwas Nützliches tun lässt. Thrall ist davon überzeugt, dass sie etwas ganz Besonderes ist, aber ich bin mir da nicht so sicher.$B$BMacht Euch selbst ein Bild davon, Jungspund ...", t = "Crossroads-Wehrpflicht"},
    [843] = {ot = "Gann Stonespire möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.$b$bBringt Gann Stonespire dann Khazgorms Tagebuch.", st = "In Einsamkeit wandere ich auf diesen Straßen.$b$bDie Zwerge Bael Modans haben keinen Respekt vor meinem Land. Entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das meinem Stamm einst als Heimat und Versorger diente, ist jetzt von zerstörerischen Zwergen durchfurcht.$b$bAlle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Jetzt ist die Zeit für entschlossenes Handeln gekommen.$b$bVertreibt die Zwerge mit Gewalt von der Bael Modan-Ausgrabung und bringt mir das Tagebuch ihres Anführers, Ausgrabungsleiter Khazgorm.", t = "Ganns Rekultivierung"},
    [844] = {ot = "Besorgt 7 Ebenenschreiterschnäbel und bringt sie Sergra Darkthorn in Crossroads.", st = "Eure erste Beute wird einfach sein.$B$BDie Ebenenschreiter im Osten fallen immer wieder über unsere Lebensmittelvorräte her und sind zu einer Plage geworden.$B$BVernichtet die Ebenenschreiter und bringt mir ihre Schnäbel.", t = "Ebenenschreiter-Bedrohung"},
    [845] = {ot = "Erschlagt Zhevra-Läufer, um für Sergra Darkthorn in Crossroads 4 Zhevra-Hufe zu erhalten.", st = "Die Zhevras sind etwas wilder als die Ebenenschreiter, auch wenn sie nicht die stärksten Wildtiere im Brachland sind. Aber macht Euch keine Sorgen - wir werden Euch bei Gelegenheit gegen größere Beute ausschicken. Vorerst könnt Ihr jedoch noch ein bisschen Übung gebrauchen.$B$BJagt die Zhevras im Norden und Süden und sammelt ihre Hufe. Bringt sie mir, und vielleicht werden wir Euch als Nächstes eine schwierigere Aufgabe stellen.", t = "Die Zhevras"},
    [846] = {ot = "Gann Stonespire möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt.", st = "Es ist klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen. Wir müssen damit rechnen, dass schon bald ein neuer Großknecht die Sache übernimmt.$b$bIch möchte den Zwergen ihre eigene Medizin zu schmecken geben. Wenn wir laut diesen Plänen Nitroglyzerin mit Holzbrei und Natriumnitrat mischen, erhalten wir eine Sprengladung. Es ist bekannt, dass die Scharfschützen, Soldaten und Offiziere in der Burg diese Dinge besitzen.$b$bHolt diese Sachen und bringt sie mir; ich werde daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden!", t = "Ganns Rache"},
    [848] = {ot = "Bringt dem Apotheker Helbrim in Crossroads 4 Pilzsporen.", st = "Die Oasen des Brachlandes verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken.$B$BErquickt und verändert.$B$BEs gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die wir, die Apotheker Lordaerons, sehr nützlich finden.$B$BBringt mir diese Sporen, dann seid Ihr unserer Dankbarkeit gewiss.", t = "Pilzsporen"},
    [849] = {ot = "Zerstört den Flugapparat bei Beal Modan und kehrt dann zu Gann Stonespire zurück.", st = "Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen.$b$bAh, fertig.$b$bAlso, $n, ich möchte Euch mit einer besonderen Aufgabe betrauen. Nehmt diese Dynamitstange und jagt damit den Flugapparat bei Bael Modan in die Luft.$b$bDieser Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an meinen Stamm.$b$bMacht mich stolz, indem Ihr diese heldenhafte Aufgabe erledigt, dann soll es Euer Schaden nicht sein.", t = "Ganns Rache"},
    [850] = {ot = "Bringt Regthar Deathgate westlich von Crossroads Baraks Kopf.", st = "Die Zentauren haben die Tauren seit Jahren geplagt. Die Kolkarzentauren des Brachlandes sind seit kurzem zu einer echten Bedrohung geworden. Normalerweise sind sie in diesen Landen eher unorganisiert, aber es haben sich unter ihnen neue Anführer erhoben. Sie sammeln sich.$B$BWir müssen diese Zentaurenanführer vernichten, um unsere Position hier zu bewahren.$B$BBringt mir den Kopf von Barak Kodobann. Er lagert in der Nähe der vergessenen Teiche im Norden.$B$BBesiegt ihn und kehrt dann zu mir zurück.", t = "Anführer der Kolkar"},
    [851] = {ot = "Bringt Regthar Deathgate westlich von Crossroads Verogs Kopf.", st = "Der Zentaur Verog der Derwisch durchwandert das Brachland und wird daher schwer auffindbar sein. Er hat jedoch ein Zentaurenkommandozelt bei der brackigen Oase im Südosten. Vielleicht könnt Ihr ihn zu Euch locken.$B$BReist zur brackigen Oase im Südosten und greift Zentauren in der Nähe des Kommandozeltes an. Es wird gefährlich werden, aber wenn Ihr genug Zentauren tötet, werden sie Alarm schlagen. Und Verog wird kommen.$B$BBringt mir seinen Kopf, dann lege ich ihn neben den von Barak Kodobann.", t = "Verog der Derwisch"},
    [852] = {ot = "Bringt Regthar Deathgate westlich von Crossroads Hezruls Kopf.", st = "Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkars spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.$B$BAlso tötet ihn. Und bringt mir genau wie zuvor bei Barak und Verog Hezruls Kopf.$B$BEr führt sein Volk von der blühenden Oase im Süden aus an.", t = "Hezrul Blutmal"},
    [853] = {ot = "Bringt der Apothekerin Zamah in Thunder Bluff die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist.", st = "Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchimistischer Waren anbieten.$B$BSie lebt bei den Teichen der Visionen in einer Höhle unter den Schamanen von Thunder Bluff. Der Pfad zu dieser Höhle ist gut versteckt, aber Ihr könnt ihn am Steilhang der Anhöhe der Geister finden.$B$BBeeilt Euch. Die Emulsion verliert nach einer Weile ihre Wirksamkeit und muss vorher luftdicht verschlossen und weiterverarbeitet sein.", t = "Apothekerin Zamah"},
    [854] = {ot = "Sprecht mit Thork in Crossroads im Brachland.", st = "Ich habe Eure Ankunft vorausgesehen, junger $C. Aber vielleicht seid Ihr ja gar nicht mehr so jung.$B$BIch glaube, dass es an der Zeit ist, dass Ihr Euch tiefer in dieses Land vorwagt. Ich fühle, dass Ihr zu Größerem berufen seid.$B$BCrossroads wartet auf Euch, denn die Orcs, mit denen wir eng verbunden sind, brauchen Unterstützung. Folgt dieser Straße weiter nach Osten und dann weiter nach Norden bis nach Crossroads. Sucht Thork in seinen Mauern, er hat den Segen der Erdenmutter.", t = "Reise nach Crossroads"},
    [855] = {ot = "Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen.", st = "Die Kolkar sind eine echte Bedrohung für die Besitzansprüche der Horde im Brachland und wir müssen deren Truppen unbedingt dezimieren. Deshalb habe ich eine lohnenswerte Aufgabe für Euch.$B$BErschlagt ihre Krieger, während Ihr Euch auf dem Territorium der Kolkar befindet, und sammelt Zentaurenarmschienen ein. Kommt zurück, wenn Ihr eine ordentliche Menge Armschienen beisammen habt, dann wird Euch die Horde reich belohnen.", t = "Zentaurenarmschienen"},
    [857] = {ot = "Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt.", st = "Ich hatte die Macht! In diesen meinen Händen! Und ich möchte sie wiederhaben! Wiederhaben möchte ich sie!$b$bDiese dreckigen Ausgräber haben sie entdeckt... sie war so wunderschön. Die Träne der Monde war die erste größere Entdeckung, die wir in Bael Modan gemacht haben.$b$bSie hätte mir gehören sollen! Mir!$b$bGeneral Twinbraid war eifersüchtig auf die Macht, die sie mir verlieh; er sperrte sie weg, in der Burg. Sagte, sie sei verflucht! Dieser Dummkopf!$b$bAndere wollten sie auch haben und sie mussten daran gehindert werden! Dieser Bastard Twinbraid jagte mich weg.$b$bJetzt möchte ich sie wiederhaben. Wiederhaben möchte ich sie!", t = "Die Träne der Monde"},
    [858] = {ot = "Holt den Zündschlüssel und bringt ihn Wizzlecrank.", st = "Euch hat nicht etwa Sputtervale geschickt? Ich stecke hier in der Klemme. Ich bin hier reingesprungen, ohne daran zu denken, dass ich einen Schlüssel brauche, um die Antriebswelle des Schredders aufzuschließen. Einer der anderen Schredderbediener fragte mich, ob alles in Ordnung sei, und da bin ich in Panik geraten! Statt ihm zu sagen, dass ich meinen Schlüssel nicht dabei hatte, sagte ich ihm, dass es irgendeine mechanische Störung gäbe.$b$bWir müssen hier weg, und zwar schnellstens! Geht hinauf zum Kontrollraum oben auf dem Kran, der Vorsteher sollte einen Schlüssel für diesen Schredder haben.$b$bHelft mir hier raus!", t = "Zündung"},
    [862] = {ot = "Bringt Grub östlich von Crossroads 8 Grubenratten.", st = "Ein $C wie Ihr muss hier im Brachland doch ziemlich hungrig sein. Ich bin den ganzen Tag am Verhungern.$b$bIch sag Euch was, ich bereite Euch einen feinen Eintopf zu. Ich brauche nur ein paar Grubenratten.$b$bScheint so, als würden diese dreckigen Zwerge in Bael Modan von unser aller Lieblingsspeise überrannt. Also reist gen Süden nach Bael Modan und bringt mir ein paar Grubenratten.$b$bIhr dürft Euch erst einen erfahrenen Abenteurer nennen, wenn Ihr Euch ein bisschen mit der Rattenjagd beschäftigt habt! Ha!", t = "Grubenratteneintopf"},
    [863] = {ot = "Schützt Wizzlecrank und den gestohlenen Goblinschredder auf dem Weg zu Sputtervalve in Ratchet.", st = "Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?", t = "Die Flucht"},
    [865] = {ot = "Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet.", st = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!$B$BUnd Ihr könntet mir helfen; sucht und bringt mir intakte Raptorhörner von Bluthornsensenklauen. Sie durchstreifen den Süden sowie den Norden des Brachlandes an der Grenze zum Wald von Ashenvale.", t = "Raptorhörner"},
    [866] = {ot = "Bringt Mebok Mizzyrix in Ratchet 8 Wurzelproben.", st = "Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.$B$BIch möchte diese Unterschiede studieren... um zu sehen, ob man daraus nicht Kapital schlagen kann!$B$BFalls Ihr in der Kräuterkunde bewandert seid, sammelt doch ein paar Wurzelproben der Kräuter, die Ihr im Brachland findet. Bringt mir diese Proben, damit ich sie mit Kräutern aus anderen Regionen vergleichen kann.", t = "Wurzelproben"},
    [867] = {ot = "Sammelt 8 Krallen der Hexenschwingen.$B$BBringt sie Darsok Swiftdagger in Crossroads.", st = "Die verdammten Harpyien haben unsere Karawanen lang genug geplündert; es ist an der Zeit, dass wir einigen von ihnen die Hälse abschneiden und ihre Anzahl verkleinern.$B$BIch hab mich bei ihren Nestern mal ein bisschen umgeschaut und herausgefunden, wer da wen anführt. Der vernichtendste Angriff wird einen guten Teil ihrer niederen Befehlskette zerstören und dann können wir uns bis zur Spitze vorarbeiten.$B$BWir fangen langsam an; schaltet die Harpyien der Hexenschwingen und Wildfedern der Hexenschwingen im Nordwesten aus und bringt mir 8 Krallen der Hexenschwingen. Das sollte ein guter Anfang sein...", t = "Räuberische Harpyien"},
    [868] = {ot = "Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel.", st = "He, $n. Man hat mich nach Crossroads geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte.$B$BEines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet. Wir wissen nur wenig über diese Kreaturen, also haben wir es uns zur Aufgabe gemacht, mehr über sie zu erfahren. Sie scheinen intelligent zu sein, intelligenter als normale Tiere.$B$BNehmt diese Grabgabel und grabt ein paar ihrer Eier aus den Hügeln aus, aber seid vorsichtig: einmal aufgeschreckt, werden sie Euch angreifen.", t = "Eierjagd"},
    [869] = {ot = "Bringt Gazrog in Crossroads 12 Raptorenköpfe.", st = "Vor kurzem wurde eine Ladung Silber aus unserem Wachturm entwendet. Sie war als Sold für die Crossroads-Wachen gedacht und wir wollen das Silber zurückhaben.$B$BDas Seltsamste daran ist... wir haben einen der Diebe in der Nacht des Raubes erwischt. Und... es war ein Raptor! Unglaublich!$B$BIch weiß nicht, wofür Raptoren Silber brauchen könnten. Aber das ist mir auch egal - ich will die Raptoren tot sehen, damit sie uns nicht wieder bestehlen!$B$BJagt Raptoren im Brachland. Sammelt ihre Köpfe für mich!", t = "Raptorendiebe"},
    [870] = {ot = "Berichtet Tonga Runetotem von Euren Entdeckungen.", st = "Vor langer Zeit war das Brachland ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. So ist es nun einmal und es macht mich traurig.$B$BIn den letzten Jahren jedoch sind Oasen im Brachland entstanden und das Leben blüht wieder auf. Und wir Druiden spüren eine Macht von ganz tief unten an die Oberfläche dringen.$B$BWir müssen ihre Quelle finden. Reist zu den vergessenen Teichen nordwestlich von Crossroads. Sucht in den dortigen Gewässern nach einer Quelle der Macht und kommt dann hierher zurück.", t = "Die vergessenen Teiche"},
    [871] = {ot = "Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Grimmhauerstamms und kehrt dann zu Thork in Crossroads zurück.", st = "Alle Stacheleber sind unsere Feinde, $n. Manche sind nur lästiger als andere.$B$BDer Grimmhauerstamm hat unsere Nachschublinien von Durotar aus angegriffen, was uns nicht wenig Ärger bereitet. Ich habe Späher ausgeschickt, um den Anführer dieser Überfälle zu finden, aber bis es so weit ist, könnte es uns schon helfen, wenn Ihr diese dreckigen Schweinemenschen etwas dezimieren würdet.$B$BBeginnt im Nordosten in Richtung Durotar. Ihr könnt ihre Baue immer an den riesigen, dornigen Ranken erkennen, die aus dem Boden wachsen. Sucht sie und erschlagt sie.", t = "Vereitelung der Angriffe"},
    [872] = {ot = "Tötet 8 Geomanten der Grimmhauer, 8 Verteidiger der Grimmhauer und Kreenig Grantelschnauze.$B$BBringt dann Thork in Crossroads Kreenig Grantelschnauzes Hauer.", st = "Einer meiner Späher war Zeuge eines Angriffs auf eine Karawane aus Durotar, $n. Die Übeltäter waren in der Tat vom Grimmhauerstamm der Stacheleber. Ein ganz bestimmter Stacheleber führte den Überfall an: Kreenig Grantelschnauze. Man hat ihn nordöstlich von hier gesehen, gleich südlich der Straße von Durotar. Wenn diese Bedrohung jemals ein Ende finden soll, dann muss Kreenig sterben.$B$BDamit diese Angriffe auch wirklich aufhören, würde ich sagen, dass wir das Ganze auf die Spitze treiben sollten. Tötet Kreenig und andere seines Stammes und kehrt dann zu mir zurück, wenn Ihr seine Hauer habt.", t = "Das Ende der Unterbrechungen"},
    [873] = {ot = "Bringt Mahren Skyseer das Herz von Isha Awak.", st = "Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.$B$BIch jedoch fürchte ihn nicht. Ich bin froh, dass er hier ist. Er ist eine würdige Herausforderung und eine ehrenhafte Beute.$B$BWenn Ihr bereit seid, schwimmt hinaus und sucht nach Isha Awak, der Tiefsten Verdammnis.$B$BSein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, Euer Schicksal zu kennen.", t = "Isha Awak"},
    [874] = {ot = "Sprecht mit Mahren Skyseer.", st = "Ihr habt die Wildtiere des Brachlandes gejagt. Euer Geist ist stark. Ein Jäger muss jedoch immer vorbereitet sein. Ein wahrer Jäger kann auf allen Pfaden seine Beute finden. Weder Berg noch Sumpf wird ihn wanken lassen.$B$BNicht einmal das Meer.$B$BSucht meine Schwester Mahren. Sie jagt die großen Wassertiere entlang der Küste. Sie wird Euch etwas über sie lehren.$B$BSeid jedoch vorsichtig, während Ihr nach ihr sucht, denn die Küste des Brachlandes ist in den Händen der Menschen.", t = "Mahren Skyseer"},
    [875] = {ot = "Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Swiftdagger in Crossroads zurück.", st = "Hahaha, $N. Ihr wollt noch mehr? Gut, das hör ich gern.$B$BDieses Mal möchte ich, dass Ihr ein paar der Offiziere der Harpyien in den trockenen Hügeln meuchelt. Nur Töter der Hexenschwingen können Offiziere werden und Ihr erkennt sie an den Ringen, die sie tragen. Sie sind ein übler Haufen, aber sie führen ein paar der Unterlinge in diesem Gebiet an. Schaltet Ihr 6 davon aus, wird das ein Entscheidungsschlag gegen ihr Matriarchat sein.$B$BSorgt dafür, dass sie schmerzvoll sterben, $n. Wir möchten, dass diese Dirnen von Harpyien lernen, wie wahnwitzig es ist, sich mit der Horde anzulegen.", t = "Offiziere der Harpyien"},
    [876] = {ot = "Erschlagt Serena Blutfeder und bringt Darsok Swiftdagger in Crossroads ihren Kopf.", st = "Ihr habt das mit den Offizieren und Unterlingen so gut erledigt, dass ich Euch noch um einen letzten Dienst bitten möchte.$B$BSerena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug. Offensichtlich wurden die Karawanen der Horde angegriffen, um ihre Schwester zu rächen.$B$BIch möchte, dass Ihr ihr die Kehle durchschneidet und mir ihren Kopf bringt. Er soll die nächste Karawane schmücken, die wir losschicken... Gebt diesen Harpyien etwas, über das sie nachdenken können.", t = "Serena Blutfeder"},
    [877] = {ot = "Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt.", st = "Erdrisse wie jene, die Ihr bei den vergessenen Teichen gefunden habt, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.$B$BWir müssen das überprüfen.$B$BHier, nehmt diese Samen. Sie sind tot und unfruchtbar, aber bringt sie dennoch zur brackigen Oase im Südosten. Falls es dort einen Riss gibt, legt die Samen hinein und ... wartet ab.", t = "Die brackige Oase"},
    [878] = {ot = "Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück.", st = "Ihr müsst meine Feinde schlagen. <schnaubt> Ihr müsst Quetschzahn und dem Grimmhauerstamm helfen, indem Ihr die Borstennacken schwächt. Beide Stämme sind sehr spirituell - gebunden an die Erde und ihre Kraft. <schnaubt> Sie gibt uns Stärke in allen Dingen... besonders im Krieg.$B$BWenn ihr herausfinden wollt, wer Thork <schnaubt> und der Horde wirklich solche Angst bereitet, dann helft Quetschzahn! Ihr greift die spirituellen Anführer der Borstennacken im Norden an und schwächt sie, sodass die Grimmhauer sie besiegen und das Brachland beherrschen können.", t = "Stämme im Krieg"},
    [879] = {ot = "Tötet Nak, Kuz und Lok Orcbane und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel.", st = "Drei meines Stammes kamen aus dem Kral, um die Überfälle gegen die Horde anzuführen, $R. <schnaubt> Sie sind ruchlos und schlau und wenn Ihr sie besiegt, dann werden Crossroads und auch der Großteil des Brachlandes Frieden haben... <schnaubt> zumindest vor dem Grimmhauerstamm. <schnaubt>$B$BSucht nach Nak, Kuz und Lok Orcbane. Sie befinden sich weit im Süden des Brachlandes. Einer ist ein Zauberer, ein weiterer ein Fährtenleser und ihr Anführer, den sie Orcbane nennen, <schnaubt> ist ein Krieger. Tötet sie, $R, so wie sie mich töteten.", t = "Verräter in den eigenen Reihen"},
    [880] = {ot = "Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen.", st = "Eure Entdeckungen sind erstaunlich, $n. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen.$B$BIch muss wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken.$B$BJagt Oasen-Schnappkiefer in der blühenden Oase und der brackigen Oase. Bringt mir ihre Schalen, damit ich sie untersuchen kann.", t = "Veränderte Wesen"},
    [881] = {ot = "Bringt Sergra Darkthorn in Crossroads Echeyakees Balg.", st = "Whitemist, Echeyakee in der Sprache der Tauren, ist der König der Savannenkatzen. Er jagt mit solcher Verstohlenheit, dass man sagt, er sei wie ein dünner, weißer Nebel auf der Erde. Und er tötet so schnell, dass seine Beute weder Angst noch Schmerz verspürt.$B$BDie Tauren sagen, er sei sowohl Gnade als auch Tod.$B$BIhr werdet erfahren, ob das wahr ist, denn ich schicke Euch aus, um Echeyakee zu jagen. Sein Unterschlupf befindet sich im Nordosten von Crossroads, zwischen den Knochen des riesigen Kodos.$B$BGeht jetzt. Blast dieses Horn, wenn Ihr seinen Unterschlupf erreicht. Blast das Horn und er wird kommen.", t = "Echeyakee"},
    [882] = {ot = "Bringt Jorn Skyseer im Camp Taurajo Ishamuhales Fangzahn.", st = "Ishamuhale - Speerzahn - ist der wildeste Bluthornraptor des Brachlandes. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist.$B$BUnd Ihr werdet Euch mit seiner Natur vertraut machen, $n, denn Euer Weg folgt jetzt den Krallenspuren Ishamuhales.$B$BBeginnt mit der Jagd. Erlegt seine Lieblingsbeute, ein Zhevra, und bringt den Kadaver zum toten Baum im Nordwesten von Ratchet. Ishamuhale wird den Kadaver riechen und von ihm angezogen werden.$B$BSeid bereit, wenn er kommt.", t = "Ishamuhale"},
    [883] = {ot = "Bringt Jorn Skyseer im Camp Taurajo Lakota'manis Huf.", st = "Lakota'manis Huf ist ein Symbol für die Kraft der großen Kodos.", t = "Lakota'mani"},
    [884] = {ot = "Bringt Jorn Skyseer im Camp Taurajo Owatankas Schwanzstachel.", st = "Wenn man Owatankas Schwanzstachel berührt, stieben Funken auf.", t = "Owatanka"},
    [885] = {ot = "Bringt Jorn Skyseer im Camp Taurajo Washte Pawnes Feder.", st = "Eine Berührung mit der Feder von Washte Pawne ist schmerzhaft.", t = "Washte Pawne"},
    [886] = {ot = "Sprecht in Crossroads mit Tonga Runetotem.", st = "Die Druiden von Thunder Bluff spüren eine große Macht, die östlich von Mulgore ins Brachland sickert.$B$BTonga Runetotem wurde entsandt, um die Quelle dieser Macht ausfindig zu machen, aber wir befürchten, dass er Hilfe brauchen wird.$B$BReist ins Brachland und sprecht mit Tonga. Er wird in Crossroads sein. Um dorthin zu gelangen, folgt der Straße von Bloodhoof aus nach Osten. Betretet das Brachland und wendet Euch bei der Weggabelung weiter nach Norden. Geht weiter Richtung Norden, dann gelangt Ihr nach Crossroads.$B$BUnd haltet Euch immer auf der Straße, $n, denn das Brachland ist ein raues Land.", t = "Die Oasen des Brachlandes"},
    [887] = {ot = "Tötet für Gazlowe in Ratchet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter.", st = "Ich wünschte, Vize-Admiral Grezzlik würde bessere Arbeit bei der Sicherung der Meere für unsere Handelsschiffe leisten. Bei all dem Gold, das die Handelsbarone in die Handelsflotten gesteckt haben, macht es mich rasend zu sehen, wie viele Piraten unbehelligt unterwegs sind, meine Schiffe überfallen und meine Waren stehlen!$b$bMir kam zu Ohren, dass die Südmeerfreibeuter südlich von hier ein Lager aufgeschlagen haben. Sie sind mir ein echter Dorn im Auge, und wenn sich Grezzlik nicht um sie kümmert, könnt Ihr mir vielleicht helfen, sie loszuwerden?", t = "Südmeerfreibeuter"},
    [888] = {ot = "Bringt Gazlowe in Ratchet die Stiefellieferung und die Teleskoplinse zurück.", st = "Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss!$b$bWie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen. Die erste Linse ist mit der Karawane aus Durotar gekommen, aber die zweite wurde per Schiff verschickt und ist nie hier eingetroffen. Ebenso ist meine Stiefellieferung von Drizzlik aus Booty Bay nicht hier angekommen!$b$bBegebt Euch zum Piratenlager und seht mal nach, ob Ihr die Dinge dort finden könnt.", t = "Gestohlene Beute"},
    [890] = {ot = "Bringt Werftmeister Dizzywig Gazlowes Geschäftsbuch.", st = "Ich warte schon eine Ewigkeit auf meine letzte Warenlieferung aus Booty Bay! Ich bin mir ziemlich sicher, dass die Seeräuber sie gestohlen haben; würdet Ihr wohl, nur um sicher zu sein, zu den Docks gehen und Dizzywig fragen, ob meine Waren vielleicht ohne mein Wissen bereits ins Lagerhaus gebracht wurden?$b$bHier, nehmt mein Geschäftsbuch mit zu Dizzywig, damit er meine Inventaraufzeichnungen mit seinen Büchern gegenprüft.", t = "Die verloren gegangene Lieferung"},
    [891] = {ot = "Kapitän Thalo'thas Brightsun aus Ratchet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Captain Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet.", st = "Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen der Feste Northwatch in die Hände gefallen!$b$bMan muss sich um diese Bastarde kümmern. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt.$b$bReist gen Süden entlang der Händlerküste zur Feste und belagert ihre Streitkräfte. Bringt mir die Medaillen ihrer Soldaten als Beweis. Und erschlagt um meiner Flotte willen Captain Hellstieg und ihre übereifrigen Kanoniere!", t = "Die Kanonen von Northwatch"},
    [892] = {ot = "Bringt Gazlowe in Ratchet sein Geschäftsbuch zurück.", st = "Laut meinen Aufzeichnungen ist alles in Ordnung, $n. Geht zurück und sagt Gazlowe, dass er wohl Pech gehabt hat. Es würde mich nicht überraschen, wenn sich die Piraten seine Waren geschnappt hätten.$b$bIch kann leider nicht mehr für ihn tun. Oh... Ihr könnt ihm allerdings sagen, dass ich ein paar Dinge aus Undermine für ihn habe, falls er die Zeit findet, sie abzuholen.", t = "Die verloren gegangene Lieferung"},
    [893] = {ot = "Bringt Tatternack Steelforge im Camp Taurajo im Brachland einen Grimmhauerrückenstecher, einen verkohlten Grimmhauerzauberstab und einen Grimmhauerkriegsschild.", st = "Die Stacheleber des Grimmhauerstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln. Ich hätte gern ein paar verschiedene Arten davon, um etwas über ihre Techniken zu erfahren, so möglich.$B$BWenn Ihr der Horde Ehre bringen wollt, dann bringt mir Exemplare von ihren Waffen. Besorgt mir einen Dolch von ihren Schleichern, einen Zauberstab von ihren Sehern und einen Schild von ihren Kriegsberserkern. Das sollte reichen!", t = "Ausgewählte Waffen"},
    [894] = {ot = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.", st = "Die Venture Company hat weit nördlich von hier, südwestlich des Schlickermoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das 'Samophlang' genannt wird.$b$bWas zum Teufel ist ein Samophlang? Na ja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.$b$bIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", t = "Samophlang"},
    [895] = {ot = "Bringt Gazlowe in Ratchet Baron Küstenschippers Kopf.", st = "GESUCHT!$b$bBaron Küstenschipper, Kapitän der GNADENLOS$b$bCaptain Küstenschipper aus Gilneas befehligt Schiffe der Südmeerfreibeuter und wird wegen Piraterie gesucht. Seine Überreste müssen in noch erkennbarem Zustand sein!$b$b- Gazlowe", t = "GESUCHT: Baron Küstenschipper"},
    [896] = {ot = "Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Dizzywig in Ratchet.", st = "Als Werftmeister eines so geschäftigen Hafens wie Ratchet habe ich mein Ohr immer am Puls der Zeit. Ich weiß alles über den Verkehr von Waren und Geld zwischen hier und Booty Bay.$b$bDie jüngste Neuigkeit, die ich erfahren habe, betrifft die Felsadermine der Venture Company nordöstlich des Schlickermoores. Einer der Minenarbeiter hat dort einen faustgroßen Smaragd gefunden. Ich kenne ein paar Käufer, die sich die Finger nach so etwas ablecken würden... und ich würde bei einem Verkauf Halbe-Halbe machen.", t = "Des Minenarbeiters Vermögen"},
    [897] = {ot = "Bringt den Ernterkopf zu Jorn Skyseer.", st = "Diese seltsame, insektenartige Kreatur scheint außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins Brachland gehören.", t = "Der Ernter"},
    [898] = {ot = "Begleitet Gilthares Firebough sicher zurück zu Kapitän Brightsun in Ratchet.", st = "Endlich! Jemand rettet mich!$b$bIch kann es nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Fanatiker aus Theramore müssen verrückt sein. Sie haben unser Schiff versenkt und mich, den einzigen Überlebenden, eingesperrt. Sie nannten mich ihren Feind und eine Gefahr für die Allianz.$b$bIch! Eine Gefahr für diesen Riesenschwindel, den sie Allianz nennen? Ich war Decksmann auf einem Fuseltransporter zwischen Ratchet und Booty Bay.$b$bGenug geredet. Helft Ihr mir, zurückzukommen nach Ratchet, ja? Lasst es mich wissen, wenn Ihr bereit seid, hier auszubrechen.", t = "Aus der Gefangenschaft befreit"},
    [899] = {ot = "Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken.", st = "Vielleicht kennt Ihr diesen Schmerz der Ungewissheit, $C, vielleicht auch nicht. Doch wisset: Ich stehe hier jeden Tag, vom Aufgang der Sonne bis zu ihrem Untergang, und suche den Horizont nach diesen Monstern ab. Ich habe jeden Schweinemenschen getötet, den ich seitdem gesehen habe, doch der Durst nach ihrem Blut ist noch lange nicht gestillt. Vielleicht hätte ich mich nach Taurajo begeben sollen, statt nördlich nach Crossroads.$B$BIhr, $C, könntet mir helfen.$B$BTötet sie. Tötet so viele Ihr könnt und bringt mir ihre Hauer, dann werden wir ihren Tod miteinander feiern.", t = "Von Hass zerfressen"},
    [900] = {ot = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", st = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", t = "Samophlang"},
    [901] = {ot = "Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen.", st = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", t = "Samophlang"},
    [902] = {ot = "Bringt das Samophlang zu Sputtervalve in Ratchet.", st = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", t = "Samophlang"},
    [903] = {ot = "Besorgt für Sergra Darkthorn in Crossroads 7 Streunerklauen von den Savannenstreunern.", st = "Es ist nun an der Zeit, etwas zu jagen, das sich wirklich wehrt. Die Streuner des Brachlandes sind von zäher Art. Zäh, erfinderisch, listig... und tödlich. Ihr findet sie zwischen den hohen Gräsern. Ihr werdet viele südwestlich von Crossroads finden.$B$BSeid vorsichtig, wenn Ihr sie jagt, $n, oder Ihr werdet feststellen, dass Ihr nicht mehr Jäger, sondern Gejagter seid.", t = "Streuner des Brachlandes"},
    [905] = {ot = "Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Darkthorn in Crossroads zurück.", st = "Tja, $n, die Jagd wird schwieriger. Jetzt müsst Ihr Eure Beute besiegen und dann Euren Weg zu ihrem Unterschlupf finden.$B$BJagt die Bluthornraptoren im Süden. Erledigt sie und nehmt Euch die Federn, die sie tragen. Legt die Federn in die Sensenklauennester südwestlich der brackigen Oase. Zeigt ihren Brüdern, dass Ihr sie nicht fürchtet!", t = "Die wütenden Sensenklauen"},
    [906] = {ot = "Bringt Loks Kopf zu Thork in Crossroads im Brachland.", st = "Bringt Loks Kopf zu Thork in Crossroads, $R. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen. Aber ich bin sicher, er wird Euch für das Ausführen einer solch großen Tat belohnen. <schnaubt>$B$BIch werde Euch auch weiterhin mit Agammagans Macht segnen, solange ich in diesem Käfig verbleibe, $R. Bis dann, lebt wohl.", t = "Verräter in den eigenen Reihen"},
    [907] = {ot = "Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Skyseer.", st = "Nun denn, $n, jetzt müsst Ihr den großen Donnerechsen gegenübertreten. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Seid vorsichtig, wenn Ihr gegen sie kämpft, denn ein einziger falscher Schritt, und schon findet Ihr Euch unter ihren Füßen wieder.$B$BIhr findet die Donnerechsen im südlichen Brachland. Man kennt sie als Sturmschnauzen, Sturmechsen und Donnerköpfe. Kehrt zu mir zurück, nachdem Ihr sie überwältigt habt.", t = "Wütende Donnerechsen"},
    [913] = {ot = "Sucht und erschlagt einen Donnerfalken und bringt Jorn Skyseer in Taurajo seine Flügel.", st = "Der Donnerfalke, $n, ist eine ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.$B$BWenn Ihr das tut, wird Eure Zeit mit mir sich ihrem Ende nähern.", t = "Der Ruf des Donnerfalken"},
    [914] = {ot = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane.", st = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.$B$BDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.$B$BGeht, $n. Sie halten sich tief in den Höhlen des Wehklagens verborgen.", t = "Anführer der Giftzähne"},
    [916] = {ot = "Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel.", st = "Ich kam nach Shadowglen, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben. Sie sind mit einer wesentlich kleineren Spinnenart verwandt. Ich glaube, der Weltbaum hat einen nicht unerheblichen Effekt auf sie und ich hätte gern ein paar Exemplare von ihnen, um dies zu belegen.$B$BAls Erstes hätte ich gern etwas von ihrem Gift. Sammelt Giftbeutel der Waldweberspinnen, die in und um die Schattenweberhöhle herum zu finden sind. Dann kann ich ihren und das Gift ihrer kleineren Verwandten auf Gemeinsamkeiten hin untersuchen.", t = "Waldwebergift"},
    [917] = {ot = "Bringt Gilshalan in Aldrassil ein Waldweberei.", st = "Jetzt, da ich das Spinnengift habe, hätte ich gern auch ein paar lebende Exemplare, um sie zu studieren. Leider kann ich Euch nicht darum bitten, eine lebende Riesenspinne für mich einzufangen, $C. Eine Riesenspinne kann ich allein sowieso nicht bewältigen!$B$BWenn Ihr mir allerdings ein unausgebrütetes Ei besorgen könntet, wäre es viel einfacher, lebende Exemplare zu bekommen, und ich könnte dafür sorgen, dass die noch nicht ausgeschlüpften Exemplare ordentlich unter Verschluss gehalten werden.$B$BTief in der Schattenweberhöhle gibt es angeblich ein Nest. Bitte, beschafft mir ein Ei aus diesem Nest und bringt es mir.", t = "Waldweberei"},
    [918] = {ot = "Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner.", st = "Die Bäumlinge von Teldrassil sind Naturelementare. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna unseres großen Baums wider.$B$BDaher ist es höchst beunruhigend zu sehen, dass die Bäumlinge so wütend geworden sind.$B$BIch glaube, es hat etwas mit dem Erdboden zu tun. Ich habe mich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Würdet Ihr bitte in der Gegend des Al'Amethsees ein paar Bäumlingssamenkörner sammeln und mir bringen?", t = "Bäumlingssamenkörner"},
    [919] = {ot = "Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen.", st = "Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.$B$BWenn Ihr auf Euren Wanderungen um den See Bäumlingssprossen seht, reißt sie bitte aus. Helft dabei, unser Land rein zu halten!", t = "Bäumlingssprossen"},
    [920] = {ot = "Sprecht in Shadowglen über den Dächern von Aldrassil mit Tenaron Stormgrip.", st = "Ihr seid $n, nicht wahr? Ich hörte, dass Tenaron nach Euch gefragt hat. Ihr findet ihn in dem am höchsten gelegenen Raum in Aldrassil.$b$bWir mögen zwar ein langes Leben haben, aber Ihr solltet ihn dennoch nicht allzu lang warten lassen.", t = "Tenarons Einladung"},
    [921] = {ot = "Füllt die Kristallphiole und bringt sie Tenaron Stormgrip über den Dächern von Aldrassil.", st = "Es ist an der Zeit herauszufinden, was Euer Schicksal ist, $n. Doch bevor Ihr bereit seid, in die Welt hinter unseren verzauberten Wäldern hinauszuziehen, gibt es noch vieles, das Ihr über unsere jüngste Vergangenheit lernen müsst.$b$bSeit der Schlacht am Berg Hyjal hat sich für unser Volk so viel verändert. Nordrassil ist nur noch ein Schatten ihres früheren Selbst, ihre Macht wurde benutzt, um Archimonde in die Knie zu zwingen und die Brennende Legion zurückzutreiben ...$b$bIhr müsst eine Aufgabe erledigen. Geht zum Mondbrunnen nördlich von Aldrassil und bringt mir eine Phiole mit Wasser daraus.", t = "Krone der Erde"},
    [922] = {ot = "Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn.", st = "$n, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Greenspyre bringen? Er ist Druide in Darnassus, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.$B$BDanke, $n. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.$B$BIhr findet Rellian normalerweise die Wege der Enklave des Cenarius in Darnassus entlangwandernd.", t = "Rellian Greenspyre"},
    [923] = {ot = "Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore.", st = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Wellspringsee im Norden von Teldrassil durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!$B$BVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.", t = "Tumore"},
    [924] = {ot = "Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück.", st = "Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.$B$BIch habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.$B$BNehmt einen Stein vom Tisch und bringt ihn zum Altar des Feuers oben auf dem Glutnebelgipfel. Reist nach Westen und bei der Weggabelung weiter nach Norden. Der Gipfel liegt zu Eurer Linken. Die sicherste Aufstiegsmöglichkeit zur Spitze bietet sich an der Nordseite.$B$BUnd beeilt Euch - die Energie des Steins nimmt mit der Zeit ab.", t = "Die Dämonensaat"},
    [926] = {t = "Fehlerhafter Kraftstein"},
    [927] = {ot = "Bringt Denalan am Al'Amethsee das moosumschlungene Herz.", st = "Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.$B$BVielleicht würde Denalan dieses Herz gern einmal sehen.", t = "Das moosumschlungene Herz"},
    [928] = {ot = "Bringt Corithras Moonrage in Dolanaar das teilweise gefüllte Gefäß.", st = "Ich könnte Euch zwar noch so viel mehr über die Mondbrunnen und Teldrassil erzählen, doch leider muss ich Euch fortschicken. Corithras Moonrage erwartet Euch. Ich habe das Wasser der Phiole, die Ihr mir brachtet, in dieses Gefäß geschüttet, damit Ihr es ihm bringen könnt.$b$bFragt nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil, die aus Shadowglen hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen.$b$bBleibt unbedingt immer auf der Straße, $n. Es gibt neuerdings ziemlich gefährliche Bestien in den Wäldern.", t = "Krone der Erde"},
    [929] = {ot = "Füllt die Jadephiole und bringt sie Corithras Moonrage in Dolanaar zurück.", st = "Lasst mich Euch zunächst ein bisschen mehr von der Aufgabe erzählen, die Euch erwartet. Die Druiden in Darnassus verbrauchen das Wasser der Mondbrunnen Teldrassils, und deshalb muss ihr Mondbrunnen von Zeit zu Zeit wieder aufgefüllt werden. Ihr könnt mit diesen speziell gefertigten Phiolen Wasser aus den Mondbrunnen schöpfen.$b$bNehmt dieses Gefäß zum Mondbrunnen außerhalb von Starbreeze im Osten mit und füllt es mit Wasser. Kehrt dann zu mir zurück. Wenn Ihr Eure Aufgabe erledigt habt, erzähle ich die Geschichte da weiter, wo Tenaron aufgehört hat ...", t = "Krone der Erde"},
    [930] = {ot = "Bringt Denalan am Al'Amethsee die leuchtende Frucht.", st = "Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.$B$BDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.", t = "Die leuchtende Frucht"},
    [931] = {ot = "Bringt Denalan am Al'Amethsee einen der schimmernden Wedel.", st = "Die Wedel der Pflanze schimmern im Dämmerlicht des Waldes und verleihen ihr eine wabernde, pulsierende Aura.$B$BIhr glaubt, dass Denalan bestimmt gern ein Exemplar davon hätte.", t = "Der schimmernde Wedel"},
    [932] = {ot = "Tötet Lord Melenas und bringt Tallonkai Swiftroot in Dolanaar seinen Kopf.", st = "Ich muss Euch warnen, $n, das hier muss absolut unter uns bleiben. Die Satyrn bereiten uns schon genug Ungelegenheiten, aber dieser eine hier scheint sich zu einer echten Bedrohung zu entwickeln.$B$BLord Melenas ist sein Name. Er lebt in der Nähe des Teufelsfelsens in einer Höhle, in der er ein großes Kontingent Grellkrieger um sich versammelt hat. Sein Herz ist so schwarz wie die Nacht und er führt etwas äußerst Übles im Schilde.$B$BIhr müsst ihn in der nahe gelegenen Höhle gleich nördlich von hier suchen und mir seinen Kopf bringen.", t = "Krankhafter Hass"},
    [933] = {ot = "Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar.", st = "Südöstlich des Ortseinganges von Darnassus, an den Ufern der Teiche von Arlithrien, gibt es noch einen Mondbrunnen. Die Schildwachen können aufgrund von Angriffen und der ständig schlimmer werdenden Hinterhältigkeit der Knarzklauenfurbolgs kaum durch dieses Gebiet patrouillieren.$b$bSeid auf der Hut, wenn Ihr Euch dem Brunnen nähert, und haltet Eure Waffen stets griffbereit.", t = "Krone der Erde"},
    [935] = {ot = "Bringt dem Erzdruiden Fandral Staghelm in Darnassus das gefüllte Gefäß.", st = "Ohne den Segen Alexstraszas der Lebensbinderin und Nozdormus des Zeitlosen gab es Makel in Teldrassils Wachstum. Man berichtet von seltsamen Wildtieren, die sich buchstäblich aus dem Nährboden des Baums erhoben haben, und von wahnsinnigen Furbolgs, die durchziehende Reisende angreifen.$b$bIch kann nur hoffen, dass der Erzdruide schnellstens eine Lösung für das Problem findet. Ich werde alles Wasser der Phiolen, die Ihr mir brachtet, in dieses Gefäß schütten, damit Ihr es nach Darnassus bringen könnt.$b$bBringt es Fandral Staghelm, Ihr findet ihn im Druidenhain.", t = "Krone der Erde"},
    [937] = {ot = "Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels.", st = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.$b$bBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.$b$bWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten deren Gürtel.", t = "Die verzauberte Lichtung"},
    [938] = {ot = "Begleitet Nebel zur Schildwache Arynia Cloudsbreak beim Mondbrunnen in der Nähe des Orakelbaums.", st = "Das Fell der Säblerkatze ist von einer auffälligen grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.$b$bSie hebt ihren Kopf und starrt Euch an, ihre glänzenden blauen Augen voll wacher Intelligenz. Sie scheint Euch folgen zu wollen.", t = "Nebel"},
    [940] = {ot = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus die gravierte Rinde.", st = "Der Wald flüstert von Euren wagemutigen Heldentaten, $n. Sobald die Harpyien aus ihren Nestern vertrieben waren, spürte ich, wie sich große Ruhe im Wald verbreitete, und dass sich die Kreaturen des Waldes wieder sicher fühlten. Ich habe nicht gewagt, noch einen Boten zum Erzdruiden zu schicken, aber ich weiß, dass Ihr dafür sorgen werdet, dass ihn meine Nachricht sicher erreicht.$b$bBringt ihm dies und wisset, dass der Wald Euch auf all seinen Wegen beschützen wird, sodass Ihr den Wald aus Stein sicher erreicht.", t = "Teldrassil"},
    [941] = {ot = "Pflanzt das besudelte Herz in Denalans Blumentopf ein.", st = "Ich habe das üble Moos von dem Herzen entfernt, aber es bleibt dennoch besudelt...$B$BVersucht, das Herz in meinem Blumentopf einzusetzen. Er ist mit einer nährstoffreichen Krume gefüllt, die das Herz säubern und heilen kann.", t = "Das Einpflanzen des Herzens"},
    [942] = {ot = "Bringt das rätselhafte Fossil zum Archäologen Flagongut im Hafen von Menethil.", st = "Dieses Fossil hat eine auffallende Ähnlichkeit mit einem anderen, das ich einst in Ironforge sah. Ein Archäologe namens Flagongut brachte es zur jährlichen Forscherliga-Konferenz mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte.$b$bDas Letzte, was ich von Flagongut hörte war, dass er sich in der Deepwater-Taverne im Hafen von Menethil verschanzt hatte und dort auf eine Eskorte zu Whelgars Ausgrabungsstätte wartete. Sucht ihn auf und zeigt ihm Remtravels Fossil. Vielleicht kann er die Geheimnisse der Vergangenheit lüften.$b$bDas Schiff nach Menethil liegt in Auberdine.", t = "Der geistesabwesende Ausgrabungsleiter"},
    [943] = {ot = "Der Archäologe Flagongut im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Flagonguts Fossil bringt.", st = "Ausgrabungsleiter Whelgar ist jetzt im Besitz des Originalfundstücks. Er hält sich in seiner Ausgrabungsstätte im Sumpfland auf. Als ich den Stein von Relu entdeckte, glaubte ich, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne.$b$bAuf dem Weg zu Whelgar wurde ich dann von Raptoren angegriffen und das Relikt ging verloren. Ich weiß nicht, welche dieser scheckigen Bestien das Relikt verschlungen hat, aber falls es Euch gelingen sollte, es zurückzuholen, könnte ich die Macht dieser Artefakte freisetzen.$B$BBringt mir den Stein von Relu und das Originalfossil.", t = "Der geistesabwesende Ausgrabungsleiter"},
    [944] = {ot = "Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen.", st = "Wie seltsam, dass sich Naga hier herumtreiben, hier in Dunkelküste. Aber was noch seltsamer ist... es sind auch welche vom Klan der Twilight-Hammer da. Dieser Kult verehrt die alten, alten Lords der Erde. Lords, die schon vor Unzeiten besiegt wurden.$B$BDie Meistergleve im Süden ist ein Ort, an dem ein solcher Lord einst gefallen ist.$B$BBegebt Euch dorthin und sucht nach weiteren Anhängern der Twilight-Hammer-Kultisten.$B$BNehmt diese Wahrsagephiole. Erschafft damit eine Wahrsageschale, nachdem Ihr die Meistergleve durchsucht habt. Sprecht dann mit mir mittels der Schale.", t = "Die Meistergleve"},
    [945] = {ot = "Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist.", st = "Hilfe!$B$BDiese dreckigen Kultisten haben mich umzingelt, während ich durch die Meistergleve spazierte. Was für ein Glück, dass ich so gut im Verstecken bin!$B$BKönnt Ihr mir hier raushelfen? Ich sollte auch meiner Schwester Therysil Bescheid geben, dass es mir gut geht. Sie wohnt in Ashenvale im Süden, beim Schrein von Aessina.", t = "Therylunes Flucht"},
    [947] = {ot = "Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe.", st = "Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen. Diese Höhle liegt hinter Cliffspring Falls im Osten, leicht nördlich entlang der Berge.$B$BIch würde ja selbst dorthin gehen, aber der Hain der Uralten hat mir geraten, mich von diesem Ort fern zu halten. Unsere altehrwürdigen Verbündeten spüren, dass die Höhle ein Versteck für etwas Neues, Böses in Dunkelküste ist.$B$BBitte, $n, sammelt doch ein paar Pilze für mich, und wenn Ihr schon dabei seid, könntet Ihr auch gleich die Höhle erkunden, um die Befürchtungen der Urtume eventuell zu bestätigen.", t = "Höhlenpilze"},
    [948] = {ot = "Sprecht im Hain der Uralten mit Onu.", st = "Onu, ein Urtum der Lehren im Hain der Uralten, hat von Eurer Reise nach Cliffwaterfalls erfahren und möchte Euch sprechen. Der Hain liegt im Süden, im Schatten der Berge.$B$BDie Urtume sind geduldig und weise, $n. Aber wenn Onu Euch um Rat bezüglich dessen ersucht, was Ihr in den Falls gesehen habt, fürchte ich, dass es wichtig ist.", t = "Onu"},
    [949] = {ot = "Sucht im Lager des Klans der Twilight-Hammer in der Meistergleve nach einem Hinweis.", st = "Niemand weiß, was der Klan der Twilight-Hammer in der Meistergleve vorhat. Aber es muss etwas Böses sein.$B$BDurchsucht ihr Lager bei der Meistergleve... Sucht nach etwas, das uns ihre Absichten verraten könnte.$B$BWir müssen unbedingt wissen, was sie im Schilde führen, bevor wir einen Plan schmieden können.", t = "Das Twilight-Lager"},
    [950] = {ot = "Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt.", st = "Der Blick in den Twilight-Folianten kann einen wahnsinnig machen. Der Text verschwimmt und tanzt vor Euren Augen, kaum dass Ihr ihn einen Moment betrachtet habt, und die einst so wunderschönen Illustrationen verzerren sich zu grotesken Formen und Mustern.$B$BIhr könnt gerade noch eine Seite des irrsinnigen Gekritzels herausreißen, bevor Ihr ohnmächtig werdet.", t = "Rückkehr zu Onu"},
    [951] = {ot = "Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten.", st = "Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text... geschrieben von Elfen! Es ist übelst verflucht und besudelt von der Verderbnis des Klans der Twilight-Hammer, aber es scheint, als würde der Kult alte Elfenmagie benutzen, um seine alten Lords in unsere Welt zurückzuholen.$B$BReist zu den Ruinen von Mathystra im Nordosten und sucht nach alten Relikten unter dem Gras und den zerbrochenen Steinen. Indem wir sie studieren, können wir vielleicht herausbekommen, auf welche Weise der Klan der Twilight-Hammer die Magie der Elfen nutzen will.", t = "Mathystra-Relikte"},
    [952] = {ot = "Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine.", st = "Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.$b$bIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.", t = "Der Hain der Uralten"},
    [953] = {ot = "Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück.", st = "Im Osten findet Ihr die Ruinen von Ameth'Aran. Sie werden heute von den ruhelosen Geistern der Hochgeborenen bewohnt, die einst dort lebten. Damals jedoch war es ein Ort, an dem die Diener Azsharas ihre mächtige Magie ungestört praktizieren konnten.$b$bMan hat mich geschickt, die Ruinen zu erkunden und ich stieß auf zwei große Schrifttafeln, auf denen die Geschichten Ameth'Arans und seines Unterganges beschrieben werden. Während ich die Runen las, traten Geister an mich heran und ich floh.$b$bBitte, wenn es Euch möglich ist, begebt Euch zu den Ruinen und entziffert an meiner Statt die Schrifttafeln.", t = "Der Untergang von Ameth'Aran"},
    [954] = {ot = "Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura.", st = "Die Ruinen von Bashal'Aran im Osten sind von dämonischen Dienern überrannt worden. Die Grimmlinge und Satyrn haben sich in dem Gebiet niedergelassen und nähren sich von den magischen Energien dort. Ihre Macht wächst, je länger sie sich dort aufhalten.$b$bDennoch habe ich festgestellt, dass es dort einen Schrein gibt, dem sie nicht zu nahe kommen wollen. An der Westseite der Ruinen auf einem kleinen Steilhang entspringt eine seltsame blaue Aura ... Das muss eine Erklärung für das Widerstreben der Dämonen sein.$b$bIch hätte gern, dass Ihr das untersucht.", t = "Bashal'Aran"},
    [955] = {ot = "Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe.", st = "Sollte ich jemals gehalten sein, die Geschichte meines Lebens zu erzählen, würde dies zweifellos die Grenzen Eurer Geduld überstrapazieren. Sagen wir einfach, dass mein Leben lang und schmerzvoll war, und dass diese meine spektrale Gestalt die schlimmste Pein von allem ist.$b$bIch werde durch Magie hier festgehalten. Mögen meine Worte auch unaufrichtig erscheinen, so versichere ich Euch doch, dass ich über die Maßen dankbar wäre, würdet Ihr mir helfen, den Grund für meine Gefangenschaft herauszufinden. Ein Siegel bindet mich, und vielleicht finde ich einen Hinweis darauf, wenn ich den Ohrschmuck der Grimmlinge und Grells nur näher betrachten könnte.", t = "Bashal'Aran"},
    [956] = {ot = "Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran.", st = "Wenn die Grells erst kürzlich mit dem Siegel in Berührung gekommen sind, das mich an dieses ewige Gefängnis bindet, glaube ich, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des Satyrs gelangt, der sie anführt.$b$bIch bin mir ganz sicher, dass es so ist, $n. Einer der Satyrn muss es besitzen. Wenn Ihr es an Euch bringen könntet, würde es mich der Überwindung der Gitterstäbe meines Gefängnisses so nahe bringen, dass es mich zu Tränen rühren würde.", t = "Bashal'Aran"},
    [957] = {ot = "Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück.", st = "Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe. In dieser Flamme könnte man dieses Siegel zerstören.$b$bAchtet auf die Ruinen, $N!", t = "Bashal'Aran"},
    [958] = {ot = "Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine.", st = "$C. Ich möchte Euch um etwas bitten.$b$bHabt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich. Einst waren sie die Heimat vieler mächtiger Hochgeborener, doch heute sind sie Zeugnis der Zerstörung, die sie mit ihrem Dilettantismus angerichtet haben.$b$bDie Schildwachen sagten mir, dass die Geister der Hochgeborenen immer noch umgehen und dass sie ihre alten, magischen Utensilien immer noch benutzen. Wir müssen uns diese Relikte aneignen, damit wir sie zerstören können.", t = "Werkzeuge der Hochgeborenen"},
    [959] = {ot = "Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", st = "Upps!$b$bWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Booty Bay war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.$b$bBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.$b$bVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?", t = "Ärger auf den Docks"},
    [962] = {ot = "Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", st = "Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, $n. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.$b$bIch studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.$b$bLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.", t = "Schlangenflaum"},
    [963] = {ot = "Befreit den Geist von Anaya Dawnrunner und bringt ihren Anhänger zu Cerellean Whiteclaw in Auberdine.", st = "Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.$b$bIch hätte nie gedacht, dass mich noch heute, Tausende von Jahren später, die Erinnerungen an Anaya um den Schlaf bringen würden. Ich wanderte wie in Trance durch die Wälder von Dunkelküste und fand mich schließlich in den Ruinen von Ameth'Aran wieder... wo ich den gequälten Geist meiner Geliebten sah.$b$bSie muss befreit werden, aber ich kann es nicht über mich bringen, dies zu tun. Ihr Geist muss zerstört werden.", t = "In ewiger Liebe"},
    [965] = {ot = "Sucht Balthule Shadowstrike in der Nähe des Turms von Althalaxx in Dunkelküste.", st = "Grüße, $R. Ich bin Elissa Starbreeze und es ist meine Aufgabe, Auberdine vor Schaden zu schützen.$b$bAus diesem Grund habe ich Balthule Shadowstrike ausgeschickt, um die seltsamen Vorkommnisse rund um den Turm von Althalaxx im Nordosten zu beobachten.$b$bEr hätte eigentlich schon längst wieder zurück sein sollen. Daher fürchte ich, dass er im Wald auf eine unvorhersehbare Gefahr gestoßen ist. Ich würde es außerordentlich zu schätzen wissen, wenn Ihr nach ihm suchen und dafür sorgen würdet, dass es ihm gut geht.", t = "Der Turm von Althalaxx"},
    [966] = {ot = "Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx.", st = "Eine Gruppe Hexenmeister hat sich in und um den Turm herum niedergelassen. Ich wollte ja schon früher nach Auberdine zurückkehren, um Elissa Bericht zu erstatten, aber ich befürchtete, hier etwas zu verpassen, solange ich fort wäre.$b$bDelgren vermutete, dass sich eine solche Gesellschaft beim Turm versammeln würde, aber er wusste nicht, warum.$b$bEin paar Pergamentfetzen, die die Hexenmeister bei sich führten, sind mir in die Hände gefallen, aber ich brauche noch mehr, um das Rätsel zu lösen. Ich warne Euch jedoch, geht lieber nicht in den Turm hinein, denn die Hexenmeister dort sind noch viel mächtiger!", t = "Der Turm von Althalaxx"},
    [967] = {ot = "Überbringt Delgren dem Läuterer in Ashenvale Balthules Brief.", st = "Mein Meister, Delgren der Läuterer, ist ein Paladin, der gütigerweise seine Unterstützung bei der Verteidigung unseres Waldes vor den Streitkräften der Dämonen und Untoten angeboten hat. Er hat mich viel über das Heilige Licht und die Kampfkunst gelehrt.$b$bDelgren muss sofort über die Machenschaften des Kults informiert werden.$b$bIhr findet ihn ganz weit südlich von hier in Maestras Posten in Ashenvale. Beeilt Euch, ich fürchte nämlich, dass die Bedrohung durch den dunklen Strangs stündlich größer wird.", t = "Der Turm von Althalaxx"},
    [968] = {ot = "Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Bonegrip im düsteren Viertel in Ironforge.", st = "Obwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar:$B$B'Die Macht in der Tiefe'$B$BIn diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen ... bei denen sehr oft lebende, humanoide Kreaturen verwendet werden.$B$BAuf der Innenseite des Einbands stehen die Worte: 'Bonegrips Runen und Verhängnisse, Düsteres Viertel, Ironforge. Inhaber: Gerrig Bonegrip.'$B$BWenn Bonegrip derartige Bücher verkauft, nimmt er dieses hier vielleicht zurück.", t = "Die Macht in der Tiefe"},
    [970] = {ot = "Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten.", st = "Balthules Brief verkündet Unheil. Dieser Kult des dunklen Strangs ist mir ein Dorn im Auge, der entfernt werden muss. Ich hatte nordöstlich von hier in Ordil'Aran schon einmal mit dem Abschaum des dunklen Strangs zu tun. Eines seiner Mitglieder besitzt einen Seelenedelstein, der, wie ich glaube, das Geheimnis der Macht des Kults enthält.$b$bBringt ihn mir, dann kann ich die darin zu findenden Geheimnisse entschlüsseln.", t = "Der Turm von Althalaxx"},
    [971] = {ot = "Bringt das 'Lorgalis-Manuskript' zu Gerrig Bonegrip in Ironforge.", st = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.$B$BEs kursieren Gerüchte um einen alten Teil einer Lehre, das 'Lorgalis-Manuskript', das sich tief unten in den Blackfathom-Tiefen in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.$B$BSucht in den Blackfathom-Tiefen nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht ... nach dem Ende aller Tage.", t = "Wissen in der Tiefe"},
    [973] = {ot = "Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magthrulls Folianten.", st = "Ilkrud Magthrull. Ja, ich kenne ihn. Er ist ein mächtiger Orc-Hexenmeister, der im Fire Scar-Schrein lebt, einem äußerst bösen Ort im südwestlichen Ashenvale.$b$bBislang ist er nur ein geringes Ärgernis und ich hatte noch nichts mit ihm zu tun, aber es sieht so aus, als wäre jetzt seine Zeit gekommen.", t = "Der Turm von Althalaxx"},
    [982] = {ot = "Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes.", st = "Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe, die SILBERMORGEN und die NEBELSCHLEIER. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Satanskreaturen.$B$BBeide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten. Ich möchte Euch bitten, sie für uns zu beschaffen; es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.", t = "Tiefer Ozean, weites Meer"},
    [983] = {ot = "Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein.", st = "He! Helft mir bei meiner neuesten Erfindung, der Dröhnkiste. Man kann damit mit Leuten sprechen, die weit weg sind!$B$BVielleicht habt Ihr sie schon mal gesehen, das sind kleine Kästchen mit Hebeln daran. Ihr einziges Problem ist, dass sie ständig gewartet werden müssen.$B$BJede hat ein anderes Problem, aber ich hab mir etwas ziemlich Schlaues ausgedacht. Ich habe alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren. Momentan hat Dröhnkiste 827 den Geist aufgegeben. Sie steht südlich von Auberdine, also gleich in der Nähe. Es werden sechs Kriecherbeine benötigt, um sie zu reparieren. Ich bezahl Euch auch dafür ...", t = "Dröhnkiste 827"},
    [984] = {ot = "Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück.", st = "Einige meiner Brüder konnten in Teldrassil vor einem verderbten Furbolg gerettet werden und ich habe geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr von uns verletzt werden... oder schlimmer.$B$BIch habe auch in Dunkelküste schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Ich denke, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde. Würdet Ihr wohl eines ihrer Lager aufsuchen und zu mir zurückkehren, falls Ihr dort irgendwelche Anzeichen von Verderbnis entdeckt?", t = "Wie groß ist die Bedrohung?"},
    [985] = {ot = "Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück.", st = "Ihr habt Euer Talent im Ausspähen unserer Feinde bereits unter Beweis gestellt, $n. Aber habt Ihr auch das Zeug dazu, sie zu bekämpfen?$B$BNicht alle Abenteurer ziehen ein offenes Gefecht der Kunst der Verstohlenheit und des Ausweichens vor.$B$BWenn Ihr glaubt, der Aufgabe gewachsen zu sein, solltet Ihr Euch das Furbolglager südlich von Auberdine vornehmen. Das stellt momentan die größte Bedrohung für unser Volk dar. Ihr werdet dort ein paar Mitglieder des Schwarzfellstamms finden. Tötet 8 Pfadfinder und 5 Windsprecher und kommt dann zu mir zurück.", t = "Wie groß ist die Bedrohung?"},
    [986] = {ot = "Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine.", st = "$n, Eure Fertigkeiten haben mir bei meinen Bemühungen sehr geholfen. Kann ich es wagen, Euch dennoch erneut zu bitten, Grimmklaue und seinem Meister Volcor zu helfen? Ich könnte Euch dazu einen magischen Umhang anfertigen, mit dem Ihr ungehindert an den Kreaturen Dunkelküstes vorbeigelangt, während Ihr nach ihm sucht.$B$BUm den Umhang anzufertigen, benötige ich fünf Mondpirscherpelze von einer Mondpirschermatriarchin oder einem Mondpirscherpatriarchen, um genügend Material zur Verfügung zu haben. Die Katzen findet Ihr südlich von hier, in der Nähe des Flusses Wildbend, oder noch weiter im Süden, in der Nähe von Ashenvale.", t = "Ein verirrter Meister"},
    [990] = {ot = "Sucht Raene Wolfrunner in Ashenvale auf.", st = "$n, meine Herrin Raene Wolfrunner erwartet Euch in Astranaar in Ashenvale. Mit Eurer Hilfe könnten wir vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breit gemacht hat.$B$BGeht von hier aus nach Süden und haltet Euch dicht an der Straße. Wenn Ihr Euch an diese Richtungsangaben haltet, erreicht Ihr problemlos Euer Ziel.", t = "Marsch nach Ashenvale"},
    [991] = {ot = "Sucht in Ashenvale nach Teronis.", st = "$n, ein alter Freund von mir unterstützt hier in Ashenvale ebenfalls die Schildwachen, aber er ist noch nicht zurückgekehrt.$B$BEr ging einer Spur nach, die zu einem Gegenstand führte, der seiner Meinung nach die Angriffe der Furbolgs auf unser Volk verlangsamen könnte - eine Rute, die von einem mittlerweile verstorbenen, bösen Hexer geschaffen wurde.$B$BVor seiner Abreise erwähnte er, dass er nach einem Edelstein für die Rute suchen wolle.$B$BEr meinte, dass dieser Edelstein möglicherweise in dem Schrein im Falathimsee am Fuße der Berge im Westen versteckt sei. Dort wurde der Edelstein jedenfalls aufbewahrt, bevor der Schrein überrannt worden ist.$B$BBitte, $n, findet meinen Freund.", t = "Raenes Säuberung"},
    [993] = {ot = "Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang.", st = "Der Umhang ist fertig, $n. Jetzt ist es an der Zeit, Volcor zu suchen. Ich hoffe nur, dass wir es noch rechtzeitig schaffen.$B$BDie Magie des Umhangs hält nicht lang an, nachdem sie herbeigerufen wurde - etwa fünf Minuten. Es liegt an Euch zu entscheiden, wann Ihr sie benutzt: Ich schlage vor, dass Ihr damit wartet, bis Ihr Grimmklaue gefunden habt.$B$BFalls es wahr ist, was er mir erzählte, findet Ihr seinen Meister in einer Höhle südlich von hier. Grimmklaue wird an der Straße auf Euch warten. Gebt ihm ein Signal, indem Ihr winkt, sobald Ihr ihn gesehen habt, dann wird er Euch den Weg zu seinem Meister weisen.", t = "Ein verirrter Meister"},
    [995] = {ot = "Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis.", st = "Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid.$B$BVergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist. Ich werde mich auf eigene Faust dort hinbegeben, da ich wahrscheinlich schneller bin als Ihr.", t = "Flucht durch Verstohlenheit"},
    [997] = {ot = "Bringt Denalan am Al'Amethsee das Gebinde rarer Erde.", st = "Seid Ihr nach Süden unterwegs? Zum Al'Amethsee? Wenn dem so ist, möchte ich Euch um einen Gefallen bitten...$B$BMein Kollege Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt Teldrassils studiert und Experimente betreibt. Er hat in Darnassus ein Gebinde rarer Erde bestellt, und die Lieferung kam erst kürzlich mit Verspätung hier in Dolanaar an.$B$BWürdet Ihr ihm dieses Gebinde wohl bringen?", t = "Denalans Erde"},
    [1001] = {ot = "Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411.", st = "Aus dem Inneren der Maschine ist eine leise Stimme zu hören.$B$B\"Hier spricht Wizbang! Die nächste Dröhnkiste befindet sich nördlich von Auberdine, am Strand.$B$BAlso, es ist die Dröhnkiste mit der Nummer 411 und es werden 3 Drescheraugen benötigt, um sie zu reparieren. Sie befinden sich direkt vor der Küste! Die Dunkelküstendrescher... *Hick*... Tut mir Leid...$B$BÜbrigens, wie beim letzten Mal wird die Dröhnkiste Eure Belohnung ausspucken, sobald Ihr die Sachen in die Maschine eingebaut habt. *Hick*... Was? Nein, mir geht's gut!\"", t = "Dröhnkiste 411"},
    [1002] = {ot = "Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein.", st = "Die Dröhnkiste gibt statische Geräusche von sich, als Wizbang zu sprechen beginnt.$B$B\"Die nächste Dröhnkiste ist Nummer 323. Schteht nördlich von Auberdine, aber... wo's das Bier? Wa...? Oh, schteht direkt an der Straße, kann man gar nicht verfehlen, gleich neben der Brücke.\"$B$BWizbang murmelt wirres Zeug vor sich hin, bevor Ihr ein lautes Schluckgeräusch hört.$B$B\"Der da fehlen Mondpirscherfangzähne... sechs davon.\"", t = "Dröhnkiste 323"},
    [1003] = {ot = "Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525.", st = "Wizbangs zitternde Stimme übertönt die Blubber- und Tropfgeräusche, die aus dem Inneren der Maschine dringen.$B$B\"Näxte is' die Straße weiter runter nach Süden. Is' leicht zu find'n... direkt am Straßenrand... neben ei'm Sssaun. Glaub, ich hab sie hinner'n paar Büscheln verschteckt... Büschen. Hehehe... Jaaa, Dröhnkiste 525 fehlen ergraute Skalps von dies'n grauhaarigen Dischtelbären. Mann, das schpricht sich blöd. Dissstelbär... Hehehe...\"$B$BIhr hört weitere Schluckgeräusche, dann schaltet sich die Maschine aus. Plötzlich erwacht sie jedoch wieder zum Leben.$B$B\"4!\"", t = "Dröhnkiste 525"},
    [1007] = {ot = "Bringt Talen im Lager in der Nähe des Zoramstrands die antike Statuette.", st = "Ich würde Euch gern eine Aufgabe übertragen, $n.$B$BIch war auf meinem kleinen Schiff und kreuzte über den versunkenen Ruinen von Zoram, als ich plötzlich von Naga angegriffen wurde, die aus dem Wasser stießen und mich mit ihren Klauen beharkten! Ich floh und nahm alle Vorräte mit, die ich tragen konnte, um dieses bescheidene Lager zu errichten.$B$BAls ich jedoch die Küste erreichte und weglief ... verlor ich meinen liebsten Besitz.$B$BBitte, $n, geht zu dem Ort vor der Küste im Norden, an dem ich in den Hinterhalt geriet, und sucht dort nach einer antiken Statuette. Sie ist der Grund, warum ich die Gefahren des Zoramstrands auf mich genommen habe.", t = "Die antike Statuette"},
    [1008] = {ot = "Bringt Shindrell Swiftfire in Astranaar 20 Köpfe von Rächerflossen.", st = "Böses lauert an unserer nordwestlichen Küste, die als Zoramstrand bekannt ist.$B$BEs ist die Ruhestätte der untergegangenen Stadt Zoram, die während der großen Teilung zerstört wurde und im Meer versank. Die Nachtelfen verloren sie vor Unzeiten. Sie war verloren und fast vergessen.$B$BJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Es ist auch unwichtig. Wir müssen diese Scheusale vernichten und zurück in die Tiefe treiben!$B$BKehrt zu mir zurück, wenn Ihr Eure Mission abgeschlossen habt.", t = "Der Zoramstrand"},
    [1009] = {ot = "Bringt Talen im Lager in der Nähe des Zoramstrands den Ring von Zoram.", st = "Ich fürchte, die Geheimnisse der antiken Statuette werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihrem antiken Schloss findet.$B$BDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der großen Teilung unterging.$B$BÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor kurzem gefunden.$B$BRuuzel, ihr Anführer, haust auf einer Insel am Nordrand von Zoram. Bitte, $n, holt mir meinen Ring!", t = "Ruuzel"},
    [1010] = {ot = "Bringt Orendil Broadleaf in Ashenvale 5 Bathranshaar-Pflanzen.", st = "Es gibt eine Pflanze, die früher einmal in den alten Ruinen von Bathrans Schlupfwinkel im Norden wuchs. Die Pflanze namens Bathranshaar war als Heilmittel für Krankheiten des Geistes bekannt.$B$BEin Kind im Dorf ist krank geworden und ich glaube, dass es sich nicht nur um eine körperliche Krankheit handelt. Würdet Ihr wohl zu Bathrans Schlupfwinkel reisen und dort für mich nach Bathranshaar suchen? Ich könnte es brauchen, wenn ich das Kind richtig behandeln soll.$B$BBathrans Schlupfwinkel liegt nördlich von Maestras Posten und gleich südlich der Grenze zu Dunkelküste.", t = "Bathranshaar"},
    [1011] = {ot = "Bringt Kayneth Stillwind in Forest Song eine Krankheitsflasche.", st = "Die Verlassenen, der untote Arm der Horde, haben sich in Ashenvale eingeschlichen und treiben sich in unseren Ruinen und Grabhügeln herum. Wir glauben, dass sie die Krankheit im Land der Nachtelfen verbreiten wollen. Wir müssen das genau wissen!$B$BDie Verlassenen haben südlich von hier, in der Nähe des Dor'danil-Grabhügels, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Kämpft Euch in das Lager hinein und stehlt eine Krankheitsflasche. Bringt mir eine solche Flasche. Ich werde sie testen und herausfinden, was sie bewirkt.", t = "Verlassenenkrankheit"},
    [1013] = {ot = "Bringt dem Bewahrer Bel'dugur im Apothekarium in Undercity das Buch von Ur.", st = "$n, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.$B$BBetretet die Burg Shadowfang und sucht das Buch. Bringt es mir, dann kann ich unserer dunklen Fürstin von Euren Diensten berichten...", t = "Das Buch von Ur"},
    [1014] = {ot = "Tötet Arugal und bringt Dalar Dawnweaver in dem Grabmal seinen Kopf.", st = "Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.$b$bIch werde mich darum kümmern, seine Magie zu neutralisieren, $n. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.$b$bReist zur Burg Shadowfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!", t = "Arugal muss sterben"},
    [1016] = {ot = "Sammelt 5 intakte Elementararmschienen und wendet die Rolle der Bestimmung darauf an. Bringt danach der Schildwache Velene Starstrike in der Silberwindzuflucht die Rolle der Bestimmung.", st = "Nehmt diese Rolle der Bestimmung; sie kann den Schöpfer dieser Elementare bestimmen. Aber Ihr werdet etwas von ihnen benötigen, um es als Reagenz zum Fokussieren der Magie dieser Rolle zu verwenden; ihre Armschienen sollten hervorragend dafür geeignet sein.$B$BEin paar wenige intakte Armschienen dieser Kreaturen dürften reichen. Die anderen Armschienen werden für unsere Zwecke nutzlos sein, aber sie könnten einem Händler etwas wert sein, wenn Ihr sie verkaufen wollt. Nachdem Ihr die intakten Armschienen habt, versucht die Rolle zu verwenden. Kehrt mit den Ergebnissen zu mir zurück und dann werden wir weitersehen.", t = "Elementararmschienen"},
    [1017] = {ot = "Erschlagt Sarilus Foulborne und bringt Schildwache Velene Starstrike in der Silberwindzuflucht seinen Kopf.", st = "Es gibt nur einen untoten Magier im Brachland, der in der Lage wäre, so viele Wasserelementare zu entweihen. Er ist auch der Einzige, der dumm genug wäre, es zu versuchen. Sarilus Foulborne sitzt wahrscheinlich jetzt gerade oben auf dem Glutnebelgipfel und lacht mich aus.$B$B$N, Ihr müsst Euch in Feindesland begeben und diesen Übeltäter vernichten. Ich habe genug von seinem Schwachsinn und wir müssen ihm zeigen, was mit jenen geschieht, die die Schildwachen verärgern.$B$BVernichtet ihn und bringt mir seinen Kopf. Vorsicht allerdings, die Horde könnte nach Euch Ausschau halten.", t = "Magier-Beschwörer"},
    [1020] = {ot = "Bringt Pelturas Whitemoon in Astranaar Orendils Heilmittel.", st = "$n, ich habe ein Heilmittel entwickelt, mit dem man dem erkrankten Kind bestimmt helfen kann. Bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Whitemoon.$B$BUm nach Astranaar zu gelangen, folgt der Straße gen Süden und dann gen Osten.", t = "Orendils Heilmittel"},
    [1021] = {ot = "Sucht in Xavian nach Anilia.", st = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!$B$B$N, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordosten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", t = "Elende Satyrn! Die Dryaden sind in Gefahr!"},
    [1022] = {ot = "Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostshadow beim Schrein von Aessina zurück.", st = "Obwohl wir viele Mittel und große Bemühungen investiert haben, um auch die letzten Dämonen aus dem Teufelswald im Norden zu vertreiben, hatten wir nur wenig Erfolg damit. Wir konnten jedoch einen Großteil der Dämonen von Ashenvale fern halten.$b$bIm Norden, nahe der Grenze zum Teufelswald, wurde der verfallene Mel'Thandris-Schrein von rätselhaften Wolfmenschen übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als \"Das heulende Tal\" bekannten Gebiet seinen Namen gegeben. Der Foliant von Mel'Thandris, der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die Wolfmenschen hier sind.", t = "Das heulende Tal"},
    [1023] = {ot = "Sucht den leuchtenden Edelstein und bringt ihn zusammen mit Teronis' Tagebuch zu Raene Wolfrunner in Astranaar.", st = "Während Ihr Teronis Habseligkeiten durchstöbert, stoßt Ihr auf ein Tagebuch, das noch in gutem Zustand ist.$B$BIhr nehmt das Tagebuch und lasst Teronis' Kadaver so wie er ist zurück.$B$BJetzt müsst Ihr nur noch eines tun: den Edelstein finden, den Teronis suchte. Raene deutete an, dass er sich in diesem Gebiet befinden würde. Vielleicht haben ihn die Murlocs ...", t = "Raenes Säuberung"},
    [1024] = {ot = "Sucht Shael'dryn beim Mondbrunnen im Nordosten auf.", st = "Ihr werdet selbst Nachforschungen anstellen müssen, aber gemäß Teronis' Notizen scheint es unsere nächste Aufgabe zu sein, die anderen Teile der Rute zu finden, die Dartol erschuf. Ich würde mich zunächst zum Mondbrunnen östlich des Irissees begeben. Wenn Ihr bereit seid, folgt der Straße und wendet Euch gen Norden, wenn Ihr einen kleinen Sitzbereich zu Eurer Linken erreicht.$B$BDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.$B$BBehaltet den Edelstein - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", t = "Raenes Säuberung"},
    [1025] = {ot = "Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfrunner in Astranaar zurück.", st = "Bevor Ihr zum Mondbrunnen aufbrecht, habe ich noch eine andere Aufgabe für Euch, wenn Ihr gern Eure Fertigkeiten auf die Probe stellen und dem Volk von Ashenvale helfen würdet.$B$BEntlang der Straße, die nach Osten führt, haben Furbolgs kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger.$B$BHelft den Schildwachen, das Land zu schützen, indem Ihr diesen Monstern dieselbe Gnade zeigt, die sie uns erwiesen haben.$B$BIch glaube, ihre Lager liegen südlich der Straße ... seid vorsichtig.", t = "Eine aggressive Verteidigung"},
    [1026] = {ot = "Sucht den hölzernen Schlüssel und das Teil von Dartols Rute, bevor Ihr zu Shael'dryn beim Mondbrunnen zurückkehrt.", st = "Ich wünschte, Ihr hättet bessere Nachrichten.$B$BRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.$B$BFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in dem es sich befindet.$B$BEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald... die Truhe ist dort irgendwo versteckt.", t = "Raenes Säuberung"},
    [1027] = {ot = "Sucht das letzte Teil von Dartols Rute und bringt es Shael'dryn beim Mondbrunnen.", st = "Das letzte Teil der Rute wurde in die Obhut der Druiden von Dor'danil gegeben. Ich habe keine Ahnung, wo sie es versteckt haben. Es tut mir Leid, dass ich Euch da nicht weiterhelfen kann.$B$BIch kann Euch nur sagen, folgt der Straße, die zum Brachland führt. Die Druiden suchten östlich dieser Straße Zuflucht, aber sie werden Euch nicht viel helfen können: Sie wurden kürzlich getötet ... Ich mag gar nicht darüber nachdenken.$B$BWenn Ihr das letzte Teil gefunden habt, bringt es mir, dann helfe ich Euch, die Rute wieder zusammenzusetzen.", t = "Raenes Säuberung"},
    [1028] = {ot = "Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut.", st = "Hier habt Ihr die vollständige Rute, $n. Es war nicht schwer, sie wieder zusammenzusetzen... Den Schrein zu finden, der die Kraft hat, sie wieder aufzuladen, ist der schwierige Teil.$B$BMit etwas Konzentration und Einsatz sollte es für jemanden wie Euch, der bereits so viel erreicht hat, allerdings nicht zu schwer sein.$B$BGeht von hier aus nach Südosten - es gibt nur wenige Wege, also seid vorsichtig - und behaltet immer den Norden im Auge. Der Schrein liegt in den Bergen verborgen, die dieses Tal umgeben.$B$BDort angekommen legt Ihr die Rute in den Schrein... der Rest ist Magie. Hehe.", t = "Raenes Säuberung"},
    [1029] = {ot = "Kehrt zu Raene Wolfrunner in Astranaar zurück.", st = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertig gestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.$B$BViel Glück, $n.", t = "Raenes Säuberung"},
    [1030] = {ot = "Sucht einen nicht verderbten Furbolg und benutzt die Macht von Dartols Rute der Transformation, um mit ihm zu sprechen.", st = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.$B$BWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen. Welche Gestalt weiß ich allerdings nicht.$B$BVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der gegen die Auswirkungen des Teufelsmooses gefeit ist.$B$BIhr solltet Eure Suche südöstlich des Mystralsees beginnen.", t = "Raenes Säuberung"},
    [1031] = {ot = "Tötet Geltharis und bringt Illiyana beim Schrein von Aessina den Zweig des Cenarius.", st = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", t = "Der Zweig des Cenarius"},
    [1032] = {ot = "Bringt Illiyana im Schrein von Aessina 16 Satyrhörner.", st = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.$B$BEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", t = "Satyrn schlachten!"},
    [1033] = {ot = "Bringt Pelturas in Astranaar die Träne von Elune.", st = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.$B$BTräne von Elune ist eine Gesteinsart, die nur an einem Ort vorkommt: auf der Insel im Irissee, östlich von Astranaar. Orendil sagte, der Stein könne Verderbnis wegwaschen ... Bitte, $n, bringt mir eine Träne von Elune und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", t = "Elunes Träne"},
    [1034] = {ot = "Bringt Pelturas in Astranaar 5 Hand voll Sternenstaub.", st = "Die Träne von Elune hat einen Teil der Erkrankung meiner Tochter weggewaschen. Ihre Alpträume haben nachgelassen und ich danke der Göttin für ihren Segen. Aber... immer noch wütet das Fieber in ihr.$B$BOrendil erzählte mir von einem gefrorenen Staub, den man in den Sternenstaubruinen findet. Vielleicht kann man damit Relaras Fieber senken. Sammelt etwas von diesem Staub und kommt dann bitte wieder zu mir zurück.$B$BDie Sternenstaubruinen liegen im Süden, $n. Möge Elune Eure Reise beschleunigen.", t = "Die Sternenstaubruinen"},
    [1035] = {ot = "Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar.", st = "Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.$B$BWir haben Mondsteine früher immer beim Fallenskysee im Südosten gesammelt... bis die Schattendickichtbäumlinge kamen.$B$BIhr Anführer, das Schattendickichtorakel, hat alle gefallenen Mondsteine eingesammelt und hortet sie. Jetzt müsst Ihr Euch einen Mondstein von dem Orakel holen.$B$BUnd dazu werdet Ihr ihn wohl erschlagen müssen, fürchte ich.", t = "Fallenskysee"},
    [1037] = {ot = "Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Bladeweaver.", st = "Velinde Starsong war hier in Ashenvale meine Vorgängerin. Zunächst schien es, als hätte sie die Lage im Teufelswald unter Kontrolle, aber nach und nach ließen ihre Bemühungen nach. Eines Tages verschwand sie einfach.$b$bMan schickte mich hierher, um ihre Arbeit fortzusetzen. Ich fürchte jedoch, dass ich nichts über die Priesterin weiß. Vielleicht weiß Thyn'tel Bladeweaver, eine der Kommandantinnen der Schildwache, mehr über ihr Verschwinden, das ich nicht miterlebt habe.$b$bSie wird sicherlich wissen, wie wichtig diese Informationen sind.", t = "Velinde Starsong"},
    [1038] = {ot = "Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Bladeweaver.", st = "Der Foliant von Mel'Thandris hat Euch das gezeigt? Dann könnte es wohl nicht schaden, wenn ich Euch erlaubte, ihre Habseligkeiten durchzusehen. Mit diesem Schlüssel könnt Ihr die Truhe öffnen, in der wir ihre Sachen in der Schildwachenbaracke aufbewahren. Sie führte ein Tagebuch über ihre Pflichten und wenn es etwas zu erfahren gibt, dann daraus.$b$bIch sollte Euch noch sagen, dass die Schildwachen denken, dass sie Gründe für ihr Verschwinden hatte und damit rechnen, dass sie jederzeit wieder auftaucht. Die Priesterin hat in der Vergangenheit viel geleistet und unser Vertrauen verdient.", t = "Velindes Besitztümer"},
    [1039] = {ot = "Sprecht in Ratchet mit Werftmeister Dizzywig.", st = "Ratchet ist der einzige Hafen des Brachlandes. Höchstwahrscheinlich hat Velinde in Ratchet ein Handelsschiff gefunden, das sie zur Schwarzmeerbucht in Azeroth brachte. Wir haben nur wenig mit den Goblins zu tun, die den Hafen leiten, aber der Dockmeister sollte über das Kommen und Gehen von Schiffspassagieren informiert sein.$b$bFolgt der Straße in südöstlicher Richtung durch Ashenvale, dann gelangt Ihr irgendwann ins Brachland. Seid auf der Hut, $n, Krieger der Horde streifen durch das Land. Im Hafen werdet Ihr jedoch sicher sein.", t = "Der Brachlandhafen"},
    [1045] = {ot = "Tötet 4 Wachen von Blutreißer und holt Euch Ran Blutreißers Schädel für Krolg in der Nähe des Mystralsees.", st = "Die Nachtelfen sind so alt wie die Zeit, aber sie zerstören ihre eigene Welt durch ihre Arroganz. Und jetzt zerstören sie auch noch unser Leben. Doch das kann man nicht mehr verhindern...$B$BIch gebe den Elfen für viele Dinge die Schuld, aber wir sind immer noch für unsere Handlungen selbst verantwortlich. Wir sind sogar trotz der Verderbnis noch zu jeder Menge Bösem fähig.$B$BRan Blutreißer ist einer dieser Bösen. Machthungrig, gierig... die Verderbnis hat ihn nur noch stärker gemacht. Mein Hass auf die Elfen lodert, aber ich wünsche ihren Kindern nichts Schlimmes, wir müssen uns selbst im Zaum halten.", t = "Raenes Säuberung"},
    [1046] = {ot = "Bringt Raene Wolfrunner in Astranaar Ran Blutreißers Schädel und Dartols Rute der Transformation.", st = "Kehrt zu Eurem eigenen Stamm zurück und lasst ihn von Eurem Sieg hier wissen.$B$BZeigt ihm Eure Trophäe und sonnt Euch in Eurem Ruhm...", t = "Raenes Säuberung"},
    [1054] = {ot = "Bringt Raene Wolfrunner in Astranaar Dal Blutklaues Schädel.", st = "Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.$B$BTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde ... vorläufig.$B$BIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.", t = "Die Auswahl der Bedrohung"},
    [1055] = {ot = "Kehrt zu Shael'dryn beim Mondbrunnen zurück.", st = "Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.", t = "Raenes Säuberung"},
    [1056] = {ot = "Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel.", st = "Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.$b$bIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.$b$bDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, $R.$b$bDie Reise wird gefährlich.", t = "Reise zum Steinkrallengipfel"},
    [1057] = {ot = "Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 6 Harpyien der Blutfurien, 6 Wegelagerinnen der Blutfurien, 6 Töterinnen der Blutfurien und 6 Wildfedern der Blutfurien erschlagt.", st = "Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.$b$bIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.$b$bDie gierige motorisierte Armee der Industrialisten hat das verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.$b$bVertreibt diese elenden Harpyien, $n!", t = "Die Rückeroberung des verbrannten Tals"},
    [1058] = {ot = "Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renner-Augen und die Schuppe eines Siechdrachen.", st = "Ich bin ja so aufgeregt!$b$bDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!$b$bIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen - man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Siechdrachen.$b$bSchnell zum Steinkrallengipfel, $n, damit ich etwas Waldmagie zusammenbrauen kann!", t = "Jin'Zils Waldmagie"},
    [1060] = {ot = "Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief.", st = "Ihr habt mir sehr geholfen, $N. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.$B$BDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.$B$BEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.", t = "Brief an Jin'Zil"},
    [1061] = {ot = "Sprecht im Steinkrallengebirge mit Seereth Stonebreak.", st = "Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.$B$BSeereth Stonebreak, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.$B$BTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus Crossroads im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.", t = "Die Geister des Steinkrallengebirges"},
    [1062] = {ot = "Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Stonebreak an der Grenze des Steinkrallengebirges und dem Brachland zurück.", st = "Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!$B$BBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...$B$BGewalt.", t = "Goblin-Eindringlinge"},
    [1063] = {ot = "Sprecht in Thunder Bluff mit Magatha.", st = "Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.$B$BIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.$B$BMagatha lebt in der Tauren-Hauptstadt Thunder Bluff auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.", t = "Die Ältestengreisin"},
    [1064] = {ot = "Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah.", st = "Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.$B$BIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.$B$BSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.", t = "Die Hilfe der Verlassenen"},
    [1065] = {ot = "Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz.", st = "Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.$B$BEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge von Hillsbrad, das im weit entfernten Lordaeron liegt.$B$BUm nach Hillsbrad zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Undercity. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich nach Hillsbrad.$B$BSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.", t = "Reise nach Tarrens Mühle"},
    [1066] = {ot = "Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger.", st = "Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?$B$BUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.$B$BGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier ... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.$B$BIhr finded die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.", t = "Das Blut Unschuldiger"},
    [1067] = {ot = "Bringt Apothekerin Zamah in Thunder Bluff Lydons Toxin.", st = "Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!$B$BBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.", t = "Rückkehr nach Thunder Bluff"},
    [1068] = {ot = "Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Stonebreak an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück.", st = "Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig ...$B$BIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!$B$BIn meiner Vision trugen diese Maschinen seltsame Symbole:$B$BXT:4 und XT:9.", t = "Schreddermaschinen"},
    [1069] = {ot = "Bringt Mebok Mizzyrix in Ratchet 15 Kluftmooseier.", st = "Omeletts aus Spinneneiern sind der letzte Schrei in Booty Bay! Das Problem ist nur... dass es in Booty Bay keine Eier gibt.$B$BDas riecht nach einer Geschäftsidee!$B$BAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!$B$BAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.$B$BIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...", t = "Eier der Kluftmoosspinnen"},
    [1070] = {ot = "Sucht Kaela Shadowspear, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet.", st = "Hallo, $n.$B$BSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.$B$BErst neulich schickte Schildwache Wolfrunner meine Freundin Kaela Shadowspear dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomen-Magier losgeschickt hat ... das deutet definitiv auf Probleme hin.$B$BWürdet Ihr sie suchen und mir dann Bericht erstatten?", t = "Wache halten im Steinkrallengebirge"},
    [1071] = {ot = "Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rustfizzle im Steinkrallengebirge zurück.", st = "Wisst Ihr, $n, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.$B$BEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!$B$BIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...", t = "Der Aufschub des Gnoms"},
    [1072] = {ot = "Sprecht mit Lomac Gearstrip in Ironforge.", st = "Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.$B$BUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.$B$BDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Gearstrip. Sucht in Tüftlerstadt nach ihm.$B$BWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.", t = "Ein alter Kollege"},
    [1073] = {ot = "Bringt Lomac Ritzeldreh in Eisenschmiede 4 schwache Manatränke und 2 Elixiere der schwachen Seelenstärke.", st = "Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!$B$BEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.$B$BEs gibt allerdings ein Problem: Ich hab nichts mehr.$B$BAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.$B$BDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer Alchimisten-Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.", t = "Stümperhaftigkeit + Chemikalien = Riesenspaß!"},
    [1075] = {ot = "Sucht Collin Mauren in Stormwind auf.", st = "Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?$B$BAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.$B$BIch brauche jedoch einen Zauber von einem Freund in Stormwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.", t = "Eine Rolle von Mauren"},
    [1076] = {ot = "Bringt Collin Mauren in Stormwind die Überreste eines Staubteufels.", st = "Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nachdem er sucht.$B$BIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.$B$BWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.$B$BIch werde hier sein, wenn Ihr zurückkommt.", t = "Teufel in Westfall"},
    [1078] = {ot = "Bringt Collin Mauren in Stormwind 8 kristallisierte Schuppen.", st = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.$B$BIm verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.$B$BWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.$B$BLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.", t = "Suche für Mauren"},
    [1085] = {ot = "Sprecht mit Gaxim.", st = "Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.$B$BDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.$B$BMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.$B$BWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.$B$BEs tut mir Leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.", t = "Wache halten im Steinkrallengebirge"},
    [1086] = {ot = "Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück.", st = "Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, $n, müsst es ausliefern.$B$BDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.$B$BPlatziert es und lauft, was Ihr könnt.", t = "Der Flugapparathafen"},
    [1087] = {ot = "Tötet für Brealyn Firehand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker.", st = "Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt ... ihren geliebten Wäldern.$b$bIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.$b$bZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.", t = "Cenarius' Vermächtnis"},
    [1088] = {ot = "Bringt Braelyn Firehand in der Nähe von Sonnenfels Ordanus' Kopf.", st = "Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!$b$bDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes in Ashenvale. Ein Name... Raynewood. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.$b$bBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.", t = "Ordanus"},
    [1090] = {ot = "Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat.", st = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.$b$bEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.", t = "Gerenzos Befehle"},
    [1092] = {ot = "Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz.", st = "Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.$b$bIch schleich mich raus und treff mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!$b$bIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.", t = "Gerenzos Befehle"},
    [1093] = {ot = "Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000.", st = "Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblin-Firma, die einen Gnom anheuert!$b$bEin Glück für mich, dass Sputtervalve ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!$b$bSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht ... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.", t = "Superschnitter 6000"},
    [1094] = {ot = "Bringt Sputtervalve im Brachland den versiegelten Umschlag.", st = "In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.$b$bSputtervalve hat sich bei Ratchet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.", t = "Weitere Instruktionen"},
    [1095] = {ot = "Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle.", st = "Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Undermine für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.$b$bRiddlevox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.$b$bWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.", t = "Weitere Instruktionen"},
    [1096] = {ot = "Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Wrenchwhistles mechanischen Arm.", st = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.$b$bNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen ... Aber Ihr seht aus, als könntet Ihr es schaffen.$b$bWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!", t = "Gerenzo Wrenchwhistle"},
    [1097] = {ot = "Sprecht mit Grimand Elmore.", st = "In Stormwind gibt es einen Zwergen-Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.$B$BIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.$B$BIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Stormwind, im nordöstlichen Teil der Stadt.", t = "Elmores Aufgabe"},
    [1098] = {ot = "Sucht die Todespirscher Adamant und Vincent.", st = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!$B$BDas ist Eure Aufgabe, $n. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.$B$BDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, $n. Versagt bitte nicht.", t = "Todespirscher in Shadowfang"},
    [1100] = {ot = "Lest Henrig Lonebrows Tagebuch.", st = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow...", t = "Lonebrows Tagebuch"},
    [1101] = {ot = "Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon.", st = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.$b$bSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.$b$bSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. $n, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.$b$bBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.", t = "Die Greisin des Krals"},
    [1102] = {ot = "Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz.", st = "Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.$b$bIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.$b$bEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.$b$bBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, $n.", t = "Ein schreckliches Schicksal"},
    [1109] = {ot = "Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano.", st = "Wie Ihr seht, $N, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.$b$bAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!$b$bIhr seht weit gereist aus, $C. Vielleicht könnt Ihr mir helfen.$b$bIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...", t = "Go, Go, Guano!"},
    [1111] = {ot = "Bringt Kravels Teile-Bestellung zu Werftmeister Dizzywig in Ratchet.", st = "Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratchet geschickt, aber es war mir nicht möglich, dorthin zu reisen.$B$BAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratchet und gebt diese Teile-Bestellung an Werftmeister Dizzywig - er wird wahrscheinlich bei den Docks sein.$B$BWenn Ihr das macht, habe ich weitere Aufträge für Euch.$B$BAufträge, bei denen eine Menge Profit rausspringen kann ...", t = "Werftmeister Dizzywig"},
    [1112] = {ot = "Bringt Kravels Teile zu Kravel Koalbeard in der schimmernden Ebene.", st = "Hier ist Kravels Paket, $n. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!", t = "Teile für Kravel"},
    [1131] = {ot = "Bringt Stahlbiss' Rippe zu Melor Stonehoof in Thunder Bluff.", st = "Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.$B$BDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.$B$BDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.$B$BSucht Stahlbiss, $n. Sucht und besiegt sie.", t = "Stahlbiss"},
    [1134] = {ot = "Bringt 12 Prachtschwingengiftbeutel zu Shindrell Swiftfire in Astranaar.", st = "Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.$B$BEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen Orc-Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!$B$BWenn das stimmt, dann müssen wir sie aufhalten, $n. Wir müssen ihnen den Zugang zu dem Gift versperren.", t = "Prachtschwingen des Steinkrallengebirges"},
    [1138] = {ot = "Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine.", st = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das ... das war's eigentlich.$B$BIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Mann kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen ...", t = "Meeresfrüchte"},
    [1140] = {ot = "Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück.", st = "Díe Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.$b$bIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und die werden in Nightrun und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Ashenvale.$b$bSeid vorsichtig da draußen, $n, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte $C wie Euch beängstigend sein.", t = "Der Turm von Althalaxx"},
    [1141] = {ot = "Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine.", st = "Ich liebe das Angeln. Die Blump-Familie ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.$B$BEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.$B$BSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Blump-Familienangel geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angel, um damit Fische zu fangen.", t = "Die Familie und die Angel"},
    [1142] = {ot = "Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus.", st = "Ich habe nicht mehr lange zu leben... so... so... schwach.$b$b... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...$b$bAber bevor ich... s-s-sterbe...$b$b... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...$b$bB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...$b$b... mit der Nachricht meines einsamen... Todes.", t = "Die Sterblichkeit schwindet"},
    [1144] = {ot = "Führt Willix den Importeur aus dem Kral von Razorfen hinaus.", st = "Endlich ist Hilfe eingetroffen!$b$bIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.$b$bWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!$b$bWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.", t = "Willix der Importeur"},
    [1145] = {ot = "Stellt Korrans versiegelte Notiz Belgrom Rockmaul in Orgrimmar zu.", st = "Viele Reisende, die durch Crossroads kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.$B$BIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Rockmaul trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.$B$BBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.", t = "Der Schwarm wächst"},
    [1146] = {ot = "Stellt Belgroms versiegelte Notiz Moktar Krin in Tausend Nadeln zu.", st = "Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.$B$BVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.$B$BIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der schimmernden Ebene. Bringt ihm diese Notiz.", t = "Der Schwarm wächst"},
    [1149] = {ot = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", st = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.$B$BDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.$B$BWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.$B$BAls Erstes ein Test des Glaubens.", t = "Test des Glaubens"},
    [1150] = {ot = "Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln.", st = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.$B$BAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", t = "Test der Belastbarkeit"},
    [1151] = {ot = "Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln.", st = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.$B$BAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.$B$BSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", t = "Test der Kraft"},
    [1153] = {ot = "Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Steelforge im Camp Taurajo im Brachland.", st = "$C, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.$B$BJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.", t = "Eine neue Erzprobe"},
    [1167] = {ot = "Sprecht mit Balthule Shadowstrike beim Turm von Althalaxx.", st = "Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er wachsam in seinem Wachturm gewesen und könnte Informationen über jüngste Entwicklungen haben.", t = "Der Turm von Althalaxx"},
    [1195] = {ot = "Bringt eine gefüllte geätzte Phiole zu Zangen Stonehoof in Thunder Bluff.", st = "Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.$b$bWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.$b$bUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Raynewood im Herzen von Ashenvale besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.", t = "Die heilige Flamme"},
    [1196] = {ot = "Bringt die gefüllte geätzte Phiole zu Rau Cliffrunner im Freiwindposten.", st = "Bringt die gefüllte Phiole zu Rau Cliffrunner beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den großen Aufzug am Südrand des Brachlandes benutzt.$b$bIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.", t = "Die heilige Flamme"},
    [1197] = {ot = "Holt den gespaltenen Huf für Rau Cliffrunner im Freiwindposten.", st = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.$b$bIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.$b$bAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.", t = "Die heilige Flamme"},
    [1198] = {ot = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", st = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.$b$bMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.$b$bEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.$b$bMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.$b$bSucht und unterstützt Thaelrid für mich, $N.", t = "Auf der Suche nach Thaelrid"},
    [1199] = {ot = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus", st = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.$b$bWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.$b$bWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.$b$bFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", t = "Die Twilight fallen"},
    [1200] = {ot = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", st = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!$b$bDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.$b$bAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.$b$bDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.$b$bBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, $n.", t = "Schurkerei in Blackfathom"},
    [1221] = {ot = "Schnappt Euch eine Kiste mit Löchern.$BSchnappt Euch einen Schnüffelnasenleitstecken.$BSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.$B$BBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.$B$BBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet.", st = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.$B$BUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.$B$BEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", t = "Blaulaubknollen"},
    [1275] = {ot = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", st = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?$b$bIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.$b$bIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.$b$bEs ist eine lange Reise, $N.", t = "Erforschung der Verderbnis"},
    [1338] = {ot = "Bringt Stormpikes Bitte zu Furen Longbeard in Stormwind.", st = "Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Longbeard und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!$B$BDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Stormwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Ironforge. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!$B$BWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?", t = "Stormpikes Bestellung"},
    [1339] = {ot = "Sprecht mit Gebirgsjäger Stormpike.", st = "Ich hörte, Gebirgsjäger Stormpike sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr ein $R, der für den Job geeignet ist?$B$BWenn ja, findet Ihr Stormpike auf der Spitze des nördlichen Wachturms.", t = "Gebirgsjäger Stormpikes Aufgabe"},
    [1358] = {ot = "Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland.", st = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.$B$BHelbrim lebt im Brachland in einem Dorf, das Crossroads heißt. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Orc-Hauptstadt Orgrimmar reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald den Ort Crossroads.", t = "Probe für Helbrim"},
    [1359] = {ot = "Bringt die Wolfherzproben zu Apothekerin Zinge nach Undercity.", st = "Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!$B$BEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Undercity.", t = "Zinges Lieferung"},
    [1431] = {ot = "Sprecht mit Keldran in Orgrimmar.", st = "Seid still, $N, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.$B$BWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.$B$BWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.", t = "Allianz-Beziehungen"},
    [1442] = {ot = "Bringt einen Kor-Edelstein zu Thundris Windwirker in Dunkelküste.", st = "Seid gegrüßt, $n. Was kann ich für einen tun, der dem heiligen Weg folgt?$B$BAh ja, Stilwell, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.$B$BEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Koredelstein edle Motive hat.$B$BWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten von Ashenvale. Dort findet Ihr die Blackfathom-Tiefe mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, $C.", t = "Suche nach dem Kor-Edelstein"},
    [1470] = {ot = "Bringt Venya Marthand 3 Schädel eines klappernden Skeletts.", st = "Seid gegrüßt, Kind. Ich sehe, dass Ihr noch unerfahren in den Dingen der Hexenmeister seid, dass sich die Macht noch Eurem Griff entzieht. Doch ich spüre Euren Eifer zu lernen.$b$bUnd Ihr werdet lernen.$b$bDurch Ignoranz kann man keine Stärke finden. Wissen ist unsere größte Macht. Indem wir es anwenden, können wir die chaotische Magie und die Wesen der Leere kontrollieren und unserem Willen beugen.$b$bIch zeige Euch, wie Ihr einen Diener an Euren Willen bindet, doch zuerst müsst Ihr mir drei Schädel der klappernden Skelette nahe der verlassenen Schmiede bringen.", t = "Der zerrissene Schleier"},
    [1471] = {ot = "Beschwört mit Hilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halger im Tempel der Verdammten zurück.", st = "Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.$b$bMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.$b$bWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.", t = "Die Bindung"},
    [1473] = {ot = "Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten.", st = "Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.$b$bEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.$b$bEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.$b$bLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.", t = "Kreatur der Leere"},
    [1478] = {ot = "Sprecht mit Carendin Halgar in Undercity.", st = "Ah, $n! Carendin Halgar ließ mich soeben wissen, dass er Euch für weitere Ausbildung sehen möchte.$b$bIhr solltet stolz auf Euch sein, $n Es kommt nicht jeden Tag vor, dass Meister Halgar persönlich einen jungen Hexenmeister unterrichtet.$b$bIhr findet ihn im Magieviertel von Undercity nahe des Tempels der Verdammten.", t = "Halgars Beschwörung"},
    [1483] = {ot = "Sprecht mit Ziz Fizziks bei der Scherwindklippe.", st = "Die Venture Company stahl viele meiner besten Goblin-Denker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.$b$bVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Wrenchwhistle ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.$b$bVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.", t = "Ziz Fizziks"},
    [1485] = {ot = "Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", st = "Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.$b$bDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.$b$bBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der schändlichen Familiare aus der Höhle im Nordosten.", t = "Üble Familiare"},
    [1486] = {ot = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", st = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.$b$bDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.$b$bWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen unter uns hinab und holt einige Deviatschuppen.", t = "Deviatbälge"},
    [1487] = {ot = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", st = "Naralex hatte ein edles Ziel.$b$bUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.$b$bNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.$b$bWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.$b$bWagt Euch in die Höhlen, $n, und löscht die Deviatbrut aus.", t = "Ausrottung der Deviat"},
    [1489] = {ot = "Sprecht mit Hamuul Runetotem.", st = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.$B$BDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runetotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.$B$BIhr findet ihn in Thunder Bluff auf der Anhöhe der Ältesten.", t = "Hamuul Runetotem"},
    [1490] = {ot = "Sprecht mit Nara Wildmane.", st = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.$B$BIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.$B$BSprecht mit Nara. Sie ist in jenem Zelt da drüben.", t = "Nara Wildmane"},
    [1491] = {ot = "Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet.", st = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!$B$BEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!$B$BIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", t = "Klugheitstränke"},
    [1492] = {ot = "Bringt die gesicherte Kiste zu Werftmeister Dizzywig in Ratchet.", st = "Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratchet zu bringen, und die letzte Karawane ist schon aufgebrochen.$b$bKönntet Ihr sie bitte freundlichst zu Werftmeister Dizzywig bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.", t = "Werftmeister Dizzywig"},
    [1499] = {ot = "Sprecht mit Zureetha Fargaze.", st = "Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die schändlichen Familiare gekämpft habt.$b$bIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.", t = "Üble Familiare"},
    [1501] = {ot = "Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar.", st = "So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.$b$bEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.$b$bAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Burning Blade gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.", t = "Kreatur der Leere"},
    [1504] = {ot = "Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück.", st = "Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Fireblades Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.$b$bIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.", t = "Die Bindung"},
    [1506] = {ot = "Sprecht mit Gan'rul Bloodeye in Orgrimmar.", st = "Ihr da. $n, richtig?$b$bIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.$b$bMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.", t = "Gan'ruls Beschwörung"},
    [1507] = {ot = "Sprecht mit Cazul in der Kluft der Schatten.", st = "Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sayaad zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.$b$bEin Sayaad kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.$b$bEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.", t = "Verschlinger der Seelen"},
    [1508] = {ot = "Sprecht mit Zankaja in Orgrimmar.", st = "Wenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus, also einen weiblichen Sayaad, beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.\n\nHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, $n, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.\n\nGeht zu ihr.", t = "Der blinde Cazul"},
    [1509] = {ot = "Sprecht mit Gazrog in Crossroads.", st = "Dogran, mein Gefährte, wurde jüngst zum Dienst nach Crossroads geschickt. Es war eine Beförderung und er war sehr stolz.$b$bIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.$b$bSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...$b$bVielleicht könntet Ihr nach Crossroads gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.", t = "Neuigkeiten von Dogran"},
    [1510] = {ot = "Sprecht mit Ken'zigla am Malaka'jin.", st = "Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.$b$bSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.", t = "Neuigkeiten von Dogran"},
    [1511] = {ot = "Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo.", st = "Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.$b$bDa habt Ihr ihn, $n. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.$b$bWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.", t = "Ken'ziglas Trunk"},
    [1512] = {ot = "Bringt den schmutzverkrusteten Anhänger zu Gan'rul Bloodeye in Orgrimmar.", st = "Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.$b$bLasst mich allein, $n. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.$b$bUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.", t = "Die Liebesgabe"},
    [1513] = {ot = "Beschwört mit Hilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Bloodeye in Orgrimmar zurück.", st = "Bringt dies zum Beschwörungskreis in Neerus Zelt, $n. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.$b$bWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.", t = "Die Bindung"},
    [1515] = {ot = "Bringt Ken'ziglas Trunk zu Dogran im Brachland.", st = "Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.$b$bDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.$b$bViel Glück.", t = "Dograns Gefangenschaft"},
    [1516] = {ot = "Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen.", st = "Die Zeit ist gekommen, junger $C. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.$B$BDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.$B$BSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.", t = "Ruf der Erde"},
    [1517] = {ot = "Sucht den Geisterfelsen und trinkt das Erdsapta.", st = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.$B$BDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo ... vergesst das nicht.$B$BBesucht den Geisterfelsen südwestlich von hier ... er befindet sich am Ende des verborgenen Pfades. Trinkt Euer Sapta dort und ... tja, Ihr werdet schon sehen.", t = "Ruf der Erde"},
    [1518] = {ot = "Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", st = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Earthcaller. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.$B$BHabt Geduld, $n. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", t = "Ruf der Erde"},
    [1519] = {ot = "Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache.", st = "Die Zeit ist gekommen, $C. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.$B$BDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.$B$BSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.", t = "Ruf der Erde"},
    [1520] = {ot = "Sucht den Kodofels und trinkt das Erdsapta.", st = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.$B$BDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.$B$BSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.", t = "Ruf der Erde"},
    [1521] = {ot = "Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache.", st = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu der Seherin Ravenfeather. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.$B$BHabt Geduld, $n. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", t = "Ruf der Erde"},
    [1524] = {ot = "Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar.", st = "Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.$B$BAm Südstromfluss in Durotar, vor dem großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht ... den Schrein der schlafenden Flamme.$B$BBringt ihm diese Fackel ... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.", t = "Ruf des Feuers"},
    [1525] = {ot = "Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar.", st = "Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.$B$BZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.$B$BIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Grimmhauer im östlichen Brachland mit sich führen.$B$BDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Burning Blade. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.", t = "Ruf des Feuers"},
    [1526] = {ot = "Besiegt die geringe Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", st = "Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.$B$BSchlagt ihn schnellstens nieder, $n, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.", t = "Ruf des Feuers"},
    [1527] = {ot = "Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland.", st = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.$B$BAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.", t = "Ruf des Feuers"},
    [1530] = {ot = "Sucht Brine im südlichen Brachland.", st = "Wenn Ihr eine Lektion über Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt.$B$BSeine Macht fließt, erodiert und reinigt alle Arten von Dingen. Seine Fähigkeit zu heilen und zu regenerieren ist unvergleichlich, jedoch nur, wenn es rein ist.$B$BWenn Ihr begreift, dass verunreinigtes Wasser alles verheeren kann, was es berührt, werdet Ihr schätzen lernen, wie lebenswichtig dieser Rohstoff ist.$B$BWenn Ihr das Wassersapta möchtet, sucht Brine tief im südlichen Brachland. Ihr Heim wird unablässig von den dortigen Stachelebern heimgesucht.", t = "Ruf des Wassers"},
    [1531] = {ot = "Sucht Prate Cloudseer in Tausend Nadeln.", st = "Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Cloudseer in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.$B$BGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.", t = "Ruf der Luft"},
    [1534] = {ot = "Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen in Ashenvale und kehrt zu Brine im Brachland zurück.", st = "Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, die die Nachtelfen Ashenvale nennen. Sie liegen weit nördlich des Brachlandes.$B$BWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und Ashenvale trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.$B$BBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.", t = "Ruf des Wassers"},
    [1535] = {ot = "Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück.", st = "Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.$B$BWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.", t = "Ruf des Wassers"},
    [1536] = {ot = "Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück.", st = "Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge von Hillsbrad. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.$B$BDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.$B$BBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.", t = "Ruf des Wassers"},
    [1578] = {ot = "Bringt 6 Kupferäxte und 6 Kupferne Kettengürtel zu Thorvald im südlichen Wachturm des Loch Modan.", st = "Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.$B$BDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.$B$BThorvald ist im südlichem Wachturm des Loch Modan.", t = "Nachschub für die Front"},
    [1579] = {ot = "Bringt 8 Klemm-Muffen zu Wizbang Cranktoggle in Auberdine.", st = "Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Ironforge nicht!$B$BDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemm-Muffen über Bord fallen! Ich brauche meine Klemmmuffen!$B$BIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...", t = "Klemm-Muffen"},
    [1580] = {ot = "Bringt 12 Elektropeller zu Wizbang Cranktoggle in Auberdine.", st = "Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, $n?$B$BEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!$B$BIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...", t = "Elektropeller"},
    [1581] = {ot = "Bringt 6 Elixiere Löwenkraft und 2 Elixiere der schwachen Verteidigung zu Syral Bladeleaf in Dolanaar.", st = "Unser Kräuter- und Alchimie-Laden floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.$B$BKönnt Ihr uns helfen?$B$BWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse rare Kräuter, die Euch nützlich sein könnten.", t = "Elixiere für die Bladeleafs"},
    [1598] = {ot = "Holt \"Die Macht der Leere\" für Drusilla La Salle zurück.", st = "Ihr da! $n, richtig?$b$bIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.$b$bIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.$b$bEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.$b$bEines davon war ein Buch, das ich selbst wollte, \"Die Macht der Leere\". Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.", t = "Der gestohlene Foliant"},
    [1599] = {ot = "Bringt 3 Federglücksbringer zu Alamar Grimm in Anvilmar.", st = "Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.$b$bKeine Bange, ich mache Euch keinen Vorwurf.$b$bDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.$b$bBringt mir drei Federglücksbringer von den Novizen der Frostmane aus der Höhle im Südwesten.", t = "Anfänge"},
    [1618] = {ot = "Tormus Deepforge möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Osgood ins Rotkammgebirge bringt.", st = "Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!$B$BDas Rotkammgebirge wird immer wieder von den Blackrockorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Osgood, Euch den einen oder anderen Trick beibringen.", t = "Die Aufrüstung im Rotkammgebirge"},
    [1638] = {ot = "Sprecht mit Harry Burlguard.", st = "Ihr habt Euch als fähiger Krieger erwiesen, $n. Aber Ihr seid noch jung und müsst noch viel lernen.$B$BSprecht mit Harry Burlguard... er ist meist in der Taverne Zum pfeifenden Schwein in der Altstadt von Stormwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.", t = "Die Ausbildung eines Kriegers"},
    [1639] = {ot = "Sprecht mit Bartleby.", st = "Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.$B$BSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.$B$BHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.", t = "Bartleby der Trunkenbold"},
    [1640] = {ot = "Besiegt Bartleby und redet dann mit ihm.", st = "Ihr wollt was??? Ihr seid verrückt!$B$BWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", t = "Besiegt Bartleby"},
    [1641] = {t = "Der Foliant der Offenbarung"},
    [1642] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.$B$BAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.$B$BBedenket das und vergesst es niemals.", t = "Der Foliant der Offenbarung"},
    [1643] = {ot = "Sucht im Handelsdistrikt von Stormwind nach Stephanie Turner.", st = "Eure Aufgabe, $n, besteht darin, jemanden hier in Stormwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.$B$BMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.", t = "Der Foliant der Offenbarung"},
    [1644] = {ot = "Bringt 10 Stück Leinenstoff zu Stephanie Turner in Stormwind.", st = "Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.$B$BMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.$B$BWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, $n.$B$BWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.", t = "Der Foliant der Offenbarung"},
    [1645] = {t = "Der Foliant der Offenbarung"},
    [1646] = {ot = "Sprecht mit Tiza Battleforge in Ironforge.", st = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.$B$BAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.$B$BBedenket das und vergesst es niemals.", t = "Der Foliant der Offenbarung"},
    [1647] = {ot = "Sucht im äußeren Ring von Ironforge nach John Turner.", st = "Eure Aufgabe, $n, ist es, jemanden hier in Ironforge zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.$B$BMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.", t = "Der Foliant der Offenbarung"},
    [1648] = {ot = "Bringt 10 Stück Leinenstoff zu John Turner in Ironforge.", st = "Meine Frau und ich führen das Waisenhaus in Stormwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Ironforge und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.$B$BDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.$B$BKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.", t = "Der Foliant der Offenbarung"},
    [1649] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.$B$BDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.", t = "Der Foliant der Ehre"},
    [1650] = {ot = "Sucht Daphne Stilwell in Westfall.", st = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.$B$BAm äußersten Ende von Longshore in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stilwells. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Ironforge gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.$B$BEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.", t = "Der Foliant der Ehre"},
    [1651] = {ot = "Verteidigt Daphne Stilwell vor dem Angriff der Defias.$B$BKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.$B$BSprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart.", st = "Ich wette, die kommen bald wieder, also macht Euch bereit.$B$BIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.$B$BIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.$B$BBittet das Licht um jeden erdenklichen Segen, denn ... habt Ihr das gehört? Ich glaube, sie kommen.$B$BWir beziehen Position beim Haus!", t = "Der Foliant der Ehre"},
    [1652] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.$B$BEr wird eine Nachricht nach Ironforge schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.$B$BOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.", t = "Der Foliant der Ehre"},
    [1653] = {ot = "Sprecht mit Jordan Stilwell in Ironforge.", st = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.$B$BJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.$B$BEr müsste noch in Ironforge sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.", t = "Die Prüfung der Rechtschaffenheit"},
    [1654] = {ot = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge.", st = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.$B$BIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, $C?", t = "Die Prüfung der Rechtschaffenheit"},
    [1656] = {ot = "Bringt das Bündel Felle zu Gastwirt Kauth in Bloodhoof.", st = "$n, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Mesa noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus von Bloodhoof abzuliefern.$B$BIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?$B$BDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.", t = "Eine unvollendete Aufgabe"},
    [1665] = {ot = "Bringt Bartlebys Becher zu Burlguard.", st = "Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.", t = "Bartlebys Becher"},
    [1680] = {ot = "Sprecht mit Tormus Deepforge.", st = "Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Deepforge. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.$B$BIhr findet Tormus hier in Ironforge bei der großen Schmiede.", t = "Tormus Deepforge"},
    [1683] = {ot = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", st = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.$B$BDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.$B$BSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.$B$BDer Weg zum Mondbrunnen ist gut verborgen, $n, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", t = "Vorlus Elendshuf"},
    [1684] = {ot = "Sprecht mit Elanaria.", st = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.$B$BDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", t = "Elanaria"},
    [1685] = {ot = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", st = "Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.$b$bIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.$b$bIhr findet ihn im Keller der Taverne Zum geschlachteten Lamm. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.", t = "Gakins Beschwörung"},
    [1688] = {ot = "Beschafft Surenas Halsschmuck für Gakin den Dunkelbinder in Stormwind.", st = "Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!$b$bDas diebische Weib brannte mit einem der Defias durch, Erlan Drudgemoor. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.$b$bIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackwells Kürbisbeet. Bringt wieder, was mir gehört.", t = "Surena Caledon"},
    [1689] = {ot = "Beschwört mit Hilfe des Blutsteinhalsschmucks einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsschmuck zu Gakin dem Dunkelbinder in Stormwind zurück.", st = "Ihr habt meinen Halsschmuck zurückgebracht und Surena bezwungen, und damit gezeigt, dass Ihr mindestens ebenso begabt seid wie sie es war.$b$bNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.$b$bIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.", t = "Die Bindung"},
    [1699] = {ot = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.$B$BIhr dürft nicht sterben und Euren Geist befreien.", st = "Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...$B$BIhr müsst binnen einer Stunde zurück sein.$B$BGanze Heerscharen von Rotkammgnollen versperren den Weg.$B$BVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!$B$BWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?", t = "Der Rethban-Spießrutenlauf"},
    [1701] = {ot = "Sammelt die Materialien, die Furen Longbeard benötigt, und bringt sie zu ihm nach Stormwind.", st = "Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstung herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.$B$BWas sagt Ihr dazu, $n? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.", t = "Feuergehärteter Panzer"},
    [1702] = {ot = "Bringt das Fässlein mit Gerstenbräu zu Furen Longbeard.", st = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, $n. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...$B$BAber sie ist in Stormwind.$B$BSprecht mit meinem Freund Furen Longbeard im Zwergendistrikt von Stormwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.$B$BHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.", t = "Der Schildschmied"},
    [1716] = {ot = "Sprecht mit Takar dem Seher im Brachland.", st = "Ein Sayaad ist ein Verschlinger der Seelen, Bezwinger des Willens, Versucher der Herzen. Er kennt nur das Böse.\n\nSchlüpfrige Geschichten bezeichnen diese Dämonen mit ihren geläufigeren Namen: Sukkubus in der weiblichen und Inkubus in der männlichen Gestalt.\n\nIhr braucht einen Anreiz, um die Kreatur anzulocken. Mit einem Symbol der Liebe als Köder wird sie gewiss auf Euren Ruf reagieren. Besiegt den Dämon und macht ihn zu Eurem Werkzeug.\n\nEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.", t = "Verschlinger der Seelen"},
    [1718] = {ot = "Sprecht mit Klannoc Macleod.", st = "Euer Ruf als Krieger wächst, $n. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.$B$BVor der Küste des Brachlandes, südlich von Ratchet, liegt eine Insel. Sie heißt Prügel-Eiland und ist ein Treffpunkt für Krieger.$B$BGeht dorthin und kämpft.$B$BSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.$B$BUm die Prügel-Eiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.", t = "Der Inselbewohner"},
    [1719] = {ot = "Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügel-Eiland.", st = "Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügel-Eiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.$B$BGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flathead, dass Ihr bereit seid, und er schickt Euch Herausforderer.$B$BWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.", t = "Der Ringkampf"},
    [1738] = {ot = "Holt das Herzholz aus Ashenvale und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", st = "Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.$b$bIm Krieg der Urtume fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.$b$bEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes von Ashenvale.", t = "Herzholz"},
    [1739] = {ot = "Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", st = "Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.$b$bSeid vorsichtig, $n, Sukkubi haben schon den stärksten Geist unterjocht.$b$bWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.", t = "Die Bindung"},
    [1740] = {ot = "Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland.", st = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.$b$bViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.$b$bDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolythen der Twilight-Hammer in der Blackfathom-Tiefe benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Shadowfang. Sucht sie, dann kann ich sie zusammenfügen...", t = "Die Kugel von Soran'ruk"},
    [1778] = {ot = "Sprecht mit Tiza Battleforge in Ironforge.", st = "Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Stormwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, $C.", t = "Der Foliant der Offenbarung"},
    [1779] = {ot = "Nehmt das Symbol des Lebens und sprecht mit Muiredon Battleforge in Ironforge.", st = "Ich möchte, dass Ihr das nehmt, $n. Es heißt Symbol des Lebens.$B$BIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.$B$BMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.$B$BNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.", t = "Der Foliant der Offenbarung"},
    [1780] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, $C. Es kommt nicht oft vor, dass $GMänner:Frauen; Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Stormwind die Bedürftigen nicht im Stich lassen.$B$BLebt wohl.", t = "Der Foliant der Offenbarung"},
    [1781] = {ot = "Bringt das Symbol des Lebens zu Gazin Tenorm in Stormwind.", st = "Nehmt das, $n. Es heißt Symbol des Lebens.$B$BIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.$B$BMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.$B$BNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.", t = "Der Foliant der Offenbarung"},
    [1783] = {ot = "Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben.", st = "Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbedsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.$B$BNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.$B$BNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.$B$BKönnt Ihr helfen, $n?", t = "Der Foliant der Offenbarung"},
    [1784] = {ot = "Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbedsee und kehrt zu Muiredon Battleforge in Ironforge zurück.", st = "Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Captain ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.$B$BEinige im Rat von Ironforge glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.$B$BBeschafft eines dieser Manuskripte und bringt es zu Muiredon, $n.", t = "Der Foliant der Offenbarung"},
    [1785] = {ot = "Sprecht mit Tiza Battleforge in Ironforge.", st = "Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.$B$B's Licht soll mit Euch sein, $C. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.", t = "Der Foliant der Offenbarung"},
    [1786] = {ot = "Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben.", st = "Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.$B$BAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.$B$BHenze wehrte sie ab, derweil ich entkam ... der elende Narr muss immer den Helden spielen.$B$BEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, $n?", t = "Der Foliant der Offenbarung"},
    [1787] = {ot = "Beschafft ein Manuskript der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Stormwind zurück.", st = "Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.$B$BMomentan bin ich nicht in der Verfassung zu kämpfen, $n. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?$B$BWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.", t = "Der Foliant der Offenbarung"},
    [1788] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!$B$BNochmals danke, $n. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.", t = "Der Foliant der Offenbarung"},
    [1791] = {ot = "Sprecht mit Bath'rah dem Windbehüter.", st = "Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.$B$BSprecht mit Bath'rah dem Windbehüter. Das ist ein Troll-Einsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.$B$BUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.", t = "Der Windbehüter"},
    [1793] = {t = "Der Foliant der Ehre"},
    [1818] = {ot = "Sprecht mit Todeswache Dillinger in Brill.", st = "Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.$B$BTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.", t = "Gespräch mit Dillinger"},
    [1819] = {ot = "Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger.", st = "Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.$B$BWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. $B$BBefreit und tötet ihn.$B$BAktiviert den Schädelstein-Auslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.$B$BUnd dann... seid bereit, $n.", t = "Ulag der Spalter"},
    [1820] = {ot = "Sprecht mit Coleman Farthing.", st = "Ihr habt Euren Wert für die dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.$B$BColeman Farthing wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.$B$BIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.", t = "Gespräch mit Coleman"},
    [1821] = {ot = "Bringt Coleman Farthing die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand.", st = "Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.$B$BUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!$B$BDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.", t = "Agamand-Erbstücke"},
    [1822] = {t = "Erbstückwaffe"},
    [1823] = {ot = "Sprecht mit Ruga Ragetotem.", st = "Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Ragetotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.$B$BEr wartet auf Krieger, die seinem Ruf folgen.", t = "Gespräch mit Ruga"},
    [1824] = {ot = "Bringt 5 zuckende Fühler zu Ruga Ragetotem im Camp Taurajo.", st = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.$B$BBringt mir einen ihrer noch zuckenden Fühler und vergeudet keine Zeit, $n, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.", t = "Prüfung auf dem Feld der Riesen"},
    [1838] = {ot = "Bringt Thun'grim Firegaze 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston.", st = "Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.$B$BAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, $n. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.$B$BHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.", t = "Brutale Rüstung"},
    [1858] = {ot = "Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", st = "Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.$b$bDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.", t = "Die Shattered-Hand"},
    [1859] = {ot = "Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", st = "Sprecht leiser, $n. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.$b$bSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.$b$bHabe ich Recht?$b$bWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.", t = "Therzok"},
    [1860] = {ot = "Sprecht in Stormwind mit Jennea Cannon.", st = "Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Stormwind und dem Wald von Elwynn von entscheidender Bedeutung.$B$BJennea Cannon kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Stormwind. Ihr solltet Euch eiligst zu ihr begeben.", t = "Gespräch mit Jennea"},
    [1879] = {ot = "Sprecht mit Bink in Ironforge.", st = "$n! Bink, meine Gnomen-Kollegin in Ironforge, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr $gein Magier:eine Magierin;, $n?$B$BWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Ironforge in der Halle der Mysterien im mystischen Krieg.", t = "Gespräch mit Bink"},
    [1881] = {ot = "Sprecht mit Anastasia Hartwell.", st = "$n, Anastasia Hartwell hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Undercity und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.", t = "Gespräch mit Anastasia"},
    [1882] = {ot = "Bringt Balnir-Löwenmäulchen zu Anastasia Hartwell im Magierviertel von Undercity.", st = "Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verdirbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.$B$BDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen - Löwenmäulchen. Sammelt sie und kehrt zurück.", t = "Balnirs Bauernhof"},
    [1885] = {ot = "Sprecht mit Mennet Carkad im Schurkenviertel von Undercity.", st = "$n? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?$b$bSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.", t = "Mennet Carkad"},
    [1886] = {ot = "Beschafft Astors Empfehlungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", st = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.$b$bIch will Euch nichts vormachen, $N, diese Aufgabe könnte Euren Tod bedeuten.$b$bIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Undercity pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.$b$bJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", t = "Die Todespirscher"},
    [1898] = {ot = "Sprecht mit Andron Gant in Undercity.", st = "Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.$b$bLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteil werden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.$b$bIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", t = "Die Todespirscher"},
    [1899] = {ot = "Bringt Astors Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Undercity.", st = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", t = "Die Todespirscher"},
    [1918] = {ot = "Bringt die beschmutzte Wasserkugel zu Mastok Wrilehiss im Splintertreeposten in Ashenvale.", st = "Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass, was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.$B$BEs ist nicht gerade weit bekannt, wer sich für solch einen Fund interessieren könnte. Vielleicht weiß die Person etwas darüber, die Euch ursprünglich zum See hinausgeschickt hatte - Mastok Wrilehiss im Splintertreeposten.", t = "Das beschmutzte Element"},
    [1919] = {ot = "Sprecht in Stormwind mit Jennea Cannon.", st = "Euer Wissen über das Handwerk wächst, $n. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?$B$BWenn ja, sprecht mit Jennea Cannon im Magiersanktum im Magierviertel von Stormwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.", t = "Meldung bei Jennea"},
    [1920] = {ot = "Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", st = "Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.$B$BIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", t = "Untersuchungen im Blauen Eremiten"},
    [1960] = {ot = "Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity.", st = "Algernons Alchimistenladen im Apothekarium ist das Zentrum einer seltsamen Störung. Unsichtbare, aus reiner Magie bestehende Kreaturen halten sich in dem Laden auf - dafür muss es einen Grund geben, und den müssen wir herausfinden!$B$BUntersucht die Störung und fangt diese Kreaturen. Nehmt Euch von dort hinten eine Truhe mit Kästen und eine Rolle. Benutzt im Laden die Rolle, um die Kreaturen sichtbar zu machen, überwältigt sie mit Euren Zaubern und fangt sie dann mit einem Kasten ein. Kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", t = "Untersuchungen im Alchimistenladen"},
    [1961] = {ot = "Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian.", st = "Jetzt ist es Zeit, Eure erste Magierrobe anzulegen, $n. Sie ist ein Zeichen Eures Ranges und ein Zeugnis für Euren Wert.$B$BUm die Robe zu bekommen, müsst Ihr Manaedelsteine von den Magiern von Dalaran im Silberwald sammeln. Ihre Überzeugungen ähneln den unseren, daher ist es ein wenig geschmacklos, sie zu töten, aber wenn sie keine Kraft haben, uns Widerstand zu leisten, verdienen sie es nicht, zu leben.$B$BBringt die Edelsteine und das Leinen zu Josef Gregorian in der Schneiderei im Magieviertel.", t = "Materialsammlung"},
    [1962] = {t = "Roben des Zauberfeuers"},
    [1963] = {ot = "Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", st = "Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln. Einst waren wir stärker, allesamt mächtige Eroberer. Diesen Stolz müssen wir zurückerlangen, und der Klan der Shattered-Hand wird dies bewerkstelligen.$b$bWir sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Eine Aufgabe müsst Ihr für mich erledigen, um Euren Wert zu beweisen.$b$bDer Troll Tazan treibt Handel mit den Piraten bei Ratchet. Er hat Informationen, die ich haben muss. Tötet ihn und bringt mir seinen Ranzen.", t = "Die Shattered-Hand"},
    [1978] = {ot = "Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Undercity.", st = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.$b$bLord Varimathras wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.$b$bAh, und wie konnte ich das vergessen?$b$bWillkommen bei den Todespirschern.", t = "Die Todespirscher"},
    [1998] = {ot = "Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Undercity.", st = "Lord Varimathras hat mir soeben in einer Botschaft über eine Gefahr für die Verlassenen berichtet, die unverzüglich ausgeschaltet werden muss. Sein Name ist Fenwick Thatros. Lord Varimathras glaubt, dass er einer der Anführer der Untoten sei, die sich im Silberwald angesiedelt haben.$b$bMir kam sofort Euer Name in den Sinn, $n. Ich habe Vertrauen in Eure Fähigkeiten und glaube, Ihr werdet diese Mission fehlerfrei abschließen.$b$bDie letzte Meldung von den Todespirschern im Silberwald deutet darauf hin, dass Thatros nahe der verfallenen Fähre am Lordameresee zu finden ist.", t = "Fenwick Thatros"},
    [2038] = {ot = "Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:$B$BBingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube.", st = "Als wäre es nicht schlimm genug gewesen, in den Loch zu stürzen, haben mich auch noch Troggs von der nahe gelegenen Insel angegriffen und mir mein Werkzeug und meinen speziellen Sprengstoff \"Superspreng\" aus der Blastenheimer-Sprengstoffstube gestohlen. Ohne Gyrokopter und Sprengstoff hat die Bewegung keine Chance!$B$BBeschafft mir meine Werkzeuge wieder und findet mein Superspreng aus der Sprengstoffstube, $n. Für Gnomeregan!", t = "Bingles' verschwundene Werkzeuge"},
    [2039] = {ot = "Sucht Bingles Blastenheimer am Loch Modan.", st = "Wir haben den Kontakt mit Bingles verloren! Er wurde zu einer Aufklärungsmission über Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht mehr gemeldet. Ich weiß, er hat sich selbst in die Luft gejagt.$B$BZuletzt sah man ihn über dem Loch fliegen. Vielleicht könnt Ihr dies untersuchen, $n?", t = "Sucht Bingles"},
    [2040] = {ot = "Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind.", st = "Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, $n.$B$BTief in den Todesminen gibt es einen funktionierenden Goblinschredder. Sucht diesen Schredder und bringt die intakte Energieversorgung mit. Mit der Energieversorgung des Schredders können wir unseren gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen!", t = "Unterirdischer Angriff"},
    [2041] = {ot = "Sprecht mit Shoni der Schtillen in Stormwind.", st = "Vielleicht... Vielleicht könnt Ihr uns im Kampf um Gnomeregan unterstützen.$B$BIn Stormwind findet Ihr den Kommandant unserer Untergrund-Kampftruppe, Shoni die Schtille. Shoni braucht Hilfe für ihre gyrobohrmatischen Exkavationatoren.$B$BIhr findet sie wahrscheinlich bei den Zwergen in Stormwind.$B$BViel Glück, $n.", t = "Sprecht mit Shoni"},
    [2078] = {ot = "Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück.", st = "Landratte, Ihr müsst meinen Ersten Maat finden.$B$BNehmt diesen Schlüssel, steckt ihn in sein' Gulliver und schafft ihn her, dasser seim Käpt’n dient.$B$BDiese Murlocs und ihr Häuptling werden nich so froh sein, wenn der Erste Maat sie zu fassen kriegt!", t = "Gyromasts Rache"},
    [2098] = {ot = "Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast.", st = "Das Piratenleben ist eines der Schwersten, Landratte. Es dreht sich nicht nur um Plündern und Saufen! Wehe, mein Schiff sank vor der Küste! Schuld daran sind diese dreisten Dreschadons.$B$BIch muss mein' Ersten Maat funktionstüchtig wiederham!$B$BAls ich an Land gespült wurde, zerbrach der Schlüssel für meinen Ersten Maat an den Felsen und wurde von den Biesterchen von Dunkelküste geraubt. Aus den Augenwinkeln sah ich tobende Kriecher, riesige Waldschreiter und Murlocs, die das Wrack durchstöberten...", t = "Gyromasts Rettung"},
    [2118] = {ot = "Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun.", st = "Eine Erkrankung breitet sich in Dunkelküste aus und befällt Körper und Geist aller, die damit in Kontakt kommen.$B$BDie Distelbären wurden am schwersten von der Seuche getroffen. Die einst edlen Tiere sind jetzt ein Instrument der Zerstörung - tollwütig und rasend. Ich habe möglicherweise ein Heilmittel für dieses Leiden.$B$BGeht mit dieser Falle in den Wald und legt sie auf den Boden. Jeder tollwütige Distelbär, der das Licht kreuzt, wird für kurze Zeit friedfertig. Wenn der Bär erst einmal friedfertig ist, wird er Euch folgen. Führt ihn hierher, $n.", t = "Verseuchtes Land"},
    [2138] = {ot = "Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück.", st = "Wie ich befürchtete, das Heilmittel wirkt nicht.$B$BEs stimmt mich traurig, Geschöpfe der Natur zum Tode zu verurteilen, aber die kranken und besudelten Distelbären müssen ausgerottet werden.$B$BKehrt in den Wald zurück und vernichtet 20 tollwütige Distelbären, $n. Das wird die Seuche sicher nicht stoppen, aber den Schaden, den die Tiere unserem Wald und seinen Bewohnern zufügen, zumindest für kurze Zeit verringern.", t = "Ausrottung der Infizierten"},
    [2139] = {ot = "Sucht und tötet die Höhlenmutter.", st = "Das Überleben unseres Volkes und unserer Länder ist mit bedauerlichen Kosten verbunden, $n.\n\nIhr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr erledigt. Das Volk von Auberdine steht in Eurer Schuld, denn die Qualen des Waldes sind gelindert - wenn auch nur vorübergehend.\n\nIch habe eine letzte Aufgabe für Euch, doch seid gewarnt, Ihr werdet wieder töten müssen. Dies wird hoffentlich das letzte Mal sein, dass ich Euch rufen muss, $n.\n\nIn einer Höhle im Nordosten, nahe Bashal'Aran, haust die Höhlenmutter. Tötet sie.", t = "Tharnariuns Hoffnung"},
    [2158] = {ot = "Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley.", st = "Jeder Abenteurer sollte ausruhen, wenn ihn die Erschöpfung überkommt - und es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus Zur Höhle des Löwen!$B$BGastwirt Farley, der Inhaber der 'Höhle des Löwen', ist mein bester Freund. Wenn Ihr ihm sagt, dass ich Euch geschickt habe, dann gewährt er Euch vielleicht einen Spezialrabatt auf Essen und Trinken.$B$BDas Gasthaus Zur Höhle des Löwen findet Ihr, wenn Ihr auf der Straße nach Süden reist - Ihr könnt es nicht verfehlen!", t = "Ruhe und Entspannung"},
    [2159] = {ot = "Bringt die Dolanaar-Lieferung zu Gastwirt Keldamyr.", st = "Seid mir gegrüßt, $C. Könnt Ihr mir helfen? Ich habe ein Päckchen Kräuter, das ich in die Stadt Dolanaar liefern muss. Aber ich habe noch etwas mit den Druiden von Shadowglen zu regeln und kann nicht weg.$B$BKönntet Ihr das Päckchen für mich zustellen? Es muss zu Gastwirt Keldamyr im Gasthaus von Dolanaar. Das liegt an der Straße nach Süden.", t = "Dolanaar-Lieferung"},
    [2160] = {ot = "Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos.", st = "He! Ihr seht wie ein beherzter Abenteurer aus. Wenn Ihr vorhabt, den Pass zu überqueren, könntet Ihr da wohl ein Päckchen ins Gasthaus von Kharanos bringen?$b$bIhr hattet doch vor, im Gasthaus abzusteigen, nicht? Wenn Ihr den Pass bezwungen habt, werdet Ihr Euch dort ganz bestimmt etwas ausruhen wollen.$b$bWie auch immer, bringt das zu Tannok Frosthammer, dem Gehilfen des Gastwirts. Ich selbst kann nicht über den Pass und es dauert Tage, bis wieder eine Gebirgsjägereskorte vorbeikommt!", t = "Vorräte für Tannok"},
    [2161] = {ot = "Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel.", st = "Entschuldigung? Könntet Ihr mir helfen?$B$BIch habe hier eine Ladung Essen. Ich bin die Straße entlanggelaufen und habe Skorpiden und Spinnen und Schlimmerem getrotzt! Ich habe das Essen ins Tal der Prüfungen gebracht, weil ich dachte, sie könnten es brauchen und weil ich gern behilflich bin. Aber sie brauchen kein Essen! Jetzt muss ich es nach Klingenhügel zurückbringen und fürchte mich vor den ganzen Bestien unterwegs...$B$BKönnt Ihr es für mich hinbringen? Ich bin nur ein Peon, Ihr aber seid $gein Held:eine Heldin;. Ihr fürchtet nichts!$B$BBringt es zu Gastwirt Grosk im Gasthaus von Klingenhügel. Danke!", t = "Die Bürde eines Peons"},
    [2178] = {ot = "Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nightsonng in Auberdine.", st = "Riecht Ihr dieses köstliche Aroma? Das ist mein Geheimrezept, $n - frischer Schreitereintopf. Köstlich!$B$BVielleicht möchtet Ihr das Rezept ja wissen?$B$BBevor ich Euch das Rezept verrate, müsst Ihr beweisen, dass Ihr den Wildtieren gewachsen seid.$B$BIch erwarte nicht, dass Ihr loszieht und eines zähmt und darauf zu mir zurückgeritten kommt, aber wenn Ihr einige Wildtiere töten könnt und mir etwas von ihrem saftigen Fleisch bringt, verrate ich Euch vielleicht das Schreiterrezept.", t = "Schreitereintopf"},
    [2205] = {ot = "Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind.", st = "Das Abzeichen? Oh, das ist gar nichts, Dumpfbacke - jedenfalls nichts, mit dem Ihr fertig werden könntet. Wenn ich Euch so ansehe, würde ich sagen, dass Mathias Euch wahrscheinlich statt für einen anständigen Schurken für einen Käselieferanten halten wird. Aber wie dem auch sei, ich habe eine Aufgabe zugewiesen bekommen und ich habe versprochen, sie zu erledigen.$B$BDa wir gerade davon sprechen, bringt Mathias dieses Päckchen, dann gibt er Euch vielleicht eine kleine Aufgabe oder auch zwei.$B$BZischt ab.", t = "Aufsuchen des SI: 7"},
    [2218] = {ot = "Sprecht mit Hulfdan Blackbeard in Ironforge.", st = "Eine weitere verirrte Seele, die nach Führung sucht, hm? Ich nehme an, Ihr wollt ein Ziel finden - Euer Ziel. Das habe ich schon tausend Mal gesehen, ein Held, der Arbeit sucht.$B$BAber heute ist Euer Glückstag. Hogral hat ein Heilmittel für Eure Leiden.$B$BIhr macht Folgendes: Schlagt diesen Weg nach Ironforge ein und begebt Euch zum düsteren Viertel. Wenn Ihr dort seid, sucht die Diebesgilde und sprecht mit Hulfdan Blackbeard. Er wird Euch den Weg zur Rettung weisen.", t = "Straße der Rettung"},
    [2241] = {ot = "Bringt Jannoks Rose zu Syurna in Darnassus.", st = "Sie sagen, ich bin 'liebeskrank', was immer das heißen mag.$B$BKlar, ich denke ununterbrochen an Syurna. Klar, mein Haus ist voll von Bildern und Zeichnungen von Syurna. Klar, es kommt vor, dass ich tagelang nicht esse, schlafe oder trinke, während ich über die Liebe lamentiere, die uns nicht zuteil wurde. Ist das so falsch?$B$BJetzt will sie mich nicht sehen! MICH! Ich habe versucht, ihr Nachrichten zu schicken, aber sie redet mit keinem, es sei denn, er wäre ein Schurke.$B$BKönntet Ihr diese Blume zu ihr bringen? Und vergesst nicht, ihr zu sagen, dass sie von Jannok ist.", t = "Der Apfel fällt"},
    [2242] = {ot = "Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.", st = "Wir glauben, dass es ein Wesen gibt, das uns verstehen helfen könnte, was mit den Wäldern von Teldrassil geschieht. Leider hatte es verheerende Folgen, als wir versuchten, dieses Wesen zur Mitarbeit zu überreden.$B$BEr versteckt sich auf einem Ast am Rand der Lichtung des Orakels. Alle, die sich dem Satyr bisher genähert haben, sei es mit Gewalt oder Diplomatie, fanden ein böses Ende. Vielleicht ist Verstohlenheit die Lösung, $n.$B$BFindet heraus, was Sethir der Uralte in seinen Rucksäcken hat und berichtet mir davon.", t = "Das Schicksal ruft"},
    [2281] = {ot = "Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius.", st = "Euch jetzt in den Einsatz zu schicken wäre Selbstmord. Renzik braucht nicht noch einen toten Schurken. Aber keine Sorge, $n... Renzik wird Euch schon Beine machen.$B$BGeht ins Rotkammgebirge und sprecht mit einem Mitglied des SI:7 namens Lucius. Ihr werdet ihn auf den Docks von Seenhain finden, wo er mit den anderen halbseidenen Taugenichtsen herumhängt.", t = "Rendezvous im Rotkammgebirge"},
    [2282] = {ot = "Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.", st = "Wir bilden hier schon seit Jahren Diebe aus! Schließlich wird nicht jeder Langfinger mit der Anmut und Finesse des alten Lucius geboren.$B$BOben an der Straße findet Ihr Althers Mühle. Ich habe dort oben eine Truhe mit wichtigem Inhalt. Holt sie für mich! Bringt mir diese Marke und Ihr bekommt Euer Zertifikat der Diebeskunst!", t = "Althers Mühle"},
    [2298] = {ot = "Reist nach Stormwind und sucht Renzik \"Das Messer\" auf.", st = "Wir war'n also grade dabei, Phase III zu planen, da platzen 'n paar von Magnis Holzköpfen hier rein, schwafeln was von 'ner Art Razzia und verhaften ein paar vom Verborgenen Kreis.$B$BSo springt keiner mit dem alten Blackbeard um! Die Diskussion wurde immer hitziger und irgendwann fiel Euer Name!$B$BMein Rat? Nehmt den ersten Greif aus Ironforge raus und geht nach Stormwind. Geht in die Altstadt und sprecht dort mit einem alten Freund von mir, der Renzik \"Das Messer\" genannt wird.", t = "Königliche Erpressung"},
    [2359] = {ot = "Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.", st = "Ich überwache diesen Turm jetzt schon seit Wochen, $n. Kürzlich kam eine größere Lieferung aus dem Dämmerwald an und mit dieser Lieferung kamen auch diese Wachen.$B$BWas sie sind? Das weiß ich genauso wenig wie Ihr. Eines kann ich Euch aber sagen: Menschen sind das nicht.$B$BWie dem auch sei, bei der Lieferung war eine Truhe dabei und ich vermute mal, das ist es, was diese Monstrositäten bewachen. Die Kreatur mit den Stacheln hat einen Schlüssel, den wir brauchen.$B$BBeschafft Euch den Schlüssel, dringt in den Turm ein und stellt fest, was in dieser Truhe ist. Berichtet dann Mathias, was Ihr herausgefunden habt.", t = "Klavens Turm"},
    [2360] = {ot = "Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten.", st = "Keinen Moment zu früh, $n. Spähtrupps des SI:7 berichten von ungewöhnlich intensiven Aktivitäten der Defias in Westfall.$B$BEs sieht so aus, als hätten die Defias einen verlassenen Wachturm der Allianz südlich der Späherkuppe übernommen und verwendeten diesen als Operationsbasis, um Güter von der Lieferroute ins Rotkammgebirge hereinzuschmuggeln.$B$BBegebt Euch nach Westfall und kontaktiert Agentin Kearnen. Sie wird Euch Bericht erstatten. Sie hält sich in der Nähe des Turms versteckt; dort findet Ihr sie.$B$B... und, $n, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.", t = "Mathias und die Defias"},
    [2378] = {ot = "Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul.", st = "Ihr habt den Schattenpirschern gut gedient, $n, aber vielleicht ist es an der Zeit, dass Ihr Euch nach draußen wagt. Zwar habt Ihr schon gezeigt, dass Ihr in der Kunst der Verstohlenheit und der Täuschung bewandert seid, doch Eure Ausbildung ist noch lange nicht beendet.$B$BDie Schattenpirscher haben Verbündete bei der Shattered-Hand. Sucht jemanden auf, der nichts dagegen hat, uns zu helfen: Shenthul in Orgrimmar.", t = "Suche nach der Shattered-Hand"},
    [2379] = {ot = "Sprecht an der Kluft der Schatten mit Zando'zan.", st = "Entschlossenheit allein reicht nicht aus, um die Hindernisse zu überwinden, die vor uns liegen.$B$BSprecht mit Zando'zan, um Eure Ausbildung als $gAgent:Agentin; der Shattered-Hand zu beginnen.$B$BErst wenn Ihr die Kunst der Verstohlenheit und die Diebeskunst gemeistert habt, könnt Ihr den nächsten Schritt auf Eurem persönlichen Weg des Schicksals gehen.", t = "Zando'zan"},
    [2381] = {ot = "Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.$B$BWenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!", st = "Ich will Euch keine Angst einjagen, $n, aber die letzten fünf Diebe, die ich ausgesandt habe, um den Schatz der Südmeerfreibeuter zu stehlen, sind in Stücken zu mir zurückgekommen.$B$BAn der Küste im Süden findet Ihr die Tide Razor, das Schiff der Südmeerfreibeuter. Unten im Laderaum findet Ihr das Gesuchte: den Schatz der Südmeerfreibeuter. Auf dem zweiten Deck des Schiffes findet Ihr die Piratenhöhle, dort bilden sie ihre Diebe aus.$B$BGeht an Bord dieses Schiffes, stehlt den Schatz und bringt ihn mir. Nutzt die Piratenhöhle, wenn Ihr Eure Diebeskunst üben wollt, aber seid vorsichtig!", t = "Das Ausplündern der Plünderer"},
    [2382] = {ot = "Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen.", st = "Zando'zan hat es gesehen! Ja, der Tag wird kommen! Thralls Tod... der Dolch in seinem Rücken, das Gift, das durch seine Adern fließt... Zando'zan hat schon zu viel gesagt.$B$B$n! Zando'zan hat eine Aufgabe für $n! $n muss nach Ratchet reisen, im Osten von Crossroads, und mit Wrenix dem Jämmerlichen sprechen. Los!", t = "Wrenix aus Ratchet"},
    [2383] = {ot = "Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", t = "Einfaches Pergament"},
    [2399] = {t = "Die sprießenden Wedel"},
    [2438] = {ot = "Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar.", st = "Einst erhielt ich von Gaerolas Talvethen, dem Bewacher der Druiden im Grabhügel von Ban’ethil, einen smaragdgrünen Traumfänger. Dieses mächtige Amulett ist in der Lage, Energie aus dem Smaragdgrünen Traum abzuziehen und damit denen, die es tragen, Glück zu bringen.$B$BLeider habe ich den Traumfänger nicht mehr aus meiner Kommode in Starbreeze holen können. Starbreeze war einst ein ruhiger Ort, aber jetzt ist er durch die Furbolgs, die sich dort aufhalten, der Verderbnis anheim gefallen.$B$BWärt Ihr vielleicht bereit, mir meinen Traumfänger wiederzubeschaffen, $C?", t = "Der smaragdgrüne Traumfänger"},
    [2458] = {ot = "Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.$B$BSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.$B$BEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert.", st = "Die Venture Company... Vielleicht habt Ihr von den Leuten schon gehört?$B$BEin Jahr lang haben wir daran gearbeitet, einen Agenten in ihre Reihen einzuschleusen. Endlich hatten wir - dank harter Arbeit und präziser Planung - Erfolg.$B$BVor kurzem haben wir jetzt gehört, dass die Venture Company irgendetwas Großes plant. Begebt Euch zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort unseren Undercover-Agenten, Zuchtmeister Fizzule.$B$BSobald Ihr den Turm gefunden habt, verwendet diese Leuchtfeuerwaffe und grüßt ihn mit dem Gruß der Shattered-Hand.", t = "Undercover"},
    [2459] = {ot = "Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet.", st = "Der Smaragd... Er ist weg! Mein Traumfänger ist beschädigt!$B$BEine Gruppe von Knarzklauenmystikern lebt im Norden von Starbreeze. Ich habe gehört, dass ihr Anführer, Ferocitas der Traumfresser, seit einiger Zeit eine Halskette trägt, die des Nachts grün leuchtet. Jetzt, wo ich meinen Traumfänger sehe, bin ich mir sicher, dass er meinen Smaragd gestohlen hat... Er würde nie verstehen, dass dessen Macht völlig nutzlos für ihn ist.$B$BFindet das verlorene Juwel, $n. Und wenn Ihr schon mal dort seid, erledigt auch gleich einige dieser verderbten Mystiker.", t = "Ferocitas der Traumfresser"},
    [2460] = {ot = "Führt Shenthul gegenüber den Shattered-Gruß aus.", st = "Als ein Schurke der Shattered-Hand müsst Ihr unbedingt den Shattered-Gruß erlernen. Dies ist die einzige Methode, mit der man ein anderes Mitglied der Hand zweifelsfrei identifizieren kann.$B$BSchaut zu, lernt, wiederholt.", t = "Der Shattered-Gruß"},
    [2478] = {ot = "Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.$B$BEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.", st = "Ihr müsst den Turmschlüssel von Großknecht Silixiz stehlen, $n. Sobald sich der Schlüssel in Eurem Besitz befindet, haltet ihn gut fest - ich könnte ihn später brauchen.$B$BVergesst nicht, das Gift hat alles in diesem Turm geschwächt. Wendet Eure Fähigkeiten an, um unter seinen Bewohnern Chaos und Zerstörung zu verbreiten. Erschlagt sie alle - zeigt keine Gnade!$B$BSobald sich dort drinnen nichts mehr rührt, knackt Ihr das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils Mixtur, der sich darin befindet. Bringt Shenthul in Orgrimmar sowohl Gallywix' Kopf als auch die Mixtur.", t = "Mission: möglich, aber nicht sehr wahrscheinlich"},
    [2479] = {ot = "Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.$B$BUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!", st = "Bringt eine Probe der Mixtur zu Serge Hinott nach Tarrens Mühle.$B$BWenn Euch überhaupt irgendjemand heilen kann, dann ist das Serge. Falls Ihr lange genug lebt, kann Serge Euch in der Kunst der Herstellung und Anwendung von Giften unterweisen.", t = "Hinotts Hilfe"},
    [2480] = {ot = "Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen.", st = "Noch nie habe ich gesehen, dass ein Gift so wundervolle Auswirkungen hatte! Zanzil, sagt Ihr? Nie von ihm gehört. Aber ich muss ihm zur Kreation dieses Gebräus gratulieren.$B$BTja, ich soll Euch also hiervon heilen und Euch dann beibringen, wie man das Gift anwendet?$B$BGebt mir einen Moment Zeit, damit ich das Toxin untersuchen kann, $n.", t = "Hinotts Hilfe"},
    [2498] = {ot = "Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht.", st = "Ich habe gerade erfahren, dass Denalan am Al'Amethsee herausgefunden hat, was der Grund für die Tumore sein könnte, von denen die Bäumlinge befallen sind. Bitte sprecht mit ihm und sagt ihm, dass ich Euch geschickt habe.$B$BSputet Euch, $n; er braucht unsere Hilfe.", t = "Rückkehr zu Denalan"},
    [2499] = {ot = "Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt.", st = "In einer Höhle am Südufer des Sees überträgt ein Bäumling namens Grimmeiche die Verderbnis auf alle Wesen, die am Al'Amethsee leben.$B$BIch habe mich nicht allzu nah herangewagt, aber selbst aus der Entfernung ist eines ganz klar: Grimmeiche wird von dem größten Tumor vergiftet, den ich je gesehen habe. Ich würde sogar sagen, er ist nicht nur groß, er ist riesengroß.$B$BIhr habt schon viel getan, um mir zu helfen, $n, und doch möchte ich Euch um einen weiteren Gefallen bitten. Spürt Grimmeiche auf und holt den Tumor. Entfernt diese Quelle der Verderbnis aus meiner Heimat!", t = "Grimmeiche"},
    [2518] = {ot = "Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt.", st = "Einst wurde Lady Sathrah von Elune geliebt. Grazil und rein spann die Spinne ihre silbernen Fäden im Mondlicht, wo sie den Abendnebel einfingen. Der silbrige Tau hatte starke Heilkräfte und wurde darum hier im Tempel aufbewahrt.$B$BDoch in jüngster Zeit ist Sathrah dem Wahnsinn verfallen. Auch die ihr nachfolgenden Generationen sind nun gefährdet.$B$BFindet Lady Sathrah, $n, und beendet ihr Leiden. Sie hält sich an der nördlichen Grenze von Teldrassil auf, in der Nähe des Wellspringsees. Sammelt ihre silbrigen Spinndrüsen und bringt sie mir.", t = "Tränen des Mondes"},
    [2519] = {ot = "Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht.", st = "Ein einstmals großes Wesen des Waldes benötigt Hilfe, $R.$B$BEine schwierige Aufgabe muss getan werden.$B$BBitte sucht Priesterin A'moora auf: Sie wird Euch alles erklären. Ihr findet sie südöstlich von hier im Tempel des Mondes.", t = "Der Tempel des Mondes"},
    [2520] = {ot = "Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.", st = "Jetzt müsst Ihr die Aufgabe vollenden, die Euch auferlegt worden ist. Nehmt die Spinndrüsen und bringt Elune Lady Sathrahs Opfer dar. Verschafft der großen Spinne die ewige Ruhe.$B$BBegebt Euch zum zentralen Brunnen in diesem Tempel. Dort könnt Ihr das Opfer niederlegen. Die heiligen Wasser werden die Verderbnis, durch die Sathrah in den Wahnsinn getrieben wurde, läutern und säubern.$B$BKommt zu mir zurück, sobald Ihr dies erledigt habt.", t = "Sathrahs Opferung"},
    [2541] = {ot = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.", st = "Die hier lebenden Schamanen der Knarzklauen haben einen Weg entdeckt, wie man den Geist eines schlafenden Druiden von seinem Körper trennen kann. Die Furbolgs haben meinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Ich selbst bin im Smaragdgrünen Traum gefangen und kann diesem Treiben keinen Einhalt gebieten.$B$BIhr müsst mir helfen. Die Knarzklauenschamanen tragen einen seltsamen Glücksbringer bei sich, mit dem dieses Ritual durchgeführt wird, und ich würde einen solchen Glücksbringer gern untersuchen. Bitte, $n, bringt mir einen.", t = "Der schlafende Druide"},
    [2561] = {ot = "Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet.", st = "Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, $n. Bitte nehmt ihn, und tut das, worum ich Euch bitte.$B$BIhr müsst die tiefsten Tiefen des Grabhügels von Ban'ethil erforschen. Dort findet Ihr meinen seelenlosen Körper. Und obwohl es mich sehr schmerzt, Euch das jetzt zu sagen, sehe ich keine andere Möglichkeit, wie ich mich der Kontrolle der Knarzklauen entziehen kann.$B$BDamit ich mich von ihnen befreien kann, müsst Ihr meinen physischen Körper töten. Sobald das getan ist, wendet den Voodooglücksbringer auf meinen gefallenen Körper an. Und wenn Ihr diese Aufgabe erfüllt habt, kommt zu mir zurück.", t = "Druide der Klaue"},
    [2607] = {ot = "Sprecht im Keller der Kaserne mit Doc Mixilpixil.", st = "Es scheint, als hättet Ihr mehr Informationen bekommen, als selbst ich erwartet hätte. Es ist schon seltsam, wie das Schicksal manchmal spielt, $n.$B$BEin Heilmittel? Hmm... Geht hinunter in den Keller und sprecht mit Doc Mixilpixil: Vielleicht kann er Euch helfen.", t = "Die Berührung von Zanzil"},
    [2608] = {ot = "Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?", st = "Meine Güte, Ihr seht ja aus wie der Tod. Nein, falsch. Ich habe den Tod schon gesehen - Ihr seht schlimmer aus. Ihr seht aus wie das, was der Tod bei seiner letzten Vorsorgeuntersuchung ausgespuckt hat.$B$BHa! Habt Ihr das gehört, Noarm? Schreibt das auf!$B$B<hustet> Ähem, ja, damit ich Euch helfen kann, muss ich Euch Blut abnehmen. Und keine Sorge, es tut nur die ersten... fünfzig Male oder so weh... Wenn Ihr bereit für die Behandlung seid, $n, solltet Ihr Euch bitte /hinlegen.", t = "Die Berührung von Zanzil"},
    [2609] = {ot = "Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, $gjunger Herr:junge Dame;.", st = "Wir sind einstimmig zu folgendem Schluss gekommen, $n... Ihr habt eine 'Itis'.$B$BZum Glück kann ich die 'Itis' heilen.$B$BUnd das brauche ich dafür: ein Bündel einfache Wildblumen, eine verbleite Phiole, eine Bronzeröhre und schließlich und endlich noch eine Rolle blassgelben Seidenfaden. Die alte Emma hat in 'Das feinste Band' eine Rolle davon für mich hinterlassen. Ihr findet den Laden an einem der Kanäle.$B$BBeeilt Euch jetzt, $n, und vermeidet es möglichst, jemanden anzufassen, bis Ihr geheilt seid. Dr. Montgomery meint übrigens, Ihr könntet eine Dusche vertragen - das hat er gesagt, nicht ich.", t = "Die Berührung von Zanzil"},
    [2745] = {ot = "Sprecht in Schloss Stormwind mit Tyrion.", st = "Hmm, eine interessante Geschichte und eine, die man nicht auf die leichte Schulter nehmen sollte. Ja, ich kann Euch helfen, aber wenn Ihr das wirklich bis zum Ende durchziehen wollt, dann müsst Ihr andere Saiten aufziehen, die... nicht ganz legal sind.$B$BLescovar und Marzon müssen erledigt werden, und zwar schnell. Glaubt Ihr, Ihr seid zu so was fähig?$B$BDie Entscheidung liegt bei Euch. Falls ja, dann geht so schnell wie möglich ins Schloss und redet dort mit einem Freund von mir, einem Gnom namens Tyrion. Er beobachtet Lescovar jetzt schon seit ein paar Wochen. Er sollte Euch dabei helfen können, die Sache zu Ende zu bringen.", t = "Eindringen ins Schloss"},
    [2746] = {ot = "Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion.", st = "Trias will also alles ein bisschen beschleunigen, wie? Na gut, können wir zwar machen, aber ich bin noch nicht bereit. Und damit eines mal klar ist: Ich hab den anstrengenderen Job, aber Ihr seid $gderjenige, der:diejenige, die; sich die Hände schmutzig macht, verstanden? Gut.$B$BAlso, Ihr müsst mir ein paar Sachen besorgen, bevor ich meinen Plan in die Tat umsetzen kann. Ich hab schon die perfekte Verkleidung, um den Spionagebot an den Wachen vorbeizubekommen.$B$BBringt mir etwas Seide und ein paar Äpfel. Wo Ihr die Seide herkriegt, ist Eure Sache, aber auf Claras kleinem Hof draußen vor der Stadt gibt es Äpfel in genau der richtigen Größe.", t = "Nicht unwichtige Gegenstände"},
    [2841] = {ot = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", st = "Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, $n!$B$BDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.$B$BTut, was Ihr tun müsst, um diese Kombination zu erlangen, $n. Dann öffnet den Safe und bringt mir diese Blaupausen!", t = "Maschinenkriege"},
    [2842] = {ot = "Sprecht mit Scooty in Booty Bay.", st = "In dem Moment, als wir durch Kernobee von der neuen Gnomen-Maschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.$B$BEndlich ist er bereit, Passagiere aufzunehmen, $n. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.$B$BNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!", t = "Chefingenieur Scooty"},
    [2843] = {ot = "Wartet, bis Scooty den Goblin-Transponder kalibriert hat.", st = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.$B$BIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.$B$BIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!$B$BJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", t = "Gnomer-weeeeg!"},
    [2904] = {ot = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay.", st = "<Kernobee stöhn.t> Was... Was ist passiert?$B$BDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.$B$BHolt mich hier raus, $n!$B$BSo ist der Plan: Bringt mich zum Ausgang; Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.$B$BGehen wir!", t = "Eine schöne Bescherung"},
    [2922] = {ot = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", st = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinander gebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!$B$BDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.$B$B", t = "Rettet Techbots Hirn!"},
    [2923] = {ot = "Sprecht mit Tüftlermeister Overspark in Ironforge.", st = "Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.$B$BWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!$B$BSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen.", t = "Tüftlermeister Overspark"},
    [2924] = {ot = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", st = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.$B$BBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.$B$BDanke, $n, und bitte beeilt Euch!", t = "Grundlegende Artifixe"},
    [2926] = {ot = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", st = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, $n.$B$BZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", t = "Gnogaine"},
    [2927] = {ot = "Sprecht mit Ozzie Togglevolt in Kharanos.", st = "Ihr glaubt doch wohl nicht, dass ich schon immer so kahlköpfig war, oder? Nein, $gwerter Herr:holde Dame;! Das Strahlungsleck in Gnomeregan rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte ich den einzigen Gnomen-Afro in ganz Azeroth.$B$B<Gnoarn schüttelt drohend die Faust.>$B$BVerdammt seien diese verdammten dreckigen Troggs, verdammt seien sie alle!$B$BVielleicht ist es noch nicht zu spät, $n. Wir können sie vielleicht immer noch retten - die Stadt, meine ich! Sprecht mit Ozzie Togglevolt in Kharanos. Er und sein Partner Razzle arbeiten an einer Lösung.", t = "Der Tag danach"},
    [2928] = {ot = "Bringt 24 robomechanische Innereien zu Shoni nach Stormwind.", st = "Es ist schrecklich, $n. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.$B$BWir brauchen Ersatzteile, $n. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.$B$BIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinander nehmen. Bringt mir ihre Innereien. Zwei Dutzend sollten ausreichen.", t = "Gyrobohrmatische Exkavation"},
    [2929] = {ot = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", st = "Ich habe Thermaplugg vertraut, $R. Ich hätte nie vermutet, dass er mich und das ganze Gnomen-Volk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts ...$B$BWir werden Gnomeregan zurückerobern, $n. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfach Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.", t = "Der große Verrat"},
    [2930] = {ot = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", st = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!$B$BIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung ... und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen ... Und wir haben alle Lochkarten in der Stadt vergessen.$B$BDas ist eine Katastrophe! Könnt Ihr helfen?", t = "Datenrettung"},
    [2945] = {ot = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", st = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.$B$BWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.", t = "Schmutzverkrusteter Ring"},
    [2947] = {ot = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", st = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.$B$BAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Ironforge. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen ...", t = "Die Rückkehr des Rings"},
    [2948] = {ot = "Bringt Talvash del Kissel in Ironforge den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", st = "Hört mir zu, $N. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...$B$BIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!$B$BVertraut mir!", t = "Gnomen-Verbesserungen"},
    [2949] = {ot = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", st = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.$B$BAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'$B$BDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder 'NOG' suchen - Entscheidungen, Entscheidungen ...", t = "Die Rückkehr des Rings"},
    [2950] = {ot = "Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", st = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom ...$B$BWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?", t = "Noggs Ringerneuerung"},
    [2951] = {ot = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", st = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:$B$B\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", t = "Der Funkelmat 5200!"},
    [2952] = {t = "Der Funkelmat 5200!"},
    [2962] = {ot = "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.$B$BOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist.", st = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.$B$BWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Brühschleimern, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", t = "Das einzige Heilmittel ist mehr grünes Leuchten"},
    [2983] = {ot = "Sucht Kranal Fiss im Brachland.", st = "Es ist eine Weile her, seit Ihr zuletzt geprüft wurdet, $n. Ihr wart in Euren Studien bisher sehr geduldig, doch es ist an der Zeit, dass Ihr etwas über größere Mächte erlernt... Es ist an der Zeit, dass Ihr wahre Macht erfahrt. Das Element des Feuers ist Euer, wenn Ihr bereit seid, dafür zu bezahlen.$B$BSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht... wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", t = "Ruf des Feuers"},
    [2984] = {ot = "Sucht Kranal Fiss im Brachland.", st = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, $n. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.$B$BSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", t = "Ruf des Feuers"},
    [2998] = {ot = "Sprecht mit Duthorian Rall in Stormwind.", st = "Seid gegrüßt, $GBruder:Schwester;. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.$B$BWenn ich Ihr wäre, würde ich nach Stormwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.", t = "Foliant der Offenbarung"},
    [2999] = {ot = "Sprecht mit Tiza Battleforge in Ironforge.", st = "Hallo, $n. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.", t = "Foliant der Offenbarung"},
    [3065] = {ot = "Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", t = "Einfache Schrifttafel"},
    [3082] = {ot = "Sprecht mit Jen'shan im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Geätzte Schrifttafel"},
    [3083] = {ot = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Verschlüsselte Schrifttafel"},
    [3084] = {ot = "Sprecht mit Shikrik im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Mit Runen beschriftete Schrifttafel"},
    [3085] = {ot = "Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Geheiligte Schrifttafel"},
    [3086] = {ot = "Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Glyphen-Schrifttafel"},
    [3087] = {ot = "Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Geätztes Pergament"},
    [3088] = {ot = "Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Verschlüsseltes Pergament"},
    [3089] = {ot = "Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Mit Runen beschriftetes Pergament"},
    [3090] = {ot = "Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.$B$BIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Besudeltes Pergament"},
    [3091] = {ot = "Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", st = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.", t = "Einfache Notiz"},
    [3092] = {ot = "Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa.", st = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.", t = "Geätzte Notiz"},
    [3093] = {ot = "Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", st = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.", t = "Mit Runen beschriftete Notiz"},
    [3094] = {ot = "Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache.", st = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.", t = "Tiefgrüne Notiz"},
    [3095] = {ot = "Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell.", st = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", t = "Einfache Rolle"},
    [3096] = {ot = "Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell.", st = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", t = "Verschlüsselte Rolle"},
    [3097] = {ot = "Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell.", st = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", t = "Geheiligte Rolle"},
    [3098] = {ot = "Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell.", st = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magielehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", t = "Glyphen-Rolle"},
    [3099] = {ot = "Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell.", st = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", t = "Besudelte Rolle"},
    [3100] = {ot = "Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Einfacher Brief"},
    [3101] = {ot = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Geweihter Brief"},
    [3102] = {ot = "Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien von Jorik, einem unserer örtlichen Lehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Verschlüsselter Brief"},
    [3103] = {ot = "Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien der Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Geheiligter Brief"},
    [3104] = {ot = "Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien von Kheldon, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Glyphen-Brief"},
    [3105] = {ot = "Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain.", st = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Lehrerinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Besudelter Brief"},
    [3106] = {ot = "Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Einfache Rune"},
    [3107] = {ot = "Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Paladinlehrer Bromos. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Geweihte Rune"},
    [3108] = {ot = "Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Jägerlehrer Thorgas. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Geätzte Rune"},
    [3109] = {ot = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Verschlüsselte Rune"},
    [3110] = {ot = "Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Geheiligte Rune"},
    [3112] = {ot = "Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Einfaches Memorandum"},
    [3113] = {ot = "Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Verschlüsseltes Memorandum"},
    [3114] = {ot = "Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magielehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Glyphen-Memorandum"},
    [3115] = {ot = "Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrer Alamar. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.$B$BUnd passt auf Euch auf, $n, man traut Leuten wie Euch hierzulande nicht gerade.", t = "Besudeltes Memorandum"},
    [3116] = {ot = "Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen.", st = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", t = "Einfaches Siegelzeichen"},
    [3117] = {ot = "Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen.", st = "Dieses Siegelzeichen  wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", t = "Geätztes Siegelzeichen"},
    [3118] = {ot = "Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen.", st = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Schurkenlehrerin Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", t = "Verschlüsselte Siegelzeichen"},
    [3119] = {ot = "Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil.", st = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", t = "Geheiligtes Siegelzeichen"},
    [3120] = {ot = "Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen.", st = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.", t = "Tiefgrünes Siegelzeichen"},
    [3221] = {ot = "Sprecht mit Apotheker Renferrel in dem Grabmal.", st = "Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.", t = "Sprecht mit Renferrel"},
    [3261] = {ot = "Sprecht im Camp Taurajo mit Jorn Skyseer.", st = "Eure Zeit bei mir ist vorbei, $n. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Skyseer sprechen. Er wird Eure Weiterbildung übernehmen.", t = "Jorn Skyseer"},
    [3281] = {ot = "Bringt das gestohlene Silber zu Gazrog in Crossroads.", st = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.$B$BGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.", t = "Gestohlenes Silber"},
    [3301] = {ot = "Sprecht mit Mura Runetotem in dem Grabmal.", st = "Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.$B$BBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.", t = "Mura Runetotem"},
    [3361] = {ot = "Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.", st = "Wir haben die Troggs aus Gnomeregan vertrieben, aber dann ist alles schrecklich schief gegangen! Jetzt ist unsere Heimat völlig von Strahlen verseucht und wir Gnome sind überall in Dun Morogh zerstreut.$B$BIn meiner Hast, der Strahlung zu entkommen, habe ich all mein ganzes Hab und Gut und auch meine Werkzeuge verloren. Die Trolle haben sie geholt. Sie haben meine Truhe, meine Kiste, und meinen Bolzeneimer gestohlen! Alles das haben sie in ihre Lager südwestlich von Anvilmar mitgenommen.$B$BIch bin nur leider kein Abenteurer - könntet Ihr bitte meine Sachen suchen und sie mir herbringen?", t = "Dilemma eines Flüchtlings"},
    [3364] = {ot = "Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!", st = "Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Furcutter im Anvilmar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Anvilmar schaffen, bevor das Gebräu kalt wird!$B$BIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Anvilmar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.$B$BDanke, $n, und vergesst nicht, mir meinen Becher zurückzubringen!", t = "Lieferung des kochend heißen Morgengebräus"},
    [3365] = {ot = "Bringt Nori Pridedrift den Becher zurück.", st = "Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.$B$BHier, bitte $n... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?", t = "Den Becher zurückbringen"},
    [3369] = {ot = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.", st = "Dieser Splitter enthält große Geheimnisse; er ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe, ist kein Traum, diese Art der Vision ist eher ein Alptraum.$B$BIch möchte Euch nicht beunruhigen, $n, aber ich denke, es ist am besten, wenn Ihr diesen Splitter so schnell wie möglich in die Hände eines weisen Druiden gebt.$B$BIhr müsst Hamuul Runetotem auf der Anhöhe der Ältesten finden. Geht nach Thunder Bluff. Mehr vermag ich Euch nicht zu sagen.", t = "Alptraum"},
    [3370] = {ot = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.", st = "Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.$B$BIch möchte Euch nicht beunruhigen, $n, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt ... $B$BIhr müsst Mathrengyl Bearwalker im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.", t = "Alptraum"},
    [3376] = {ot = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.", st = "$n... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.$B$BWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!$B$BIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.", t = "Tötet Spitzhauer!"},
    [3519] = {ot = "Sprecht mit Dirania Silvershine in Shadowglen.", st = "Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.$B$BSagt es bitte Dirania Silvershine. Sie wird mir helfen können.$B$BBeeilt Euch... Mir ist so schwindelig...", t = "Ein Freund in Not"},
    [3521] = {ot = "Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.", st = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.$B$BIch brauche Hyazinth-Pilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grell südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.$B$BDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.", t = "Iverrons Gegengift"},
    [3522] = {ot = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.", st = "Das Gegengift ist fertig, $n. Bitte achtet darauf, dass Iverron es auch trinkt.$B$BEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.$B$BMögen Eure Füße beflügelt sein, $n.", t = "Iverrons Gegengift"},
    [3524] = {ot = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", st = "Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.$B$BEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?", t = "An Land gespült"},
    [3741] = {ot = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", st = "Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.$B$BKönnt Ihr die Kette bitte für uns suchen?", t = "Hilarys Halskette"},
    [3765] = {ot = "Reist zu Gershala Nightwhisper in Auberdine.", st = "Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.$b$bIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.$b$bMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.$b$bDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener $C sein, so wie Ihr.", t = "Verderbnis in der Fremde"},
    [3901] = {ot = "Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid.", st = "Ihr habt den Verlassenen Euer Potenzial unter normalen Umständen gezeigt, $n. Jetzt wollen wir mal sehen, wie es damit bestellt ist, wenn Ihr unter Druck steht.$B$BDie klappernden Skelette, weitere hirnlose Diener des Lichkönigs, sind zähere Feinde als die Zombies, mit denen Ihr es bisher zu tun hattet. Auch hier heißt es wieder: Dünnt ihre Reihen aus und beweist den Verlassenen, dass Ihr der Aufgabe gewachsen seid. Frisch ans Werk ... und redet wieder mit mir, wenn Ihr fertig seid.", t = "Klappernde Skelette"},
    [3902] = {ot = "Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück.", st = "Ihr da! Wenn Ihr Euch irgendwie nützlich machen wollt, dann hört zu!$B$BWir benötigen frisch erweckte Rekruten, die sich nach Deathknell begeben und dort nach allem suchen, was wir irgendwie gebrauchen können. Die Dinge werden sich höchstwahrscheinlich in gestapelten Kästen befinden. Wir rechnen damit, dass sich in Kürze weitere Rekruten erheben werden, und wenn wir nicht wollen, dass die nackt herumtappen, dann müssen wir wohl oder übel was für sie suchen.$B$BAlso, macht Euch an die Arbeit, elendes Knochengestell! Und ohne ein bisschen Eile gibt es auch keine Belohnung.", t = "Beutesuche in Deathknell"},
    [3903] = {ot = "Sprecht mit Milly Osworth.", st = "Ihr habt Euch als verlässlich erwiesen, $n. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?$B$BTja, eine Freundin von mir, Milly Osworth, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.", t = "Milly Osworth"},
    [3904] = {ot = "Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.", st = "Eine Bande von Briganten, die Defias, sind in die Weinberge von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.$B$BBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie in den Weinbergen im Südosten zurückgelassen.$B$BBringt mir diese Kisten! Rettet meine Ernte!", t = "Millys Ernte"},
    [3905] = {ot = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", st = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.$B$BIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", t = "Traubenliste"},
    [3921] = {ot = "Bringt das zerbrochene Samophlang zu Wenikee Boltbucket.", st = "Ich glaube, ich habe das Samophlang zerbrochen. Das ist schlecht, denn ich habe schon einigen Kollegen aus Undermine davon erzählt, und die waren äußerst fasziniert. Wir müssen einen Weg finden, es zu reparieren!$B$BBringt das zerbrochene Samophlang zu Wenikee Boltbucket beim Außenposten der Horde, zwischen dem Brachland und Ashenvale. Sie ist sehr schlau und wissbegierig. Wenn Ihr ihr das Samophlang zeigt, dann, wette ich, stürzt sie sich sofort darauf und will es reparieren.", t = "Wenikee Boltbucket"},
    [3922] = {ot = "Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland.", st = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Nugget-Patronen mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.$B$BDer nächstgelegene Ort, an dem man sie bekommen kann, ist das Schlickermoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Geht ins Schlickermoor und schaut in den Werkzeugkisten nach, die Ihr dort findet. Kommt zu mir zurück, sobald Ihr genug Nugget-Patronen gesammelt habt.", t = "Nugget-Patronen"},
    [3923] = {ot = "Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob.", st = "Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber ... ich glaube, das würde alles nur noch schlimmer machen.$B$BIhr solltet das Samophlang zu Rilli Greasygob bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.$B$BIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.", t = "Rilli Greasygob"},
    [3924] = {ot = "Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob.", st = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Copperplug. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...$B$BBoss Copperplug war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.", t = "Samophlang-Handbuch"},
    [4021] = {ot = "Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads.", st = "Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!$B$BStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.$B$BWir zählen auf Euch, $n.", t = "Gegenangriff!"},
    [4161] = {ot = "Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.", st = "Vor langer Zeit nannte man die Nachtelfen 'Kaldorei', was übersetzt 'Kinder der Sterne' bedeutet. Für Euch als $C ist es besonders wichtig etwas über die Vergangenheit zu erfahren, also hört gut zu, was ich Euch zu sagen habe, $n.$B$BDie Kaldorei waren schon immer stolz auf ihre harmonische Beziehung zur Natur. Das bedeutet, dass wir von der Natur nur nehmen, was notwendig ist, und es in gleichem Maße vergelten. Dieses Gleichgewicht bedeutet uns viel, $n.$B$BGeht und sammelt sieben kleine Spinnenbeine - und nicht mehr, und kommt dann zu mir zurück.", t = "Rezept der Kaldorei"},
    [4402] = {ot = "Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.", st = "Hier im Tal der Prüfungen wird es ganz schön heiß.$B$B<Galgar wischt sich den Schweiß von der Stirn.>$B$BWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.$B$BIch sag Euch was, $n. Wenn Ihr mir 10 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt, und schenke Euch dazu noch ein Ausbildungshandbuch. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", t = "Galgars Kaktusapfel Surprise"},
    [4495] = {ot = "Sucht Iverron an der Höhle im Norden.", st = "Ich habe einen Freund, Iverron, der mich normalerweise jeden Tag um dieselbe Zeit besucht. Komischerweise ist er heute noch nicht da gewesen - genau genommen ist er sogar schon etliche Stunden über seiner sonstigen Zeit.$B$BIch muss zugeben, ich bin etwas besorgt, $n. Iverron verbringt viel Zeit bei der Spinnenhöhle oben im Norden und ich bin sicher, Ihr wisst, wie gefährlich es dort ist - überall Spinnen!$B$BFalls Ihr zufällig dort vorbeikommen solltet, könntet Ihr dann nach ihm Ausschau halten?", t = "Ein guter Freund"},
    [4542] = {ot = "Bringt Klippenbehüter Longhorn am Freiwindposten die dringende Nachricht.", st = "$gTapferer Reisender:Tapfere Reisende;, die Zentauren haben ihre Angriffe in diesem Gebiet verstärkt. Der Freiwindposten muss umgehend über diese erneuten Angriffe informiert werden! Sucht Klippenbehüter Longhorn am Freiwindposten im Südosten auf und gebt ihm diese dringende Nachricht.$b$bDoch seht Euch vor und geht dem hier in der Nähe herumlungernden Grimmtotemklan aus dem Weg... in letzter Zeit benehmen die Leute sich seltsam uns gegenüber.", t = "Nachricht zum Freiwindposten"},
    [4581] = {ot = "Bringt Shindrells Notiz zu Kayneth Stillwind in Forest Song.", st = "Der Druide Kayneth Stillwind hat sich bei mir gemeldet. Er hätte gern einen Bericht über das, was an unserer Küste und in den Wäldern um Astranaar vorgeht. Er befürchtet, dass eine Verderbnis durch Ashenvale zieht... und vielleicht hat er Recht damit.$B$BHier, bringt ihm meinen Bericht. Ihr werdet ihn im Schrein von Forest Song finden, in den Nightsongwäldern im Osten.", t = "Kayneth Stillwind"},
    [4641] = {ot = "Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen.", st = "Endlich seid Ihr alt genug, $n... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.$B$BJa...$B$B<Kaltunk mustert Euch.>$B$BDoch, doch, Ihr eignet Euch.$B$BZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.$B$B<Kaltunk lacht.>$B$BMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, $C. Ihr findet Gornek im Höhlenbau im Westen.", t = "Euer Platz in der Welt"},
    [4681] = {ot = "Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.", st = "Die gestrandete Kreatur ist kein Einzelfall hier in Dunkelküste. Entlang der Ufer und sogar im Wasser gibt es noch mehr davon. Ich möchte, dass Ihr einen weiteren Fall untersucht, von dem wir wissen - da wurde die Kreatur westlich von Auberdine im Meer gesichtet, und zwar in der Nähe eines gesunkenen Schiffes. Kommt mit allem, was Ihr findet und was uns bei unseren Forschungen behilflich sein könnte, zu mir zurück.$B$BAußerdem begegnet Ihr auf Euren Reisen vielleicht auch noch anderen Kreaturen. Falls Ihr etwas entdecken solltet, dann zögert bitte nicht und informiert uns darüber!", t = "An Land gespült"},
    [4722] = {ot = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Ihr findet den Kadaver einer Meeresschildkröte, die sich vor einiger Zeit an das Ufer von Dunkelküste an den Strand geworfen hat. Der Kadaver wurde von den Murlocs gefleddert, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", t = "Gestrandete Meeresschildkröte"},
    [4723] = {ot = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Die Überreste eines riesigen Dreschers - viel größer als alles, was Ihr in Dunkelküste zu finden erwartet hättet - liegen gestrandet an der Küste des Nebelrandes. Wie es diese Kreatur hierher verschlagen hat, ist nicht zu sagen - die Murlocs, die sich jetzt an dem Gerippe gütlich tun, sehen viel zu schwach aus, als hätten sie, selbst in großer Anzahl, die Bestie erlegen können. $B$BWährend ein Teil des Kadavers bereits sauber abgenagt wurde, ist doch noch genug davon übrig, um Gwennyth Bly'Leggonde aus Auberdine eine Probe zur Untersuchung bringen zu können.", t = "Gestrandete Meereskreatur"},
    [4725] = {ot = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Entlang der Küste liegen weitere Überreste von gestrandeten Meeresschildkröten. Bei diesem speziellen Kadaver ist eine Art Sänfte auf dem Panzer der Schildkröte angebracht. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Grauflossenmurlocs haben sich jetzt an den Überresten der Kreatur niedergelassen und fressen das Aas.$B$BIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", t = "Gestrandete Meeresschildkröte"},
    [4727] = {ot = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Am Sandstrand im Norden von Dunkelküste liegen die skelettierten Überreste einer Meeresschildkröte. Entweder haben die Grauflossenmurlocs dieses Gerippe nicht gefunden, oder sie haben es zwar gefunden, halten sich aber aus irgendeinem unbekannten Grund davon fern. Wie dem auch sei, es ist genug von der Schildkröte übrig, dass Ihr Gwennyth Bly'Leggonde in Auberdine eine Probe bringen könnt, damit der Tempel des Mondes diese studieren kann.", t = "Gestrandete Meeresschildkröte"},
    [4728] = {ot = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Der Kadaver von etwas, das wie ein riesiger Meeressäuger aussieht, liegt teilweise ausgeweidet am Strand. Eine Schubkarre und verschiedenste Werkzeuge liegen bei der riesigen, gestrandeten Meereskreatur verstreut, ganz so, als habe schon einmal jemand den Versuch unternommen, sie zu untersuchen. Zwar wurde die Bestie bereits von Murlocs zerfleddert, doch es ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde aus Auberdine einzusammeln.", t = "Gestrandete Meereskreatur"},
    [4730] = {ot = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Am Strand liegt der halb aufgefressene Kadaver von etwas, das vielleicht einmal ein riesiger Meeressäuger war. Eine Bande Murlocs, stärker als diejenigen, die näher an Auberdine zu finden sind, haben ihr Lager um die verendete Kreatur herum aufgeschlagen. Es ist noch genug von der Kreatur übrig, um Gwennyth Bly'Leggonde in Auberdine eine passende Probe ihrer Knochen bringen zu können.", t = "Gestrandete Meereskreatur"},
    [4731] = {ot = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Erneut findet Ihr gestrandete Meeresschildkrötenüberreste. Bei diesen Überresten ist eine Art Sänfte auf dem Panzer der Schildkröte festgeschnallt. Vielleicht wurde diese Kreatur von unbekannten Wesen an den Strand getrieben, statt sich selbst auf Strand zu setzen, wie sich aus einigen der anderen Überreste schließen ließ. Mächtige Grauflossenmurlocs haben sich beim Gerippe der Kreatur niedergelassen.$B$BIn der Sänfte findet Ihr einen Kasten mit seltsamen Zeichen darauf - vielleicht kann Gwennyth Bly'Leggonde in Auberdine sich einen Reim darauf machen.", t = "Gestrandete Meeresschildkröte"},
    [4732] = {ot = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Ihr findet den Kadaver einer Meeresschildkröte, die sich selbst vor einiger Zeit an das Ufer von Dunkelküste auf Strand gesetzt hat. Der Kadaver ist schon fast vollständig von Grauflossenmurlocs abgefressen worden - eben jenen Murlocs, die um die Überreste der Kreatur herum ihr Lager aufgeschlagen haben. Dennoch scheinen an den Überresten der Kreatur noch einige geeignete Proben zu haften, aus denen Gwennyth Bly'Leggonde aus Auberdine vielleicht noch etwas machen kann.", t = "Gestrandete Meeresschildkröte"},
    [4733] = {ot = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.", st = "Die Überbleibsel dessen, was anscheinend einmal ein riesiger Drescher war, wurden an den steinigen Gestaden des Zwielichtufers angeschwemmt. Der Drescher ist wesentlich größer als alle anderen Drescher, die in diesen Landesteilen gesichtet wurden. Wo immer die Kreatur auch hergekommen sein mag, es scheint nicht so, als sei sie in Dunkelküste heimisch.$B$BObwohl das Wesen schon stellenweise angefressen wurde, ist noch genug davon übrig, um eine passende Probe für Gwennyth Bly'Leggonde in Auberdine einzusammeln.", t = "Gestrandete Meereskreatur"},
    [4740] = {ot = "Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.$B$BInformiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.", st = "Achtung!$B$BEine Belohnung wird ausgesetzt für den Tod des Murlocs \"Gurgelbacke\". Diese üble Bestie ist nachgewiesenermaßen verantwortlich für den Tod mindestens einer Schildwache und wird verdächtigt, den Untergang von mindestens zwei Frachtschiffen in den Gewässern vor Dunkelküste verursacht zu haben!$B$BZuletzt wurde Gurgelbacke an einem Barackenlager der Murloc südlich von Auberdine gesehen. Es wird angenommen, dass er die Hütten dort verteidigt. Das Kopfgeld kann bei Schildwache Glynda Nal'Shea in Auberdine eingefordert werden.$B$BDer Dorfrat von Auberdine", t = "GESUCHT: Gurgelbacke!"},
    [4761] = {ot = "Sprecht mit Thundris Windwirker in Auberdine.", st = "Beim Erkunden des Furbolglagers seid Ihr auf Neuigkeiten gestoßen, über die Ihr Thundris Windwirker informieren solltet. Er fungiert umsichtig als der Älteste von Auberdine und kümmert sich weise und gerecht um die täglichen Angelegenheiten des Dorfs. Bitte setzt ihn von den Dingen, die Ihr bislang über die Furbolgangelegenheit in Erfahrung gebracht habt, in Kenntnis.$B$BIch glaube, er hat bezüglich der Gründe für deren Verderbnis seine eigene Theorie. Vielleicht könnt Ihr zusammen mit ihm einen Plan erarbeiten, mit dem das Gleichgewicht der Natur hier wiederhergestellt werden kann!", t = "Thundris Windwirker"},
    [4762] = {ot = "Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.$B$BKehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück.", st = "Der Cliffspring wird immer verderbter. Er mündet in Nebelrand und ich fürchte, dass sich das verunreinigte Wasser bald auf Auberdine auswirken wird. Ich halte die Furbolgs der Schwarzfelle flussaufwärts für den Auslöser der Besudelung, aber ich vermute auch, dass sie nicht die wahre Ursache sind.$B$BNehmt diesen Probenbehälter und begebt Euch zur Mündung des Flusses nördlich von hier. Geht weiter landeinwärts bis zum ersten Wasserfall und entnehmt dem Teich dort eine Probe. Oberhalb davon seht Ihr eine Brücke. Kommt zu mir nach Auberdine zurück, sobald Ihr die Probe habt.", t = "Der Cliffspring"},
    [4763] = {ot = "Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.$B$BHolt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.$B$BMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.$B$BNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.", st = "Wir haben herausgefunden, dass die Satyrn ein Grund für die Verderbnis der Furbolgs sind. Sie sollen ihre Macht durch Talismane ausüben, mit denen sie ihre Magie kanalisieren können. Damit die Furbolgs Aussicht auf Rettung haben, müssen wir den Satyrverderber aus seinem Versteck locken und ihm diesen Talisman abnehmen!$B$BFüllt diese Schale an unserem Mondbrunnen und holt aus dem Lager der Furbolgs im Norden ein paar Proben ihrer Lebensmittel. Mischt alles zusammen und stellt die Schale in die Nähe des Freudenfeuers am Fluss. Sobald die Furbolgs davon essen, werden sie lang genug gesäubert, um den Satyrverderber herauszulocken... Den Ihr dann töten müsst!", t = "Die verderbten Schwarzfelle"},
    [4767] = {ot = "Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen.", st = "Mir wurde aufgetragen, weitere Flügeldrachen für die Meisterwindreiter zu rekrutieren. Sie werden immer mehr und ich hoffe, selbst eines Tages ein Windreiter zu werden. Wie dem auch sei, wir können gar nicht genug Flügeldrachen auszubilden, um der Nachfrage gerecht zu werden. Vielleicht könnt Ihr mir helfen, $n.$B$BIch möchte, dass Ihr zum Steilhang reist, um dort ein paar Flügeldracheneier zu sammeln. Geht von hier aus nach Nordwesten entlang der Talwände, bis zu einer Rampe, die in das Gebiet des Steilhangs hineinführt. Seid vorsichtig, Flügeldrachen haben einen starken Beschützerinstinkt, was ihre Eier angeht, und schätzen keine Eindringlinge.", t = "Windreiter"},
    [4770] = {ot = "Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane.", st = "Bitte helft mir, $C! Ich verstecke mich jetzt schon eine ganze Weile hier am Steilhang und seit Tagen habe ich kein freundliches Gesicht mehr gesehen. Ich kam hierher, um die Flügeldrachen zu studieren, und bin dabei wohl etwas zu dicht herangekommen. Nachdem ich von einem der Nester verjagt wurde, habe ich mich verlaufen.$B$BIch muss zum Weißgipfelposten zurückkehren! Motega weiß nicht, dass ich vermisst werde, und er wird wütend sein, wenn er hört, dass ich allein zum Steilhang gegangen bin.$B$BDer Weißgipfelposten liegt direkt östlich von hier ... bringt mich bitte dorthin!", t = "Auf der Heimreise"},
    [4811] = {ot = "Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", st = "Im Osten streifen immer mehr feindliche Moonkin umher. Man dachte einst, dass sie sanftmütige, fast mystische Kreaturen wären. Wenn auch viele ihnen weiterhin Ehrfurcht entgegenbringen, zwingt mich die Sicherheit Auberdines, die Sache realistischer zu sehen.$B$BIch habe Berichte erhalten, dass es die Moonkin zu einem großen roten Kristall an der östlichen Bergkette von Dunkelküste zieht. Niemand weiß, was dieser Kristall ist oder ob er wirklich existiert. Ich möchte, dass Ihr ihn dort sucht und mir meldet, was Ihr vorgefunden habt.", t = "Der rote Kristall"},
    [4812] = {ot = "Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", st = "Benutzt diese leere Phiole und füllt hier in Auberdine Mondbrunnenwasser hinein. Solch mächtige Magie sollte einen Hinweis auf die Zusammensetzung des Kristalls liefern. Zu diesem Zweck gießt Ihr etwas Flüssigkeit über den Kristall; alles Weitere sollte sich dann von selbst ergeben.$B$BWenn ich auch nicht erwarte, dass Euch etwas Böses zustoßen könnte, möchte ich dennoch, dass Ihr vorsichtig seid. Über uns im Osten liegt der Teufelswald; falls dieser Kristall mit jenem Ort verbunden ist, wie ich es vermute, könnte sich das als sehr gefährlich erweisen.", t = "Wenn das Wasser fließt"},
    [4813] = {ot = "Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", st = "Das Mondbrunnenwasser hat enthüllt, dass im Inneren des Kristalls einige kleine Knochenfragmente sowie ein Teil eines Kieferknochens eingebettet sind. Der Kieferknochen scheint menschlich zu sein, aber um Klarheit darüber zu gewinnen, müsste man den Kristall aufbrechen - eine Leistung, die sogar für die stärkste Magie schier unmöglich erscheint.$B$BDa Ihr die gestellte Aufgabe erfüllt habt, bleibt nur noch, Schildwache Glynda Nal'Shea in Auberdine Bericht zu erstatten.", t = "Die Fragmente im Inneren"},
    [4821] = {ot = "Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei.", st = "Es wurde ein Gerücht über ein fremdartiges Ei hier in Tausend Nadeln in Umlauf gebracht. Diejenigen, die dieses Ei gesehen haben, konnten aber nicht nahe genug herankommen, um es ausführlich zu untersuchen. Schlangen bewachen das Ei, als wäre es eines ihrer eigenen.$B$BIch möchte, dass Ihr dieses fremdartige Ei sucht und es mir bringt, damit ich es untersuchen kann. Berichten zufolge soll sich das Ei in einem Schlangenbau befinden, aber es gibt mehrere Schlangenbaue entlang des Fußes der Klippenwand südlich und nordöstlich des Freiwindpostens.", t = "Fremdartiges Ei"},
    [4841] = {ot = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück.", st = "$n, ich flehe Euch an, diese Zentauren zur Strecke zu bringen. Sie sollen den Zorn unserer Rache spüren. Greift das Zentaurenlager im Norden des Freiwindpostens an! Lasst den Zorn Eure Hand führen!", t = "Befriedung der Zentauren"},
    [4865] = {ot = "Berichtet Motega Firemane von Euren Entdeckungen.", st = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich es nie für möglich gehalten haben. Die Rache kam nach Tausend Nadeln!$B$B<Hagar wischt sich den Schweiß von der Stirn.>$B$B$n, Ihr müsst Euch beeilen! Geht sofort los und sucht Motega Firemane auf. Ihr findet ihn im Weißgipfelposten nordwestlich des Freiwindpostens, entlang der Straße. Er wird wissen, was zu tun ist!", t = "Wilde Schlange"},
    [4881] = {ot = "Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten.", st = "Der Tauren Kanati Greycloud war so dreist, in Tausend Nadeln ein Jägerlager aufzuschlagen. Wir müssen ihn töten, damit dieses Jägerlager und alle, die ihm möglicherweise folgen, verschwinden. Wir werden uns dem kleinen Posten südwestlich des großen Aufzugs nähern.", t = "Auftragsmordplan"},
    [4904] = {ot = "Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide.", st = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er... er tötete meinen Bruder, dann brachte er mich hierher. Mein armer Bruder...$B$B$n, würdet Ihr mich wohl vom Düsterwolkengipfel hinab geleiten? Bitte... ich muss zu Thalia zurückkehren! Sie macht sich bestimmt große Sorgen um mich.", t = "Endlich frei"},
    [4921] = {ot = "Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.", st = "Wir wurden getrennt, als wir in einem kleinen Taurenlager gemeinsam kämpften - sie hat drei Borstennacken im Alleingang bezwungen. Aber dann waren sie plötzlich in der Überzahl. Ich lockte ein paar fort, dann sah ich, wie sie von Neuankömmlingen überwältigt wurde. Rasend vor Zorn stellte ich mich meinen Feinden, aber da es derer so viele waren, ging ich schon bald zu Boden.$B$BIch kam im Zelt eines Taurendruiden zu mir, der meine Wunden versorgte - er kam zufällig die Goldstraße entlang, als ich fiel.$B$BBitte, $C, sucht nach einem Lebenszeichen von meiner Frau.", t = "In der Schlacht vermisst"},
    [4966] = {ot = "Beschützt Kanati Greycloud vor den Angriffen der Zentauren.", st = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, $N, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.", t = "Kanati Greycloud schützen"},
    [5041] = {ot = "Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück.", st = "Die Karawane, die angegriffen wurde, führte Vorräte mit sich, die wir dringend benötigen.$B$BIhr wart bisher tapfer genug, den Grimmhauerstamm zu bekämpfen, und ich werde Euch bitten, es erneut zu tun. Dieses Mal wüsste ich aber gern, ob ich Euch bitten könnte, nach unseren verlorenen Vorräten Ausschau zu halten. Ihr könnt sie wahrscheinlich in ihren Lagern finden; die Stacheleber werden durch ihre schändlichen Taten fett.$B$BDie Einwohner von Crossroads wären in Eurer Schuld.", t = "Vorräte für Crossroads"},
    [5052] = {ot = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.$B$BSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet.", st = "Zusammen mit diesen Dornen wirkte sich das Blut <schnaubt> auf andere Aspekte der Erde aus: blutrote Steine gemischt mit anderen Mineralien. Die Borstennacken graben diese Splitter aus und tragen sie als Totems <schnaubt> für Kraft im Kampf und als Totems für ihre Magie. <schnaubt>$B$BIch kenne die Geheimnisse dieser Magie.$B$BBringt Quetschzahn einen dieser Blutsplitter, um zu zeigen, dass Ihr verstanden habt. Bringt Quetschzahn viele dieser Splitter und er wird Euch mit Stachelebermagie segnen - der Magie von Agammagan! <schnaubt>", t = "Blutsplitter von Agammagan"},
    [5061] = {ot = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen.", st = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Mathrengyl Bearwalker nach Darnassus zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.$B$BAuf Wiedersehen. Wir werden uns wieder sprechen.", t = "Wassergestalt"},
    [5062] = {ot = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff.", st = "Arikara ist eine tödliche Kreatur, die schnell beseitigt werden muss. Um sie zur Strecke zu bringen, müsst Ihr das hochheilige Feuer des Lebens anzünden - so wird Arikara beschworen.$B$BGeht nun und holt eine seltene Pflanze, die Brandpulveragave. Wenn Ihr genug Agaven gesammelt habt, sucht den Rat von Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff. Sie ist eine mächtige Schamanin, die die Agavenpflanze verzaubern kann, um ein Pulver zu erzeugen, das das Feuer entzünden kann.$B$BReist in Richtung Osten zum Siedenden Teich und sammelt Brandpulveragaven.", t = "Hochheiliges Feuer"},
    [5064] = {ot = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", st = "$n, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten. Wir haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.$b$b$n, wenn Ihr bei dieser gefährlichen Mission erfolgreich seid, werde ich Euch entsprechend belohnen.", t = "Grimmtotemspionage"},
    [5088] = {ot = "Tötet Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Taten.", st = "Nehmt dieses veredelte, gereinigte Brandpulver nach Tausend Nadeln mit und werft es in das hochheilige Feuer des Lebens. Ihr findet es im Düsterwolkengipfel auf einer abgeschiedenen Nadel, wo sie ihre Toten bergaben.$B$BDie Magie, die ich in das Brandpulver gewoben habe, beschwört Arikara für Euch, $n.$B$BIch fürchte, dass sie Cairne Bloodhoof verfolgt. Es hat sich zu viel in der Geschichte der Tauren getan und ich habe die Befürchtung, dass dieser Umstand Arikara erzürnt hat. Beeilt Euch, bevor es zu spät ist, $C!", t = "Arikara"},
    [5147] = {ot = "Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten.", st = "Gesucht: Arnak Grimmtotem$B$BArnak der Ausgestoßene wird wegen ruchloser Verbrechen des Mordes und der Entführung gesucht. Ansehnliche Belohnungen winken dem, der mutig genug ist, diesen Verbrecher der Gerechtigkeit zuzuführen.$B$BArnak wurde zuletzt auf den Klippen in der Nähe des Düsterwolkengipfels gesehen. Zeigt dem Klippenbehüter Longhorn im Freiwindposten den Beweis Eurer Tat, um die Belohnung zu beanspruchen.", t = "GESUCHT: Arnak Grimmtotem"},
    [5151] = {ot = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück.", st = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist. Ha! Sogar die Zentauren erzittern in Anwesenheit dieser wilden Bestie!$B$BHier ist der Schlüssel zu dem Käfig. Sie haben alles dorthin gebracht, ihn aber in Ruhe gelassen. Erledigt diese Bestie, bringt meinen Hyperkondensator zurück und ich werde Euch belohnen.$b$bDie überfallene Karawane befindet sich nördlich von hier.", t = "Hyperkondensator-Dingsda"},
    [5261] = {ot = "Sprecht mit Eagan Peltskinner.", st = "Eagan Peltskinner sucht nach jemandem, der für ihn Wölfe jagt. Das ist gut, da wir es hier im Nordhaintal in letzter Zeit verstärkt mit Wölfen zu tun haben.$B$BWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", t = "Eagan Peltskinner"},
    [5321] = {ot = "Eskortiert Kerlonian Evershade zu Liladris Moonriver nach Süden entlang der Straße, um seine Tasche in Dunkelküste zu finden.", st = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Moonriver zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...\n\n<gähnt>\n\nUnd ich kann meine Sachen nirgends finden! Könntet Ihr mir helfen, sie zu finden?\n\nIch weiß, dass Maestras Posten südlich von hier ist, entlang der Straße in Ashenvale. Ich bin von dort gekommen...\n\nAußerdem könnte ich einschlafen. Wenn Ihr mich also einmal aufwecken müsst, dann benutzt dazu bitte mein Horn. Ihr findet es in der Truhe hier.", t = "Der Schläfer ist erwacht"},
    [5441] = {ot = "Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", st = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.$B$BIhr seht wie geschaffen für meinen Auftrag aus, $R. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.$B$BVerdammte faule Peons ...", t = "Faule Peons"},
    [5481] = {ot = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof.", st = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.$b$bWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland auf Brill-Friedhof.", t = "Gordos Aufgabe"},
    [5482] = {ot = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", st = "Ihr seht also die Zwickmühle, in der ich mich befinde, $n. Dieses Ding da draußen sammelt die falschen Kräuter! Ich werde Euch dafür belohnen, wenn Ihr sammelt, was ich wirklich benötige. Bringt mir genug Verdammniskraut und ich werde Euch eine angemessene Belohnung geben.$B$BSoweit mir bekannt ist, verseucht es gern die Flora in der Nähe des Massengrabs, nördlich des Friedhofes von Brill. Beeilt Euch und hütet Euch vor den Gnollen in dem Gebiet.", t = "Verdammniskraut"},
    [5541] = {ot = "Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.", st = "Hegnar Schlingerschuss verkauft Gewehre an der Straße nach Ambossar. Scharfschützen und Mörsertrupps verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition.$B$BAber... die letzte Munitionskiste, die ich ihm geschickt habe, ist unterwegs verloren gegangen. Mein Kurier sagte, er lagerte nahe des Graufelsbaus, als Wendigos ihn davonjagten... und der Dummkopf hat Schlingerschuss' Munition zurückgelassen!$B$B$n, könnt Ihr diese Munition beschaffen und zu Schlingerschuss bringen? Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.", t = "Munition für Rumbleshot"},
    [5545] = {ot = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", st = "Ich habe hier ein echtes Problem. Ich habe einen Liefertermin für eine Bestellung Holz und mir läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben meine Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten.$B$BIch habe bereits mit Deputy Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber ich brauche jemanden, der das Holz für mich holt. Wenn Ihr acht Holzbündel für mich holen würdet, könnte ich den Termin vielleicht noch einhalten.", t = "Ein Bündel Probleme"},
    [5621] = {ot = "Sucht die Schildwache Shaya und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morninglight in Dolanaar zurück.", st = "Ich brauche Eure Hilfe, $n. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen. Sie wurde beim Patrouillieren der Stadt verletzt und benötigt unsere Hilfe. Ihr Name ist Shaya.$B$BWenn Ihr sie findet, heilt Ihre Wunden, und stärkt dann Ihren Körper mit Euren Zaubern. Das wird sie zumindest etwas länger vor Schaden bewahren, wenn es wieder hart auf hart kommt. Kehrt zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.", t = "Gewänder des Mondes"},
    [5622] = {ot = "Sprecht mit Laurna Morninglight in Teldrassil.", st = "$n, sobald Eure Aufgaben hier in Shadowglen abgeschlossen sind, müsst Ihr nach Dolanaar reisen. Dort werdet Ihr Laurna Morninglight finden. Sie wird Euch weiter in den Dingen Elunes unterweisen und bei ihr werdet Ihr Euch Eure ersten Gewänder verdienen, die Eure Position als $GPriester:Priesterin; von Elune kennzeichnen.$B$BSeid vorsichtig und möget Ihr auf Euren Reisen beschützt werden.", t = "Elune geneigt"},
    [5623] = {ot = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.", st = "Ich grüße Euch, $Gjunger Priester:junge Priesterin;. Die Zeit ist gekommen, mehr über unsere Religion zu lernen. Nachdem Ihr Eure Aufgaben hier in Nordhain abgeschlossen habt, sucht bitte Priesterin Josetta in Goldhain auf. Sie kann Euch noch mehr beibringen und hat gehört, dass Ihr in den Wegen des Lichts gut voranschreitet. Sie freut sich darauf, Euch weiter unterrichten zu können.", t = "Dem Licht geneigt"},
    [5624] = {ot = "Sucht die Wache Roberts und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Priesterin Josetta in Goldhain zurück.", st = "Normalerweise stelle ich den Gefolgsleuten des Lichts eine kleine Herausforderung, um ihre Fertigkeiten zu prüfen. Ich möchte sehen, ob sie es wert sind, ihre ersten Roben zu tragen - sie sind ein Zeichen, dass die Kirche $gden Priester:die Priesterin; nach außen hin trägt und unterstützt.$B$BDoch hier ist die Situation etwas anders. Einer der Bürger von Goldhain sah eine verletzte Wache nahe dem See östlich von hier. Er heißt Roberts. Sucht ihn, heilt ihn, stärkt seinen Körper und kehrt hierher zurück. Wenn Ihr das für mich tun könnt, dann werde ich Eure Prüfung als bestanden ansehen.", t = "Gewänder des Lichts"},
    [5625] = {ot = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", st = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.$B$BWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", t = "Gewänder des Lichts"},
    [5626] = {ot = "Sprecht mit Maxan Anvol in Dun Morogh.", st = "He! $n! Habt Ihr einen Moment Zeit?$B$BIhr seid dem Licht jetzt lange genug gefolgt, um den Weg zu Maxan Anvol in Kharanos zu finden. Er wird Euch mehr über den Weg beibringen, dem Ihr folgt, und wenn Ihr Euch als würdig erweist, wird er Euch Eure ersten Roben geben, die Eure Position als $GPriester:Priesterin; kennzeichnen.$B$BAlso dann mal los! Sobald Ihr hier fertig seid, geht durch den Tunnel - er wird auf Euch warten.", t = "Dem Licht geneigt"},
    [5629] = {ot = "Sprecht mit der Priesterin Alathea in Darnassus.", st = "Hallo, $n. Ich weiß, dass Ihr damit beschäftigt wart, unserem Volk zu helfen, aber Ihr müsst Euch auch Zeit für Euch selbst nehmen. Die Priesterin Alathea hat jemanden hergeschickt, um nach Euch zu suchen. Es scheint, dass Ihr die Aufmerksamkeit unserer Ältesten erregt habt, und sie sind der Meinung, dass Ihr für größere Dinge bereit seid. Begebt Euch zum Tempel des Mondes in Darnassus und sucht dort nach Alathea. Sie wird Euch erwarten. Viel Glück, und möge Elune mit Euch sein.", t = "Heimkehr"},
    [5634] = {ot = "Sprecht mit Hohepriester Rohan in Ironforge.", st = "Ein Priester hat kürzlich unsere Hallen besucht und Euch gesucht, $R. Er sagte, er hätte den Auftrag, Euch zu finden, und dass Ihr so bald wie möglich zur Halle der Mysterien in Ironforge zurückkehren solltet. Wenn Ihr ankommt, sucht Hohepriester Rohan auf - er wird Euch mehr berichten.$B$BDas Licht sei mit Euch, $n.", t = "Verzweifeltes Gebet"},
    [5641] = {t = "Züchtigung"},
    [5642] = {ot = "Sprecht mit Ur'kyo in Orgrimmar.", st = "In Orgrimmar geht etwas Wichtiges vor, $n.$B$BNormalerweise sind die Boten, die hier durchkommen und nach Trollpriestern suchen, recht umgänglich. Dieses Mal schienen sie jedoch in großer Eile zu sein. Trödelt nicht zu lange in Donnerfels herum. Ich würde so schnell wie möglich zum Tal der Geister zurückkehren.", t = "Schattenwache"},
    [5644] = {ot = "Sprecht mit Aelthalyste in Undercity.", st = "Ah, ein wundervoller Tag für Euch, $n. Aufgrund der Lektionen, die Ihr gelernt habt, kann ich sehen, dass die Zeit gekommen ist, Euch zu Aelthalyste zurückzuschicken. Es gibt Dinge, die nur sie Euch beibringen kann, und auch das nur, wenn Ihr Euch als würdig erweist.$B$BIch werde die Überraschung für Euch nicht verderben, aber ich erinnere mich daran, wie es war, als ich ein junger Priester war und etwas über die wahre Macht lernte...die göttliche Macht. Ja, das waren noch Zeiten.$B$BKehrt zu Aelthalyste nach Unterstadt zurück, $n. Sie erwartet Euch im Kriegsviertel.", t = "Dunkles Opfer"},
    [5648] = {ot = "Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", st = "Ihr seid bereit für Eure erste Prüfung, $n. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Proudmores alten Truppen bekämpfte. Es geht ihr nicht allzu gut und es wäre wirklich gut, wenn einer unserer Art ihr helfen könnte. Sucht sie - ihr Name ist Kor'ja -, heilt ihre Wunden und gebt ihr den Segen unserer Vorfahren.$B$BWenn Ihr das tut, sehe ich das als ausreichenden Beweis dafür an, dass Ihr bereit seid, unseren Pfad weiter zu beschreiten.", t = "Gewänder der Spiritualität"},
    [5649] = {ot = "Sprecht mit Tai'jin in Durotar.", st = "Ja, Mann. Unser Volk hat sich der Horde angeschlossen, weil sie gut für uns ist. Die da sind loyal und lehren uns viel über Dinge wie Ehre. Aber unsere alten Gewohnheiten sterben nur langsam. Die Orcs mögen nicht alle unsere Traditionen billigen, aber das bedeutet nicht, dass wir einige davon nicht im Geheimen ausüben können.$B$BIhr wisst das, und darum schicke ich Euch zu Tai'jin in Klingenhügel. Sie wird Euch mehr über unsere Geschichte lehren. Sie wird Euch in den Wegen unseres Stammes unterrichten. Geht zu ihr, wenn Ihr bereit seid.", t = "Der Spiritualität geneigt"},
    [5650] = {ot = "Findet die Todeswache Kel und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryl in Brill zurück.", st = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, $n, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen. Das ist weise. Doch bevor Ihr die Dunkelheit kennen lernen könnt, müsst Ihr erst das Licht kennen. Und daher habe ich eine Prüfung für Euch.$B$BNördlich des Friedhofs befindet sich eine verwundete Todeswache - Todeswache Kel. Er hat uns seit geraumer Zeit vor Gnollen beschützt und braucht Heilung. Doch Ihr müsst auch seinen Körper stärken, bevor er seinen Dienst wieder aufnehmen kann. Tut beides mit Euren Zaubern und kehrt dann zu mir zurück.", t = "Gewänder der Dunkelheit"},
    [5651] = {ot = "Sprecht mit dem Dunklen Kleriker Beryl in Tirisfal.", st = "Es gibt viele Lektionen, die die Verlassenen durch Erfahrung gelernt haben... Dinge, die einige Völker allenfalls erahnen können. Und obwohl unser Weg in Dunkelheit liegt, werdet Ihr feststellen, dass sehr viele Dinge sowohl vom Licht als auch von der Dunkelheit abhängen. Eure Lektionen sollen Euch lehren, beides zu nutzen... mit Umsicht. Aber beachtet meine Worte: vergesst nie, wir wurden in die Verderbnis gezwungen und der Fäulnis überlassen wie ein Stück Aas. Die Dunkelheit ist unser Heim.$B$BSucht den Dunklen Kleriker Beryl in Brill auf, wenn Ihr bereit seid, mehr zu erfahren.", t = "Der Dunkelheit geneigt"},
    [5654] = {ot = "Sprecht mit Ur'kyo in Orgrimmar.", st = "Es ist an der Zeit, Euch mit Ur'kyo zu treffen, $n. Er befindet sich im Tal der Geister in der Orc-Stadt. Geht dorthin und sprecht mit ihm. Es ist an der Zeit, dass Ihr mehr über die alten Wege unserer Art lernt. Es wird Zeit, dass Ihr in den Kreis eingeführt und zu einem wahren Priester unseres Stammes gemacht werdet.", t = "Verhexung der Schwäche"},
    [5658] = {t = "Berührung der Schwäche"},
    [5672] = {t = "Elunes Anmut"},
    [5676] = {t = "Arkane Rückkopplung"},
    [5713] = {ot = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale.", st = "Ich war mit einer wichtigen Nachricht auf dem Weg nach Auberdine, als ich von dem Furbolg Marosh und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde ich vergiftet, wodurch ich kaum noch stehen konnte. Ich kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.$B$BIch möchte Euch bitten, mich zu verteidigen, bis ich das Gegengift anwenden kann. Ich werde Euch, so gut es geht, mit meinem Bogen helfen.$B$BFalls wir überleben, kann ich meine Botschaft nach Auberdine überbringen, während Ihr mit Onaeya bei Maestras Posten sprecht, um sie von diesem Vorfall zu unterrichten.", t = "Ein Schuss, ein Treffer"},
    [5722] = {ot = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", st = "Die Troggs sind nicht das Einzige, das Magatha im Ragefireabgrund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird ... und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.$B$BBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.$B$BBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.", t = "Die Suche nach dem verloren gegangenen Ranzen"},
    [5723] = {ot = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück.", st = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.$B$BSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Ragefireabgrund und vernichtet sie alle.", t = "Die Kraft des Feindes wird auf die Probe gestellt"},
    [5724] = {ot = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff.", st = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.$B$BIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Thunder Bluff zurückzukehren.", t = "Wiederbeschaffung des verloren gegangenen Ranzens"},
    [5725] = {ot = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity.", st = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.$B$BEine Sekte des Schattenrates, die sich Searingblade nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Searingblade in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", t = "Die Macht der Zerstörung..."},
    [5726] = {ot = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar.", st = "Eines werde ich in meinen Reihen auf keinen Fall dulden, $n: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.$B$BAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.$B$BWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir die Insignie eines Offiziers der Burning Blade dort und kehrt zu mir zurück.", t = "Verborgene Feinde"},
    [5727] = {ot = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", st = "Und jetzt lasst uns sehen, ob die Insignie, die Ihr gefunden habt, der Mühe wert ist.$B$BIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Burning Blade. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.$B$BBringt diese Insignie zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", t = "Verborgene Feinde"},
    [5728] = {ot = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", st = "Hmmm, Anführer der Searingblade... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.$B$BKehrt zur Kluft der Schatten zurück und begebt Euch in den Ragefireabgrund, $n. Findet diese beiden Anführer der Searingblade und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für $gseinen Kampfgenossen:seine Kampfgenossin; halten.", t = "Verborgene Feinde"},
    [5729] = {ot = "Sprecht mit Neeru Fireblade in Orgrimmar.", st = "Ich glaube, unser nächster Schritt sollte sein, Euch in Neerus Nähe unterzubringen. Falls er wirklich so beunruhigt ist, wie die Berichte vermuten lassen, könnten wir zwei Fliegen mit einer Klappe schlagen. Erstens könntet Ihr mehr über den Rat oder zumindest die Searingblade in Erfahrung bringen, und zweitens könnte er Euch möglicherweise genug vertrauen, um Euch zu bitten, ihm zu helfen. Vielleicht wird er Euch für jemanden halten, der die Lücken füllt, die der Tod der Anführer gerissen hat.$B$BKehrt zur Kluft zurück und sprecht noch einmal mit ihm, aber haltet Euch bedeckt.", t = "Verborgene Feinde"},
    [5730] = {ot = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.", st = "Ihr seid einer meiner Offiziere! Macht Euch bereit, $C. Ich werde Euch bald benötigen.$B$BDie Zeit, die ich für die Searingblade aufgebracht hatte, war jetzt vielleicht reine Zeitverschwendung, aber das bedeutet nicht, dass die restlichen Pläne des Schattenrates darunter leiden müssen. Ich werde tun, was ich kann, um den Schaden hier im Ragefireabgrund zu begrenzen. In der Zwischenzeit sollen meine Agenten im Brachland und in Ashenvale mit der Arbeit an unserem neuesten Geheimplan beginnen. Kommt bald zu mir zurück.", t = "Verborgene Feinde"},
    [5761] = {ot = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar.", st = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Burning Blade sind eine Gefahr, aber es gibt auch noch andere. Die Searingblade zum Beispiel, die sich im Ragefireabgrund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.$B$BUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.$B$BTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", t = "Vernichtung der Bestie"},
    [5881] = {ot = "Maggran möchte, dass Ihr Grish Longrunner am großen Aufzug im Brachland einen Brief zustellt.", st = "Die Horde kümmert sich gut um ihre Truppen... seit dem großen Krieg ging es uns hier in Kalimdor sehr gut.$B$BIhr müsst mir einen Gefallen tun. Ich lasse einen Jungen namens Grish Longrunner den großen Aufzug im südlichen Brachland bewachen. Gebt ihm diesen Brief, er wird ihn wissen lassen, dass ich einen Ersatzmann angefordert habe, um ihn von seinem Dienst zu entbinden, damit er seine Familie besuchen kann. Er bat mich vor einer Weile darum und wird sich über diese Nachricht freuen.", t = "Hinzurufen der Reserve"},
    [5921] = {ot = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", st = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Staghelm und dem Bewahrer Remulos, dem Wächter von Moonglade. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.$B$BAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, $gjunger Druide:junge Druidin;.", t = "Moonglade"},
    [5922] = {ot = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", st = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - Moonglades Wächter - wacht über allen Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.$B$BAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, $gjunger Druide:junge Druidin;.", t = "Moonglade"},
    [5923] = {ot = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", st = "Entschuldigung...$B$BEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.$B$BEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", t = "Dem Ruf folgen"},
    [5928] = {ot = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", st = "Entschuldigung...$B$BEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.$B$BEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", t = "Dem Ruf folgen"},
    [5929] = {ot = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", st = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.$B$BGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", t = "Großer Bärengeist"},
    [5930] = {ot = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", st = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.$B$BGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", t = "Großer Bärengeist"},
    [5931] = {ot = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius.", st = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bearwalker bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.$B$BGeht jetzt. Wir sehen uns wieder.", t = "Zurück nach Darnassus"},
    [5932] = {ot = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.", st = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runetotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.$B$BGeht jetzt. Wir sehen uns wieder.", t = "Zurück nach Thunder Bluff"},
    [6001] = {ot = "Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.$B$BSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.", st = "Unmittelbar östlich von Auberdine liegen viele Moonkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Moonkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.$B$BIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, $n... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", t = "Körper und Herz"},
    [6002] = {ot = "Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.$B$BSprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.", st = "Auf Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Moonkinstein. Moonkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.$B$BIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, $n... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", t = "Körper und Herz"},
    [6061] = {ot = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", st = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.$B$BAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", t = "Die Zähmung der Bestie"},
    [6062] = {ot = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", st = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.$B$BEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.$B$BAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", t = "Die Zähmung der Bestie"},
    [6063] = {ot = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", st = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.$B$B$n, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.$B$BEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", t = "Die Zähmung der Bestie"},
    [6064] = {ot = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", st = "Hallo, $GBursche:Mädchen;! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?$B$BGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!$B$BAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", t = "Die Zähmung der Bestie"},
    [6081] = {ot = "Sprecht mit Ormak Grimshot in Orgrimmar.", st = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.$B$BReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimshot sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn nahe der Halle der Kriegerhelden.$B$BViel Glück, $n.", t = "Die Ausbildung des Tiers"},
    [6082] = {ot = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", st = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.$B$BWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", t = "Die Zähmung der Bestie"},
    [6083] = {ot = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", st = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, $n! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.$B$BDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", t = "Die Zähmung der Bestie"},
    [6084] = {ot = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.", st = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.$B$BNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", t = "Die Zähmung der Bestie"},
    [6085] = {ot = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", st = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!$B$BWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.", t = "Die Zähmung der Bestie"},
    [6086] = {ot = "Sprecht mit Belia Thundergranite in Ironforge.", st = "$n, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.$B$BReist nach Ironforge und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Thundergranite sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, $GBursche:Mädchen;.$B$BBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, $n.", t = "Die Ausbildung des Tiers"},
    [6087] = {ot = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", st = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.$B$BAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.$B$BIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.$B$BHier habt Ihr die Zähmrute, $n. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", t = "Die Zähmung der Bestie"},
    [6088] = {ot = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", st = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.$B$BWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", t = "Die Zähmung der Bestie"},
    [6089] = {ot = "Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff.", st = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.$B$BReist nach Thunder Bluff. Dort müsst Ihr mit Holt Thunderhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.$B$BHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, $n.", t = "Die Ausbildung des Tiers"},
    [6101] = {ot = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", st = "Auf die Vielfalt der Natur kann man sich verlassen, $n. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.$B$BDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.$B$BNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", t = "Die Zähmung der Bestie"},
    [6102] = {ot = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", st = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.$B$BWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", t = "Die Zähmung der Bestie"},
    [6103] = {ot = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", st = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.$B$BReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.$B$BJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, $n.", t = "Die Ausbildung des Tiers"},
    [6121] = {ot = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.", st = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, $n. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.$B$BReist nach Moonglade und sprecht mit Dendrite Starblaze. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", t = "Neue Lektionen"},
    [6122] = {ot = "Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.$B$BBringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste.", st = "Cliffspring Falls in Dunkelküste dient als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.$B$BWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nightsong in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", t = "Die eigentliche Ursache"},
    [6123] = {ot = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.", st = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.$B$BUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Moonkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", t = "Das Heilmittel sammeln"},
    [6124] = {ot = "Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.", st = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, $n. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.$B$BDendrite Starblaze in Moonglade wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", t = "Heilung der Kranken"},
    [6125] = {ot = "Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück.", st = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.$B$BIhr solltet jetzt zu Mathrengyl Bearwalker in Darnassus zurückkehren, $n. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.$B$BLebt wohl, junger Druide. Wir sprechen uns wieder.", t = "Macht über Gift"},
    [6181] = {ot = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", st = "Wir bekommen zwar nicht viel Unterstützung von Stormwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Stormwind.$B$BUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?$B$BDer schnellste Weg nach Stormwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Stormwind.", t = "Eine eilige Nachricht"},
    [6261] = {ot = "Bringt Osrics Kiste zu Dungar Longdrink dem Greifenmeister.", st = "$n, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?$B$BWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Longdrink ist unser Greifenmeister drüben im Handelsdistrikt.$B$BSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", t = "Dungar Longdrink"},
    [6281] = {ot = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Stormwind.", st = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Stormwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.$B$BWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", t = "Weiter nach Stormwind"},
    [6282] = {ot = "Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", st = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.$B$BDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.$B$BIhr müsst die Harpyen für mich dezimieren, $n!", t = "Harpyien drohen"},
    [6283] = {ot = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", st = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!$B$BFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.$B$BGeht zurück zum verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", t = "Blutfuriengeschlecht"},
    [6284] = {ot = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", st = "Warnung: Betretet Sishir Canyon westlich von hier auf eigene Gefahr.$B$BBesseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnen Unterschlupf erkoren.$B$BMaggran Earthbinder in Sonnenfels hat ein Kopfgeld auf Besseleth ausgesetzt. Tötet sie und bringt einen Beweis Eurer Tat zu Maggran. Dort werdet Ihr eine Belohnung erhalten, wenn Ihr der achtbeinigen Gefahr ein Ende gemacht habt.", t = "Arachnophobie"},
    [6285] = {ot = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Longdrink, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", st = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.$B$BDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.$B$BIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", t = "Zurück zu Lewis"},
    [6301] = {ot = "Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", st = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.$B$B$n, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.$B$BWenn Ihr mir die Samenkörner bringt, werde ich sie mit schamanistischer Macht magieerfüllen, um ihr Wachstum zu beschleunigen.", t = "Zyklus der Wiedergeburt"},
    [6321] = {ot = "Bringt Podrigs Liste zu Karos Razok.", st = "Exekutor Hadrec bat mich, eine Inventur unserer Ausrüstung beim Grabmal durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.$B$BIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.$B$BHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendham in Undercity. Bringt die Anforderungsliste zum Fledermausmeister Karos Razok und sprecht mit ihm über den Transport zur Undercity.", t = "Nachschub für das Grabmal"},
    [6322] = {ot = "Bringt Gordons Kiste zu Michael Garret.", st = "Ich habe den Nachschub für das Grabmal in diese Kiste getan. Wenn Ihr das Grabmal schon besucht und mit dem Fledermausmeister gesprochen habt, könnt Ihr mit einer Fledermaus zu ihm reiten.$B$BSprecht mit Michael Garret, dem Fledermausmeister von Undercity. Er kann Euch eine Fledermaus zum Grabmal zur Verfügung stellen.", t = "Michael Garrett"},
    [6323] = {ot = "Bucht einen Fledermausritt zur Undercity bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendham in Undercity.", st = "Gegen eine geringe Gebühr kann Euch eine meiner Fledermäuse zur Undercity bringen. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport vereinbaren können.$B$BIhr findet Gordon Wendham im Handwerksviertel von Undercity. In diesem Viertel landet auch meine Fledermaus.", t = "Flug nach Undercity"},
    [6324] = {ot = "Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garret und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal.", st = "Der Fledermausmeister im Grabmal ist Karos Razok. Wenn Ihr schon bei ihm gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihm fliegen könnt.$B$BUnsere Fledermäuse fliegen stets zur Undercity, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.$B$BIhr habt Karos im Grabmal getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", t = "Rückkehr zu Podrig"},
    [6341] = {ot = "Bringt Nessas Sammlung zu Vesprystus.", st = "Den Anglern des Dorfes Rut'theran geht es sehr gut, denn die Fische dort sind extrem groß und zahlreich. Ich würde die hier vorkommenden Arten gern mit denen des Festlandes vergleichen.$B$BIch habe eine Sammlung von Fischgräten und Schuppen, die ich gern zu einem Kollegen von mir in Dunkelküste bringen würde. Er heißt Laird und ist ein Fischverkäufer im Dorf Auberdine.$B$BBringt meine Sammlung zu unserem Hippogryphenmeister Vesprystus und besprecht mit ihm, wie Ihr am besten nach Auberdine kommt.", t = "Die Arten von Teldrassil"},
    [6342] = {ot = "Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird.", st = "Von Rut'theran gibt es zwei Reisemöglichkeiten nach Auberdine: mit der Fähre und mit einem Hippogryphen. Beide sind schnell und zuverlässig, aber wenn Ihr noch nicht mit dem Hippogryphen nach Auberdine geflogen seid, solltet Ihr das schleunigst nachholen.$B$BEin guter Rat: Sprecht in jeder Stadt, in der es einen gibt, mit dem Hippogryphenmeister. Sobald Ihr mit dem Meister gesprochen habt, könnt Ihr von anderen Städten aus dorthin fliegen.$B$BHier ist Nessas Sammlung. Sprecht wieder mit mir, wenn Ihr bereit seid, nach Auberdine zu fliegen und Nessas Sammlung bei Laird abzuliefern.", t = "Flug nach Auberdine"},
    [6343] = {ot = "Bringt Lairds Antwort zu Nessa Shadowsong.", st = "Ich muss Nessa eine Antwort schicken. Sie interessiert sich bestimmt dafür, wie sehr sich die Fische hier von denen an der Küste Teldrassils unterscheiden. Wir können nur vermuten, was die Ursache sein mag, ich persönlich hege jedoch die Befürchtung, dass der Weltbaum die Natur um sich herum beeinflusst!$B$BBitte bringt Nessa diese Antwort. Wenn Ihr einen Hippogryphen zurück nach Rut'theran nehmen wollt, dann sprecht mit der Hippogryphenmeisterin Caylais Moonfeather. Wenn Ihr die Fähre nehmen wollt, so ist auch das kein Problem: Es legt regelmäßig eine vom Dock im Nordwesten ab.", t = "Rückkehr zu Nessa"},
    [6344] = {ot = "Sprecht mit Nessa Shadowsong.", st = "Eine Freundin von mir, Nessa Shadowsong, ist Anglerbedarfshändlerin in Rut'theran. Sie muss ein Päckchen nach Dunkelküste bringen und sucht jemanden, der ihr hilft.$B$BWenn Ihr zu Nessa wollt, dann müsst Ihr in Darnassus das Portal nach Rut'theran benutzen. Ihr findet das Portal westlich der Tempelgärten.", t = "Nessa Shadowsong"},
    [6361] = {ot = "Bringt das Bündel Bälge zu Windreitermeister Devrak in Crossroads.", st = "Ich habe ein Bündel Bälge von Tieren des Brachlands und muss es nach Thunder Bluff bringen. Dort fertigt Ahanu, ein Kollege, Lederwaren aus diesen Häuten an.$B$BBringt Ihr ihm die Bälge für mich?$B$BDer schnellste Weg nach Thunder Bluff ist auf dem Rücken eines Windreiters. Bringt das Bündel Bälge zu Devrak, unserem Windreitermeister in Crossroads, und sprecht mit ihm über den Transport nach Thunder Bluff.", t = "Ein Bündel Bälge"},
    [6362] = {ot = "Bucht einen Windreiter nach Thunder Bluff bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Thunder Bluff.", st = "Für ein kleines Entgelt gebe ich Euch einen Windreiter nach Thunder Bluff. Es gibt kein schnelleres Transportmittel in die Stadt!$B$BSollte das akzeptabel sein, sprecht wieder mit mir, wenn Ihr abreisefertig seid.$B$BWenn Ihr diese Bälge zu Ahanu bringen wollt, dann schätze ich, er ist in Hewas Waffenkammer am Fundament des Windreiterturms in Thunder Bluff. Und genau dort werdet Ihr landen!", t = "Flug nach Thunder Bluff"},
    [6363] = {ot = "Bringt Ahanus Lederwaren zu Tal in Thunder Bluff.", st = "Ich habe Lederwaren für Jahan zum Verkauf in Crossroads vorbereitet. Würdet Ihr sie ihm bringen?$B$BWenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem unserer Thunder-Bluff-Windreiter zu ihm zurück.$B$BBringt die Lederwaren zu Tal, unserem Windreitermeister in Thunder Bluff, und sprecht mit ihm über den Transport nach Crossroads.", t = "Tal der Windreitermeister"},
    [6364] = {ot = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Hawkwing.", st = "Um zu einer Stadt zu fliegen, müsst Ihr schon einmal dort gewesen sein und mit dem Windreitermeister dieser Stadt gesprochen haben. Ihr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr gegen ein geringes Entgelt von hier mit einem unserer Windreiter zu ihm.$B$BSprecht wieder mit mir, wenn Ihr bereit seid. In Crossroads könnt Ihr die Lederwaren zu Jahan Hawkwing bringen.", t = "Rückkehr zu Jahan"},
    [6365] = {ot = "Bringt Zarghs Fleisch zu Devrak in Crossroads.", st = "Ich habe hier ausgewählte Fleischstücke, die ich einer Freundin schicken möchte. Ihr Name ist Gryshka, sie ist die Gastwirtin in Orgrimmar. Würdet Ihr das Fleisch für mich abliefern?$B$BDas schnellste Transportmittel nach Orgrimmar ist ein Windreiter. Bringt das Fleisch zu Crossroads Windreitermeister Devrak und sprecht mit ihm über den Transport nach Orgrimmar.", t = "Fleisch für Orgrimmar"},
    [6381] = {ot = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels.", st = "Wie Ihr sehen könnt, $C, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im verbrannten Tal. Aber seid wachsam, denn Harpyien und Feuerelementare verseuchen das vernarbte Land noch immer.$B$BNehmt diese verzauberten Gaeasamenkörner und pflanzt sie in fruchtbare Erdhügel, $n. Der Zyklus des Lebens muss weitergehen!", t = "Neues Leben"},
    [6382] = {ot = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", st = "Eure Kraft beeindruckt mich, $C. Die Entschlossenheit, mit der Ihr Euch der Jagd zuwendet, erfüllt mich mit der Gewissheit, dass Ihr Euch größerem Wild... und größeren Herausforderungen zuwenden könnt.$B$BDer Wald von Ashenvale ist eine große, ungezähmte Wildnis, der die Horde ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Wenn Ihr Euch in einem unerforschten Land beweisen wollt, dann sucht die Führung von Senani Thunderheart im Splintertreeposten. Der Außenposten liegt nördlich des Pfads, der aus dem Brachland führt.", t = "Die Jagd in Ashenvale"},
    [6383] = {t = "Die Jagd in Ashenvale"},
    [6384] = {ot = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleisch zu Gryshka in Orgrimmar.", st = "Für eine Handvoll Münzen lasse ich Euch mit einem Windreiter nach Orgrimmar bringen. Wenn Ihr dort eintrefft, bringt Zarghs Fleisch zu Gryshka. Ihr Gasthaus liegt im Tal der Stärke, nicht weit vom Himmelsturm entfernt, wo mein Windreiter Euch absetzen wird.$B$BSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", t = "Flug nach Orgrimmar"},
    [6385] = {ot = "Bringt Gryshkas Brief zu Doras in Orgrimmar.", st = "Ich habe Zargh einen Dankesbrief geschrieben. Könnt Ihr ihn für mich zustellen? Wenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem Windreiter dorthin zurück fliegen.$B$BBringt meinen Brief zu Forak, dem Windreitermeister von Orgrimmar, und sprecht mit ihm über den Transport nach Crossroads.", t = "Doras der Windreitermeister"},
    [6386] = {ot = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh in Crossroads.", st = "Meine Windreiter wurden ausgebildet, an viele verschiedene Orte zu fliegen, wenn Ihr schon an diesem Ort gewesen seid und mit dem Windreitermeister dort gesprochen habt.$B$BIhr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr jetzt direkt zu ihm fliegen. Wenn Ihr in Crossroads seid, könnt Ihr Gryshkas Brief zu Zargh bringen.$B$BSprecht wieder mit mir, wenn Ihr bereit zum Aufbruch seid.", t = "Kehrt nach Crossroads zurück"},
    [6387] = {ot = "Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar.", st = "Ich sehe viele junge Zwerge vor meiner Tür, die begierig sind, den Bergbau zu erlernen. Und wenn ein Minenarbeiter eines mehr als alles andere braucht, dann ist das eine Hacke!$B$BIch habe eine Liste von Bergbaustudenten mit vorzüglichen Abschlussprüfungen, die sich eine Ehrenhacke verdient haben. Bringt meine Liste zu Golnir Bouldertoe in Ironforge. Er wird die Hacken fertigmachen.$B$BDas schnellste Transportmittel nach Ironforge ist ein Greif, also bringt die Liste Thorgrum Borrelson, unserem Greifenmeister, und sprecht mit ihm über den Transport nach Ironforge.", t = "Ehrenstudenten"},
    [6388] = {ot = "Bringt die Ehrenhacken zu Gryth Thurden in Ironforge.", st = "Hier sind die Ehrenhacken für Brocks Studenten. Wenn Ihr schon in Thelsamar gewesen seid, dann solltet Ihr mit einem Greifen dorthin zurückfliegen!$B$BBringt die Hacken zu unserem Greifenmeister Gryth Thurden und sprecht mit ihm über die Rückreise nach Thelsamar.", t = "Gryth Thurden"},
    [6391] = {ot = "Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge.", st = "Für nur ein paar Münzen bringt Euch einer meiner Greifen nach Ironforge. Bringt dann Brocks Liste zu Golnir Bouldertoe. Ihr findet ihn in der Deepmountain-Bergbaugilde. Sie liegt im Distrikt der Großen Schmiede von Ironforge, und genau dort setzt Euch mein Greif ab!$B$BSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", t = "Flug nach Ironforge"},
    [6392] = {ot = "Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar.", st = "Für ein geringes Entgelt könnt Ihr einen Greifenritt nach Thelsamar buchen... wenn Ihr schon einmal dort gewesen seid. Greifen fliegen nur zu Orten, an denen Ihr schon einmal gewesen seid, sprecht also mit jedem Greifenmeister, den Ihr seht, dann könnt Ihr später direkt zu ihm fliegen.$B$BIhr seid schon bei Thorgrum, dem Greifenmeister von Thelsamar, gewesen, daher könnt Ihr jetzt zu ihm zurückkehren. Wenn Ihr in Thelsamar seid, könnt Ihr Brock Stoneseeker die Hacken bringen.$B$BSprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", t = "Rückkehr zu Brock"},
    [6393] = {ot = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", st = "Das Tribunal der Gezeiten hat mich geschickt, um den Feuerelementaren hier im Steinkrallengebirge den Krieg zu erklären. Neptulon der Gezeitenjäger, der Lord aller Wasserelementare hier, hat ein persönliches Interesse daran, dass unsere feurigen Vettern ausgelöscht werden.$B$B$n, Ihr könnt mir helfen, die Gunst des Tribunals zu erringen, indem Ihr die Feuerelementare im verbrannten Tal vernichtet. Wenn Feuerelementare zerstört werden, hinterlassen sie Pyrophore. Bringt sie mir, dann werde ich Euch belohnen.", t = "Krieg der Elementare"},
    [6394] = {ot = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", st = "$n, Ihr seid ein $R, auf den man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?$B$BVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Burning Blade, und meine Hacke holen?$B$BIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet ... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", t = "Thazz'rils Hacke"},
    [6395] = {ot = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück.", st = "Meine Freundin Marla Fipps lebte vor der Seuche mit ihrem Mann Samuel zusammen, doch als die Seuche kam, erlag Samuel ihr und lief zur Geißel über.$B$BMarla wurde der Untod erspart, doch sie starb durch die Hand ihres jetzt hirnlosen Mannes. Aber ihre Liebe war so stark, dass sie sterbend den letzten Wunsch äußerte, zusammen mit ihrem geliebten Samuel begraben zu werden.$B$BSamuel Fipps streift durch ein verwüstetes Lager nordöstlich von Deathknell. Besiegt ihn und erfüllt Marlas Wunsch: Begrabt ihn in ihrem Grab in der ersten Reihe unseres Friedhofs.", t = "Marlas letzter Wunsch"},
    [6401] = {ot = "Teilt Tammra Windfield, die in Sonnenfels lebt, die gute Nachricht mit.", st = "Teilt Tammra Windfield, Kayas Tante, die in Sonnenfels lebt, die gute Nachricht mit! Kaya lebt! Wir hatten sie nach dem brutalen Angriff auf unser Dorf schon verloren geglaubt. Folgt dem Pfad nach Westen, um nach Sonnenfels zu gelangen.", t = "Kaya lebt"},
    [6421] = {ot = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", st = "Irgendetwas stimmt hier im Steinkrallengebirge nicht. Spürt Ihr die Spannung, die in der Luft liegt, $n?$B$BSüdlich von hier liegt eine tiefe Höhle in der Steinschlagklamm. Die Kobolde dort schürfen wie wild nach einem seltenen Kristall, dem so genannten Resonit. Ich möchte, dass Ihr mir ein paar Erzproben bringt, damit ich herausfinden kann, was in dieser Höhle vor sich geht. Ich hätte auch gern, dass Ihr die Tiefen dieser Höhle untersucht.$B$BGeht nun, $C, es ist von größter Bedeutung, dass ich in Erfahrung bringe, welche Bösartigkeiten unter diesen Bergen lauern.", t = "Steinschlagklamm"},
    [6441] = {ot = "Sammelt für Pixel im Splintertreeposten 16 Satyrhörner.", st = "He! Ich bin auf der Durchreise nach Ratchet, habe ganz Ashenvale durchquert und mich entschlossen, hier in Splintertree Rast zu machen. Ich suche immer nach guten Gelegenheiten und es scheint mir, dass in Ratchet zurzeit Satyrhörner sehr gefragt sind.$B$BNachdem ich mich hier ein bisschen umgehört habe, glaube ich, dass die Satyrn in Night Run, Satyrnaar und Xavian genau die Art Hörner besitzen, die ich suche. Ich kann mich mit diesen Satyrn nicht messen... aber Ihr!$B$BIch sag Euch was: Wenn Ihr mir die Hörner bringt, soll es Euer Schaden nicht sein.", t = "Satyrhörner"},
    [6442] = {ot = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", st = "Entlang der Küste hier lauert das Böse, $R.$B$BEs ist die Ruhestätte der untergegangenen Stadt Zoram, die vor langer Zeit zerstört wurde und im Meer versank. Sie war verloren und fast vergessen.$B$BJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Die Gründe sind jedoch auch nicht weiter wichtig. Wir müssen das Land verteidigen, um das wir so hart gekämpft haben.$B$BBringt mir 20 ihrer Köpfe! Treibt die Naga in die Tiefen zurück!", t = "Die Naga am Zoramstrand"},
    [6461] = {ot = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", st = "Wir Trolle hier am Malaka'jin haben von dem Land profitiert. Das Steinkrallengebirge bietet reiche Jagdgründe, von denen wir leben können.$B$BIn letzter Zeit jedoch scheinen wir die falschen Gäste angezogen zu haben... Die Spinnen in diesen Bergen haben nachts unsere Lager überfallen, um uns unsere Jagdbeute zu stehlen.$B$BWenn Ihr uns helfen könntet, diese schrecklichen Bestien zu töten, würden wir hier am Malaka'jin zutiefst in Eurer Schuld stehen. Die Spinnen sind überall im Steinkrallengebirge - geht einfach von hier aus nach Norden, dann werdet Ihr sehen, was ich meine.", t = "Blutfresser"},
    [6462] = {ot = "Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer.", st = "Meine Leute waren mit vielen hochheiligen Troll-Glücksbringern im Gepäck unterwegs, aber dann wurden sie von Distelfellfurbolgs angegriffen und getötet, bevor sie Zoram'gar erreichen konnten! Diese elenden Furbolgs!$B$BIch vermisse meine getöteten Brüder und Schwestern, aber wir werden uns im Jenseits wiedersehen. Die Troll-Glücksbringer haben in dieser Welt jedoch hohen Wert. Es ist eine Schande, dass sie jetzt in den Händen der Furbolgs sind!$B$B$n, Ihr müsst diese Glücksbringer zurückholen! Sie befinden sich in Kisten in der Höhle, einer Höhle der Distelfelle am Ende des Lagers der Distelfelle nördlich von Astranaar.", t = "Troll-Glücksbringer"},
    [6481] = {ot = "Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", st = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, $C. Das Resonitfässlein, das Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.$B$BIch habe die Mixtur der Resonitkristalle, die Ihr gesammelt habt, mit Hilfe meiner Schamanenkräfte verändert. Nehmt den verzauberten Resonitkristall und zerschmettert das Resonitfässlein, in dem sich der Irdene befindet.$B$BWenn Goggeroc erwacht, wird er noch geschwächt sein... erschlagt ihn, $n!", t = "Der Irdene erhebt sich"},
    [6482] = {ot = "Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten.", st = "Huch? Wer seid Ihr?$B$B$n? Ihr seid kein Furbolg. Sie sind verflucht! Sie haben mich für einen Bären gehalten und mich eingefangen. Jetzt lassen sie mich verhungern! Meine Kraft schwindet...$B$BHelft mir zu entkommen, dann sprecht mit meiner Schwester Yama im Splitterholzposten im Osten.$B$B$n! Ich muss entkommen!", t = "Freiheit für Ruul"},
    [6503] = {ot = "Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück.", st = "Es wurde uns berichtet, dass Kundschafter Ashenvales vor nicht langer Zeit den Außenposten der Silverwing verlassen haben und sich jetzt in der Nähe unserer Territorien im Wald herumtreiben. Wir möchten nicht, dass sie unsere Verteidigung ausspionieren!$B$BSchleicht durch den Wald südlich unseres Postens und östlich des Außenpostens der Allianz von Silverwing. Findet und tötet die Kundschafter und kehrt dann zu mir zurück.", t = "Die Kundschafter von Ashenvale"},
    [6522] = {ot = "Bringt die kleine Rolle zu Varimathras nach Undercity.", st = "Milady,$B$BIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.$B$BErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf weiteres abseits der Hügel von Razorfen aufhalten.$B$BHochachtungsvoll,$BBotschafter Malcin", t = "Eine unheilige Allianz"},
    [6523] = {ot = "Begleitet Kaya Flathoof zum Camp Aparaje und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", st = "Habt Dank für meine Rettung! Wir müssen schnell fort von hier, ehe man bemerkt, dass ich frei bin. Bitte begleitet mich zum Camp Aparaje. Von dort aus kenne ich den Weg.$b$bMein Vater Makaba Flathoof wird unbedingt wissen wollen, dass ich in Sicherheit bin.", t = "Schützt Kaya"},
    [6541] = {ot = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", st = "Seid Ihr jemals im Norden von Ashenvale gewesen? Die Horde hat dort vor kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.$B$BWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Ashenvalekampagne und kann Euch weitere Befehle geben.", t = "Meldung bei Kadrak"},
    [6543] = {ot = "Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.", st = "Ich habe kürzlich ein paar Späher nach Ashenvale entsandt und brauche jetzt einen Läufer, der ihnen neue Befehle übermittelt und mir einen Bericht über deren Entdeckungen bringt.$B$BEuer erster Halt sollte der Zoram'gar-Außenposten an der Küste Richtung Westen sein. Dort solltet Ihr den ersten Läufer finden. Ihr müsst weiterhin beim Splintertreeposten im Norden und an der Straße nach Osten, die nach Azshara führt, Halt machen. Dort findet Ihr einen Späher und einen Vorreiter.$B$BErstattet allen Bericht und lasst Euch von ihnen über ihre Entdeckungen informieren.", t = "Die Warsongberichte"},
    [6544] = {ot = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht.", st = "He! $C! Kommt mal her!$B$BMeine Räuber und ich wollten gerade den Außenposten der Silberschwingen im Westen angreifen. Unser Ziel ist die dortige Anführerin, Duriel Mondfeuer. Späher berichten, dass der Außenposten durch Schildwachen und Krieger stark verteidigt wird. Das wird ein ruhmreicher Kampf!$B$BWollt Ihr an dem Ruhm teilhaben und uns helfen, $n? Falls ja, könnt Ihr meinem Vorgesetzten Ertog Zornhauer im Splitterholzposten später davon berichten.$B$BWas meint Ihr? Seid Ihr dabei?", t = "Toreks Angriff"},
    [6548] = {ot = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", st = "Der Grimmtotemklan hat mein Dorf überfallen und fast alle getötet. Ich habe so viele ich konnte niedergestreckt, bin aber nur um Haaresbreite lebend entkommen.$b$bJetzt wünsche ich mir nichts mehr, als noch mehr von ihnen tot zu sehen, $n. Ihr findet sie gleich westlich von hier.", t = "Rächt mein Dorf"},
    [6561] = {ot = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.", st = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!$b$bDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.$b$bAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.$b$bDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.$b$bBitte, erschlagt Kelris und bringt Bashana in Thunder Bluff seinen Kopf, $n.", t = "Blackfathom-Schurkerei"},
    [6562] = {ot = "Sprecht in Ashenvale mit Je'neu Sancrea.", st = "Je'neu Sancrea braucht Hilfe. Er befindet sich im Zoram'gar-Außenposten in Ashenvale. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, $n. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird.", t = "Ärger in der Tiefe"},
    [6563] = {ot = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.", st = "Im Eingangsbereich des Tunnels der Blackfathom-Tiefe findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.$B$BWerdet Ihr mir helfen, $n? Die Blackfathom-Tiefe liegt am Zoramstrand nördlich unseres Außenpostens.", t = "Die Essenz von Aku'mai"},
    [6564] = {ot = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale.", st = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:$B$B\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.$B$BIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"", t = "Treue zu den Alten Göttern"},
    [6565] = {ot = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.", st = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, $n. Ich kann mich leider nicht selbst darum kümmern ... ich bin zu schwach.$B$BGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", t = "Treue zu den Alten Göttern"},
    [6607] = {t = "Nat Pagle, Extremangler"},
    [6629] = {ot = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", st = "$n, Ihr habt gute Arbeit geleistet, indem Ihr Grimmtotem tötetet. Grundig Finsterwolke und seine persönliche Schlägerbande sind bei weitem die Schlimmsten von allen, wenn Ihr Euch traut. Er war einer derjenigen, die den brutalen Angriff auf mein Dorf anführten.$b$bIhr findet ihn im Grimmtotemposten ein Stück weiter den Weg nach Westen hinauf. Tötet ihn, dann werde ich Euch immer dankbar sein.", t = "Tötet Grundig Finsterwolke"},
    [6641] = {ot = "Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.$B$BWenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin.", st = "Vorsha die Peitscherin... die satanische Hydra, die die Meere durchstreift...$B$BSie hat unseren Außenposten angegriffen, völlig ohne Grund, und dabei alles verheert, was auf ihrem Weg lag.$B$BAber ich bin bereit, $n. Ich bin bereit, die Hydra zu besiegen und den Angriffen auf Zoram'gar ein Ende zu setzen.$B$BDie Naga verehren die tückische Natur dieser Bestie mit einer Kohlenpfanne, die auf einer Insel gleich vor der Küste immer am Brennen gehalten wird. Ich denke, dass Vorsha erzürnt auftauchen wird, wenn wir sie löschen.$B$BWir werden jedoch Hilfe brauchen, also solltet Ihr ein paar starke Verbündete mitbringen.", t = "Vorsha die Peitscherin"},
    [6661] = {ot = "Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid.", st = "Haltet ein, Taugenichts. Arrrr... Sucht Ihr Arbeit? Wir ha'm hier ein echtes Rattenproblem und nicht genügend Leute auf dem Hüttendeck.$B$BWas sagt Ihr? Ihr müsst nur diese Rattenfängerflöte nehmen und dem Ungeziefer ein Liedchen vorspielen. Die folgen Euch dann bis ans Ende der Welt!$B$BFangt mir fünf von den kleinen Mistviechern und bringt sie mir. Ich brauch sie lebendig.$B$BArrrrr...", t = "Tiefenbahn-Ratten-Razzia"},
    [6662] = {ot = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Stormwind.", st = "Mein Bruder Nipsy hat 'n Rattengeschäft auf der anderen Seite der Tiefenbahn. Ihr müsst die Kiste mit Ratten hier zu ihm bringen, bevor sie schlecht werden. Zackig!$B$BIhr seid doch wohl schon mal mit 'ner Bahn gefahren, oder? Ganz einfach. Steigt einfach ein, wenn sie kommt, und genießt die Fahrt. Und haltet Eure Arme und Beine während der Fahrt drinnen, wenn Ihr keine Holzgräten haben wollt.", t = "Mein Bruder Nipsy..."},
    [6921] = {ot = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", st = "Die Twilight-Hammer sind in die Mondschreinruinen der Blackfathom-Tiefe eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.$B$B$n, geht nach Blackfathom und findet den Fathom-Stein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Fathom-Kern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", t = "Inmitten der Ruinen"},
    [6922] = {ot = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", st = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.$B$BWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich im Zoram'gar-Außenposten der Horde in Ashenvale.", t = "Baron Aquanis"},
    [6981] = {ot = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.$B$BLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.", st = "Der Splitter ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Ihr fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt Ihr auch, dass etwas sehr Beunruhigendes von ihm ausgeht.$B$BVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", t = "Der leuchtende Splitter"},
    [7383] = {ot = "Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", st = "Mit Teldrassil stand es jedoch nicht zum Besten. Staghelms sorgfältig durchdachte Pläne für den neuen Weltbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.$b$bWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.", t = "Krone der Erde"},
    [65601] = {ot = "Sprecht mit Magar in Orgrimmar.", st = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, $n, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", t = "Liebe kann schmerzhaft sein"},
    [65602] = {ot = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", st = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden ins Ashenvale, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", t = "Alles aus Liebe"},
    [65603] = {ot = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", st = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", t = "Die Bindung"},
    [65604] = {ot = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück.", st = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, $n. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", t = "Die Bindung"},
    [65610] = {ot = "Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht.", st = "Ich habe Krilge bei der Herstellung von Mondstoff im Ashenvale kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Fallenskysee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Ashenvale gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", t = "Irgendwo anders"},
    [76156] = {ot = "Schleicht Euch in die Mine der Venture Company südöstlich von Thunder Bluff und sammelt 5 Zephyriumbergbauladung aus Loren mit Sprengvorräten, dann kehrt zu Eberton Schattentotem in Thunder Bluff zurück.", st = "Ich spüre ein verborgenes Talent für die subtilen Künste in Euch, $SC. Nutzt diese Maske, um die nahegelegene Mine der Venture Company zu infiltrieren und ihre Vorräte zu stehlen. Das mag nicht nach einer überzeugenden Verkleidung aussehen, aber ein fähiger Schurke kann sich mit so wenig wie einem charmanten Lächeln und einer klugen Ablenkung an jeder Wache vorbeischleichen. Ich bin überzeugt, Ihr besitzt diese Fähigkeit ebenfalls.", t = "Schleicht mit der Erdenmutter"},
    [76160] = {ot = "Sammelt 8 Windzornzapfen nördlich von Thunder Bluff, zerstampft sie mit Mörser und Stößel und kehrt mit dem Ergebnis zu Eberton Schattentotem in Thunder Bluff zurück.", st = "Vielleicht könnt Ihr besser mit Giften umgehen als mit Verkleidungen. Die Harpyien im Norden nisten in einem Baum, der ein stark toxisches Harz produziert. Sammelt die heruntergefallenen Zapfen um die Nester herum auf, dann zerstampft sie zu einer Salbe. Wenn Ihr sie auf eine Klinge auftragt, wird sie sich in das Fleisch Eurer Feinde brennen und ihr Blut in Salz verwandeln.", t = "Schleicht mit der Erdenmutter"},
    [76240] = {ot = "Kauft oder fangt einen rohen glänzenden Kleinfisch, dann nutzt das Messerset, um ihn vor Eberton Schattentotem in Thunder Bluff zu filetieren.", st = "Ich habe noch eine letzte Idee, die uns zum Erfolg führen könnte. Ich spüre immer noch ein verborgenes Talent in Euch, aber vielleicht müssen wir es indirekter herauslocken.\n\nGeht und besorgt einen rohen glänzenden Kleinfisch. Bringt ihn her und nutzt diese Dolche, um ihn zu säubern und zu filetieren. Denkt nicht zu viel darüber nach. Tut einfach, was sich natürlich anfühlt.", t = "Schleicht mit der Erdenmutter"},
    [79360] = {ot = "Besiegt Charlga Razorflank im Kral von Razorfen und sammelt Informationen über die Pläne der Stacheleber.", st = "Da Ihr nun die Elemente gemeistert habt, seid Ihr ihnen gegenüber verpflichtet, und damit auch gegenüber ganz Azeroth. Wir bitten sie um Hilfe, wir fordern nicht ihre Macht. Es ist an der Zeit, dass Ihr Euch für die Gaben revanchiert, die Euch gewährt wurden. Und ich glaube, ich weiß wie.\n\nDie Stacheleber verdrehen die Elemente für ihre eigenen Zwecke und scheinen ihren Einfluss innerhalb dieser Grenzen immer weiter auszudehnen. Begebt Euch in ihr Kral und bereitet ihren Plänen ein Ende. Diese Lande müssen beschützt werden.", t = "Elementare Hilfe"},
    [79364] = {ot = "Sprecht mit Prate Cloudseer in Tausend Nadeln.", st = "In der Notiz, die Ihr gefunden habt, heißt es, dass die Grimmhauer sich in Tausend Nadeln eingegraben haben, um eine Art geheimes Ritual durchzuführen. Tobende Stürme und steigende Fluten...\n\nDie Stacheleber müssen eine grausame Hexerei anwenden, die sie von Hirzek gelernt haben, einem Schamanen, der vor nichts zurückscheute, um die Elemente zu verdrehen. Wenn sie vorhaben, die Schlucht zu fluten, würde dies verheerende Elementarkräfte erfordern.\n\nWir sind nicht dafür gerüstet, das zu verhindern, aber ein mächtiger Schamane wie Ihr muss eine Idee haben. Kehrt zu Euren Verbündeten zurück und versucht, eine Antwort zu finden.", t = "Blick zum Himmel"},
    [86574] = {ot = "Sammelt $1oa Vorratskisten des Steinkrallengebirges von Prachtschwingenwyvern und bringt sie zu Gastwirtin Faralia.", st = "<Der Leichnam trägt die Spuren eines heftigen Prachtschwingenwyvernangriffs. Ein Rucksack liegt zerfleddert daneben; von seinem Inhalt fehlt jede Spur. Nur ein kleiner Zettel in der Hand der Verstorbenen verrät, was verloren ging: eine Lieferung für Gastwirtin Faralia auf dem Steinkrallengipfel.>\n\n<Vermutlich haben die Wyvern die Bündel fortgetragen, um ihre Nester damit auszupolstern.>", t = "Versorgungsgüter fürs Steinkrallengebirge"},
    [86576] = {ot = "Bringt Mor'rogal $1oa glitzernde Sonnensteine.", st = "Die Harpyien der Blutfurien verbreiten nicht nur ihren Schmutz im Verbrannten Tal, sie raffen auch alles an sich, was glänzt. Wie ich hörte, sammeln sie goldgelbe Sonnensteine als Schmuck. Ich selbst habe keine Verwendung für solchen Zierrat, doch Mor'rogal erwähnte einmal, dass er sie gut gebrauchen könne.\n\nHaltet also während Eures Kampfes gegen die Harpyien Ausschau nach glitzernden Sonnensteinen und bringt sie ihm. Ihr findet ihn oben in den Hügeln.", t = "Blutfurienzierrat"},
    [86585] = {ot = "Erhebt das Banner von Ironforge, lockt den Trogg Kopfspalter hervor und tötet ihn. Meldet Euch anschließend bei Captain Rugelfuss.", st = "Die gefallene Gebirgsjägerin trägt das Banner von Ironforge. Vielleicht wurde sie bei einer Erkundungstour überrascht, vielleicht wagte sie einen aussichtslosen Angriff. Wie dem auch sei, das Banner liegt im Dreck und wurde gründlich zertrampelt. Ein Trogg hat der Gebirgsjägerin einen solchen Schlag versetzt, dass ihr der Helm vom Kopf geflogen ist. Der Hieb, vermutlich mit einer Keule voller Eisenspitzen, muss sie auf der Stelle getötet haben.\n\nDer Trogg dürfte sich noch immer in der Nähe aufhalten. Und vermutlich erinnert er sich an das Banner. Wenn Ihr das Banner von Ironforge erneut erhebt, könntet Ihr ihn hervorlocken.", t = "Banner der Gefallenen"},
    [86613] = {ot = "Bringt $1oa Ausgrabungswerkzeuge zu Magmar Fellhew.", st = "Die Ausgrabungswerkzeuge, die von den Zwergen zurückgelassen wurden, als sie vor den Troggs flohen, sehen unberührt aus. Ihr würdet den Ausgräbern sicher bei ihrer Arbeit helfen, wenn Ihr sie ihnen zurückbringt.", t = "Ausgrabungswerkzeuge"},
    [86614] = {ot = "Bringt die silberne Haarklammer mit Monogramm der Person, der sie gehört.", st = "<Unter den Angelsachen in dem Gerümpel befinden sich verrostete Haken, gerissene Drahtspulen und eine etwas angelaufene, aber aufwendige silberne Haarklammer mit dem Monogramm \"K.D.\">", t = "Silberschatz der Wellen"},
    [86667] = {ot = "Bringt einen Krug mit Schnee zu Norric Lochthane bei seinem Haus am nordwestlichen Ufer des Loch.", st = "Mein alter Lehrmeister Norric hat mir einen kleinen Elementargeist geschickt und eine sonderbare Bitte ausrichten lassen: Norric braucht ein Glas Schnee für irgendein schamanisches Ritual! Ich habe keine Ahnung, was er damit vorhat, aber seine Methoden in Sachen Magie hinterfragt man besser nicht.\n\nIch bin zurzeit damit beschäftigt, mich hier einzuleben und die örtlichen Elementargeister kennenzulernen. Deshalb kann ich ihm leider nicht selbst helfen. Würdet Ihr das für mich übernehmen? Geht zum Südtorpass. Dort herrscht das ganze Jahr über Winter. Füllt diesen Krug mit Schnee und bringt ihn zu Norric, bevor er schmilzt.", t = "Eingeschneit"},
    [86758] = {ot = "Findet und besiegt den Krokilisken Dolchzahn und holt Mareks Messer zurück.", st = "Habe ich Euch schon mal erzählt, wie ich fast eine Hand an einen Krokilisken verloren hätte? Ich konnte ihm mein Messer in den Schlund rammen und habe geschaut, dass ich davonkomme. Ich dachte, ich hätte das Messer hier irgendwo, aber ich kann es nicht finden.\n\nJedenfalls jagt der Krokilisk wahrscheinlich immer noch am Seeufer. Dieses Mistvieh muss weg, schon allein, um die anderen Jäger zu schützen.\n\nIch nenne es mittlerweile Dolchzahn. Grüßt es doch schön von mir, falls Ihr es seht! Und mit \"grüßen\" meine ich \"abstechen\".", t = "Ist dies ein Dolch"},
    [86784] = {ot = "Sammelt $1oa trockene Äste und bringt sie zu Eleanor Shackleton.", st = "Meine Kollegin Eleanor Shackleton ist stolz darauf, draußen in der Wildnis allein zurechtzukommen, Wind, Wetter und Monstern zum Trotz. Sie hat ihr Lager nicht weit von hier aufgeschlagen, in den Hügeln im Westen. Ich erinnere mich noch gut an einen Rat, den sie mir einmal gab: \"Wenn Ihr glaubt, genug Feuerholz gesammelt zu haben, sammelt die fünffache Menge.\"\n\nFalls Ihr etwas Zeit übrig habt, könntet Ihr diesen Korb mit Brennholz füllen und zu ihrem Lager bringen. Ich bin sicher, sie hat den einen oder anderen Rat für Euer Abenteurerleben.", t = "Stöcke und Knochen"},
    [87288] = {ot = "Bringt Aldria $1oa weiche Nachtsäblerpelze.", st = "Hallo $uReisender:Reisende;! Ich hoffe, Ihr genießt Euren Besuch in unserem Dorf. Ich mag Dolanaar; es ist klein, charmant und alle sind freundlich.\n\nIch bin ein örtlicher Händler und habe allerlei Werkzeuge und Schmuckstücke im Angebot, die Euch auf Euren Reisen von Nutzen sein könnten. Tatsächlich kann ich Euch einen Tauschhandel anbieten, falls Ihr interessiert seid! Ich benötige einige Nachtsäblerpelze. Diese majestätischen Kreaturen sind wunderschön, doch in dieser Gegend auch recht aggressiv. Ihr könnt es also als Selbstverteidigung verbuchen.", t = "Weiche Säblerpelze"},
    [87760] = {ot = "Findet eine Tierbändigerin der Sturmschuppen, tötet sie und nehmt ihre Rute der Tiefenherrschaft an Euch.", st = "$n, ich habe Nachricht aus Darnassus erhalten!\n\nAnhand der tierischen Proben konnten wir feststellen, dass die Naga die Meeresbewohner unterjocht haben, um sie als Reit- und Lasttiere einzusetzen. Diejenigen, die sich widersetzten oder zu alt beziehungsweise zu schwer verletzt waren, wurden zum Vergnügen der Naga verstoßen. Welch ungeheuerliche Grausamkeit!\n\nEs ist unsere heilige Pflicht, dem ein Ende zu setzen.\n\nDie Naga unterhalten Streitkräfte in den Ruinen von Mathystra. Vermutlich fangen sie dort vor der Küste die Drescher. Findet ihre Tierbändigerin, tötet sie und bringt mir ihre Rute!", t = "Auf heiliger Tauchmission"},
    [90902] = {ot = "Heal $1oa verletzte Todeswachen mit Eurer Fähigkeit 'Heiliges Licht'.", st = "Ich bin stolz, einen jüngst auferstandenen Paladin in unseren Reihen begrüßen zu dürfen. Während Ihr Eure Verbindung zum Licht erneuert, werdet Ihr feststellen, dass viele Eurer früheren Fähigkeiten Euch nun große Schmerzen bereiten. Besonders solche, für die Ihr das Licht kanalisieren müsst, um Euch oder andere zu heilen.\n\nDie einzige Möglichkeit, dieses Problem zu umgehen, ist leider: Augen zu und durch. Wie mit jedem anderen zurückgebildeten Muskel müsst Ihr den Schmerz durchstehen und das Fleisch trainieren, damit es wieder voll funktionsfähig wird.", t = "Das Licht wiederentdecken"},
    [91208] = {ot = "Findet den verängstigten Paladin in Deathknell.", st = "Nicht alle auferstandenen Paladine können sich schnell an ihre neue Realität gewöhnen. Einige haben Schwierigkeiten, sich damit abzufinden, dass sie nun mehr oder weniger genau das sind, wogegen sie ihr Leben lang gekämpft haben.\n\nDie meisten brauchen meist nur eine freundliche Geste und jemanden, der ihnen zuhört. Andere greifen leider schnell zur Gewalt. Findet den verängstigten Paladin, der in die Hügel westlich von dieser Kapelle geflohen ist. Bietet ihm Eure Freundschaft an. Bringt ihn zurück ins Licht, wenn Ihr könnt.", t = "Trauerbewältigung"},
    [91209] = {ot = "Folgt der Straße nach Osten aus Deathknell heraus, um nach Brill zu gelangen. Meldet Euch bei Shari Stilwell, um Eure Ausbildung fortzusetzen.", st = "Lordaeron ist vielleicht nicht mehr das, was es einst war, aber unsere Heimat muss immer noch vor allen möglichen Bedrohungen geschützt werden. Es ist Zeit, dass Ihr in die Welt hinauszieht. Euer nächster Halt sollte die Stadt Brill im Herzen von Tirisfal sein. Geht und trefft Euch dort mit Shari Stilwell. Sie kann Eure weitere Ausbildung übernehmen.\n\nEin letzter Ratschlag, bevor Ihr geht: Seid auf der Hut, wenn Ihr als Paladin durch das Land der Verlassenen reist. Die Dunkle Fürstin hat viele in ihren Diensten, die uns und unserer Nähe zum Licht misstrauen.", t = "Setzt Eure Ausbildung fort"},
    [91282] = {ot = "Findet die Bandarionfestung und meldet Euch dort bei Brenton Samuels.", st = "Es ist ermutigend, meine jüngst erhobenen Brüder und Schwestern gedeihen zu sehen, wenn Ihr so wollt. Doch nur durch enge Gemeinschaft und gemeinsamen Glauben können wir unser volles Potenzial ausschöpfen. Und deswegen haben wir begonnen, einen Paladinorden genau hier in Tirisfal zu gründen.\n\nWenn Ihr mehr erfahren wollt, solltet Ihn unser Kloster am Nordhangfels besuchen. Es heißt Bandarionfestung, liegt gleich an der Klippe nordwestlich von Sollidens Bauernhof und sollte schwer zu übersehen sein.", t = "Ein zweites Zuhause"},
    [91285] = {ot = "Tötet $1oa Angreifer der Finsterflossen und $2oa Seher der Finsterflossen und erstattet Brenton Samuels nach getaner Arbeit Bericht.", st = "Normalerweise würde ich unseren Neuankömmlingen gastfreundlicher gegenübertreten, aber wir haben gerade ein kleines Murlocproblem.\n\nEin Murlocstamm hat die Festung früher als Laichgrund genutzt. Sie machen uns Ärger, seit wir hier eingezogen sind und sie rausgeworfen haben. Aber so langsam gerät es außer Kontrolle. Ihr seht aus, als hättet Ihr einiges erlebt. Glaubt Ihr, Ihr könntet uns helfen, einige dieser Quälgeister zu vertreiben? Sie lauern in den Felsen entlang der Straße im Osten und bei den Lagern am See im Westen.", t = "Murlocs vor der Toren"},
    [91294] = {ot = "Sprecht mit den Einwohnern der Bandarionfestung.", st = "Nun, da die unmittelbare Bedrohung durch die Murlocs unter Kontrolle ist, seht Euch doch in unserer Festung um. Sie ist noch nichts besonderes, aber sie ist unser Zuhause.\n\nWenn Ihr genug erkundet habt, geht zu Danitha Morr, unserer Anführerin. Sie kann Euch helfen, Euch einzuleben.\n\nIch bin froh, Euch getroffen zu haben, $n. Möge das Licht Euch leiten.", t = "Ein Rundgang durch die Anlage"},
    [91316] = {ot = "Sammelt 12 Stück stabiles Bauholz aus Schattental in Tirisfal.", st = "So weit von Undercity entfernt ist die Logistik eine Herausforderung und wir haben einen akuten Mangel an Baumaterialien, die wir dringend für den Wiederaufbau dieser Festung benötigen. Dabei möchte ich Euch um Eure Hilfe bitten.\n\nDas zerstörte Dorf Schattental liegt in den Flüsternden Wäldern, südwestlich von hier. Eines der Gebäude hat einen alten Wurzelkeller, in dem viele verschiedene Dinge gelagert wurden. Dort könnt Ihr wahrscheinlich noch brauchbare Materialien finden. Bergt so viel wie möglich und kehrt zu uns zurück.", t = "Reparaturen"},
    [91317] = {ot = "Tötet 8 befleckte Akkordarbeiter sowie 6 befleckte Fanatiker und holt Euch den Kopf von Kommandant Rudolph Gelhardt in Tirisfal.", st = "Nicht alle auferstandenen Paladine haben sich gut an unser neues Dasein gewöhnt, wie Ihr vielleicht selbst schon gesehen habt. Einige haben ihre Vorurteile aus dem Leben mitgenommen und wenden weiterhin Gewalt gegen andere Verlassene an.\n\nIm Augenblick misstraut uns unser Volk, das sich noch gut an die Verfolgung durch die Lebenden im Namen des Lichts erinnert, und diese Angriffe sind nicht gerade hilfreich. Ein paar dieser Befleckten haben sich in Schattental im Südwesten niedergelassen. Tötet sie und bringt mir den Kopf ihres Anführers.", t = "Der Befleckte"},
    [91723] = {ot = "Tötet 8 Koboldgeomanten in der Jaspismine und kehrt anschließend zu Hamish Bergwort im Turm von Azora zurück.", st = "Verflixt nochmal! Jedes Mal, wenn ich versuche, diese empfindlichen arkanen Instrumente zu kalibrieren, werden meine Bemühungen durch einen Energiestoß zunichte gemacht.\nDie Energiestöße scheinen aus dem Norden zu kommen, wo diese ungehobelten Kobolde ihre primitive Magie praktizieren. Könntet Ihr ein paar von ihnen aus dem Weg räumen, sodass ich meine Arbeit fortsetzen kann?", t = "Empfindliche Instrumente"},
    [91724] = {ot = "Tötet 6 abtrünnige Hexer der Defias um den Steinhügelsee und kehrt anschließend zu Hamish Bergwort im Turm von Azora zurück.", st = "Fast geschafft, und... Beim Nether! Etwas stört noch immer meine Instrumente.\nDas ist äußerst frustrierend, $n. Ich habe Gerüchte gehört, dass die lokalen Banditen in der Nähe des Steinhügelsees ihre Zauber üben. Vielleicht werden diese Störungen endlich aufhören, wenn Ihr sie aufhaltet, sodass ich meine Arbeit erledigen kann?", t = "Empfindliche Instrumente"},
    [91725] = {ot = "Sammelt 5 gestohlene Verzauberkunstmaterialien in Gnoll-Lagern um den Steinhügelsee und kehrt anschließend zu Blixie Fitzwink in der Nähe des Turms von Azora zurück.", st = "Meister Theocritus hat mich geschickt, um Verzauberkunstbedarf vom Handelsposten abzuholen, aber auf dem Weg zurück wurde ich von einer Gruppe Gnolle überfallen.\n\nIch habe das Paket fallen gelassen und konnte entkommen, aber wenn ich ohne es zurückkehre, werde ich als Bestrafung wochenlang nach den Verwandlungsexperimenten saubermachen müssen! Könnt Ihr den Verzauberkunstbedarf für mich finden?", t = "Gestohlene Verzauberkunstmaterialien"},
    [91732] = {ot = "Sammelt 4 Bergbauwerkzeuge in der Jaspismine und kehrt damit zu Hagar Lowe im Holzfällerlager des Osttals zurück.", st = "Guter Stahl ist seit dem Krieg Mangelware, und unsere Werkzeuge haben darunter gelitten. Die Minenarbeiter in der Jaspismine verwendeten die feinsten Spitzhacken und ich vermute, dass einige von ihnen noch in den Tiefen der Mine sind. Könntet Ihr ein paar für mich bergen? Ich werde anschließend untersuchen, ob ich den Stahl wiederverwerten kann.", t = "Guter Stahl"},
    [91733] = {ot = "Sammelt die durchnässte Axt, durchnässte Säge und den durchnässten Werkzeugkasten, die vom Holzfällerlager des Osttals flussabwärts gespült wurden, und kehrt damit zu Ormin Pelford zurück.", st = "Ich wollte eine Ladung Vorräte vom Handelsposten mitbringen, aber mein Wagen ist umgekippt und alle Vorräte sind in den Fluss gefallen! Bevor ich sie abfangen konnte, wurden sie schon alle flussabwärts getragen.\nMit den ganzen Murlocs und Wölfen da unten habe ich keine Chance, die Vorräte allein zu bergen. Ihr seht mir aus wie jemand, der zuhauen kann. Würdet Ihr sie bitte für mich finden?", t = "Flussabwärts"},
    [91740] = {ot = "Bringt Quakis Kopf zu Merell Ross in der Kammwacht.", st = "Dieser Murloc versetzt die örtlichen Straßen zweifellos seit einer ganzen Weil in Angst und Schrecken. Ihr vermutet, dass die Wächter in der Nähe von seinem Ableben erfahren möchten.", t = "Quakis Kopf"},
    [91741] = {ot = "Bringt das Buch zu Bruder Paxton zurück.", st = "<Einer der Kobolde hat dieses Buch fallen lassen. Es scheint so, als hätte der Kobold versucht, es zu essen.\n\nBruder Paxton kümmert sich in der Abtei um eine kleine Bibliothek. Von dort muss das Buch stammen.>", t = "Angeknabbertes Buch"},
    [91743] = {ot = "Bergt $1oa gestohlene Bücher von den Kobolden im Nordhaintal und bringt sie zurück zu Bruder Paxton.", st = "Diese vermaledeiten Kobolde essen meine Bücher! Ihr müsst sie zurückholen, bevor sie meine ganze Bibliothek verschlingen!", t = "Nervige Nager"},
    [91745] = {ot = "Sprecht mit Kelsey Fargo außerhalb der Echokammmine im Nordhaintal.", st = "Sprecht mit dem neuen Bergbaulehrling Kelsey Fargo. Sie arbeitet direkt außerhalb der Mine und hat höchstwahrscheinlich gesehen, was die Kobolde treiben. Vielleicht kann sie Euch dabei gleich das ein oder andere über den Bergbau beibringen.", t = "Bergbauberater"},
    [91746] = {ot = "Bringt Ulmpfotes Kopf zu Helene Peltskinner in der Nähe von Goldhain.", st = "Die Trophäe ist eine beeindruckende Erinnerung an Euren Sieg über Ulmpfote. Ein lokaler Jäger oder Kürschner würde die Geschichte vielleicht gerne hören.", t = "Ulmpfotes Kopf"},
    [91751] = {ot = "Häutet Wölfe im Wald von Elwynn, um 7 raue Wolfspelze zu erhalten, und bringt sie zu Helene Peltskinner in der Nähe von Goldhain.", st = "Sucht Ihr nach einer Gelegenheit, das Kürschnerhandwerk zu üben? Mein Mann hilft normalerweise bei der Wolfsjagd aus, aber er hat in der Abtei zu tun. Ich könnte eine helfende Hand bei der Beschaffung der Pelze brauchen, um die offenen Bestellungen abzuschließen.", t = "Raue Wolfspelze"},
    [91752] = {ot = "Bergt einen Sack voller \"Bilderbücher\" von Glitzerfinder Narf. Bringt den Sack zu Marshal McBride in der Abtei von Nordhain.", st = "Immer mal wieder kommt hier ein Kobold durch und ruft \"Ein Bild für Narf!\". Ich weiß nicht, wer dieser Narf ist. Vielleicht einer der Koboldanführer im hinteren Teil der Mine? Ich wette, er besitzt mittlerweile einen ganzen Sack voller Bücher.\n\nHolt diese Bücher und bringt sie zu unserem örtlichen Gesetzeshüter Marshal McBride. Holt Euch einen Freund zu Hilfe. Diese Kobolde in der Mine sind deutlich fieser.", t = "Das große Ganze"},
    [91753] = {ot = "Kitta Firewind im Turm von Azora möchte, dass Ihr 3 leuchtende Rückstände sammelt.\n\nLeuchtende Rückstände erhaltet Ihr durch Entzaubern von primitiven Wachsbildnissen, die von Koboldgeomanten fallen gelassen werden.", st = "Akademische Genauigkeit ist natürlich ein wesentlicher Bestandteil der Verzauberkunst, doch eine praktische Grundlage kann sich ebenfalls auszahlen. Nehmt beispielsweise den gemeinen Kobold. Obwohl ihm eine fundierte Ausbildung fehlt, so zeigt er dennoch eine gewisse angeborene Begabung für einfache Verzauberungen.\n\nBeschafft einige ihrer Wachsbildnisse und zerlegt die darin gebundenen Zauber. Dabei könnt Ihr sicher einige aufschlussreiche Erkenntnisse gewinnen.", t = "Verzaubernde Erkenntnisse"},
    [91758] = {ot = "Sprecht mit Tordrin Sternblade in der Nähe des Stalls hinter der Abtei von Nordhain.", st = "Ihr seid mit diesen Kobolden noch nicht fertig. Wir haben gerade von Kelsey erfahren, dass ein Kobold die Mine mit einem großen Sack voller Bücher verlassen hat. Ich möchte, dass Ihr diesen Kobold ausfindig macht, damit wir die Bücher für Bruder Paxton zurückholen können.\n\nSprecht mit Tordrin Sternblade. Er ist der neue Jägerlehrer, der gerade erst aus Ironforge eingetroffen ist. Ihr findet ihn hinter der Abtei, in der Nähe des Stalls. Er kann Euch helfen, diesen Kobolddieb ausfindig zu machen.", t = "Folgt diesem Kobold!"},
    [91772] = {ot = "Folgt den Koboldspuren und meldet Euch bei Marshal Dughan in Goldhain mit Euren Erkenntnissen und dem Kobold-Fährtenleseset.", st = "Na schön. Nehmt dieses Kobold-Fährtenleseset. Damit könnt Ihr den Kobold verfolgen, um den es Marshal McBride geht.\n\nFolgt den Spuren und bringt Eure Funde zu Marshal Dughan in Goldhain.\n\nMich beschleicht das Gefühl, diese kleinen Racker planen irgendetwas außerhalb von Nordhain. Ihr braucht also Dughans Hilfe.", t = "Pssst! Wir jagen Kobolde"},
    [91775] = {ot = "Findet 6 verlorene Bücher sowie \"Spaß mit Elementaren\" und bringt sie zu Marshal Dughan zurück.", st = "Seht, ob Ihr während der Untersuchung der Tiefenschachtmine Bruder Paxtons Bücher findet, um sie zurückzubringen. Vor allem ist er sehr besorgt über ein Buch namens \"Spaß mit Elementaren\". Er denkt, sogar ein Kobold könnte es nutzen, um einen Elementardiener zu beschwören. Doch seid gewarnt: Die Tiefen der Mine sind ziemlich gefährlich. Ihr solltet Freunde mitbringen.\n\nNehmt diese Büchertasche, um die Bücher zu schützen, wenn Ihr welche findet!", t = "Buchrückgabe"},
    [91777] = {ot = "Findet \"Geomantie für neugierige kleine Zauberer\" und \"Arkane Erläuterungen: Magisches in einfachen Worten\" und bringt sie zu Bruder Paxton in der Abtei von Nordhain zurück.", st = "Es fehlen nur noch zwei Bücher von Bruder Paxtons Liste: \"Geomantie für neugierige kleine Zauberer\" und \"Arkane Erläuterungen: Magisches in einfachen Worten\".\n\nDie Kobolde müssen sie zur Jaspismine gebracht haben. Bitte findet diese zwei Bücher und bringt sie zu Bruder Paxton zurück.\n\nAber ich befürchte, dass es ziemlich gefährlich sein wird. Wenn der \"Koboldlehrling\" einen Elementar beschwören kann, will ich mir gar nicht ausmalen, wozu der Meister imstande ist. Ich an Eurer Stelle würde ein paar Freunde mitbringen.", t = "Seltene Bücher"},
    [91858] = {ot = "Reist zum Grabmal im Silberwald und sprecht mit Trevan Rol über die vermissten Reisenden des Irdenen Rings.", st = "Eine ausgesprochen unglückliche Wendung der Ereignisse im Silberwald gibt uns eine einzigartige Gelegenheit, uns der Horde würdig zu erweisen.\n\nEinige Würdenträger des Irdenen Rings auf dem Weg nach Tarrens Mühle sind im Silberwald verschwunden. Sonst wissen wir nicht viel, aber die Gerüchte besagen, dass es zu einem ernstzunehmenden diplomatischen Zwischenfall geworden ist. Wenn wir die vermissten Personen finden können, würde uns das zu der Legitimität verhelfen, die wir so dringend benötigen.\n\nWir haben einen Mann im Grabmal, Trevan Rol. Geht dort hin uns sprecht mit ihm.", t = "Diplomatischer Zwischenfall"},
    [91859] = {ot = "Sprecht mit Todeswache Baldren über die mysteriösen Reisenden des Irdenen Rings, die kürzlich durch das Grabmal gekommen sind.", st = "Machen wir es kurz, diese \"Würdenträger\" sind keine gewöhnlichen Diplomaten. Einer war ein Tauren. Gewöhnlich genug für den Irdenen Ring, aber der andere - und das werdet Ihr mir nicht glauben - war ein Elf. Ein *Hochelf*. Er hatte sich verhüllt, aber ich habe schon genug Quel'dorei gesehen und verwette meinen kleinen Finger, dass er einer ist.\n\nWarum ein Elf allerdings einen Tauren durch das Territorium der Horde begleitet? Nun, da wisst Ihr so viel wie ich. Mehr kann ich Euch nicht sagen, Ihr solltet also mit Todeswache Baldren beim Eingang zum Dorf sprechen.", t = "Ein seltsames Paar"},
    [91860] = {ot = "Untersucht die Insel Fenris im Osten, um vom Schicksal der Reisenden des Irdenen Rings zu erfahren.", st = "Als ich gestern auf Nachtpatrouille war, sah ich eine Gruppe von Gnollen, die an der Küste der Insel Fenris eine große Leiche auf einen Scheiterhaufen warfen. Ich habe zwar keine Elfen oder kleinere Leichen gesehen, aber das bedeutet wohl nichts Gutes für die beiden.\n\nWenn Ihr mutig oder dumm genug seid, stürmt gern die Insel Fenris, um mehr zu erfahren. Aber wenn Ihr mich fragt, ist das zu viel Arbeit für einen hochnäsigen Elf, der bestimmt längst tot ist.\n\nIch weiß, Ihr Paladine liebt es, Schwüre abzulegen und Euch hoffnungsloser Fälle anzunehmen. Aber dieser ist es nicht wert. Glaubt mir.", t = "Ein grausiges Schicksal"},
    [91861] = {ot = "Untersucht Burg Fenris im Norden und versucht, das vermisste Mitglied der Gruppe des Irdenen Rings zu finden.", st = "<Die Tatsache, dass Ihr nur eine Leiche gefunden habt, ist ein gutes Zeichen. Vielleicht lebt die Hochelfe noch, die Trevan und Hadrec beschrieben haben, und wird in der Festung in der Nähe festgehalten?>", t = "In die Burg Fenris"},
    [91862] = {ot = "Beschafft den Schlüssel zur Insel Fenris von den Moderfellgnollen und verwendet ihn, um Lumina Windsinger zu befreien.", st = "Quel'dorei? Nein, ich bin keine \"Quel'dorei\". Ich bin Lumina Windsinger und eine Shen'dorei. Eine der Himmelsgeborenen der Windformer.\n\nIch kam als Gast des Irdenen Rings in diese Lande. Mein Begleiter Banon und ich reisten durch Silverpine, um das Arathihochland zu erreichen, um dort die Elementarkonvergenzen zu studieren. Zweifellos haben wir das nicht geschafft.\n\nDoch dafür haben wir jetzt keine Zeit. Tötet die Gnolle in der Nähe. Beschafft den Schlüssel zu diesem Käfig und befreit mich. Ich werde Euch den Rest erzählen, sobald wir in Sicherheit sind.", t = "Lumina Windsinger"},
    [91920] = {ot = "Sammelt 3 Murlocaugen und bringt sie zu Apotheker Renferrel am Grabmal.", st = "Ich würde es nie wagen, die Effektivität von Apotheker Renferrels Formeln zu hinterfragen. Aber ich würde lügen, würde ich behaupten, dass der Trank irgendeinen erkennbaren Unterschied gemacht hätte.\n\nEntlang des Ufers des Lordameresees gibt es einen Schwarm von Murlocs und, ganz wichtig, Murlocs haben Augen. Ich vermute, die Bereitschaft des Apothekers, neue Dinge auszuprobieren, wird von seiner Besessenheit mit Herzen beeinträchtigt. Bringt ihm ein paar Augen.\n\nWenn ich mich entscheiden muss, ob ich einen unausweichlichen zweiten Tod sterben oder mich von Renferrel umbringen lassen will, weil ich seine Methoden hinterfrage, wähle ich Letzteres.", t = "Wilde Augen"},
    [92109] = {ot = "Bringt 5 leere Phiolen, 5 Silberblatt und 5 Friedensblumen zur jungen Alchimistin in der Scheune von Moonbrook in Westfall.", st = "Ähm... Hallo? Ich... Ich darf eigentlich nicht mit Fremden reden, aber... He, wofür sind denn die ganzen glitzernden Fläschchen, die aus Eurem Rucksack schauen? Seid Ihr $gAlchimist:Alchimistin;? Wie cool!\n\nWenn ich groß bin, möchte ich auch Alchimistin werden. Papa lässt mich nicht mit seinen Kräutern spielen. Viel zu gefährlich, sagt er.\n\nAber ich will jetzt schon lernen! Könntet Ihr mir vielleicht... ein paar Sachen besorgen? Oh bitte, bitte?", t = "Mein erstes Alchimieset"},
    [92110] = {ot = "Sammelt 3 Murlocaugen für die junge Alchimistin in der Scheune von Moonbrook in Westfall.", st = "Wow! Mein allererster Trank! Wusstet Ihr, dass sich der Trank leuchtend rot färbt, wenn man diese beiden Kräuter miteinander mischt? Ich jedenfalls nicht!\n\nDas hat Spaß gemacht. Aber ein paar Blumen zusammenzumischen sieht noch nicht nach der Alchimie aus, die Papa macht. Er benutzt auch noch andere Zutaten.\n\nIch weiß nur nicht, welche... Also probieren wir einfach das Erste aus, das mir einfällt! Hm ... vielleicht Murlocaugen? Das klingt total eklig, aber ich wette, damit passiert irgendwas.", t = "Mein erster echter Trank"},
    [92124] = {ot = "Sprecht in der Bibliothek mit Daniel, Bruder Paxtons Gehilfe.", st = "Wir müssen herausfinden, wie viele Bücher fehlen!\n\nSprecht mit meinem nutzlosen Assistenten Daniel. Er kann eine schnelle Bestandsaufnahme machen und herausfinden, wie gravierend das Problem ist.\n\nEr ist besessen von den verschiedenen Handelsberufen im Wald von Elwynn. Der Junge konzentriert sich lieber darauf, anstatt mir zu helfen.\n\nWürgt ihn ab, wenn er anfängt, von Berufsfertigkeiten zu schwadronieren, und findet heraus, was mit meinen Büchern geschehen ist!", t = "Bücherliste"},
    [92401] = {ot = "Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron.", st = "Es geht um meinen Mann, Edward...\n\nEr ist nicht von seiner wöchentlichen Reise zum Friedhof in den Ruinen von Lordaeron zurückgekehrt. Unser Sohn ging verloren, als Arthas die Stadt zerstörte, und mein geliebter Edward hat noch immer Schuldgefühle und leidet darunter, dass wir seine Leiche nie gefunden haben. Ich habe ihn davor gewarnt, diese überrannten Ruinen zu durchsuchen, aber er weigert sich aufzugeben. Ich versuche, mir keine Sorgen zu machen, aber er ist schon seit Tagen fort.\n\nEs gibt dort Dinge, mit denen ich es nicht aufnehmen kann. Aber wärt Ihr vielleicht so gut? Ich muss Gewissheit über das Schicksal meines Ehemanns haben.", t = "Eine verängstigte Bitte"},
    [92415] = {ot = "Bringt den blutbefleckten Brief zu Waisenmatrone Nightingale in Stormwind.", st = "<Ein zerrissenes und schmutziges Pergamentbündel hat gerade so die von Untoten zertrampelte Friedhofserde überstanden. Darin wird ein vermisstes Kind der Familie Heartweaver erwähnt. Vielleicht weiß die Waisenmatrone in Stormwind mehr darüber.>", t = "Denk daran, ich liebe dich"},
    [92421] = {ot = "Sammelt $1oa intakte Gliedmaßen in den Ruinen von Lordaeron für Morbin Lightbane in Undercity.", st = "Als Paladin der Verlassenen ist es meine Pflicht, den Willen der Dunklen Fürstin auszuführen und gleichzeitig die Bedürfnisse unseres Volkes zu erfüllen. Zum Glück bietet sich uns eine Gelegenheit, beides zu tun.\n\nÜber Undercity streifen immer noch Anhänger der Geißel in großen Zahlen herum. Unsere Truppen schwinden beim Versuch, unser Land zurückzuerobern, und verwesendes Fleisch kann nicht geflickt werden. Nicht ohne Ersatzteile.\n\nIch weiß, was unser glorreicher Hauptmann Garek Bandarion sich wünschen würde, wäre er noch unter uns. Zu beenden, was er begonnen hat, und unser Volk zu heilen. Für Lordaeron!", t = "Die Gerechtigkeit des Lichts"},
    [92422] = {ot = "Tötet Rath'mael in den Ruinen von Lordaeron für Todeswache Kristof in Brill.", st = "Es sind Berichte aus der Warte Lordamere tief in den Ruinen von Lordaeron eingetroffen. Ein unheiliger Nebel hat sich über die Straßen und den Friedhof gelegt, der es der Geißel dort oben teilweise erlaubt, im Verborgenen zu agieren.\n\nUnsere Späher berichten, dass er von einer neuen Macht in ihren Rängen herbeigerufen wird, einem Totenbeschwörer namens Rath'mael. Wir können es uns nicht leisten, dem einfach zuzusehen, $n.\n\nWenn Ihr Verbündete habt, versammelt sie, und eilt den Verlassenen zur Hilfe. Vertreibt diese Kreatur aus unseren Landen.", t = "Der Zorn von Rath'mael"},
    [92432] = {ot = "Meldet Euch beim Abbild der Erzmagierin Modera in der Nähe von Dalaran.", st = "Ich bringe schlimme Neuigkeiten aus Dalaran. Etwas hat unsere Leylinien unterbrochen und die Konstrukte der Stadt verhalten sich unberechenbar und zerstörerisch.\n\nWir wissen noch nicht, was dieses Chaos verursacht. Der Hohe Rat hat angeordnet, diese Sache vertraulich zu behandeln, damit unser Orden nicht in Verruf gerät. Aber wir können die Scharade nicht ewig beibehalten. Die Stadt wird überrannt, während wir sprechen!\n\nErzmagierin Modera hat mich ausgeschickt, um Hilfe von außen zu beschaffen. Sucht ihr Abbild in der Nähe von Dalaran am Lordameresee auf.", t = "Eine alarmierende Bitte"},
    [92434] = {ot = "Findet entlang des Lordameresees einen Weg nach Dalaran.", st = "Was auch immer Dalarans Barriere geschwächt hat, es hat die Stadt ins Chaos gestürzt. Nachdem Ihr Euch nun um ihre Patrouillen gekümmert habt, ist das der perfekte Zeitpunkt, um uns rein zu schaffen und ihre Geheimnisse aufzudecken.\n\nNehmt den Schlüssel, den Ihr im Internierungslager gefunden habt und sucht an am nördlichen Stadtrand nach Eingängen zur Kanalisation. Mit etwas Glück haben die Magier keinen Grund gesehen, einen derart... unangenehmen Zugang magisch zu schützen.", t = "Blut in den Straßen"},
    [92456] = {ot = "Pflückt eine teufelserfüllte Blüte in Dalaran für Shylamiir in Stormwind.", st = "Wenn Ihr mir schon auf die Nerven geht, könnt Ihr Euch wenigstens nützlich machen. Ich habe eine Besorgung zu erledigen.\n\nFür eine Stadt der Magie hat Dalaran ein überraschend großes Interesse an Botanik. Die Kirin Tor bleiben gern unter sich, aber ich hätte sehr gerne eine Probe ihrer mit Mana angereicherten Vegetation.\n\nIhr fühlt Euch ganz offensichtlich am meisten dort zuhause, wo Ihr nicht erwünscht seid, also schafft Ihr es vielleicht in die Stadt hinein. Sollte es Euch gelingen, so bringt mir Proben von all jenen Pflanzen, die in ihren inneren Gärten wachsen.", t = "Eine grüne Probe"},
    [92457] = {ot = "Besiegt $1oa suchende Fragmente, $2oa gesättigte Fragmente und $3oa Manaechos in Dalaran für Erzmagierin Modera vor Dalaran.", st = "Der Ausbruch beeinträchtigt viele unserer Handlanger und Verzauberungen in der ganzen Stadt, darunter auch viele, die für unsere Verteidigung wichtig sind. Diese fragmentierte arkane Energie zieht abtrünnige Elementare an, die sich an der freifließenden Magie sättigen wollen.\n\nIhr würdet den Kirin Tor einen großen Gefallen tun, wenn Ihr diesen elementaren Pulk auslöschen könntet, während wir uns um die Zauberschutze und andere Zwischenfälle kümmern.", t = "Verhungernder Arkaner"},
    [92458] = {ot = "Holt den Arkanpartikel für das Abbild von Erzmagierin Modera in der Nähe von Dalaran.", st = "Was auch immer die Leylinien gestört hat, es begann an der Spitze der Violetten Zitadelle. Ein Donnerknall hallte von den Turmzimmern und jetzt werden wir von ungezügelter arkaner Macht überrannt. Es verlangt uns alles ab, allein die Schutzzauber aufrechtzuhalten.\n\nWir können es nicht länger aufschieben, wir brauchen Hilfe.\n\nDie Kirin Tor sind drinnen beschäftigt, aber Ihr werdet Euch dennoch auf inoffiziellem Wege Eintritt verschaffen müssen. Nehmt diesen Schlüssel und trefft mich in der Zitadelle, sobald Ihr in der Stadt seid. Wir müssen dieser Störung ein Ende machen.", t = "Das Herz der Störung"},
    [92460] = {ot = "Sprecht mit Rorian dem Tagsucher im Thendalhain.", st = "Seht Euch an: voller Tatendrang und bereit fürs Abenteuer! Hier in Thendal brauchen wir jede Hilfe, die wir kriegen können, also kommt Eure Ankunft sehr gelegen. Ich kann mir vorstellen, dass Ihr Eurer Zukunft nervös entgegenblickt. Schließlich wird man nur einmal im Leben erwachsen.\n\nGeht, sucht Euren Dorfanführer Rorian den Tagsucher auf. Er steht am Eingang des Altvaterbaums westlich von hier und wird Euch die ersten Schritte auf Eurem Weg zeigen.", t = "Erwachsen werden"},
    [92461] = {ot = "Tötet 8 junge Vuldren im Thendalhain.", st = "Diese Zeiten sind für unser Volk von Unsicherheit geprägt. Wir sehen uns ungeahnten Herausforderungen gegenüber, die gewagte Lösungen erfordern. Gleichzeitig müssen wir hier im Thendalhain jedoch auch Alltägliches bewältigen. Nehmen wir zum Beispiel die jüngste, nicht mehr tragbare Vermehrung der Vuldren.\n\nDie Vuldren sind ein unverzichtbarer Teil unseres Ökosystems. Etwaige Störungen des Gleichgewichts müssen jedoch behoben werden, um die zerbrechliche Harmonie aller Lebewesen im Thendalhain zu bewahren.\n\nGeht Richtung Osten und dezimiert dort einige Vuldren.", t = "Harmonisches Gleichgewicht"},
    [92462] = {ot = "Tötet 8 lästige Zirrusfliegen im Thendalhain.", st = "Einer unserer Waldläufer hat kürzlich einen Befall durch Zirrusfliegen hier im Thendalhain gemeldet.\n\nZirrusfliegen können gefährlich werden, wenn der Schwarm zu groß wird. Begebt Euch daher bitte zum östlichen Ende des Hains und vernichtet so viele von ihnen wie möglich.", t = "Befallsbegutachtung"},
    [92463] = {ot = "Vernichtet die Zirrusfliegenkönigin im Thendalhain.", st = "Wenn der Wald wirklich so wimmelt von diesen Insekten, wie es sich anhört, wird es nicht reichen, einfach nur die Arbeiter zu töten.\n\nBegebt Euch tiefer in den Wald hinein und sucht die Königin. Sie wird sich in der Nähe des Baus befinden und von größeren und aggressiveren Soldaten umgeben sein. Seid also vorsichtig.\n\nErledigt sie und kommt hierher zurück, wenn Ihr damit fertig seid. Dann haben wir hier ein Problem weniger, um das wir uns kümmern müssen.", t = "Die Zirrusfliegenkönigin"},
    [92464] = {ot = "Sprecht mit Yala Windwächter im Thendalhain.", st = "Seit unsere elementaren Wohltäter uns verlassen haben, scheinen wir von einer Aufruhr in die nächste zu schlittern. Unser aktuelles Problem besteht darin, dass die Manifestationen der Winde bei den Menhiren im Nordesten aufgebracht sind.\n\nSie sind nicht wirklich empfindsam wie die Windgeister, die einst dort lebten. Diese einfacheren Wesen reagieren auf Kräfte, Gefühle und Absichten der Kreaturen um sie herum und geben sie wieder.\n\nMeine Schülerin Yala Windwächter ist losgezogen, um sie zu beobachten. Sucht sie auf und findet heraus, was sie in Erfahrung gebracht hat.", t = "Unruhige Elemente"},
    [92465] = {ot = "Tötet $2oa aufgewühlte Winde und $1oa Konvertiten der Al'Aketh im Thendalhain.", st = "Der Kult der Al'Aketh sucht dieses Land heim. Die Kultisten sind gewiss dafür verantwortlich, die einfachen Windgeister aufzuhetzen, die hier leben, und sie aggressiv zu machen.\n\nLeider werden wir diese brodelnden Winde hier auflösen müssen, bevor sie noch jemandem etwas tun. Außerdem müssen wir dem Kult eine klare Botschaft senden, dass er in diesem Hain nicht willkommen ist.\n\nWerdet Ihr mir helfen, $C?", t = "Aufrührer"},
    [92466] = {ot = "Bringt Windformer Boro ein Siegel von Akir.", st = "Während wir einen Großteil unseres Wohlstands den Elementen des Windes verdanken, erfordert der von uns beschrittene Pfad, dass wir dem Ruf aller vier Primärelemente gehorchen und für jedes eine Prüfung abschließen. Bevor Ihr jedoch ernsthaft Eure erste Prüfung antretet, müsst Ihr die Stärke Eurer Entschlossenheit beweisen.\n\nReist zu den Menhiren im Osten. Eine Kraft von Al'Akeths Konvertiten wurde dort gesichtet und muss vertrieben werden. Konfrontiert die Kultisten dort und bringt mir eines ihrer Siegel als Beweis für Eure Taten.", t = "Ruf der Erde"},
    [92467] = {ot = "Sucht die Anhöhe der Geister und trinkt das Erdsapta.", st = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.$B$BDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo... vergesst das nicht.$B$BBesucht die Anhöhe der Geister nordöstlich von hier. Trinkt Euer Sapta dort und... tja, Ihr werdet sehen, was Ihr sehen müsst.", t = "Ruf der Erde"},
    [92468] = {ot = "Bringt den Rohquarz zu Windformer Boro im Thendalhain.", st = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu demjenigen, den Ihr Windformer Boro nennt. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Splitter sein soll. So winzig er scheinen mag, werdet Ihr feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.$B$BHabt Geduld, $n. Bleibt stark und sucht Weisheit. Dies verlangen die Elemente von Euch. Am Ende solltet Ihr eins mit der Erde werden... Respektiert sie so, wie sie Euch respektiert.", t = "Ruf der Erde"},
    [92469] = {ot = "Berichtet Rorian dem Tagsucher im Thendalhain von den Al'Aketh.", st = "Ihr habt hier genug getan, $C. Ich werde hierbleiben und mich um den Rest kümmern.\n\nKehrt ins Dorf zurück und meldet Rorian, dass der Kult hier eine Präsenz hat. Er wird wenig erfreut sein.", t = "Rückkehr zu Rorian"},
    [92470] = {ot = "Tötet 8 Urseraplünderer und beschafft den Kopf ihrer Höhlenmutter Urs'anah im Thendalhain.", st = "Rorian hat Euch Bescheid gesagt, dass ich Euch beobachtet habe. Ich biete Euch jetzt eine Prüfung Eurer Entschlossenheit an. Seid jedoch gewarnt: Sie wird Euch in große Gefahr schicken.\n\nGeht zu den Höhlen im Süden. Dezimiert die Ursera dort und findet ihre Matriarchin. Die Waldläufer nennen sie \"Urs'anah\". Erledigt sie und bringt mir einen Beweis ihres Ablebens. Sobald Ihr das geschafft habt, habt Ihr einen wichtigen Schritt auf Eurem Weg hinter Euch.", t = "Widerwärtige Matriarchin"},
    [92471] = {ot = "Sprecht mit Aetheen von den Winden im Thendalhain.", st = "Es mag Euch nicht klar sein, aber alles, was Ihr getan habt, stellte eine Art Prüfung dar. Als Vorbereitung darauf, was Euch bevorsteht. Eine große Insel liegt da draußen, und Zephras braucht entschlossene junge Abenteurer wie Euch, wenn unser Volk die Schwierigkeiten überstehen soll, die ihm bevorstehen.\n\nZu den Anführern unseres Volkes hier auf der Insel Zephras gehört eine, die man Aetheen von den Winden nennt. Sie hat Euch beobachtet und sie hat eine Aufgabe für Euch, die Ihr abschließen müsst. Sprecht mit Ihr, um mehr darüber zu erfahren.", t = "Aetheen von den Winden"},
    [92472] = {ot = "Meldet Euch bei Wachtmeisterin Aonda in Shen'dar.", st = "Eine der allgegenwärtigsten Bedrohungen auf der Insel Zephras ist der Al'Aketh-Kult. Sie sind religiöse Zeloten, die sich der Anbetung des vermeintlichen Elementarherrschers des Himmelswalls, Al'Akir der Windlord, verschrieben haben. Sie sind brutal, unbeirrbar und ihre Macht und ihr Ehrgeiz nehmen von Tag zu Tag zu.\n\nEure Reise wird Euch bald in das Dorf Shen'dar im Süden führen. Meldet Euch bei Wachtmeisterin Aonda, sobald Ihr ankommt. Der Kult bedroht Shen'dar und sie brauchen Hilfe. Sagt Aonda, dass ich Euch geschickt habe.", t = "Der nächste Schritt"},
    [92473] = {ot = "Sammelt 6 magere Urseraklauen von mageren Ursera im Thendalhain.", st = "Die Urserahöhle im Südwesten wird immer mehr zum Problem. Letzte Woche mussten die Waldläufer erst einen halbwüchsigen Ursera töten, der zu nah ans Dorf gekommen war und einen Jungen angreifen wollte, der unter dem Ältestenbaum im Dorfzentrum gespielt hat.\n\nWir hatten Glück, dass der Junge lebendig davongekommen ist. Hunger und Verzweiflung machen diese Tiere so gefährlich, dass wir sie in die Schranken weisen müssen. Zieht gen Süden und dezimiert die schmächtigsten Ursera. Bringt mir dann ihre Klauen als Beweis, dass es getan ist.", t = "Aggressive Übergriffe"},
    [92474] = {ot = "Springt von der Spitze des Wachturms im Thendalhain und verlangsamt Euren Fall mit Eurer Fähigkeit \"Luftwandeln\".", st = "Seid gegrüßt, $n! Möchtet Ihr ein Spiel spielen?\n\nDazu müsst Ihr nur auf diesen Sims treten... und springen! Nutzt Eure angeborene Fähigkeit, in der Luft zu wandeln, um Euren Fall zu verlangsamen. Seht, wie weit Ihr so schweben könnt!\n\nDie Regeln sind ausgedacht und die Punkte unwichtig, aber falls Ihr direkt vor Rorian dem Tagsucher landet und ihn erschreckt, erhaltet Ihr Bonuspunkte! Das wird ihm nicht gefallen, aber ich werde mich kaputtlachen, wenn er sich aufregt! Ha!", t = "Fallen mit Stil"},
    [92479] = {ot = "Lest den gekritzelten Brief und sprecht mit Tordrin Stemblade in der Abtei von Nordhain.", st = "Ich wurde gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $n. Es scheint sich um einen versiegelten Brief mit dem Zeichen von Tordrin Stemblade, unserem örtlichen Jäger, zu handeln. Nehmt Euch die Zeit, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", t = "Ein gekritzelter Brief"},
    [92481] = {ot = "Untersucht den leuchtenden Rückrufkristall und sprecht dann mit Dorii Brightwhisper im Thendalhain.", st = "Während Ihr mit Eurem Vuldrenproblem beschäftigt wart, hat unsere Magielehrerin, Dorii Brightwhisper, diesen Kristall für Euch hiergelassen. Er enthält eine Art Nachricht für Euch, also schaut ihn Euch an. Danach könnt Ihr Dorii im Gebäude direkt hinter mir finden.", t = "Ein Schüler des Arkanen"},
    [92482] = {ot = "Lest die gekritzelte Notiz und sprecht dann mit Tai'ree Farsight im Thendalhain.", st = "Während Ihr mit Eurem Vuldrenproblem beschäftigt wart, hat unsere Jägerlehrerin, Tai'ree Farsight, eine Nachricht für Euch hiergelassen. Ihr könnt sie dort drüben in der Nähe der Mitte des Dorfes finden. Lest die Nachricht und sucht sie dann auf.", t = "Der Weg des Jägers"},
    [92483] = {ot = "Lest die einfache Notiz und sprecht dann mit Akeri Duskblade im Wachturm im Thendalhain.", st = "Während Ihr mit Eurem Vuldrenproblem beschäftigt wart, hat unser Schurkenlehrer, Akeri Duskblade, verlangt, mit Euch zu sprechen. Er hat diese Nachricht hinterlassen, also lest sie zuerst und sucht ihn dann im Wachturm hier im Dorf auf.\n\nEr ist eine zwielichtige Gestalt, aber das gilt ja auch für Euch. Ich glaube, Ihr werdet Euch gut verstehen.", t = "Zu Hause in den Schatten"},
    [92484] = {ot = "Untersucht den summenden Rückrufkristall und sprecht dann mit Windformer Boro im Thendalhain.", st = "Während Ihr mit Eurem Vuldrenproblem beschäftigt wart, hat unser Schamanenlehrer, Windformer Boro, verlangt, diesen Rückrufkristall für Euch hinterlegt. Bitte schaut ihn Euch an und sprecht dann mit Boro dort drüben in der Nähe der Mitte des Dorfes.", t = "Hingabe zu den Elementen"},
    [92485] = {ot = "Lest das gefaltete Pergament und sprecht dann mit Xyton Silberwind im Thendalhain.", st = "Während Ihr mit Eurem Vuldrenproblem beschäftigt wart, hat unser Druidenlehrer, Xyton Silberwind, eine Nachricht für Euch hiergelassen. Lest sie so bald wie möglich und sucht dann Silberwind auf der unteren Ebene des großen Baums direkt hinter mir auf.\n\nWürdigt seine Worte und Ratschläge, denn er kann Euch viel beibringen.", t = "Ein Schüler der Natur"},
    [92489] = {ot = "Tötet den Manaelementar in Dalaran für Zaubermeister Andromath in Stormwind.", st = "Die Kirin Tor sind seit langer Zeit Verbündete der Allianz. Nach der Zerstörung ihrer Stadt durch die Hand des Erzdämons Archimonde ist die einst stolze Magierstadt zurückgezogen und misstrauisch gegenüber Fremden geworden.\n\nSeit einigen Jahren widmen sie sich dem Wiederaufbau, um Dalaran zu seinem früheren Ruhm zurück zu verhelfen. Aber Berichte zeigen, dass sie mit einem Ausbruch unkontrollierbarer arkaner Energie zu kämpfen haben.\n\nWir müssen ihnen mit diesen Angriffen helfen, wenn wir nicht einen unserer mächtigsten Verbündeten verlieren wollen.", t = "Überwältigende Macht"},
    [92514] = {ot = "Sprecht mit Illaya Amberwind und Coriella Calmbreeze in Shen'dar.", st = "Ihr habt diese \"Windformer-Aura\" an Euch. Es ist wie ein statisches Prickeln auf der Haut, das die Anwesenheit eines Geistberührten verrät. Bevor ich Euch hier zum Einsatz bringe, solltet Ihr Euch bei unserer hiesigen Ältesten der Windformer melden, Illaya Amberwind. Sie ist gleich draußen, in der Nähe des Dorfzentrums.\n\nOh, und schaut auch bei Coriella Calmbreeze vorbei, sie führt das Gasthaus vor Ort und kann Euch mit einer Unterkunft und Vorräten versorgen, falls Ihr sie braucht.", t = "Willkommen in Shen'dar"},
    [92515] = {ot = "Sammelt 10 Rudelkrallenpelze von Rudelkrallen im Shen'darhochland.", st = "Als wären Banditen und wahnsinnige Kultisten nicht schlimm genug, wimmelt es in den Hügeln jetzt auch noch vor Rudelkrallen. Sie nähern sich dem Dorfrand und werden jeden Tag mutiger. Es ist nur eine Frage der Zeit, bis sie das Haustier oder Kind von jemandem holen. Es wäre uns ein Segen, sie jetzt auszumerzen, anstatt erst nachdem es zu einer Tragödie kam.\n\nBringt mir ein Dutzend ihrer Pelze. Daraus kann ich alle möglichen Waren herstellen, die dem Dorf zugutekommen.", t = "Das Problem mit Rudelkrallen"},
    [92516] = {ot = "Tötet 8 junge Hippogryphen, 6 Hippogryphenbeschützer und eine Hippogryphenmatriarchin im Shen'darhochland.", st = "Ein Schwarm Hippogryphen nistet seit einer Weile südöstlich von Shen'dar und belästigt die Reisenden auf der Straße. Ich brauche jemanden, der dort hingeht und sie für uns ausdünnt.", t = "Hippogryphenschikane"},
    [92517] = {ot = "Tötet 10 Hochlandbanditen und ihren Anführer \"Übelwind\" Bennic im Shen'darhochland.", st = "Es gibt eine Höhle im Norden, versteckt hinter einem Wasserfall. Es ist mir wohlbekannt, dass es eine Gruppe von Banditen gibt, die von dieser Höhle aus operieren. Sie waren ein Problem für uns, bevor der Kult hier ankam, aber jetzt haben sie sich zu einem wahren Schrecken entwickelt. Ich kann leider keine Leute entbehren, um sie zu vertreiben.\n\nIch bitte Euch, dorthin zu gehen und Euch für mich um sie zu kümmern. Tötet so viele Ihr könnt und schaltet wenn möglich ihren Anführer aus, den sogenannten \"Übelwind\" Bennic. Es ist gefährlich in der Höhle, gebt also acht.", t = "Das kriminelle Element"},
    [92528] = {ot = "Seht Euch in Falaath um, um die Absichten des Kultes im Shen'darhochland herauszufinden.", st = "Die Gläubigen von Al'Akir werden mit jedem eifrigen neuen Rekruten wie Euch immer stärker. Wie Ihr seht, verleiht unsere Stärke dem Sturm selbst seine Form!\n\nNormalerweise würde ich Euch für die Bewertung direkt zu Himmelspriester Aanders schicken, aber er ist gerade damit beschäftigt, einen Gast im Wirtshaus im Norden der Stadt zu empfangen. Haltet Euch für den Moment von diesem Ort fern. Ein ungeformter Rekrut wie Ihr wäre in der Gegenwart eines solch hohen Gastes unangemessen.\n\nSeid vorerst einfach niemandem im Weg.", t = "Inmitten der Gläubigen"},
    [92529] = {ot = "Meldet Euch bei Missionar Jasaan in der Nähe des Eingangs von Falaath.\n\nWenn Ihr Euer Mal von Akir verliert, sprecht mit Sania Silverstream in Shen'dar, um ein neues zu erhalten.", st = "Es erfreut mein Herz, dass Ihr Al'Akir dienen wollt. Unsere aktuellen Prüfungen als Volk sind Folge unserer Selbstgefälligkeit. Wir gaben uns dem Stolz hin und hielten die Gaben der Winde für selbstverständlich. Die Stagnation, die darauf folgte, ist der Grund, warum die Geister des Windes uns verlassen haben.\n\nNur durch Akte der Buße können wir hoffen, einmal mehr die Umarmung des Windes zu spüren. Wenn Ihr die Gesellschaft Gleichgesinnter Shen'dorei sucht, geht nach Falaath und sucht Missionar Jasaan auf. Ich werde Euch mit einem Zeichen versehen, sodass die Gläubigen Euch als Rekruten erkennen.", t = "Falaath"},
    [92532] = {ot = "Lest die zusammengeknüllte Notiz, die man Euch gab, und sucht dann Klingenmeisterin Ren im Wachturm des Dorfes auf.", st = "Während Eurer Abwesenheit bat unsere Kriegerlehrerin, Klingenmeisterin Ren, darum, Euch nach Eurer Rückkehr zu ihr zu schicken. Und sie hat Euch dieses Schreiben hier hinterlassen.\n\nLest es durch und sucht dann Klingenmeisterin Ren im Wachturm hier im Dorf auf.", t = "Der Pfad des Kriegers"},
    [92544] = {ot = "Tötet 6 Schläger der Al'Aketh, 4 Neophyten der Al'Aketh und Malduko Cloudcrush im Thendalhain.", st = "Eine Gruppe Unruhestifter der Al'Aketh hat sich in der Nähe der Tempelruinen südwestlich von hier eingenistet. Angeführt werden sie von einem richtigen Ungeheuer, genannt Malduko Cloudcrush. Diese Bande wurde zweifelsohne von Hohepriesterin Lorthuna am Schrein von Akir hergeschickt, um Reisende anzugreifen und uns zu zwingen, dem Kult beizutreten.\n\nIch muss auf meinem Posten bleiben, um Reisende auf dem Weg aus dem Hain zu warnen, aber ich wäre Euch dankbar, wenn Ihr etwas gegen diese Kultisten und ihren Anführer unternehmen könntet.", t = "Schläger der Al'Aketh"},
    [92550] = {ot = "Reist in die Ruinen von Falaath und tötet 6 Sturmrufer der Al'Aketh, 4 lebendige Blitze und holt Euch den Kopf von Kommandant Cyclas.", st = "Unsere beste Verteidigung könnte hier ein starker Angriff sein. Wir haben gerade den Vorteil, dass wir mit einem Angriff rechnen. Was sie nicht erwarten werden ist, dass wir zuerst zuschlagen.\n\nIch habe bereits viel von Euch verlangt, aber geht bitte zurück nach Falaath. Tötet so viele Kultisten wie Ihr könnt und, falls Ihr ihm nahe genug kommt, tötet ihren Anführer und bringt mir seinen Kopf. Ich bleibe hier und bereite die Bürger und unsere wenigen Friedensbewahrer auf die Verteidigung vor... Nur, falls Ihr nicht zurückkehrt.", t = "Verwüstung im Hochland"},
    [92551] = {ot = "Sammelt 10 Pakete gestohlener Vorräte der Shen'dar in Falaath im Shen'darhochland.", st = "Ich habe gehört, dass Ihr nach Falaath geht? Wenn Ihr dort seid, haltet bitte die Augen nach unseren gestohlenen Vorratskisten offen.\n\nDie Al'Aketh überfallen seit Monaten unsere Versorgungskarawanen, die Waren wie Nahrung und Windsteine ins und aus dem Flachland transportieren. Sie schieben es natürlich auf die Banditen, aber wir alle wissen, dass am Schluss alles am selben Ort landet. Wenn Ihr etwas davon in Falaath findet, wäre es uns eine große Hilfe, wenn Ihr es zurückbringt.", t = "Gestohlene Versorgungsgüter"},
    [92553] = {ot = "Sammelt $1oa kleine Eier und $2oa Stück Schreiterfleisch von den Kreaturen im Shen'darhochland.", st = "Sucht Ihr Arbeit? Ich könnte etwas Muskelkraft von einer abenteuerlichen Gestalt wie Euch brauchen. So gefährlich wie es hier in letzter Zeit geworden ist, hat niemand mehr Zeit zum Jagen oder Sammeln. Jemand muss für mich da raus gehen und mir frische Eier und Schreiterfleisch beschaffen, um das Dorf zu ernähren.\n\nIch bringe Euch gern eines meiner berühmten Rezepte bei, wenn Ihr mir bringt, was ich brauche. Was meint Ihr?", t = "Die Vorratskammern auffüllen"},
    [92579] = {ot = "Bringt Aondas schriftlichen Bericht zu Valennia Stormfist in Valanaar.", st = "Für den Moment scheinen der Pylon und unser Dorf sicher zu sein, ich möchte Euch also bitten, diesen Bericht zu Valennia Stormfist in Valanaar zu bringen, an der südöstlichen Küste der Insel. Valennia ist die Anführerin der Friedensbewahrer auf der Insel und sie muss erfahren, was hier passiert ist.\n\nDer Kult breitet sich rasend schnell aus und die Friedensbewahrer sind bisher einer direkten Konfrontation aus dem Weg gegangen, aber diese Tage sind vorbei. Valanaar muss sich auf einen Kampf gefasst machen.\n\nSo oder so, ich danke Euch. Ihr werdet immer Freunde in Shen'dar haben, $n.", t = "Nach Valanaar"},
    [92595] = {ot = "Hört Euch an, was Illaya Amberwind zu sagen hat.", st = "<Illaya schenkt Euch ein warmes Lächeln.>\n\nIch bin froh, dass Ihr für ein Gespräch mit mir zurückgehkehrt seid, Kind der Winde. Ich wusste, dass Ihr eine Begabung für die Himmelssicht besitzt. Findet Ihr das überraschend? Selbst jene, die nicht zu einem Schamanen ausgebildet wurden, können diese Gabe besitzen.\n\nKommt, sprechen wir über die Pflicht der Windformer, die Natur unserer Mühen auf Zephras und die Misere unseres Volkes.", t = "Die Windformer"},
    [92596] = {ot = "Setzt Euch und sprecht mit Rathiril Sunlance.", st = "Die Aura der arkanen Energie, die Euch umgibt, ist selbst für einen Magier wie Euch von ungewöhnlicher Stärke. Ich bin sicher, dass Ihr $gein fähiger Abenteurer:eine fähige Abenteurerin; sein werdet, und Eure Verbindung zu unserer uralten Magie wird Euch stets ein Segen sein - selbst wenn Ihr in Eurer Zauberkunst nie auch nur ein einziges Wort der Macht sprecht.\n\nKommt, setzen wir uns und sprechen über die Natur des Arkanen hier auf Zephras und die Misere unseres Heimatlandes.", t = "Der Hohe Orden"},
    [92597] = {ot = "Nutzt Eure Volksfähigkeit \"Leylinie erschließen\" an der Leylinie im Thendalhain.", st = "Hier auf der Elementarebene erschließen wir einen großen Teil unserer arkanen Kraft aus den Leylinien, die immer noch durch den Boden unter unseren Füßen fließen. In letzter Zeit haben diese Leylinien begonnen, die Oberfläche zu durchbrechen, sodass wir direkteren Zugang auf und mächtigere Möglichkeiten mit diesen latenten arkanen Energien haben.\n\nGeht zu den Menhiren im Nordosten. Dort befindet sich eine Leylinie. Nutzt Euer Geburtsrecht und zapft ihre Energie an.", t = "In den Leylinien lesen"},
    [92598] = {ot = "Verwendet Eure Volksfähigkeit \"Himmelssicht\" bei der Elementarkonvergenz im Thendalhain.", st = "Als Windformer habt Ihr die Fähigkeit, die heilige Himmelssicht zu nutzen, die uns von den Elementargeistern geschenkt wurde. Reist zu den Menhiren im Nordosten des Dorfes. Findet die Elementarkonvergenz dort und verwendet Eure Gabe.\n\nIhr könnt Eure Himmelssicht an einem beliebigen Ort nutzen, ihre Macht ist jedoch viel größer, wird sie in der Gegenwart einer Elementarkonvergenz eingesetzt. Manchmal erhaltet Ihr auch andere Weisheiten von den Geistern, die von derartigen machterfüllten Orten angezogen werden.", t = "Die Gabe der Himmelssicht"},
    [92640] = {ot = "Sprecht mit Valanaar Stormfist in Valanaar und folgt ihren Anweisungen.", st = "Da ein direkter Angriff auf den Kult im offenen Feld nicht infrage kommt, besteht unsere beste Chance darin, diese Gelegenheit zu nutzen und den Schrein selbst anzugreifen. Wir können Lorthuna selbst ausschalten, bevor sie ihren Teil dieses Plans in die Tat umsetzen kann.\n\nEs trifft sich gut, dass Valennia schon seit geraumer Zeit eine Strategie für einen potenziellen Angriff auf den Schrein vorbereitet. Das einzige Problem ist, dass wir Hilfe brauchen werden.\n\nSprecht mit Valennia, um die Einzelheiten zu erfahren.", t = "Verzweifelte Zeiten"},
    [92642] = {ot = "Tötet 4 Heiler der Al'Aketh und 8 Muskelprotze der Al'Aketh im Böenbeerentiefland.", st = "Valennia hat nur eine einzige Person geschickt, um einen Großangriff abzuwehren... bei den Winden.\n\nIhr macht keinen großen Eindruck, aber ich nehme jede Hilfe, die ich kriegen kann. Wir müssen so viel Schaden wie möglich anrichten, um dem Ganzen bald ein Ende zu setzen. Meine Leute halten nicht mehr lange durch.\n\nGeht den Hügel hinunter und stört ihre Logistik. Ihre Heiler sorgen dafür, dass immer neue Angreifer nachrücken. Wenn wir sie ausschalten, können wir uns vielleicht sammeln und sie zurückschlagen. Jeder andere Kultist, den Ihr da draußen erschlagt, ist ebenfalls eine Hilfe.", t = "Störung der Logistik"},
    [92643] = {ot = "Findet den abtrünnigen Kultisten im Haus im Hochland nordwestlich von Valanaar.", st = "Es gibt einen Abtrünnigen unter dem Al'Aketh. Er behauptet, die wahren Absichten des Kults für die Insel zu kennen, und will sich uns anschließen - allerdings nur unter der Zusage von absolutem Schutz.\n\nDieser Deserteur versteckt sich in einem abgelegenen Anwesen direkt nordwestlich von Valanaar im Hochland. Ich brauche jemanden, der sich diskret dorthin begibt, den Verräter ausfindig macht und ihn sicher zu uns geleitet. Das Ganze könnte eine Falle sein, aber wenn diese Informationen so wichtig sind, wie dieser Verräter behauptet, ist es das Risiko wert.", t = "Der Abtrünnige"},
    [92644] = {ot = "Überbringt den leuchtenden Kristall an Talaanis Shadowsong in Valanaar.", st = "<Ihr greift unter den noch warmen Körper des abtrünnigen Kultisten und findet einen kleinen, leuchtend blauen Kristall. Er scheint beschädigt, aber immer noch von Bedeutung zu sein. Der Hochälteste Shadowsong könnte daran interessiert sein.>", t = "Bedauerliche Neuigkeiten"},
    [92645] = {ot = "Tötet Kommandantin Belguilos im Böenbeerentiefland.", st = "Es wird schwer, diesen Angriff abzuwehren, solange wir nicht die Kommandantin des Kults ausschalten. Belguilos \"die Brecherin\" nennen sie sie, und sie ist ein regelrechter Alptraum. Sie war früher selbst eine Friedensbewahrerin, bevor der Kult außer Kontrolle geriet, und schon damals war sie... seltsam. Jetzt, da sie eine Kultistin ist, mag ich mir kaum ausmalen, wie viel schlimmer sie geworden ist.\n\nVielleicht schicke ich Euch direkt in Euren Tod, aber jemand muss Belguilos ausschalten, wenn wir hier überleben wollen. Ihr findet sie bei der Villa am Fuße des Hügels. Viel Glück, $c.", t = "Die Brecherin brechen"},
    [92646] = {ot = "Nehmt das Portal zu den Türmen der Rohashi oben und schließt Euch Elaadrin Evengale und Ayessa Dawnsinger bei ihrer Konfrontation mit der Hohepriesterin Lorthuna an.", st = "Lorthuna ist mithilfe einer Art von Portal zu den Spitzen geflohen. Ayessa und Elaadrin sind ihr gefolgt. Das ist gerade erst passiert.\n\nIch fürchte, ich habe einen Treffer zu viel eingesteckt und muss daher hier bleiben. Geht durch das Portal, findet Ayessa und helft ihnen, Lorthuna aufzuhalten.\n\nWenn die Hilfe, die Elaadrin und Ayessa uns versprochen haben, nicht bald eintrifft, seid Ihr von hier an auf Euch allein gestellt. Viel Glück, $C.", t = "Konfrontiert Lorthuna"},
    [92679] = {ot = "Hört Euch an, was Alvarion Windfield zu sagen hat, und sucht Aamelia Windfield in Obsthain der Windfields auf.", st = "H-Hallo, :Fremder:Fremde;. Ihr seht aus wie :ein fähiger Abenteurer:eine fähige Abenteurerin. Ich...\n\n<Der Himmelsgeborene zuckt zusammen, sichtlich von schrecklichen Schmerzen gepeinigt.>\n\n... Ich habe mich gefragt, ob Ihr auf der Suche nach Arbeit seid? Ich bin nach Valanaar gekommen, um Kämpfer zu rekrutieren, die mir bei der Rettung meines Hofes helfen können. Falls Ihr Interesse habt, sucht bitte nach meiner Gattin Aamelia Windfield in unserem Obsthain westlich von Valanaar, im Tiefland.", t = "Blutzoll"},
    [92682] = {ot = "Sammelt 10 reife Sturmäpfel und tötet 5 hungrige Banditen im Obsthain der Windfields.", st = "Oh, Ihr habt also mehr Mut als Verstand? Nun gut, ich werde nicht mit Euch streiten.\n\nFerauu und seine Handlanger werden ihre Ernte noch nicht abholen, also werde ich Euch für Eure Mahlzeiten arbeiten lassen, bis sie eintreffen.\n\nGeht nach draußen und sammelt die Sturmäpfel von heute für mich. Oh, und die Banditen lauern zwischen den Sturmapfelbäumen... Sie halten sich für gerissen, sind sie aber nicht. Tötet sie für mich. \n\nMal sehen, was Ihr im Kampf so draufhabt.", t = "Macht Euch nützlich"},
    [92683] = {ot = "Sammelt 5 Flatterfliegenstaub von den Flatterfliegen um das Böenbeerentiefland.", st = "Ihr habt sicherlich schon die riesigen Flatterfliegen auf den äußeren Feldern nahe dem Obsthain bemerkt? Sie sind wahrlich hübsch anzusehen, doch sie bergen noch einen anderen Nutzen; und zwar ihren Flügelstaub. Es kann eine recht unschöne Angelegenheit sein, doch wenn Ihr ihn in großen Mengen sammelt, kann er sich im Haushalt als überaus nützlich erweisen.\n\nNehmt diese Flatterfliegenklatsche und verpasst den großen Käfern einen kräftigen Hieb für mich. Gewöhnlich erschrecken sie bloß und ergreifen die Flucht, doch manchmal sind sie etwas gekränkt. So oder so werden sie ihr Hinterteil schütteln und einen Haufen Staub fallen lassen.", t = "Flatterfliegenstaub"},
    [92684] = {ot = "Sammelt 7 Tieflandwindschreiterfilets von den störrischen Windschreitern, die im Böenbeerentiefland zu finden sind.", st = "Als ob die Ernte in diesem Jahr nicht ohnehin schon dürftig genug ausgefallen wäre, fallen nun auch noch die Windschreiter in dieser Gegend in den Obsthain ein und stehlen meine Sturmäpfel. Glaubt Ihr, Ihr könntet Euch zu den Feldern begeben und sie für mich ausschalten?\n\nSeid jedoch auf der Hut, $gFremder:Fremde;, diese Tieflandwindschreiter sind größer und aggressiver als die aus dem Hochland. Passt auf Euch auf. Ein wohlgezielter Tritt reicht völlig aus, um Euch für immer zu Strecke zu bringen, solltet Ihr nicht achtsam sein.\n\nBringt mir etwas von ihrem Fleisch und ich werde daraus eine warme Mahlzeit für uns zubereiten.", t = "Störrische störrische Windschreiter"},
    [92685] = {ot = "Plündert 7 blutbefleckte Banditenmasken von den Banditenstraßenräubern im Böenbeerentiefland.", st = "Die Banditen haben überall Lager und es gibt ein kleines in den Hügeln nördlich von hier. Begebt Euch dorthin und schlagt ein paar Schädel ein. Wenn es uns gelingt, sie unvorbereitet zu überraschen und sie auszuschalten, ehe sie Jagd auf uns machen, könnten wir das Blatt gerade weit genug wenden, um eine Chance zu haben.\n\nBringt mir ihre Masken. Je blutiger, desto besser.", t = "Die Hügel der Augen"},
    [92693] = {ot = "Sprecht mit Aamelia Windfield, wenn Ihr bereit seid, den Banditenanführer zu konfrontieren.", st = "Ihr habt viel getan, um uns eine faire Chance zu geben. Selbst wenn wir heute fallen sollten, so wissen wir doch zumindest, dass wir unser Bestes gegeben haben.\n\nDies ist Eure letzte Gelegenheit, $g:Fremder:Fremde;. Wenn Ihr nach Valanaar zurückkehren wollt, um einen weiteren Tag zu überleben, würde ich Euch keinen Vorwurf machen.\n\nSolltet Ihr andererseits wahrlich eine Vorliebe für aussichtslose Unterfangen hegen, lasst mich einfach wissen, wann Ihr bereit zum Aufbruch seid. Wir werden erhobenen Hauptes dort hinausschreiten und unser Schicksal akzeptieren.", t = "Standhaft bleiben"},
    [92698] = {ot = "Sprecht mit Aamelia Windfield über das fehlerhafte Wirbelsturmkonstrukt.", st = "<Ihr lehnt Euch dicht heran, um die Worte zu vernehmen, die unter den Rüstungsplatten des riesigen Konstrukts hervordringen.>\n\n...Funktionsfehler...\n\n...Frage...\n\n...Was ist....\n\n...Funktion...\n\n<Diese fragmentierten Wörter und Phrasen scheinen sich zu wiederholen. Vielleicht weiß jemand in der Nähe mehr über dieses Konstrukt?>", t = "Was ist meine Funktion?"},
    [92699] = {ot = "Findet Elaadrin Evengale in Valanaar.", st = "Da Ihr nun in Valanaar angekommen seid, wollt Ihr gewiss mit den anderen anwesenden Mitgliedern des Ordens sprechen. Der gegenwärtige oberste Magister Elaadrin Evengale und sein Gefolge arbeiten in einer Hütte in einem entlegenen Teil südöstlich von Valanaar.\n\nIhr solltet jedoch acht geben, der Hohe Orden und die Windformer kommen hier nicht besonders gut miteinander aus. Seid vorsichtig und geht den Windformern besser aus dem Weg. Wir haben mit dem Kult schon alle Hände voll zu tun, ich werde keine Gewalt zwischen den Fraktionen auf den Straßen von Valanaar dulden.", t = "Der oberste Magister"},
    [92700] = {ot = "Findet Ayessa Dawnsinger in Valanaar.", st = "Da Ihr nun in Valanaar angekommen seid, wollt Ihr gewiss mit den anderen anwesenden Mitgliedern der Windformer sprechen. Die gegenwärtige hohe Himmelseherin und ihr Gefolge arbeiten in einer Hütte in der Nähe des Zentrums von Valanaar.\n\nIhr solltet auch wissen, dass die Windformer und der Hohe Orden hier nicht besonders gut miteinander auskommen. Seid vorsichtig und geht dem Hohen Orden besser aus dem Weg. Wir haben mit dem Kult schon alle Hände voll zu tun, ich werde keine Gewalt zwischen den Fraktionen auf den Straßen von Valanaar dulden.", t = "Die hohe Himmelseherin"},
    [92701] = {ot = "Bringt Aondas schriftlichen Bericht zu Valennia Stormfist in Valanaar.", st = "Für den Moment scheinen der Pylon und unser Dorf sicher zu sein, ich möchte Euch also bitten, diesen Bericht zu Valennia Stormfist in Valanaar zu bringen, an der südöstlichen Küste der Insel. Valennia ist die Anführerin der Friedensbewahrer auf der Insel und sie muss erfahren, was hier passiert ist.\n\nDer Kult breitet sich rasend schnell aus und die Friedensbewahrer sind bisher einer direkten Konfrontation aus dem Weg gegangen, aber diese Tage sind vorbei. Valanaar muss sich auf einen Kampf gefasst machen.\n\nSo oder so, ich danke Euch. Ihr werdet immer Freunde in Shen'dar haben, $n.", t = "Nach Valanaar"},
    [92703] = {ot = "Sprecht mit lvarion Windfield in Valanaar.", st = "Ich schätze, es fühlt sich nicht ganz richtig an, Euch nach all dem $g:Fremder:Fremde; zu nennen, also... vielen Dank, $n. \n\nSolltet Ihr nichts dagegen einzuwenden haben und Euer Weg Euch wieder dorthin zurückführen, berichtet Alvarion bitte, was hier vonstatten ging. Sagt ihm bitte auch, dass sobald er auf den Beinen ist, er einen Windformer hierher zurückbringen muss, um einen Blick auf das Konstrukt zu werfen, um sicherzustellen, dass es sicher für uns... unsere Familie ist.\n\n<Aamelia berührt sanft ihren Bauch.>\n\nEr weiß nichts davon. Behalten wir diesen Teil vorerst einfach unter uns.", t = "Überbringung der Neuigkeiten"},
    [92706] = {ot = "Bringt Bruuz' Rückenflosse zu Gazlowe in Ratchet.", st = "Aufruf an alle Angler!\n\nEin riesiger Hai macht seit einer Weile seine Runden in den Gewässern in der Nähe des Schiffsdocks und greift Matrosen sowie kleine Boote an. Dockarbeiter haben ihm dem Spitznamen \"Bruuz\" gegeben. Eine stattliche Belohnung wartet auf denjenigen, der mir seine Flosse bringt!\n\n-- Gazlowe", t = "GESUCHT: Bruuz"},
    [92708] = {ot = "Hört Euch an, was Ayessa Dawnsinger zu sagen hat.", st = "Die Windformer haben unermüdlich daran gearbeitet, auf die gegenwärtige Krise auf der Insel Zephras zu reagieren. Wir haben einige überraschende Entdeckungen auf der Suche nach unseren vermissten Windgeistern gemacht, und wir arbeiten derzeit an einer Strategie, die uns helfen könnte, uns die nötige Macht zu verleihen, um die Insel zu retten.\n\nWir brauchen jedoch starke Abenteurer wie Euch für dieses Unterfangen. Bitte, wenn Ihr einen Augenblick entbehren könnt, lasst uns dies weiter vertiefen.", t = "Ein großes Abenteuer"},
    [92709] = {ot = "Hört, was Elaadrin Evengale in Valanaar zu sagen hat.", st = "Eure hochgeborene Abstammung leuchtet so klar in Euren Augen wie der Himmel über uns. Ihr seid $geiner:eine; von uns, und es ist die Jugend wie Ihr, die uns helfen wird, unsere Heimat zu retten. Doch lasst mich Euch zuerst mehr über unsere Mission und Pläne erzählen - hier auf Zephras... und darüber hinaus.", t = "Ein großes Abenteuer"},
    [92727] = {ot = "Findet heraus, was aus Fillion Flamebreeze geworden ist.", st = "Die Suche nach Wissen ist die vorrangige Aufgabe des Hohen Ordens, doch diese Arbeit war auf Zephras noch nie zuvor so gefährlich wie heute.\n\nEiner unserer Gelehrten - Fillion Flamebreeze - war auf dem Weg zum Shen'darhochland, um Daten über die Windmagie zu sammeln, die sich dort an einigen Orten ansammelt. Bedauerlicherweise ist er noch nicht zurückgekehrt und wir befürchten, dass ihm auf der Straße etwas zugestoßen ist.\n\nFindet ihn bitte für uns, wenn Ihr könnt. Er wurde zuletzt auf der Straße nach Westen von Valanaar in Richtung Shen'darhochland gesehen.", t = "Der vermisste Gelehrte"},
    [92741] = {ot = "Reist in den Schattenwindwald und sammelt 8 Kreischlingskrallen für Iaadaria Bitterwind in Valanaar.", st = "Der Schattenwindwald ist unglaublich gefährlich und für normale Abenteurer in der Regel tabu. In den letzten Monaten explodierte die Kreischlingpopulation und sie haben begonnen, ihr Territorium außerhalb der Wälder auszubreiten, was ein potenzielles Problem darstellt. Ich bin an den alchemistischen Eigenschaften der Kreischlingskrallen interessiert, somit birgt eine bitter nötige Dezimierung zugleich die Gelegenheit für akademische Erkenntnisse.\n\nReist in den Schattenwindwald und macht Jagd auf die Bestien. Bringt mir so viele ihrer Krallen wie möglich.", t = "Unwillkommene Besucher"},
    [92742] = {ot = "Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln.", st = "Wir müssen die Quelle und Natur des Gifts, das dieses Land verdirbt, bestimmen. Lasst uns mit dem Grundwasser unter den Höfen in diesem Gebiet beginnen.\n\nGeht zu Jansens Hof Richtung Norden und Molsens Hof nordwestlich von hier, und sammelt Proben von den Brunnen dort.", t = "Test der Brunnen"},
    [92744] = {ot = "Alba Fairmoon möchtet, dass Ihr 7 Murlockiemen von Longshore an der Küste von Westfall sammelt.", st = "Die Verderbnis, die die Pflanzen von Westfall befallen hat, ist möglicherweise auch ins Meer gesickert. Wenn auch die örtlichen Fische betroffen sind, könnte es Stormwind zu einer Hungersnot verdammen.\nSammelt Kiemen von den Murlocs an der Küste und bringt sie zu mir. Murlocs sind ziemlich zäh, aber ihre Physiologie ist extrem empfindlich gegenüber Schadstoffen. Jegliche Giftstoffe im Meerwasser werden in den Kiemen, die Ihr findet, offensichtlich zu finden sein.", t = "Murlochkiemen"},
    [92745] = {ot = "Tötet 4 Koboldbuddler im Jangoschacht und 6 Minenarbeiter der Flusspfoten im Goldküstensteinbruch.", st = "Die Brunnenproben, die Ihr gesammelt habt, enthalten giftige Metalle! Wenn wir dieser Verderbnis nicht schnell ein Ende bereiten, wird es Jahrzehnte dauern, bis wir etwas in diesem Boden anpflanzen können.\nDie Defias haben die Minen von Westfall beschlagnahmt und nutzen Kreaturen als Arbeitskräfte, um Ressourcen abzubauen. Stört sie, indem Ihre ihre Minenarbeiter im Jangoschacht im Norden und im Goldküstensteinbruch im Westen tötet.", t = "Der Status der Minen"},
    [92747] = {ot = "Sammelt 8 verdächtige Industriebedarfsvorräte von Moonbrook.", st = "Seltsam... Das Gift scheint nicht aus den Minen zu stammen, die Ihr untersucht habt.\n\nEs heißt, die Todesminen unter der Stadt Moonbrook wären die größten und tiefsten Minen von Westfall, wurden aber mit dem Ersten Krieg aufgegeben. Könnten die Todesminen wieder aktiv sein?\n\nBitte reist nach Moonbrook, $n, und sucht nach Hinweisen auf Bergbau- oder Industrieaktivitäten. Das ist die letzte Spur, die wir haben!", t = "Moonbrookspionage"},
    [92748] = {ot = "Reist zum Zwergendistrikt in Stormwind und findet einen Ingenieur, der Euch helfen kann.", st = "Die Vorräte, die Ihr gefunden habt, deuten auf eine groß angelegte industrielle Operation irgendwo in den Todesminen hin. Es besteht kein Zweifel, dass sie die Ursache für die Toxine ist, die das Ackerland von Westfall kontaminieren Wir müssen dem so schnell wie möglich ein Ende machen.\n\nWas auch immer dort unten ist, wird nur schwer zu zerstören sein. Begebt Euch zum Zwergendistrikt von Stormwind und treibt einen Ingenieur auf, der uns mit Sprengstoff versorgen kann.", t = "Explosive Beratung"},
    [92749] = {ot = "Erhaltet 10 grobes Dynamit durch Herstellung, Handel oder im Auktionshaus, und kehrt anschließend zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind zurück.", st = "Industriesabotage? Ihr habt meine Aufmerksamkeit!\nBeginnen wir mit etwas Dynamit...", t = "Ein explosiver Plan"},
    [92750] = {ot = "Sprecht mit jemanden beim Geheimdienst von Stormwind über die Beschaffung eines Fernzünders.", st = "Ich nehme an, Ihr wollt eine \"kontrollierte\" Explosion? Macht nicht so viel Spaß, aber eine gute Wahl, wenn Ihr all Eure Gliedmaßen behalten möchtet.\nIch fürchte, ich habe keinen Fernzünder. Ihr solltet Euch mit den raffinierten Leuten beim Geheimdienst von Stormwind unterhalten. Sie sollten in der Lage sein, etwas für uns zu finden.", t = "Detonation aus der Ferne"},
    [92751] = {ot = "Bringt das Fernzünderset zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind.", st = "Ihr müsst etwas zerstören? Das hat nicht zufällig etwas mit Euren Aktivitäten in Moonbrook zu tun? Schaut nicht so überrascht. SI:7 ist immer auf dem Laufenden über alles, was in Stormwind vor sich geht.\nWenn Ihr vorhabt, eine Explosion in den Höhlen unter Westfall auszulösen, müsst Ihr Euch lange aus dem Staub gemacht haben, bevor alles in die Luft geht. Nehmt diesen Fernzünder - er ist ein neuer Prototyp von unseren Ingenieuren.\nOh, und es wäre wohl am besten, wenn Ihr meine Beteiligung gegenüber Eurem Elfenfreund nicht erwähnt.", t = "Detonation aus der Ferne"},
    [92752] = {ot = "Kehrt zu Alba Fairmoon in Westfall zurück.", st = "Fertig, die Bombe ist bereit! Seid vorsichtig mit dem Zünder.", t = "Explosive Beratung"},
    [92753] = {ot = "Findet die versteckte Schmiede in den Todesminen und platziert die besonders zerstörerischen Sprengladungen in der Nähe. Trefft dann Alba Fairmoon am Ausgang der Todesminen.", st = "Die Quelle dieses Gifts ist wahrscheinlich eine Art große metallurgische Schmiede. Sucht einen Weg in die Todesminen und findet die Schmiede. Platziert dann den Sprengstoff.\nIch warte auf den Hügeln hinter Moonbrook auf Euch. Sobald Ihr zurückkehrt, sprengen wir die Schmiede in die Luft. Hoffentlich kann das Land heilen, sobald sie fort ist.", t = "Zerstörung in den Todesminen"},
    [92819] = {ot = "Verwendet den Zünder.", st = "Wir sind fast fertig. Verwendet den Zünder und macht dem ein Ende.", t = "Zerstörung in den Todesminen"},
    [92834] = {ot = "Sammelt nördlich von Valanaar, auf den Böenbeerenfeldern oder am Schrein von Akir 10 Windsteinamulette der Kultisten der Al'Aketh.", st = "Als der Kult seinen Feldzug der Gewalt begann, reagierten die Friedensbewahrer und Windformer mit bloßem Säbelrasseln. Ich hielt dies für eine törichte Eskalation und plädierte stattdessen für einen friedlichen Dialog. Gestern schickte ich meinen Freund Belathaan Brightwish zum Schrein von Akir, in der Hoffnung, diesen Dialog einzuleiten.\n\nGerade eben ist eine Kiste eingetroffen - sie enthält Belathaans Zunge, getaucht in Silberpigment.\n\nMir ist jetzt klar, dass man mit dem Kult nicht vernünftig reden kann. Tötet jeden Kultisten, den Ihr seht, und bringt mir die Gebetsamulette, die sie bei sich tragen.", t = "Zehnfache Vergeltung"},
    [92840] = {ot = "Bringt den Index Esoteria zu den Menhiren der Warte im Shen'darhochland und verwendet ihn an den Windsteinformationen in der Umgebung, um Daten zu sammeln.", st = "Fillion wurde mit einem speziellen Gerät zu den Menhiren der Warte geschickt, um die elementare Energie dort zu messen und zu studieren.\n\nNehmt dies - einen Index Esoteria - und verwendet ihn, um Daten aus den gewaltigen Windsteinformationen zu gewinnen, die sich dort bilden. Seid jedoch auf der Hut, denn die Windformer bewachen diese Stätte jetzt vermutlich mit Argusaugen.\n\nSollte jemand versuchen, Euch aufzuhalten, nun... tut, was getan werden muss. Ich habe keine Geduld mehr für ihre Einmischung.", t = "Windfang"},
    [92849] = {ot = "Sucht weiterhin nach Fillion Flamebreeze.", st = "<Nach dem zu urteilen, was Ihr gerade gefunden habt, ist es sehr wahrscheinlich, dass Fillion hier etwas zugestoßen ist. Möglicherweise ist er noch in der Nähe und benötigt Hilfe. Ihr erblickt eine Höhle im Norden Eurer aktuellen Position. Ihr solltet Eure Suche nach ihm dort fortsetzen.>", t = "Der vermisste Gelehrte"},
    [92850] = {ot = "Tötet die Kreischlingmatriarchin im Kreischlingsbau und bringt ihren Kopf zu Fillion Flamebreeze in Valanaar zurück.", st = "Ich fühle mich bereits viel besser. Ich bin bewandert in den arkanen Künsten und wir sind nicht weit entfernt von Valanaar. Das schaffe ich allein. Viel wichtiger als meine Sicherheit ist jedoch, wie nahe an Valanaar diese Kreischlinge ihr Nest gebaut haben und die Gefahr, die sie darstellen. Wenn es Euch nichts ausmacht, geht bitte zurück hinein und holt Euch den Kopf dieser Bestie!\n\nSobald das erledigt ist, könnt Ihr mich bei Dondallion zurück in Valanaar finden. Ich muss so schnell wie möglich zu ihm zurückkehren. Er ist meinetwegen wahrscheinlich verrückt vor Sorge.", t = "Der vermisste Gelehrte"},
    [92860] = {ot = "Meldet Euch bei Valennia Stormfist und versichert ihr, dass der Hohe Orden ihr im Kampf gegen die Al'Aketh zur Seite steht.", st = "Der Hohe Orden hat sein Bestes getan, um einen direkten Konflikt mit dem Kult zu vermeiden, aber das ist nun offensichtlich keine Option mehr. Seine Feindseligkeit wurde unmissverständlich unter Beweis gestellt und nun gibt es Gerüchte über größere Bewegungen des Kults auf der Insel. Sie rüsten sich eindeutig für etwas, und was auch immer es ist, es verheißt nichts Gutes für die Menschen von Zephras.\n\nBerichtet Valennia Stormfist davon und informiert sie darüber, dass sich Valanaar auf die volle Unterstützung des Hohen Ordens gegen die Al'Aketh verlassen kann, sollte sie notwendig werden.", t = "Im Dienste von Zephras"},
    [92871] = {ot = "Meldet Euch bei Valennia Stormfist und versichert ihr, dass die Windformer ihr im Kampf gegen die Al'Aketh zur Seite stehen.", st = "Valennia Stormfist und ihre Friedenshüter waren seit jeher die Beschützer von Zephras. Wir haben geholfen, wo wir konnten. Es gibt Gerüchte über großflächigere Kultbewegungen auf der Insel. Ganz eindeutig bereiteten sie sich auf etwas vor.\n\nBerichtet Valennia davon und erinnert sie daran, dass sich Valanaar auf die volle Unterstützung der Windformer gegen die Al'Aketh verlassen kann, sollte sie notwendig werden.", t = "Für Zephras"},
    [92880] = {ot = "Bringt Yornas Bericht zu Valennia Stormfist in Valanaar.", st = "Ich schätze, es wird noch etwas dauern, bis wir den Rest der Angreifer vernichtet haben, aber unsere Chancen stehen jetzt weitaus besser. Kehrt nach Valanaar zurück und lasst sie wissen, dass sich die Lage hier fürs Erste stabilisiert hat.\n\nIch kann Euch nicht genug für Eure Hilfe danken. Ohne Euch stünden wir weitaus schlechter da. Ich hatte um Verstärkung gebeten, und wie es aussieht, habe ich stattdessen $g:einen angehenden Helden:eine angehende Heldin; bekommen. Das nehme ich gerne an.\n\nMögen die vier Winde mit Euch sein, $c.", t = "Rückkehr nach Valanaar"},
    [92881] = {ot = "Sprecht mit Talaanis Shadowsong in Valanaar.", st = "Die Angriffe auf den westlichen und östlichen Wachturm sind kein Zufall. Nach dem, was Ihr uns über die Vorkommnisse mit diesem Himmelspriester am westlichen Wachturm berichtet habt, vermuten wir, dass der Kult irgendetwas mit den Ankerpylonen im Schilde führt.\n\nSprecht bitte mit dem Hochältesten Shadowsong. Er wird Euch von einer Spur erzählen, die sich als vielversprechend erweisen könnte.", t = "Das Gesuch des Hochältesten"},
    [92909] = {ot = "Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 14 Golemisofedern und 5 Gyrostabilisatoren für Erntearbeiter bringt.", st = "Oh nein... Jetzt stecke ich in der Klemme!\n\nIch habe von den Erntern gehört, die die Felder von Westfall heimsuchen, also bin ich den ganzen Weg von Ironforge hierher gereist, um zu sehen, ob ich sie rekalibrieren kann. Aber sie sind viel aggressiver, als es meine Berechnungen vorhergesehen haben, und sie haben mich in diesen Stall gejagt!\n\nWenn ich ein paar Isofedern und Gyrostabilisatoren von den Erntern hätte, könnte ich ein Gerät bauen, um meine Flucht zu vertuschen. Könnt Ihr die Teile für mich besorgen?", t = "Die Ernter ernten"},
    [92910] = {ot = "Bringt die Präzessions-Autokognitions-Einheit zu Ozwin Ironsprocket auf Saldeans Hof.", st = "Das Teil, das Ihr von den Erntern geborgen habt, scheint größtenteils intakt zu sein. Jemand, der an Erntegolems interessiert ist, möchte dies vielleicht sehen.", t = "Die Ernter ernten"},
    [92911] = {ot = "Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 8 Golemisofedern, 4 Kupfermodulatoren und ein kunstloses Zielfernrohr bringt.", st = "Ich verstehe... das verschafft mir einen Einblick in die Denkweise dieser Monster. Ich habe eine Idee, wie wir ihre Systeme überschreiben können, zumindest kurzzeitig.\n\nIch werde weiterhin mit der Einheit herumexperimentieren, die Ihr mir gebracht habt. Könntet Ihr in der Zwischenzeit einige Teile für das Gerät auftreiben?", t = "Die Ernter ernten"},
    [92947] = {ot = "Tötet $1oa Wächter der Al'Aketh, $2oa Geistrufer der Al'Aketh und $3oa Klingenmeister der Al'Aketh, und erstattet anschließend Hyusaa Quickbreeze beim Schrein von Akir Bericht.", st = "Alle sind hier, gut. Ich habe soeben einige meiner besten Kämpfer durch den Vordereingang des Schreins geschickt, um ein wenig Unruhe zu stiften und als Ablenkung zu dienen, während ich die Windformer und den Hohen Orden über die Flanke hineinführe.\n\nWenn alles gut geht, sollten wir in der Lage sein, rasch durchzubrechen und die Hohepriesterin auszuschalten. Was Euch angeht: Geht rein und schlagt ein paar Schädel ein. Trefft meine rechte Hand, Hyusaa Quickbreeze, in der Nähe der Stufen neben dem Schrein, nachdem Ihr für etwas Aufruhr gesorgt habt.\n\nDie Winde leiten Euch, $C.", t = "Unser Aufbruch"},
    [93036] = {ot = "Sprecht mit Sania Silverstream in Shen'dar.", st = "Ihr wisst es vielleicht nicht, aber Sania Silverstream da drüben ist eine \"Missionarin\" der Al'Aketh. Sie tun gerne so, als wären sie ein gewöhnlicher, religiöser Orden und schicken nicht bedrohlich wirkende Botschafter aus, um Mitglieder anzuwerben. Wir haben Sania bisher geduldet, um einen direkten Konflikt mit dem Kult zu vermeiden, aber es ist offensichtlich, dass die Illusion des Friedens nicht mehr lange anhalten wird.\n\nIhr seid hier neu und den meisten unbekannt. Es würde mich interessieren, ob Ihr dem Kult über Sania näher kommen und herausfinden könnt, was ihre Pläne für das Dorf sind.", t = "Den Kult infiltrieren"},
    [93065] = {ot = "Sprecht mit Valanaar Stormfist im Böenbeerentiefland.", st = "Die Friedensbewahrer mobilisieren ihre Kräfte und wir bereiten uns darauf vor, in den Kampf zu ziehen. Trefft alle nötigen Vorkehrungen und trefft uns an der östlichen Straße, die nach Norden aus der Stadt führt. Wir werden ein letztes Mal mit allen Rücksprache halten, bevor wir ausrücken.", t = "Bereit für die Schlacht"},
    [93089] = {ot = "Sprecht mit Elaadrin Evengale, wenn Ihr bereit seid, die Insel Zephras zu verlassen.", st = "Bitte richtet Elaadrin meinen Dank für alles, was der Hohe Orden und Eure Freunde von diesen \"Kirin Tor\" für die Insel Zephras getan haben, aus. Ich weiß von dem Plan des Hohen Ordens zum Verlassen der Insel, und Euer Orden hat meinen Segen und die besten Wünsche für diese Expedition.\n\nIch kann nur hoffen, dass, welche arkane Lösung der Hohe Orden auch finden mag, sie uns wahrlich jene Beständigkeit schenkt, die wir in den vergangenen Jahren so schmerzlich vermissten. Wenn Ihr vorhabt, ihn zu begleiten... nun, seine Mission wird dadurch stärker sein.\n\nMögen die Winde mit Euch sein, $n.", t = "Was kommt als Nächstes"},
    [93090] = {ot = "Sprecht mit Ayessa Dawnsinger, wenn Ihr bereit seid, die Insel Zephras zu verlassen.", st = "Bitte richtet Ayessa meinen Dank für alles aus, was die Windformer und Eure neuen Freunde von diesem \"Irdenen Ring\" für die Insel Zephras getan haben. Ich weiß, dass sie die Insel mit den Windformerschamanen verlassen möchte, und Euer Orden hat meinen Segen und die besten Wünsche für diese Expedition.\n\nIch kann nur hoffen, dass, welche Lösung die Windformer auch finden mögen, sie uns wahrlich jene Beständigkeit schenkt, die wir in den vergangenen Jahren so schmerzlich vermissten. \n\nMögen die Winde mit Euch sein, $n.", t = "Nächste Schritte"},
    [93159] = {ot = "Sprecht mit dem seltsamen Einsiedler im Schattenwindwald und erfahrt mehr über ihn.", st = "Äh, ähm... h-hallo, ich meine, hallöchen! Seid gegrüßt! Tut mir leid... Es ist lange her, dass ich mit jemandem gesprochen habe. Ich bin wohl etwas eingerostet.\n\n<Die seltsame verhüllte Gestalt rutscht verlegen herum.>\n\nAlso, ähm... wie läuft's so?", t = "Der seltsame Einsiedler"},
    [93160] = {ot = "Sammelt $1oa Schattenwindeicheln.", st = "Ich freue mich, dass Ihr Euch die Zeit nehmt, Euch mit mir zu unterhalten. W-Wenn Ihr wirklich helfen wollt, könnte ich Hilfe dabei gebrauchen, Eicheln vom Waldboden zu sammeln. Die nahen habe ich fast alle eingesammelt, aber im Wald gibt es doch einige Raubvogeldinger. Da draußen ist es gefährlich und ich möchte nicht wirklich Vogelfutter werden.\n\nAlso, wenn Ihr möchtet, würdet Ihr sie für mich sammeln? Dann mache ich uns etwas Leckeres!", t = "Die Schätze des Waldes"},
    [93165] = {ot = "Sammelt 10 Ohren von Al'Aketh-Kultisten im Schattenwindwald, beim Schrein von Akir oder im Böenbeerentiefland.", st = "Die Al'Aketh haben bei unserer Enklave für eine große Tragödie gesorgt, und Blut muss mit Blut vergolten werden.\n\nIch habe ein Angebot für Euch. Solltet Ihr in Konflikt mit diesen verfluchten Kultisten geraten, bringt mir die Ohren aller, die Ihr tötet. Ich werde mich bei Euch mit Gold erkenntlich zeigen - und zu einem späteren Zeitpunkt mit Zugang zu den Geheimnissen der Nachtklaue, solltet Ihr Euch als wahrer Freund erweisen.", t = "Unerhörte Gnade"},
    [93172] = {ot = "Zerstört 10 Windhüllen im Schattenwindwald.", st = "Die meisten Elfen auf der Insel scheinen zu glauben, dass dieser Wald heimgesucht wird, und sie haben auch nicht unrecht.\n\nBei den alten Ruinen im Nordosten versammeln sich seltsame gespenstartige Geister. In manchen Nächten kann man sie beinahe \"singen\" hören. Ganz anders als jedes Lied, das ich je gehört habe, aber eindeutig ein Lied. Und es ist so traurig.\n\nIch weiß auch nicht warum, aber ich denke, dort muss einmal etwas Schreckliches passiert sein, und die Geister sind dort gefangen. Wenn Ihr mutig genug seid, könnt Ihr sie vielleicht befreien?", t = "Die Hüllen befreien"},
    [93317] = {ot = "Sammelt 6 Stück Windweisenkriecherfleisch.", st = "Seid Ihr vertraut mit den Windweisenkriechern? Wisst Ihr, dass diese Krabben ausschließlich am Windweisensee hier auf Zephras heimisch sind und sie nur in wenigen Wochen im Jahr gefangen werden können?\n\nBei all den jüngsten Aktivitäten des Kults konnte ich mich nicht zum See hinauswagen, um sie zu fangen, und unser Zeitfenster schließt sich zusehends. Ich wäre Euch sehr dankbar, wenn Ihr losziehen und einige für mich einsammeln könntet. Man findet sie im Allgemeinen an den Ufern rund um den See und in den Flüssen.\n\nAber gebt gut acht, sie sind fieser, als sie aussehen!", t = "Krabbensaison"},
    [93318] = {ot = "Tötet Vulgara den Unersättlichen im Shen'darhochland and bringt ihren Kopf zu Danarii Bellowveil.", st = "Auf Befehl von Wachtmeisterin Aonda von den Friedensbewahrern wird hiermit ein Kopfgeld auf die Geißel des Hochlands, Vulgara den Unersättlichen ausgesetzt. Die geflügelte Bestie wurde zuletzt auf einem Hügel südwestlich von Shen'dar gesehen. Sie ist gefährlich und man sollte sich ihr nur mit größter Vorsicht nähern.\n\nBringt den Kopf der Bestie zu Danarii Bellowveil, um Eure Belohnung zu erhalten.", t = "GESUCHT: Vulgara der Unersättliche"},
    [93319] = {ot = "Sammelt 10 gestohlene Windsteine von den Hochlandbanditen im Shen'darhochland.", st = "Wir verlassen uns in unserem alltäglichen Leben hier auf Zephras immer mehr auf die Windsteine, deswegen versuchen wir, stets einen Vorrat für den Notfall übrig zu haben. Mir ist aufgefallen, dass in letzter Zeit einige von unserem Lager fehlen.\n\nWir haben Windsteine bei vor Kurzem gefangen genommenen Banditen gefunden und ich vermute, dass sie hinter dem Verschwinden stecken.\n\nWenn Ihr zufällig an der Banditenhöhle im Norden vorbei kommt, schlagt doch einige Köpfe ein und bringt mir ein paar unserer gestohlenen Windsteine zurück.", t = "Gestohlene Windsteine"},
    [93320] = {ot = "Meldet Euch bei Yorana Windyreed im östlichen Wachturm im Böenbeerentiefland.", st = "Ich habe soeben Nachricht erhalten, dass der Kult den Pylonen-Wachturm direkt vor der Stadt angreift! Ich habe die wenigen zusätzlichen Friedensbewahrer, die wir hier haben, losgeschickt, um die feindliche Nachhut zu durchbrechen und die Verteidiger zu entlasten. Doch jede weitere Hilfe könnte darüber entscheiden, ob unsere Leute dort leben oder sterben.\n\nBitte brecht unverzüglich zum östlichen Wachturm auf und helft, so gut Ihr könnt.\n\nMein Lieutenant Yorana Windyreed führt den Entsatztrupp an. Wenn sie noch am Leben ist, kann sie Euch sagen, wie Ihr am besten helft.", t = "Turmverteidigung"},
    [93461] = {ot = "Sprecht mit Rathiril Sunlance und Coriella Calmbreeze in Shen'dar.", st = "Ihr habt diesen \"Hoher-Orden-Blick\" an Euch. Alle mit hochgeborenen Vorfahren haben dieses Funkeln in den Augen, das sie verrät. Bevor ich Euch hier zum Einsatz bringe, solltet Ihr Euch bei unserem hiesigen Ältesten des Hohen Ordens melden, Rathiril Sunlance. Ihr könnt ihn hier im Haupthaus finden, gleich bei mir um die Ecke.\n\nOh, und schaut auch bei Coriella Calmbreeze vorbei, sie führt das Gasthaus vor Ort und kann Euch mit einer Unterkunft und Vorräten versorgen, falls Ihr sie braucht.", t = "Willkommen in Shen'dar"},
    [93552] = {ot = "Sammelt 15 Windsteinhaufen von rohen Windsteinen im Thendalhain.", st = "Windsteine sind eine bedeutende Ressource auf der Insel Zephras. Sie enthalten die rohe, konzentrierte Energie der Winde. Die Windelementare, die früher bei uns auf Zephras lebten, sind vor einigen Jahren verschwunden. Seitdem lässt die Magie, die diese Insel nährt, langsam nach. Das gilt aber nicht unbegrenzt: Die Windsteine sind immer noch eine verlässliche Energiequelle und daher enorm wertvoll für uns.\n\nIhr findet rohe Windsteine im ganzen Hain verteilt. Könnt Ihr mir helfen, sie anzuzapfen?", t = "Windsteine anzapfen"},
    [93680] = {ot = "Holt den Kanalisationsschlüssel von Dalaran für Magus Wordeen Voidglare in Tarrens Mühle.", st = "Die Allianz hatte eine Armee von Magiern, bekannt als die Kirin Tor. Sie waren zwar mächtig, aber die Brennende Legion stellte sich als noch mächtiger heraus. Der Erzdämon Archimonde machte ihre Stadt mit nur einem Streich dem Erdboden gleich, als wäre sie nicht mehr als ein Spielzeug. Alle, die überlebten, waren lange nicht mehr als ein paar obdachlose Vagabunden.\n\nZumindest, bis sie Dalaran wiederaufbauten. Und das auch noch direkt vor der Tür der Dunklen Fürstin!\n\nSucht in ihren Lagern nach etwas, das uns ungesehen in die Stadt bringen kann. Ich muss mehr wissen.", t = "Schlüssel zur Stadt"},
    [93735] = {ot = "Findet Riaani Nightwind im westlichen Teil von Valanaar.", st = "Traditionellerweise kümmerten sich die Windformer um die magischen Instrumente und Geräte, die uns die Geister des Windes geschenkt haben. Das gilt auch für die vielfältigen magischen Konstrukte überall auf der Insel. Seit die Geister uns verlassen haben, funktionieren nur noch wenige von ihnen.\n\nEines der wenigen noch funktionierenden Konstrukte in Valanaar wurde beschädigt. Einer unserer Handwerker wurde dorthin geschickt, aber womöglich braucht er Hilfe. Reist ans westliche Ende der Stadt und helft ihm, so gut Ihr könnt.", t = "Das kaputte Konstrukt"},
    [93736] = {ot = "Sammelt 10 Windhüllenessenzen von Windhüllen im Schattenwindwald.", st = "Den Windformern liegt vor allem daran, besser zu verstehen, warum die Geister uns verlassen haben und was wir vielleicht tun könnten, um sie zurückzuholen. Seltsame Arten von Windgeistern, die manche \"Hüllen\" nennen, befinden sich im Norden des Schattenwindwaldes. Wir wissen nur wenig über sie und warum sie dort sind, aber wir wissen, dass sie erst erschienen sind, als die Geister des Windes uns verlassen haben.\n\nGeht dorthin und vertreibt sie. Die Überreste könnt Ihr einsammeln und hierher zurückbringen.", t = "Unerwünschte Geister"},
    [93737] = {ot = "Sprecht mit Rianni Nightwind und hört, was er zu sagen hat.", st = "Oh, hallo. Ayessa hat Euch geschickt, damit Ihr mir helft? Nun gut. \n\nIch weiß ja nicht, was so ein Neuling, wie Ihr es eindeutig seid, tun kann, aber wenn Ihr kurz wartet, bis ich aus den Innereien dieses Konstrukts rausgeklettert bin, habe ich vielleicht ein paar Ideen, wie Ihr mich unterstützen könnt.", t = "Das kaputte Konstrukt"},
    [93738] = {ot = "Erstattet Ayessa Dawnsinger in Valanaar Bericht.", st = "Brightwish, was? Also wollte der Hohe Orden diese Komponenten aus irgendeinem Grund entfernen. Aber warum?\n\nDer Hohe Orden war immer lästig und wollte mit der Magie der Windgeister experimentieren. Sie sind viel zu unvorsichtig und wir haben ihnen strengstens verboten, mit Wissen der Windformer zu spielen, aber in letzter Zeit stellen sie unsere Geduld auf die Probe. \n\nIch denke, Ihr solltet Ayessa Dawnsinger berichten, was Ihr erfahren habt. Sie kann Euch sagen, wie Ihr weiter vorgehen sollt.", t = "Das kaputte Konstrukt"},
    [93740] = {ot = "Sammelt 10 Windsteinamulette der Al'Aketh von toten Kultisten im Böenbeerentiefland.", st = "Einige unserer Windformernovizen wurden heute Morgen tot im Hochland gefunden. Wir können es nicht mit Gewissheit sagen, aber es liegt nahe, dass die Al'Aketh dafür verantwortlich sind. Windformer vergelten Blut immer mit Blut.\n\nReist in den Norden und tötet alle Al'Aketh, die Euch begegnen. Bringt mir Ihre Windsteingebetsamulette als Beweis. Wir vergeben und vergessen nicht.", t = "Blut für Blut"},
    [93746] = {ot = "Konfrontiert Belathaan Brightwish auf der Straße zum Schrein von Akir.", st = "Der Hohe Orden kennt die Konsequenzen, wenn er sich in die Angelegenheiten der Windformer einmischt. Ich denke, wir sollten ein Exempel an Belathaan statuieren und ihn mit ein paar blauen Flecken und einem gesunden Respekt vor unseren Grenzen zum Hohen Orden zurückschicken.\n\nBelathaan wurde beim Verlassen der Stadt gesehen. Er war unterwegs gen Norden zum Schrein von Akir. Ich weiß nicht, warum er dorthin will, aber ihn allein auf der Straße zu stellen, ist bestimmt am sichersten. Findet ihn und jagt ihm ein bisschen Angst ein.", t = "Eine entschiedene Reaktion"},
    [93791] = {ot = "Sprecht mit Belann Windwood in Valanaar.", st = "$n, es ist offensichtlich, dass Eure Fertigkeiten im Umgang mit der Magie wachsen, und ich bin überzeugt, dass es an der Zeit für Euch ist, an einer der ältesten Traditionen des Hohen Ordens für junge und aufstrebende Magier teilzunehmen. Es ist an der Zeit, dass Ihr Euren eigenen Zauberfokus herstellt.\n\nFindet Belann Windwood in Valanaar. Er stellt schon seit über einem Jahrhundert allerlei Zauberstäbe für den Hohen Orden her, Ihr seid bei ihm also bestens aufgehoben.", t = "Sprecht mit Belann"},
    [93797] = {ot = "Bringt einen winddurchfluteten Zweig zu Belann Windwood in Valanaar.", st = "Es ist eine lange gepflegte Tradition, dass junge Magier ihren eigenen Zauberfokus herstellen, sobald sie einen gewissen Grad magischer Fähigkeiten aufweisen. Normalerweise sammeln sie dafür einen abgebrochenen Zweig von unseren ältesten Bäumen, da ihnen Spuren der elementaren Winde innewohnen.\n\nIch habe die am besten geeigneten in der Nähe des Windschreins gefundenen, gleich südlich von Falaath. Bringt mir einen langen Stock und ich weise Euch in die Tradition ein, während wir Euren Zauberfokus herstellen.", t = "Zweige im Wind"},
    [93835] = {ot = "Nehmt das Portal zu den Türmen der Rohashi oben und schließt Euch Elaadrin Evengale und Ayessa Dawnsinger bei ihrer Konfrontation mit der Hohepriesterin Lorthuna an.", st = "Lorthuna ist mithilfe einer Art von Portal zu den Spitzen geflohen. Ayessa und Elaadrin sind ihr gefolgt. Das ist gerade erst passiert.\n\nIch fürchte, ich habe einen Treffer zu viel eingesteckt und muss daher hier bleiben. Geht durch das Portal, findet Elaadrin und helft ihnen, Lorthuna aufzuhalten.\n\nWenn die Hilfe, die Elaadrin und Ayessa uns versprochen haben, nicht bald eintrifft, seid Ihr von hier an auf Euch allein gestellt. Viel Glück, $c.", t = "Konfrontiert Lorthuna"},
    [93836] = {ot = "Sprecht mit Talaanis Shadowsong in Valanaar.", st = "Muln hat mir viel von den Elementarlords erzählt und ich befürchte, dass wir einen guten Grund haben, Al'Akir zu fürchten. Jetzt wo die Zauberschutze, die Zephras verborgen hielten, nicht mehr aktiv sind, stehen wir ohne Verteidigung da... Sollte er sich für einen Angriff entscheiden, haben wir keine Chance hier in seinem Reich.\n\nHochältester Shadowsong muss von der Gefahr erfahren, in der wir schweben, und - was noch viel wichtiger ist - welche Absichten wir mit unserer Mission in Azeroth verfolgen. Wir werden einen Weg finden, um unsere Heimat zu retten. Ich schwöre es.", t = "Das Schicksal Zephras'"},
    [93926] = {ot = "Findet Friedensbewahrer Vaaniel im westlichen Wachturm.", st = "Aus welchem Grund auch immer der Kult den Turm angreift, er ist es nicht wert, unsere Leute dafür zu opfern.\n\nGeht bitte für uns nach Südwesten und seht nach dem Turm. Findet die Friedensbewahrer dort und sagt ihnen, sie sollen ins Dorf zurückkehren. Die Verteidigung dieses Turmes ist die Leben nicht wert, die sie kosten würde. Da versammle ich die Verteidiger, die wir haben, lieber hier, um unsere Bürger zu schützen.\n\nFriedensbewahrer Vaaniel hat das Kommando. Sagt ihm, er soll so schnell wie möglich hierher zurückkehren. Beeilung!", t = "Die Westwacht"},
    [93927] = {ot = "Hebt die Notiz auf, die Ihr bei dem toten Friedensbewahrer gefunden habt, um über Eure nächsten Schritte zu entscheiden.", st = "<Während Ihr die Leiche des Friedensbewahrers untersucht, fällt ihm eine blutige Notiz aus der Hand. Wenn Ihr sie aufhebt und lest, könnte Euch das einen Hinweis geben, wie Ihr weitermachen sollt.>", t = "Eine letzte Bitte"},
    [93948] = {ot = "Überbringt das Siegel der Familie Shadowsong an Talaanis Shadowsong in Valanaar.", st = "Da Ihr sowieso nach Valanaar geht, bringt den Siegelring, den Ihr im Turm gefunden habt, bitte zu Talaanis Shadowsong dort.\n\nEr will ihn bestimmt zurückhaben und, viel wichtiger, er wird das Schicksal seines Neffen erfahren wollen. Talaanis ist der Hochälteste der Insel Zephras und, viel wichtiger, er ist ein guter Mann und trotz der schweren Umstände in letzter Zeit sehr beliebt beim Volk. Ich will gar nicht daran denken, wie er auf diese Neuigkeiten reagiert. Drückt ihm bitte mein Beileid für seinen Verlust aus.", t = "Überbringt das Siegel"},
    [93949] = {ot = "Tötet Himmelshüpfer in Valanaar, bis Ihr $1oa verzauberte Himmelshüpfer eliminiert habt.", st = "Die Plage hat uns erreicht.\n\nIm Tiefland haben die Himmelshüpfer Saison und diese Schädlinge sind überall. Einer der Magier des Hohen Ordens hat berichtet, dass eines der Insekten, die er getötet hat, irgendwie verzaubert war. Bei einer genaueren Untersuchung stellte es sich als eine Art Abhörzauber heraus.\n\nWir gehen davon aus, dass der Kult diese verzauberten Insekten als Spione nutzt. Tötet sie für uns. Ihr seht ihnen nicht an, welche verzaubert sind, Ihr müsst sie also alle töten.", t = "Geplagt"},
    [93951] = {ot = "Sammelt 8 Hippogryphendaunen im Shen'darhochland.", st = "Die Hippogryphen, die sich südwestlich des Dorfes angesiedelt haben, können lästig sein. Aber dadurch bietet sich auch eine recht einzigartige Gelegenheit, an ihre Federn zu kommen. Viele Himmelsgeborene schmücken ihre Haare gern mit bunten Federn, und die Daunenfedern eines Hippogryphen sind besonders farbkräftig und, viel wichtiger, seidenweich.\n\nWenn Ihr in diese Richtung reist, versucht so viele ausgefallene Federn wie möglich um ihre Nistplätze herum zu sammeln. Aber seid vorsichtig, wilde Hippogryphen sind nicht sehr gastfreundlich.", t = "Ein wenig Schönheit"},
    [93958] = {ot = "Sprecht mit Valanaar Stormfist im inneren Sanktum beim Schrein von Akir.", st = "Valennias Streitkräfte haben gerade das innere Sanktum erreicht. Es gab zunächst einen heftigen Kampf, aber jetzt ist es dort geradezu... unheimlich still. Geht dort rein und versucht, Euch mit Valennia und ihren Streitkräften zusammenzuschließen... sofern es diese noch gibt.\n\nIch werde hierbleiben und Euch den Rücken freihalten.", t = "Das Innere Sanktum"},
    [94003] = {ot = "Holt das Bollwerk der Himmelsbrecher von Zaal Stormshield am Schrein von Akir zurück.", st = "Ich bin alles, was von der Linie der Himmelsbrecher hier auf Zephras übrig ist. Die anderen wurden von den Al'Aketh ermordet.\n\nDas einzige, was noch größer ist als mein Kummer, ist meine Scham. Der alte Schild meiner Familie, das Bollwerk der Himmelsbrecher, ist jetzt in den Händen eines Kultisten namens Zaal Stormshield. Unsere Familie erzählte sich, dass einem würdigen Träger des Schildes nichts passieren würde.\n\nZaal ist nicht würdig, so viel ist sicher. Findet den Mann am Schrein von Akir und nehmt ihm meinen Schild ab. Wenn Ihr dies tut, zeige ich Euch die Verteidigung der Himmelsbrecher.", t = "Das Bollwerk der Himmelsbrecher"},
    [94006] = {ot = "Sprecht mit Urs'endris in der Nähe der Wasserfälle im Nordosten von Valanaar.", st = "Seid gegrüßt, $n. Eure Druidenstudien sind nun so weit fortgeschritten, dass ich es für an der Zeit halte, Euch einen der großen Geister vorzustellen, der hier auf Zephras lebt. Urs'endris ist ein weiser, edler Geist, der seit Generationen Druiden lehrt, die Urseraform anzunehmen. Leider hat sein Territorium wie so viele Gebiete auf Zephras begonnen, zu welken und Richtung Himmel zu fallen.\n\nUm ihn zu finden, müsst Ihr in den Nordosten in die Nähe des Wasserfalls im Schatten des Schreins von Akir reisen. Er sollte Euch weiterhelfen können.", t = "Der große Urserageist"},
    [94013] = {ot = "Benutzt die Zähmerrute, um einen Vuldrenalpha im Böenbeerentiefland zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück.", st = "Ihr habt nun schon zwei Bestien erfolgreich gezähmt. Jetzt ist es Zeit für Eure letzte Prüfung. Der Wind über Zephras flüstert schon von größeren Herausforderungen. \n\nNehmt diese Zähmerrute und reist ins Böenbeerentiefland. Zähmt dort einen Vuldrenalpha und beweist Euer Können. \n\nWenn Ihr diese Lektion abgeschlossen habt, seid Ihr bereit, noch tiefer in die Welt der Jäger einzutauchen.", t = "Die Bestie zähmen"},
    [94050] = {ot = "Sprecht mit Quel'dora Quickgale in Valanaar.", st = "Ihr könnt jetzt ein Tier zähmen, aber Ihr braucht auch die Fähigkeiten, um es abzurichten. Niemand könnte Euch dies besser beibringen als meine Schwester Quel'dora. Sie zeigt Euch, wie Ihr Euer neues Haustier ausbildet. \n\nGeht mit dem Wind, $C.", t = "Die Bestie abrichten"},
    [94369] = {ot = "Sprecht mit Talaanis Shadowsong in Valanaar.", st = "Ansirem hat mir viel von den Elementarlords erzählt und ich befürchte, dass wir einen guten Grund haben, Al'Akir zu fürchten, jetzt wo die Zauberschutze, die Zephras verborgen hielten, nicht mehr aktiv sind. Sollte der Windlord sich für einen Angriff entscheiden, haben wir keine Chance, uns zu verteidigen, während wir hier in seinem Reich sind.\n\nDer Hochälteste Shadowsong muss von der Gefahr erfahren, in der wir schweben, und - was noch viel wichtiger ist - welche Absichten wir mit unserer Mission in Azeroth verfolgen. Wir werden einen Weg finden, um unsere Heimat zu retten. Ich schwöre es.", t = "Das Schicksal Zephras'"},
    [94373] = {ot = "Bringt 2 Bärenanhänger der Frostmane zu Teo Hammerstorm in Anvilmar.", st = "Aye, die Zeit ist gekommen, $gjunger Schamane:junge Schamanin;. Ihr seid kräftig und robust geworden, wie ein Stein unter unseren Stiefeln. Den Weg eines Schamanen einzuschlagen zeigt, dass Ihr die Weisheit eines Berges habt, sogar bevor Ihr Euch bewiesen habt... Ihr habt den Mut eines Steins, den Pfad der Erde zu beschreiten.\n\nAber um seine Gunst zu verdienen, müsst Ihr ihm angemessen gegenübertreten. Südlich von hier leben die Frostmanetrolle in einer Höhle.\n\nBringt mir zwei der Halsketten, die sie tragen - gefertigt aus Eiskrallenbären. Dann werden wir uns weiter über Eure Zukunft unterhalten.", t = "Ruf der Erde"},
    [94374] = {ot = "Sucht den Geisterstein und trinkt das Erdsapta.", st = "Aye, Sapta is' ein Gebräu, aus Magie geschmiedet, das uns'ren Geist an die Elemente bindet. Nur wen'ge Schamanen kennen das Rezept, und das is' nix für schwache Gemüter. Trinkt das, und Ihr werdet seh'n, was andere nich' seh'n können. Bleibt standhaft, das darf nur an 'nem heiligen Ort getrunken werden.\n\nGeht nach Norden zum Geisterstein, der am Ende von 'nem verborgenen Pfad den Berg 'rauf versteckt liegt. Trinkt es dort... und seht, was die Erde Euch zu offenbaren hat.", t = "Ruf der Erde"},
    [94375] = {ot = "Bringt den Rohquarz zu Teo Hammerstorm in Ambossar zurück.", st = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Teo Hammerstorm. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.\n\nHabt Geduld, $n. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", t = "Ruf der Erde"},
    [94411] = {ot = "Tötet 6 Lehrlinge des Hohen Ordens im Shen'darhochland.", st = "Seid gewarnt, Mitglieder des Hohen Ordens wurden in der Nähe der Menhire nördlich des Dorfes gesichtet. Wir haben sie wieder und wieder davor gewarnt, an unseren geheiligten Stätten herumzupfuschen, aber sie werden immer dreister. Beweist Eure Loyalität uns gegenüber, indem Ihr zu den Menhiren reist und sie vertreibt.\n\nIch verabscheue Blutvergießen, aber tut, was getan werden muss, um sie fernzuhalten. Kehrt zu mir zurück, wenn Ihr Eure Aufgabe erledigt habt.", t = "Einmischende Magier"},
    [94413] = {ot = "Tötet 6 Sehernovizen der Windformer im Shen'darhochland.", st = "Das Auftreten von Leylinien auf der Oberfläche von Zephras in letzter Zeit war grundlegend für unseren Orden. Wir haben einen direkteren und greifbareren Zugang zu den Energien, die diesen Ort durchdringen und es hat unser Verständnis dieser Magie erheblich vertieft.\n\nDie Windformer sehen dieses Aufkommen jedoch als Narben des Landes, die \"geheilt\" werden müssen. Das ist ein Affront gegen unseren Orden und etwas, das wir einfach nicht zulassen können.\n\nGeht zu der Leylinie im Wald südwestlich von hier und vertreibt alle Windformer, die Ihr dort findet.", t = "Ein magischer Affront"},
    [94414] = {ot = "Sprecht mit Halaan Hawk-Eye und leiht Euch seine Gabe, den Ankerpylon in der Entfernung zu sehen.", st = "Seid gegrüßt, $gjunger:junge; $n. Ich komme oft her, um den uralten Ankerpylon anzusehen. Diese Geschenke von den Geistern der Winde halten unser Land zusammen und nähren es. In letzter Zeit ist ihre Magie jedoch instabil und wechselhaft geworden.\n\nSie leiden keine Not, so weit ich sehen kann. Ihre Pracht bleibt unverändert.\n\nWenn Ihr mögt, kann ich Euch meine Gabe leihen, damit Ihr sie selbst erblicken könnt.", t = "Die Anker von Zephras"},
    [94427] = {ot = "Sprecht mit Tanis Alderwood in Undercity.", st = "Einer der wichtigsten Grundsätze der Paladine ist das Streben nach Göttlichkeit. Damit ist nicht das Streben nach Gottsein gemeint, sondern das Streben nach Güte selbst, und zwar dem Guten zuliebe. Wir alle sind hier aus mehr oder weniger tragischen Gründen angekommen und es wäre nur zu leicht, den Anstand zu verlieren, der uns als Paladine zu Lebzeiten ausgemacht hat.\n\nGeht nach Undercity und sprecht mit Tanis Alderwood im Handwerksviertel. Er steckt in Not und könnte etwas Anstand gebrauchen.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94434] = {ot = "Bringt 10 Stück Leinenstoff zu Tanis Alderwood in Undercity.", st = "Wartet, Ihr wollt... helfen? Warum sollte ein Paladin einem Bettler wie mir helfen?\n\nNun, ich schätze schon, dass Ihr mir helfen könntet.\n\nEs geht um meine Frau... Sie... nun, sie fällt auseinander. Und zwar buchstäblich. Die Apotheker können sie wieder zusammenflicken, aber sie sind mit der Dunklen Fürstin beschäftigt und es hat keiner Zeit, ihr zu helfen. Wenn Ihr mir etwas sauberen Stoff bringt, könnte ich zumindest einen Wickel für sie anfertigen, der sie zusammenhält, während wir auf die Apotheker warten.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94435] = {ot = "Kehrt zu Danitha Morr in der Bandarionfestung zurück.", st = "Ich weiß nicht, warum Ihr Euch die Mühe machen würdet, mir zu helfen, aber ich weiß es wirklich zu schätzen. Wenn Euch jemand zu mir geschickt hat, dann richtet der Person bitte auch meine Wertschätzung aus. Ihr werdet in Tanis Alderwood stets einen Freund haben, $C.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94436] = {ot = "Sprecht mit Todeswache Billmuth bei der Bandarionfestung.\n\nFalls Ihr Euer Symbol des Lebens verliert, kehrt zu Danitha Morr zurück und bittet sie um ein neues.", st = "Es ist an der Zeit, Eure Fähigkeit zu beweisen, eine der bedeutendsten Gaben des Lichts zu kanalisieren.\n\nDer Gegenstand, den ich Euch gerade gegeben habe, ist als Symbol des Lebens bekannt. Seid vorsichtig. Es könnte Euch einiges an Unbehagen bereiten, einen solchen Talisman des Lichts zu führen. Das Licht mag ein Gräuel für die Kräfte sein, die uns geschaffen haben, doch es bleibt nach wie vor unser Wegweiser und Verbündeter. Der Schmerz erinnert uns daran.\n\nGeht runter zu Todeswache Billmuth. Er ist gerade erst eingetroffen und hat um unsere Hilfe gebeten. Beweist ihm und den Verlassenen, wozu ein wahrer Paladin imstande ist.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94438] = {ot = "Nehmt das Symbol des Lebens und benutzt es, um Todeswache Falgan im Giftwebertal wiederzubeleben.\n\nFalls Ihr Euer Symbol des Lebens verliert, kehrt zu Danitha Morr zurück und bittet sie um ein neues.", st = "Falgan und ich wurden auf eine Mission geschickt, die Aktivitäten des Scharlachroten Kreuzzugs im Giftwebertal auszukundschaften. Wir konnten uns nah genug an eines ihrer Lager schleichen, um ihre neuen Befehle bezüglich eines Angriffs auf Brill zu erhaschen. Doch bevor wir unsere nächsten Schritte planen konnten, bin ich auf einen Zweig getreten, wodurch sie auf uns aufmerksam wurden.\n\nFalgan brüllte, dass ich fliehen sollte, also nahm ich die Beine in die Hand. Ich war bereits auf halbem Wege nach Brill, als mir erst bewusst wurde, dass er nicht an meiner Seite war. Dieser wackere Idiot hat sich vermutlich geopfert, um mir Zeit zu verschaffen.\n\nIch bitte Euch, findet meinen Freund und helft Ihm, wenn Ihr könnt.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94440] = {ot = "Beschafft die Angriffspläne des Scharlachroten Kreuzzugs von den Scharlachroten Kreuzzüglern im Giftwebertal und kehrt zu Todeswache Billmuth in Tyrs Wacht zurück.", st = "Diese Scharlachroten Kreuzzügler haben oft Taschen mit ihren Einsatzbefehlen dabei. Wir wissen, dass ein Angriff bevorsteht, aber wenn wir uns ihre Befehle beschaffen, können wir den Rest der Todeswache warnen und einen Hinterhalt vorbereiten.\n\nIhr seid offensichtlich ein beeindruckender Paladin. Tötet diese scharlachroten Bastarde, beschafft Euch eine Kopie ihrer Befehle und bringt sie dann zu Todeswache Billmuth. Er wird dann übernehmen.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94441] = {ot = "Sprecht mit Danitha Morr in der Bandarionfestung.", st = "Bitte sprecht Danitha Morr meinen Dank aus und sagt ihr, dass die restliche Todeswache davon erfahren wird, welchen Dienst uns die Paladine von Tyrs Wacht erwiesen haben.\n\nIhr seid ein vielversprechender Paladin und ich bin stolz, jemanden wie Euch in den Reihen der Verlassenen zu haben. Die Dunkle Fürstin schütze Euch, $n.", t = "Eine Lektion in Sachen Göttlichkeit"},
    [94449] = {ot = "Findet Bruegs Kindleborn in Dun Morogh.", st = "Eure letzte Prüfung ist schon ein wenig her, $n. Ihr habt Euch in Geduld geübt, aye... aber jetzt ist die Zeit gekommen, um Chaos und Zerstörung kennenzulernen. Der Ruf des Feuers ist laut, und wenn Ihr den Preis bezahlt, wird es zu Euch sprechen.\n\nSucht Bruegs Kindleborn in den Bergen weit im Osten auf. Er bewohnt eine Höhle oberhalb des Südtoraußenpostens. Er wird wissen, ob Ihr wirklich bereit seid.", t = "Ruf des Feuers"},
    [94465] = {ot = "Bringt die Fackel der schlafenden Flamme zu Braldir Ashmantle in Loch Modan.", st = "Aye, Ihr seid stark genug für das Totem des Feuers... aber Stärke allein reicht nicht aus.\n\nJenseits des Tals der Könige, zwischen den Felsen von Loch Modan, liegt der versteckte Pfad zu einem unserer heiligsten Gipfel. Dort wacht Braldir Ashmantle über den Schrein der schlafenden Flamme.\n\nZeigt ihm diese Fackel, sie wird Eure Absichten klarstellen. Bringt sie mit den Flammen der Kohlenpfanne des Schreins zurück, dann werdet Ihr Euch das Totem verdienen können.", t = "Ruf des Feuers"},
    [94466] = {ot = "Bringt 1 Feuerteer und 1 Reagenzienbeutel zu Braldir Ashmantle in Loch Modan.", st = "Pah, Ihr habt den ganzen Weg sicher nicht für ein paar Geschichten erklommen, oder, $n? Ihr sucht nach der ewigen Flamme und dem Feuertotem.\n\nAls Erstes braucht Ihr ein Sapta, um Eure Seele an die Flamme zu binden.\n\nIch werde es zusammenbrauen... aber dafür brauche ich zwei Dinge: Feuerteer von den Geomanten der Tunnelratten in den Koboldhöhlen im Norden, und den Reagenzienbeutel eines Sehers der Splittersteintroggs, die in den südlichen Hügeln lauern. Gefährliche Aufgaben, aber der Flamme würdig.", t = "Ruf des Feuers"},
    [94467] = {ot = "Besiegt die schwache Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", st = "Das Feuersapta ist vollendet, $n. Jetzt stellt Ihr Euch der Flamme. Trinkt das Sapta am Schrein und klettert dann bis zum Gipfel empor. Dort werdet Ihr dem Geist begegnen... er wird nicht zuerst zuschlagen, aber er wird wissen, dass Ihr ihn sehen könnt.$B$BZögert nicht im Kampf. Je länger Ihr wartet, desto stärker lodern seine Flammen. Wenn er besiegt ist, legt Ihr seine Glut in die Kohlenpfanne. Entzündet die Fackel und empfangt die Gunst des Feuers.", t = "Ruf des Feuers"},
    [94468] = {ot = "Bringt die Fackel der ewigen Flamme zu Bruegs Kindleborn in Dun Morogh.", st = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Loch Modan schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.$B$BAuf der Suche nach Bruegs Kindleborn betretet Ihr den Pfad zurück nach Dun Morogh.", t = "Ruf des Feuers"},
    [94484] = {ot = "Findet und sprecht mit Elegael Thornpaw im nordöstlichen Teil des Schattenwindwaldes.", st = "Wartet einen Moment, $n. Reist Ihr in Richtung des Schattenwindwaldes? Es gibt dort eine Druidenkonklave in einer Höhle im Nordosten. Ich warte seit einiger Zeit auf eine Antwort von ihnen, aber ihr Brief ist lange überfällig.\n\nMit Ban'aethal in Schutt und Asche und all den Unruhen in letzter Zeit befürchte ich das Schlimmste. Bitte, falls Ihr dazu in der Lage seid, sucht Elegael Thornpaw auf und verschafft meinem Geist etwas Ruhe.", t = "Unangenehme Stille"},
    [94485] = {ot = "Sammelt $1oa Damentränenmoose.", st = "Wenn wir meine Gefährten in der Nachtklauenhöhle retten wollen, werde ich einige Zutaten für einen Umschlag brauchen. Die erste und wichtigste Zutat ist ein spindeldürres Moos, Damenträne genannt. Normalerweise wächst es hier in Schattenwind unter den Bäumen.\n\nDas Moos sondert eine klebrige Substanz ab, die antiseptisch wirkt und sich perfekt für das Verbinden offener Wunden eignet. Ich habe bereits das Wenige gesammelt, was sich in Reichweite befand, aber es gibt noch mehr in diesem Wald.\n\nGeht schnell. Wir werden einiges davon brauchen, falls die Verwundeten noch am Leben sind, die ich zurückgelassen habe.", t = "Die Tränen einer Dame"},
    [94486] = {ot = "Sammelt $1oa Federn der Schattenwindkreischlinge im Schattenwindwald.", st = "Die andere Zutat, die ich für den Umschlag brauche, sind Federn der Schattenwindkreischlinge, die diesen Wald durchstreifen. Ihre Jungtiere verfügen über isolierende Federn, die sich perfekt über dem Moos platzieren lassen würden. Diese Federn werden den antiseptischen Saft am Austrocknen hindern und zumindest etwas Schutz vor den Elementen bieten.\n\nSeid gewarnt, die Kreischlinge sind normalerweise friedlich, aber in letzter Zeit waren sie extrem feindselig. Ihre großen Klauen können Euch mit Leichtigkeit ausweiden, wenn Ihr nicht acht gebt.", t = "Verbindende Federn"},
    [94487] = {ot = "Sammelt $1oa blutige Erbstücke von Fußsoldaten der Al'Aketh und von Sturmjägern der Al'Aketh im Schattenwindwald.", st = "Die Kultisten der Al'Aketh haben uns ohne Vorwarnung überfallen, aber ihre Motive sind mir immer noch ein Rätsel. Ich wusste, dass diese Kultisten nur Luft im Kopf haben, aber ich hätte nie gedacht, dass sie das zarte Gleichgewicht hier auf Zephras mit solcher Brutalität stören würden. Geht, tötet so viele, wie Ihr könnt, und bringt mir ihre Erbstücke, falls sie welche tragen.\n\n<Elegael spuckt aus.>\n\nDiese sturmverdammten Kultisten sind es nicht wert, Shen'dorei genannt zu werden. Die Bestien des Waldes können ihre Leichen haben. Ihre Asche verdient den Wind nicht.", t = "Ungewollt und unwürdig"},
    [94488] = {ot = "Tötet Kommandant Haalien und bringt seinen Kopf zu Elegael Thornpaw im Schattenwindwald.", st = "Der Grund für die Anwesenheit der Kultisten ist mir noch immer ein Rätsel, aber ein mir vertrauter Geruch dringt aus diesem Blutbad.\n\nEiner der Druiden unseres Zirkels, Haalien, ist vor Monaten verschwunden. Scheinbar hat er seine Tatzen in den Dienst der Kultisten gestellt.\n\nZeigt ihm, was passiert, wenn man das Blut seines eigenen Volkes vergießt! Bringt mir seinen Kopf.", t = "Blutsbande"},
    [94489] = {ot = "Betretet die Nachtklauenhöhle und heilt $1oa Druiden und findet Jorel Windsinger im Schattenwindwald.", st = "Die Umschläge sind fertig. Schnell, bringt sie zu den Druiden in der Höhle, direkt nördlich auf der anderen Seite der Lichtung. Ich weiß, dass meine Gefährten in weit schlechterem Zustand sind als ich. Vermutlich sind sie zu schwer verwundet, um ihre Wunden selbst zu heilen. Es gibt so wenige Druiden unter den Shen'dorei, jedes ihrer Leben ist kostbar.\n\nBevor Ihr geht, habe ich eine egoistische Bitte. Mein Partner Jorel Windsinger war schwer verletzt, als ich aufbrach. Bitte kümmert Euch um seine Wunden, falls er noch am Leben ist.", t = "Der Schmerz des Verrats"},
    [94490] = {ot = "Bringt das zerfetzte Schreiben zu Elegael Thornpaw im Schattenwindwald.", st = "<Unter einer von Haaliens Armschienen lugt eine Notiz hervor, die während Eures Kampfes eingerissen und mit Blut verschmiert worden sein muss. Sie scheint nützliche Informationen über die Gründe hinter dem Angriff der Kultisten auf die Druidenhöhle zu enthalten. Elegael wäre sicher daran interessiert.>", t = "Zerfetztes Schreiben"},
    [94491] = {ot = "Bringt das Schreiben zu Lotheluum in Valanaar und berichtet ihm, was geschehen ist.", st = "Es scheint, dass sich ein Spion in Valanaar versteckt, der den Kult mit Informationen versorgt. Offensichtlich bin ich in keiner Verfassung, um diese Reise anzutreten, aber Lotheluum muss wissen, was hier geschehen ist.\n\nEr sollte auch das Schicksal jener erfahren, die nicht länger unter uns weilen. Dank Eurer Hilfe haben wir die gegenwärtige Lage selbst im Griff, auch wenn das geschehene Leid nicht rückgängig gemacht werden kann.\n\nBitte beeilt Euch, $n. Ich hoffe, dass sich unsere Pfade eines Tages erneut kreuzen mögen. Bis dahin gibt es Kultisten, die ich töten muss.", t = "Das Schicksal der Höhle"},
    [94494] = {ot = "Findet Norric Lochthane in Loch Modan.", st = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, $n. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht Norric Lochthane in Loch Modan auf. Er befindet sich am Westufer des Sees, südlich des Stonewroughtdamms. Ihr findet ihn in seiner Erdhütte. Viel Glück, $n.", t = "Ruf des Wassers"},
    [94495] = {ot = "Findet Hervdana Saegrund im Sumpfland.", st = "Wenn es eine Wahrheit gibt, die Ihr über das Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt. Es schleift Fels, reinigt Schmutz und heilt die Schwachen – aber nur, wenn es rein ist. Verunreinigt es und es wird alles verderben, was es berührt.\n\nWenn Ihr das Wassersapta sucht, findet Hervdana Saegrund im Sumpfland. Ihre Familie lebt in einer Höhle unter den südlichen Wasserfällen.\n\nGeht, lasst Euch nicht vom Fluss abhängen.", t = "Ruf des Wassers"},
    [94497] = {ot = "Füllt den leeren braunen Wasserschlauch am Fuß der Wasserfälle unterhalb von Hervdanas Höhle und kehrt damit zu ihr ins Sumpfland zurück.", st = "Ah, Ihr sucht also das Sapta, wie? Nun, dann hört ganz genau zu, Schätzchen. Um das Sapta zu finden und zu verstehen, müsst Ihr Wasser in seinen verschiedensten Formen suchen. Während Ihr die Proben sammelt, haltet die Augen offen. Achtet auf die Tiere, die es bewachen, das Land, das es nährt, und wie es Leben verändert.\n\nWir fangen ganz leicht an: Füllt diesen Schlauch am Fuß der Wasserfälle, wo frisches auf Brackwasser trifft. Nun geht, gebt Acht im Sumpf.", t = "Ruf des Wassers"},
    [94499] = {ot = "Füllt den leeren roten Wasserschlauch an den Steinwachtfällen in der Nähe der Nachtkriechermurlocs und kehrt dann zu Hervdana Saegrund im Sumpfland zurück.", st = "Aye, das Rotkammgebirge trinkt vom Immerruhsee, doch bis das Wasser die Steinwachtfälle hinabstürzt, sickert etwas hinein. Die Murlocs dort sind große, verderbte Schläger. Anders als die, die Ihr hier oder im Loch findet. Zum Glück der Dorfbewohner bleiben sie am Fuß der Wasserfälle.\n\nBringt mir eine Probe. Ich würde gern wissen, ob es Magie, Gift oder etwas Schlimmeres ist, das das Wasser nahe der alten Burg verunreinigt.", t = "Ruf des Wassers"},
    [94500] = {ot = "Füllt den leeren blauen Wasserschlauch mit dem Wasser von Astranaar in Ashenvale und kehrt zu Hervdana Saegrund im Sumpfland zurück.", st = "Nehmt diesen Wasserschlauch und reist tief in den smaragdgrünen Schatten von Ashenvale. Astranaar ruht umschlossen von Gewässern, die von der Verderbnis noch unberührt sind. Ruinen bedecken den Grund des Sees, Zeugen einer vergangenen Ära. Bringt mir eine Probe aus dem See. Reines, uraltes und möglicherweise verzaubertes Wasser.\n\nEs ist die letzte Flüssigkeit, die ich brauche, bevor ich Euch zu Norric zurückschicke.\n\nGeht an Bord des Schiffes, das von Menethil nach Auberdine übersetzt. Es hält unterwegs in Southshore.\n\nUnd gebt auf Euch Acht... Der Wald hat Augen, und sie blinzeln niemals.", t = "Ruf des Wassers"},
    [94568] = {ot = "Sprecht mit Talaanis Shadowsong und beobachtet das Gespräch.", st = "Der Abtrünnige hatte offensichtlich so große Angst vor den Plänen der Sekte, dass er die Seiten wechselte und uns um Hilfe bat. Es ist wirklich bedauerlich, dass er tot ist und seine Geheimnisse mit ins Grab genommen hat.\n\nWir müssen dies weiter besprechen, um unsere nächsten Schritte zu bestimmen.", t = "Die wahren Pläne des Kults"},
    [94638] = {ot = "Findet und tötet Ur'endra im Shen'darhochland.", st = "Ihr seid zu mir gekommen, weil Ihr von mir lernen wolltet, eine Form der Stärke anzunehmen. Ich habe eine Aufgabe für Euch, die mich schwer belastet.\n\nMeine Partnerin Ur'endra ist dem Wahnsinn zum Opfer gefallen und wendet sich gegen ihre eigene Art. Ohne die Winde haben viele Tiere sich verloren und Ur'endras große Macht stellt eine ernste Bedrohung für das empfindliche Gleichgewicht dar. Sie zieht durch das Shen'darhochland im Nordwesten.\n\nBeweist, dass Ihr die Standhaftigkeit besitzt, ihr Leid zu beenden, dann gewähre ich Euch meinen Segen.", t = "Stärke und Gnade"},
    [94774] = {ot = "Sprecht mit Hohepriesterin Laurena in Stormwind.", st = "Ihr habt die Aufmerksamkeit unserer Vorgesetzten erregt, $n. Sie bitten, dass Ihr so bald wie möglich zur Kathedrale des Lichts in Stormwind reist. Anscheinend sind sie der Meinung, dass Ihr Euch bereits würdig erwiesen habt und bereit seid, Eure Ausbildung weiterzuführen. Wenn Ihr dort anlangt, sucht nach der Hohepriesterin Laurena. Sie kann Euch weitere Anweisungen geben. Viel Glück, und möge das Licht mit Euch sein.", t = "Göttliche Anmut"},
    [94792] = {ot = "Benutzt die Zähmerrute, um einen Steinhauteber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Josephine Carson zurück.", st = "Viele Jäger bevorzugen es, mit tierischen Begleitern zu reisen. Mit einer Bestie an Eurer Seite könnt Ihr sogar die gefährlichsten Umstände überleben. Wie man so schön sagt, alles ist einfacher mit einem Freund. Die Beschaffung eines tierischen Begleiters ist jedoch etwas, das mit Vorsicht erfolgen muss. Das Gleichgewicht der Natur ist äußerst empfindlich und muss immer respektiert werden.\n\nNehmt diese Zähmerrute mit in den Wald. Damit könnt Ihr einen Steinhauteber zähmen und Eure Fertigkeiten als Jäger üben.", t = "Die Bestie zähmen"},
    [94793] = {ot = "Sprecht mit Isaac Chan in Goldhain.", st = "Ihr könnt jetzt ein Tier zähmen, aber Ihr braucht auch die Fähigkeiten, um es abzurichten. Niemand könnte Euch dies besser beibringen als Isaac Chan, ein lebenslanger Waldmann. Er zeigt Euch, wie Ihr Euer neues Haustier ausbildet. \n\nGeht mit dem Wind, $C.", t = "Die Bestie abrichten"},
    [94818] = {t = "Notfallplan"},
    [94824] = {ot = "Sprecht mit Hohepriesterin Mims in Ironforge.", st = "Die Zeit ist für Euch gekommen, nach Stormwind zu gehen, $n. Die Hohepriesterin Mims in der Halle der Mysterien möchte mit Euch sprechen. Es muss etwas sehr Gutes oder sehr Schlechtes sein, wenn die Hohepriesterin Euch persönlich dort sehen will, aber ich denke, dass Ihr nur Gutes getan habt und dass es eine gute Sache ist, dass sie mit Euch sprechen möchte.$B$BVerschwendet hier aber nicht allzu viel Zeit. Ich an Eurer Stelle würde mich umgehend auf den Weg machen.", t = "Verwirrender Lichtblitz"},
    [94863] = {ot = "Benutzt die Zähmerrute, um einen grauen Forstwolf zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Josephine Carson zurück.", st = "Ihr habt bereits meisterhaft einen Eber gezähmt. Nun ist es Zeit für die nächste Lektion. Der Wald beherbergt wildere Gefährten und wenn Ihr mit Bedacht handelt, könnt Ihr ihr Vertrauen gewinnen.\n\nNehmt diese Zähmerrute und sucht nach einem grauen Forstwolf. Denkt daran, das Gleichgewicht der Natur muss respektiert werden. Stellt Eure Fertigkeiten als Jäger noch einmal unter Beweis.", t = "Die Bestie zähmen"},
    [94864] = {ot = "Benutzt die Zähmerrute, um einen jungen Waldbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Josephine Carson zurück.", st = "Durch das Zähmen eines Ebers und eines Wolfs habt Ihr Euer Können unter Beweis gestellt. Nun ist es an der Zeit für Eure letzte Herausforderung. Elwynns Gleichgewicht ist abhängig von Respekt und Können. Nehmt diese Zähmerrute und sucht nach einem jungen Waldbären. Beweist, dass Ihr das Vertrauen selbst des mächtigsten Begleiters verdienen könnt.\n\nDer Abschluss dieser Lektion wird Eure Abstimmung auf Wildtiere vertiefen.", t = "Die Bestie zähmen"},
    [94896] = {ot = "Sammelt $1oa zurückgelassene Habe.", st = "Ihr scheint mir fähig zu sein. Ihr reist nicht zufällig in Richtung des Schattenwindwaldes? Ban'aethal liegt tief in seinem Inneren. Wir alle stammen von dort.\n\n<Ealaane deutet auf die anderen Flüchtlinge.>\n\nVor Kurzem mussten wir Ban'aethal evakuieren, weil es begann, Richtung Himmel zu fallen. Es geschah so plötzlich und mitten in der Nacht. Falls Ihr in diese Richtung reist, könntet Ihr Ausschau nach zurückgelassenen Habseligkeiten halten? Der Wald und das Dorf sind jetzt viel zu gefährlich für uns, um zurückzukehren.", t = "Hilfe für die Flüchtlinge"},
    [94897] = {ot = "Findet Resaan in den Ruinen von Ban'aethal.", st = "Falls Ihr nach Ban'aethal reist, habe ich eine selbstsüchtige Bitte. Mein Geliebter, Resaan... Ich glaube, er ist nicht länger Teil dieser Welt. Er ist auf der Suche nach Vorräten umgekehrt, obwohl ich ihn angefleht habe, zu bleiben. Nun ist schon mehr als eine Woche vergangen, und ich befürchte das Schlimmste.\n\nBitte, falls Ihr ihn findet, bringt ihn nach Hause. Falls er von uns gegangen ist, bringt mir sein Erbstück.", t = "Das Schicksal eines Geliebten"},
    [94911] = {ot = "Sprecht mit Turak Runetotem in Thunder Bluff.", st = "Seid gegrüßt, $R. Ich sehe, dass viel Potenzial für die Druidenkünste in Euch schlummert. In Thunder Bluff wartet jemand, mit dem Ihr vermutlich sprechen wollt: Turak Runetotem. Er wird Euch zeigen, wie Ihr die Festung des Zirkels des Cenarius in Kalimdor findet, Moonglade. \n\nMan wird Euch dort willkommen heißen und die Druiden des Zirkels werden ihr Wissen gern mit Euch teilen. \n\nWie Ihr sagen würdet: Geht mit dem Segen des Windes. Ich wünsche Euch viel Erfolg auf Euren Abenteuern.", t = "Kind der Natur"},
    [94912] = {ot = "Sprecht mit Sheldras Moontree in Stormwind.", st = "Hallo, $C. \n\nHabt Ihr schon vom Zirkel des Cenarius gehört? Hätte ich auch nicht erwartet. Es handelt sich um einen alten Orden von Naturalisten und Praktizierer der Druidenkünste, wie Ihr es seid. In Stormwind findet Ihr einen Nachtelfen namens Sheldras Moontree. Er wird Euch zeigen, wie Ihr die Festung des Zirkels des Cenarius in Kalimdor erreicht, einen Ort namens Moonglade.\n\nGeht jetzt. Ihr müsst noch viel lernen, wenn Ihr Euer Zuhause retten wollt.", t = "Kind der Natur"},
    [94913] = {ot = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", st = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen. Bewahrer Remulos, Moonglades Wächter, wacht über allen Druiden, die hier ihren Winterschlaf halten. Ich bringe Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.$B$BAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, $gjunger Druide:junge Druidin;.", t = "Moonglade"},
    [94946] = {ot = "Nehmt das Himmelsseglerschiff von der Insel Zephras nach Dalaran und sprecht mit Danaaris Stargale, wenn Ihr ankommt.", st = "Ich hatte eigentlich vor, als Erster von uns einen Fuß auf Azeroth zu setzen, doch die jüngsten Ereignisse rund um den Kult haben meine Pläne durchkreuzt. Daher werde ich noch eine Weile hier in Valanaar bleiben. Aber keine Sorge, mehrere unserer Magier werden bei der Ankunft Eures Volkes in Dalaran bereits auf Euch warten. Ich würde Euch empfehlen, Azeroth zu erkunden, während wir hier unsere Angelegenheiten regeln. Wir melden uns bei Agenten wie Euch, wenn wir Eure Hilfe benötigen.\n\nWenn Ihr soweit seid, geht einfach zum Dock außerhalb dieser Behausung hier und betretet das Himmelsseglerschiff.", t = "Die magische Stadt Dalaran"},
    [94947] = {ot = "Benutzt das Portal der Himmelsgeborenen nach Stormwind und meldet Euch bei Bolvar Fordragon in Burg Stormwind.", st = "Unter uns liegt eine große Welt, und es ist an der Zeit, dass unser Volk ausschwärmt, um sie zu erkunden. Da kommt Ihr ins Spiel.\n\nDie Kirin Tor sind Mitglied einer \"Allianz\" gleichgesinnter Nationen. Das wahre Herz dieser Allianz ist die Stadt Stormwind im Süden. Elaadrin hat mich gebeten, jemanden zu finden, der nach Stormwind reist und sich mit dem Lordregenten dort trifft, ein Mensch namens Bolvar Fordragon.\n\nWenn Ihr bereit seid, haben die Magier der Kirin Tor ein besonderes Portal für den Hohen Orden geschaffen, um nach Stormwind zu gelangen.", t = "Willkommen in Azeroth"},
    [94978] = {ot = "Benutzt die Zähmerrute, um einen Windweisenkriecher in der Nähe von Gewässern zu zähmen. \nÜbt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück.", st = "Jeder Jäger lernt zuerst das Band zwischen Bestie und Meister kennen. Dies ist Eure erste Herausforderung. Bald werdet Ihr Kreaturen aus jeder Ecke der Welt zähmen, aber jetzt beginnt Ihr einmal hier, inmitten der Flüsse und Seen auf Zephras. \n\nNehmt diese Zähmerrute und sucht nach einem Windweisenkriecher.\n\nBeweist, dass Ihr sein Vertrauen erlangen könnt. Das ist der erste Schritt auf Eurem Weg zu wahrer Meisterschaft.", t = "Die Bestie zähmen"},
    [94979] = {ot = "Benutzt die Zähmerrute, um einen störrischen Windschreiter im Böenbeerentiefland zu zähmen.\nÜbt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück.", st = "Ihr habt bewiesen, dass Ihr Wasserbewohner zähmen könnt. Jetzt ist es Zeit, Euch auf festem Boden zu beweisen. In den Ebenen von Zephras hallen die Schreie der Windschreiter wider - stolzer, geflügelter Jäger, die laufen wie der Wind.\n\nNehmt diese Zähmerrute und sucht einen. Reist ins Tiefland und verdient Euch sein Vertrauen.\n\nBeweist damit, dass Ihr bereit für die kommenden Prüfungen seid.", t = "Die Bestie zähmen"},
    [95034] = {ot = "Sprecht mit Lumina Windsinger im Grabmal.", st = "Ihr solltet wissen, dass es nicht die Gnolle waren, die uns auf der Straße angegriffen haben.\n\nTatsächlich wurden wir von einer riesigen, wolfsgleichen Kreatur angegriffen, die ich mittlerweile als \"Worgen\" kenne. Er hat unsere Wachen erledigt und ist dann mir hinterher, als sich Banon ihm in die Quere geschmissen hat. Ich konnte gerade noch so einen Zauber wirken, der die Kreatur aufscheuchen und in die Flucht schlagen konnte, aber davor hat er Banon noch einen üblen Biss versetzt. Er bestand darauf, dass ich ihn zurücklasse, doch das habe ich vehement abgelehnt.\n\nWir sind hierher gehumpelt, als die Gnolle uns fanden. Was danach kam, war einfach entsetzlich...", t = "Die Schuld"},
    [95065] = {ot = "Bringt $1oa glänzende Schmuckstücke und $2oa Nachtkriecher zu Gilbert Gray am Hafen von Stormwind.", st = "Was für eine Aussicht... Das Beste, was sich ein alter Mann nur wünschen kann.\n\nDie Fische beißen gerade richtig gut an, und ich habe nur noch einen Köder. Ihr habt nicht zufällig etwas Angelzubehör übrig, oder? Natürlich nicht, vergebt mir. Ich bin so aufgeregt, wenn ich daran denke, die Rute erneut auszuwerfen, dass mir gar nicht in den Sinn kam, dass ich wohl einer der wenigen bin, die ständig Vorräte mit sich herumtragen.\n\nKönntet Ihr mir dabei helfen, meinen Vorrat wieder aufzustocken? Catherine Leland hat eine Auswahl an Angelbedarf gleich westlich des Handelsdistrikts entlang der Kanäle. Sagt ihr, der alte Gray schickt Euch.", t = "Zeit zu fischen"},
    [95161] = {ot = "Bringt den blutbefleckten Brief zu Avette Felwood im Dämmerwald.", st = "Wenn Ihr nach Jeremy Heartweaver sucht, solltet Ihr mit seiner neuen Adoptivmutter sprechen, Avette Felwood aus dem Dämmerwald. Eine nette Dame. Vermutlich braucht sie ein Paar helfende Hände für die Arbeit, aber es ist besser als im Waisenhaus zu bleiben.\n\nWenn Ihr den kleinen Jeremy seht, sagt ihm, wir denken alle an ihn.", t = "Denk daran, ich liebe dich"},
    [95189] = {ot = "Bringt das Wappen von Lordaeron zu Lady Dena Kennedy in Stormwind.", st = "<Ein verwittertes Wappen zeigt das Emblem von Lordaeron. Bei den wenigen Relikten, die nach dem Fall des Reiches noch übrig sind, gibt es sicherlich jemanden in Stormwind, der daran Interesse hat.>", t = "Wappen von Lordaeron"},
    [95195] = {ot = "Sammelt $1oa blutverschmierte Insignien und bringt sie zu General Marcus Jonathan in Stormwind.", st = "<Die alte Allianzinsignie scheint einem Soldaten von Lordaeron gehört zu haben. Diese Ruinen sind vermutlich voll mit ähnlichen Medaillen, die deren Hinterbliebene bestimmt gern zurück haben würden.>", t = "Blutverschmiertes Insigne"},
    [95204] = {ot = "Bringt das Wappen von Lordaeron zu Oran Snakewrithe in Undercity.", st = "<Ein verwittertes Wappen zeigt das Emblem von Lordaeron. Bei den wenigen Relikten, die nach dem Fall des Reiches noch übrig sind, gibt es sicherlich jemanden in Undercity, der daran Interesse hat.>", t = "Wappen von Lordaeron"},
    [95212] = {ot = "Sammelt 6 makellose Leopardenpelze und bringt sie zur Amberstill-Ranch.", st = "Wir bereiten einen Widdertrupp darauf vor, die Alterac-Expedition zu unterstützen, aber uns ist das Material ausgegangen, aus dem wir ihre Sattel fertigen.\n\nSammelt die Pelze der größten und wildesten Leoparden östlich von hier und bringt sie mir. Da oben sitzt einem der Frost in den Knochen, und unsere Streitkräfte verdienen nur die besten Pelze, um sich zu wärmen!", t = "Kein Sattel ohne Qualität"},
    [95213] = {ot = "Bringt das leere Pulverfass zu Steinbruchmeister Thesten im Steinbruch Gol'Bolar.", st = "Das Fass hat einen Stempel:\n\nSPRENGPULVER. GEFAHR. NICHT ANFASSEN. GEFAHR. NUR MIT ERLAUBNIS DES STEINBRUCHMEISTERS. GEFAHR\n\nEuch beschleicht das ungute Gefühl, dass dies nicht in die Hände der Troggs gehört. Es wäre besser, dem Steinbruch lieber früher als später darüber Bericht zu erstatten.", t = "Gestohlenes Sprengpulver"},
    [95214] = {ot = "Bergt $1oa Teile gestohlenes Sprengpulver von den Troggs östlich des Steinbruchs Gol'Bolar und kehrt dann zu Steinbruchmeister Thesten zurück.", st = "In diesem Fass war genügend Sprengpulver, um König Magnis Thronsaal ins Freie zu verlegen. Wir müssen es den Troggs wieder abnehmen, bevor sie herausfinden, wie man es entzündet.", t = "Gestohlenes Sprengpulver"},
    [95216] = {ot = "Bergt den hochgiftigen Erreger von Welkzahn in den Ruinen von Lordaeron für Theodore Griffs in Undercity.", st = "Herzlich willkommen im lebenswichtigsten Organ von Undercity, dem Apothekarium! Hier führen wir Experimente an den aggressivsten exotischen Exemplaren von Azeroth durch.\n\nIch bin gut gelaunt, deswegen will ich Euch von meiner neuesten Untersuchung berichten. Anscheinend lauert ein besonders giftiger Gliederfüßler in den Ruinen über unserer schönen Stadt. Sein Gift soll sogar untotes Fleisch zersetzen. Wie aufregend!\n\nIch möchte der Sache gerne nachgehen. Und solltet Ihr aufgrund seines Bisses verkümmern, hätte ich gerne eine Probe.", t = "Die neue Seuche"},
    [95217] = {ot = "Sammelt 12 Kupferbarren und 4 gekräftigte Eberbälge und bringt sie zu Frast Dokner.", st = "Ihr wollt also die Schmiedekunst erlernen? Vielleicht können wir einander helfen.\n\nDas Versorgungsschiff verspätet sich, und ich brauche Materialien, um Reparaturen im Lager zu bewerkstelligen. Wenn Ihr mir bringt, was ich benötige, lehre ich Euch einige meiner Techniken. Abgemacht?", t = "Der Schmied des Steinbruchs"},
    [95250] = {ot = "Holt den Kopf des Barons in den Ruinen von Lordaeron und bringt ihn zu Hauptmann Truman.", st = "Was wollt Ihr, $R? Seht Ihr nicht, dass es hier einen Krieg zu gewinnen gilt?\n\nMein Meister ist schon in den Kampf gestürmt und hat mir befohlen, auf meinem Posten zu bleiben. Das ist allerdings schon einige Zeit her.\n\nIch bezweifle, dass Ihr zehn Minuten im Kampf überleben würdet, aber wenn es Euren beschränkten Geist beschäftigt, dann sucht doch den Großmarschall auf. Er ist der größte Held, den Ihr je erblickt habt, mit einer Gestalt wie eine Statue. Ihr erkennt ihn, wenn Ihr ihn seht.", t = "Scheußliche Kreaturen"},
    [95314] = {ot = "Sammelt $1oa Flaschen mit flüsterndem Elixier aus Schattental und kehrt dann zu Carolai Anise in Brill zurück.", st = "Vor der Invasion der Geißel war das zurückgezogene Dorf Schattental für sein flüsterndes Elixier bekannt. Destilliert aus Kräutern, die sich nur in Tyrs Fall finden lassen, war das Elixier bei Apothekern, Mystikern und Giftmischern gleichermaßen begehrt, selbst, nachdem es in der Stadt verboten wurde.\n\nIch habe Nachfragen von einer ganzen Reihe an Interessenten, die es gar nicht erwarten können, das Elixier in die Hände zu bekommen. Reist nach Westen, zu den Ruinen Schattentals tief im Flüsternden Wald. Euch erwartet eine beträchtliche Kompensation, wenn Ihr mir einige Flaschen beschaffen könnt.", t = "Ein Elixier so grün wie das Schattental"},
    [95328] = {ot = "Bringt die Überreste des flüsternden Schreckens zu Vater Lankester im Kriegsviertel von Undercity.", st = "Wider besseren Wissens kratzt Ihr die sich windenden Reste der Bestie zusammen. Jemand in Undercity wird dafür vielleicht Verwendung haben.", t = "Überreste des flüsternden Schreckens"},
    [95349] = {ot = "Nehmt das Himmelsseglerschiff von der Insel Zephras nach Mulgore und sprecht mit Alaana Stormwalker, wenn Ihr ankommt.", st = "Die jüngsten Ereignisse rund um den Kult haben meine Pläne, nach Azeroth zu reisen, verzögert, und ich muss vorerst hier in Valanaar bleiben. Deswegen werdet Ihr und eine Handvoll anderer Windformer unsere Vorhut bilden. Alaana Stormwalker wird unsere Windformer bei ihrer Ankunft in Mulgore erwarten. Ich würde Euch empfehlen, Azeroth zu erkunden, während wir hier unsere Angelegenheiten regeln. Wir werden uns Euch zeitnah anschließen.\n\nWenn Ihr soweit seid, geht einfach zum Dock außerhalb dieser Behausung hier und betretet das Himmelsseglerschiff.\n\nBanu-Alah, $n.", t = "Der Irdene Ring"},
    [95350] = {ot = "Reist nach Orgrimmar und sprecht mit Thrall im Tal der Weisheit.", st = "Hier wartet eine große Welt und unsere neuen Verbündeten sind entscheidend für unser Überleben.\n\nDer Irdene Ring ist ein Mitglied der Horde, einer stolzen Gruppe Gleichgesinnter. Die nahe Stadt Thunder Bluff gehört zur Horde und weiter im Osten liegt die Hauptstadt Orgrimmar.\n\nBesucht den Flugmeister im Zentrum von Thunder Bluff. Er bringt Euch nach Orgrimmar, wo Ihr den Kriegshäuptling der Horde Thrall in Vertretung der Windformer trefft. Mögen die Winde Euch leiten, $n.", t = "Willkommen in Azeroth"},
    [95494] = {ot = "Sammelt 6 Savannenlöwenbälge von den Savannenmatriarchinnen und Savannenpartiarchen im Brachland.", st = "Ich brauche jemanden mit einem starken Schwertarm und freier Zeit, um mir bei der Beschaffung einiger Löwenfelle zu helfen. Es kratzt an meinem Stolz, einen Fremden um Unterstützung zu bitten, aber ich habe mich vor Kurzem am Bein verletzt. Bis es verheilt ist, bin ich nicht in der Verfassung, selbst jagen zu gehen. Aber ich habe Verpflichtungen einzuhalten.\n\nDie Großen hier in der Gegend haben für gewöhnlich die besten Bälge, fangt also mit denen an.", t = "Verletzter Stolz und Löwenbalg"},
    [95495] = {ot = "Bringt das Bündel Bälge dem Einsiedler auf dem Bergkamm über den Trockenen Hügeln im Brachland.", st = "Diese Bälge sind für einen Kürschner, mit dem ich regelmäßig Handel treibe. Er ist ein ziemlicher Einsiedler und lebt allein auf dem Bergkamm hinter mir. Ich bin gerade nicht in der Verfassung, einen steilen Hang zu erklimmen, ich würde also tief in Eurer Schuld stehen, wenn Ihr diese Lieferung für mich übernehmen könntet.\n\nOh, und wegen des... Aussehens dieses Kürschners. Ihr müsst Euch keine Sorgen machen. Er mag fies aussehen, aber er ist keine Bedrohung. Ich schwöre.", t = "Der einsiedlerische Kürschner"},
    [95507] = {ot = "Sammelt 8 gefangene Wildtiere aus den ausgelösten Fallen im Brachland.", st = "Es wäre großartig, wenn Ihr mir helfen könntet, meine Fallen zu überprüfen, während Ihr da draußen unterwegs seid. Ich habe sie überall im Tal verteilt.\n\nBringt mir jedes Kleinwild, das ich gefangen habe. Haltet aber die Augen nach anderen Wildtieren offen. Diese Gegend kann gefährlich sein, wenn man nicht aufpasst.", t = "Vrangs Spiel"},
    [95508] = {ot = "Helft Walton, die Begegnung mit Terry Longdrink und der Marine von Kul Tiras zu überleben.", st = "Ja, ich gehörte einst der Marine von Kul Tiras an. Nachdem der Lord Admiral Theramore einnahm und seinen Feldzug in Durotar begann, hatte ich... \"Bedenken\" bezüglich seiner Methoden. Besonders die Methoden, die die Hinrichtung von Zivilisten beinhalteten.\n\nEs ist eine lange Geschichte, aber... Moment... was ist das?\n\nDa kommt ein Trupp von Männern über den Kamm!", t = "Unwillkommene Gäste"},
    [95621] = {ot = "Reist zur verunglückten Karawane und findet heraus, warum die Kul Tiraner hier sind.", st = "Heute Morgen habe ich eine Gruppe von Menschen im Tal nach irgendetwas suchen gesehen. Ich konnte mit dem Fernrohr meines Gewehrs einen genaueren Blick darauf werfen und sie waren eindeutig Soldaten in der Tracht von Kul Tiras.\n\nWenn Ihr mir etwas Arbeit abnehmen wollt, geht zur verunglückten Karawane im Süden, wo diese Soldaten ihr Lager aufgeschlagen haben. Tötet alle, denen Ihr begegnet, und findet heraus, was sie hier suchen.", t = "Ärger im Tal"},
    [95646] = {ot = "Tötet einen Hochlandschrecken in den Ausgrabungsstätten und bringt seinen Wurzelkern zu Rethiel dem Sumpfhüter im Sumpfland.", st = "In diesem abgestandenen Sumpf gibt es eine große Quelle des Süßwassers des Südens. Es schmerzt mich, doch in meinen Wurzeln spüre ich eine Verderbnis durch diesen Bergquell hindurchsickern.\n\nWie in unserer Ebene reagieren die Kreaturen hier verbitterter auf die Verunreinigung. Ihnen fehlt seit dem Erblühen des Lebens das abhärtende Salz der See, deswegen können sie sich kaum gegen solches Übel wehren.\n\nGeht ins Hochland und bringt mir den Kern des Hochlandschreckens.", t = "Schrecken im Hochland"},
    [95647] = {ot = "Findet Ardin Grassman bei den Ausgrabungsstätten", st = "Mein Mann, Ardin, hat eine seltene Gabe, die Natur zu spüren. Er würde jeden Gipfel erklimmen, um die Kräuter und Blumen zu sammeln, die ich für meine Alchemie brauche, und um unsere Regale und Vorratskammer gefüllt zu halten.\n\nAber ich fürchte, er ist in Schwierigkeiten geraten. Ein Ausgrabungstrupp ist auf der Suche nach Vorräten vorbeigekommen. Sie sprachen unter anderem von riesigem Gras, wie sie es noch nie gesehen hatten. Da sagte er, das müsse er mit eigenen Augen sehen. Aber er ist schon zu lange fort!\n\nWenn Ihr irgendetwas über ihn herausfindet, wäre ich sehr dankbar.", t = "Im Dickicht verloren"},
    [95663] = {ot = "Reist ins Sumpfland und trefft die Todespirscheragentin in den Hügeln über dem Lager der Dragonmaw.", st = "Die Dragonmaw sind ein furchterregender Klan.\n\nSie sind für ihre Bindemagie bekannt, die mächtig genug sein soll, um Drachen in ihre Dienste zu zwingen. Es gibt Gerüchte, dass sie etwas Derartiges im Sumpfland vorbereiten. Ob das nun stimmt oder nicht, die Todespirscher können sich nicht mit halbgarem Geflüster aufhalten. Die Titanenwinde haben nicht mehr zu mir getragen.\n\nIn den Hügeln über dem Lager der Dragonmaw gibt es eine Agentin der Todespirscher, die eine helfende Hand braucht. Such sie auf. Sie wird Euch alles weitere erklären.", t = "Gerüchte von den Dragonmaw"},
    [95664] = {ot = "Bringt das Relikt der Titanen zur Anhöhe der Ältesten in Thunder Bluff und haltet Ausschau nach jemandem, der Euch mehr darüber erzählen kann.", st = "Dieser ungewöhnlich zusammengesetzte Splitter streut das Licht wie ein lebendiges Prisma. Seine Herkunft ist ungewiss, doch seine Kraft scheint uralt zu sein. Die größten Experten für Artefakte aus diesem längst vergangenen Zeitalter müssen auf der Anhöhe der Ältesten in Thunder Bluff zu finden sein.", t = "Wissen der Ältesten"},
    [95682] = {ot = "Erledigt die Dragonmawtruppen in der Ausgrabungsstätte und kehrt mit allem, was Ihr dort findet, zur Todespirscheragentin draußen zurück.", st = "Dragonmaw. <Sie stößt ein trockenes, amüsiertes Prusten aus.>\n\nDie Überreste des Drachenbändigerklans glauben, etwas gefunden zu haben, das ihnen helfen könnte, ihre frühere Macht wiederzuerlangen. In den Augen von wem? Ihres falschen Kriegshäuptlings?\n\nErledigt diesen zusammengewürfelten Haufen in den Ausgrabungsstätten, damit sich unsere Todespirscher unbemerkt dort einschleichen können.\n\nWenn die Dragonmawkrieger etwas von Bedeutung dabei haben, bringt es mir zurück. Diese Information geht nur uns und unsere königliche Befehlsstelle etwas an.", t = "Her damit"},
    [95697] = {ot = "Geht zu den Ausgrabungsstätten im Sumpfland und besorgt Dickichtraptorfleisch", st = "Zamja sagt, wir müssen mehr kochen wie zu Hause.\nSie glaubt, wenn wir anfangen, Raptor zu verkaufen, wird das Gäste anlocken, die Borstans Feuergrube normalerweise nicht besuchen.\n\nIhre Idee ist gar nicht schlecht. Aber ich will etwas, das über den Geruch unserer Geburtsdörfer hinausgeht. Wir sind in Orgrimmar! Borstan sollte eine prächtige Interpretation der vertrauten Lieblingsgerichte anbieten.\n\nVor Kurzem kam ein Jäger mit einer riesigen Kralle aus dem Sumpfland zurück, die von den Dickichtraptoren der Ausgrabungsstätten stammte.\n\nSucht Ihr Arbeit?", t = "Geschmackswandel"},
    [95772] = {ot = "Sucht in Whelgars Ausgrabungsstätte nach dem Bruder von Dorin Songblade, Daewyn.", st = "Mein Bruder hat versucht, mich mit einer Bande Ausgräber raus aus Loch Modan und ins Sumpfland zu schleppen. Meinte, sie gehen für eine Ausgrabung zu Hügeln, auf die noch nie ein Zwerg einen Stiefel gesetzt hat.\n\nAye, ich wäre mitgegangen, wenn ich nicht schon mit dieser Ladung Gürtel, die ich anpassen soll, spät dran wäre.\n\nDaewyn schreibt mir normalerweise, nachdem er auszieht, aber ich hab noch nichts von ihm gehört. Gibt mir ein ungutes Gefühl diesmal.\n\nWenn Ihr in die Richtung marschiert, würdet Ihr nach meinem Bruder sehen?", t = "Suche nach Songblade"},
    [95774] = {ot = "Erschlagt Stacheleber und sammelt $1oa von Olgras Schmuckstücken für Mankriks Denkmal.", st = "Der Heiler, der mich gerettet hat, konnte für Olgra nichts mehr tun. Sie ist im Kampf gefallen. Ich werde sie niemals vergessen.\n\nHabt Ihr ihren Schmuck nicht bei ihr gefunden? Sie trug viele kunstvoll gearbeitete Knochenornamente.\n\nErschlagt die Räuber der Grimmhauer in dem Gebiet, wo Olgra gestorben ist, und bringt mir ihre kostbaren Schmuckstücke!\n\nIch möchte sie an dem Denkmal niederlegen, das ich für Olgra errichte.", t = "Ihr Name ist Olgra"},
    [95795] = {ot = "Kehrt zu Dorin Songblade zurück", st = "<Ihr bedeckt die Leiche des Zwerges mit seinem Umhang.>\n\nReist nach Seenhain und berichtet Dorin Songblade persönlich davon, was seinem Bruder in den Ausgrabungsstätten zugestoßen ist.", t = "Gefallen im Moor"},
    [95803] = {ot = "Bringt den Kopf von Rudolph Gelhardt zu Sylvanas Windrunner in Undercity.", st = "Jetzt, wo wir den Kopf des befleckten Kommandanten haben, müsst Ihr ihn nach Undercity bringen. Sylvanas Windrunner misstraut uns zutiefst und verunglimpft uns fast schon öffentlich.\n\nBringt den Kopf von Rudolph Gelhardt zur Dunklen Fürstin. Zeigt ihr, dass wir uns um unsere eigenen Reihen kümmern und uns dem Wohl der Verlassenen verschrieben haben.", t = "Ein Zeichen des guten Glaubens"},
    [95805] = {ot = "Bringt das glimmende Räucherwerk innerhalb von zehn Minuten zum Schrein von An'she und Mu'sha in den südöstlichen Hügeln, bevor es zu Asche verbrennt.", st = "Die Sonne und der Mond, An'she und Mu'sha, gehören nicht zu unserer Welt wie die Elemente. Und doch schenkt uns ihr Licht Leben, Weisheit und Hoffnung.\n\nWir erweisen den Geistern der Welt unsere Ehrerbietung, und ebenso ehren wir die Zwillinge.\n\nWenn auch Ihr ihnen Euren Respekt erweisen möchtet, nehmt dieses glimmende Räucherwerk und bringt es zu einem Schrein in den Hügeln im Südosten, die über die Mesa emporragen, südlich der Stacheleber. Beeilt Euch, damit Ihr den Schrein erreicht, bevor das Räucherwerk verglüht.\n\nUnd passt auf, dass es nicht nass wird.", t = "Gunst von An'she und Mu'sha"},
    [95809] = {ot = "Kehr zu Caitlin Grassman im Hafen von Menethil zurück.", st = "Ich muss mich einen Moment ausruhen, bevor ich hier verschwinde.\n\n<Er zieht einige Schilfhalme aus seiner Tasche und flechtet geschwind ein Herz daraus.>\n\nBringt das zu Caitlin. Sagt ihr, ich bin bald zu Hause! Nachdem wir dank Euch nun einen sicheren Pfad haben, werde ich meine Büschel einpacken und Eurer Spur folgen.\n\nDanke.", t = "Herzverwoben"},
    [95810] = {ot = "Bringt das Relikt der Titanen zu Ausgrabungsleiter Whelgar an der Ausgrabungsstätte des Sumpflands.", st = "Ihr hebt ein Fragment des Fels-Automaten auf. Seine Textur ist mit nichts vergleichbar, was Ihr je berührt habt. Es ist ein Verbundstoff von unbekannter Zusammensetzung. Dieses Teil fällt ganz sicher mehr unter die Kategorie \"Gerät\" als unter die Kategorie \"Trümmer\".\n\nDer Ausgrabungsleiter Whelgar der Ausgrabungsstätte könnte vielleicht etwas Erhellendes darüber erzählen.", t = "Reliktbeförderung"},
    [95883] = {ot = "Sammelt eine gequälte Seele von den Untoten in der Nähe von Berens List im Silberwald.", st = "<Die Vorbereitungen für ein hastig auf die Beine gestelltes Ritual liegen sorglos auf dem Altar. Laut Notiz wurde alles zusammengetragen. Es fehlen nur noch eine Opfergabe des Blutes und eine gequälte Seele.\n\nDie Untoten in der Umgebung sehen reichlich gequält aus. Vielleicht haben sie, wonach Ihr sucht.>", t = "Die gequälte Seele"},
    [95884] = {ot = "Findet den Opfergabenstein in Berens List im Silberwald.", st = "<Der Großteil des Schriftfetzen lässt sich nicht entziffern. Was sich allerdings ausmachen lässt, sind Notizen zur Vorbereitung einer Opfergabe.\n\nEs ist von einem Opfergabenstein und einem Ritual die Rede.\n\nVielleicht lässt sich dieser Opfergabenstein irgendwo in der Umgebung finden.>", t = "Der Opfergabenstein"},
    [95885] = {ot = "Nutzt die gequälte Seele, um dem Opfergabenstein in Beren's Peril ein Blutopfer darzubringen.", st = "<Jetzt fehlt nur noch die Opfergabe des Blutes.\n\nDer Schriftfetzen sprach von einem \"willigen Opfer\".\n\nEuch überkommt ein grausiger Schauer.>", t = "Die Opfergabe des Blutes"},
    [95981] = {ot = "Tötet $1oa Hexer von Dalaran und $2oa Behüter von Dalaran für Schattenpriester Allister am Grabmal.", st = "Ihnen die Amulette wegzunehmen, ist nur der erste Schritt. Wenn die Kirin Tor tatsächlich regelmäßig Relikte aus Dalaran liefern, müssen wir sie an der Quelle stoppen.\n\nSucht die Straßen rund um Ambermill nach den Zauberern und Wächtern von Dalaran ab. Ihre Anwesenheit hat viel zu lange den offenen Zugang über unsere Grenzen hinweg ermöglicht. Wenn wir vermögen, ihre Zahl zu verringern, sollte das verhindern, dass diese Anhänger überhaupt erst in den Silberwald gelangen.", t = "Straßensperre"},
    [95998] = {ot = "Setzt Euch an Sams einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Hallöchen, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Schön für Euch. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nEs ist eine große weite Welt da draußen und Ihr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer, macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [95999] = {ot = "Bringt Magistrat Solomon in Seenhain den zerbrochenen Stab von Verbrenner Gar'im.", st = "Gesucht! Verbrenner Gar'im, Anführer einer Orc-Invasion in Renders Tal. Arbeitet angeblich mit dem Blackrockklan der Burg Steinwacht zusammen.\n\nVorsicht vor Verbrenner Gar'im. Er und seine Schattenwirker sind extrem gefährlich. Jede tapfere Seele, die einen Beweis für Verbrenner Gar'ims Ableben bei Magistrat Solomon erbringen kann, erwartet eine attraktive Belohnung.", t = "GESUCHT: Verbrenner Gar'im"},
    [96031] = {ot = "Geht nach Ironforge und sprecht mit Gretta Finespindle, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
    [96044] = {ot = "Geht nach Kharanos und sprecht mit Tognus Flintfire, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also dazu entschieden, $gSchmied:Schmiedin; zu werden. Eine sehr gute Wahl, denn so bleiben Eure Klingen immer scharf.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Schleifstein für Euer Lager bauen könnt. Wenn Ihr den Schleifstein aufstellt, stehen bald alle Krieger und Schurken aus der Gegend bei Euch Schlange, um ihre Waffen zu schärfen.", t = "Grundlagen des Zeltens: Schmiedekunst"},
    [96045] = {ot = "Geht nach Ironforge und sprecht mit Vosur Brakthel, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Jetzt, wo Ihr mit der Alchimie angefangen habt, kann ich Euch beibringen, wie Ihr einen Manabrunnen für Euer Lager bauen könnt, sobald Ihr etwas Wissen erlangt habt. Bald werden alle möglichen Heiler und Zauberwirker angerannt kommen, um sich an Eurem Brunnen zu erfrischen.", t = "Grundlagen des Zeltens: Alchimie"},
    [96046] = {ot = "Geht nach Kharanos und sprecht mit Yarr Hammerstone, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.", t = "Grundlagen des Zeltens: Bergbau"},
    [96047] = {ot = "Geht nach Kharanos und sprecht mit Thamner Pol, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ihr habt Euch also für Erste Hilfe entschieden? Als $C ist das eine ehrbare Wahl... und auch eine pragmatische.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Verbandtasche für Euer Lager herstellen könnt. Bei Abenteurern stehen Verletzungen an der Tagesordnung, und wenn Ihr in Eurem Lager Heilung anbietet, könntet Ihr damit sogar Leben retten.", t = "Grundlagen des Zeltens: Erste Hilfe"},
    [96050] = {ot = "Geht nach Dun Morogh und sprecht mit Paxton Ganter in der Nähe des Iceflowsees, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ob Ihr es glaubt oder nicht, Eure Fähigkeiten als $gAngler:Anglerin; können für Euer Lager durchaus nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fischglas für Euer Lager herstellen könnt. Mit diesem Schmuckstück könnt Ihr Euch selbst und anderen Abenteurern ein wenig Freude bereiten. Denn fröhliche Abenteurer sind starke Abenteurer und ich bin mir sicher, dass sich das auch in Euren Kampffähigkeiten niederschlagen wird.", t = "Grundlagen des Zeltens: Angeln"},
    [96055] = {ot = "Geht nach Ironforge und sprecht mit Reyna Stonebranch, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [96056] = {ot = "Geht nach Ironforge und sprecht mit Balthus Stoneflayer, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Kunst, erlegten Tieren Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.", t = "Grundlagen des Zeltens: Kürschnerei"},
    [96057] = {ot = "Geht nach Ironforge und sprecht mit Urthar Threx, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [96058] = {ot = "Geht nach Kharanos und sprecht mit Bronk Guzzlegear, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Als $gIngenieur:Ingenieurin; könnt Ihr allerlei Bauteile, Bots und Bomben basteln, egal, ob zum Vergnügen oder für den Profit.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Materialbot für Euer Lager bauen könnt. Dieser hilfreiche Automat stockt Eure Vorräte auf, sodass Euch und Euren Freunden nie die Materialien für Zauber ausgehen.", t = "Grundlagen des Zeltens: Ingenieurskunst"},
    [96059] = {ot = "Geht nach Ironforge und sprecht mit Thonys Pillarstone, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Jetzt, wo Ihr in die Verzauberkunst eingestiegen seid, kann ich Euch beibringen, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt, sobald Ihr ein paar Kenntnisse habt.\n\nUnterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [96101] = {ot = "Setzt Euch an Raans einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohl zu fühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96102] = {ot = "Geht nach Orgrimmar und sprecht mit Snang, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [96130] = {ot = "Besiegt Chakuyak und bringt ihr Fell mit.", st = "Unter den Präriewölfen, die in den nahen Hügeln jagen, gibt es eine Wölfin, die besonders aggressiv ist. Wir nennen sie Chakuyak. Sie ist zu einer Gefahr für Reisende geworden, die aus fernen Ländern zu uns kommen.\n\nSie streift durch den Wald westlich des Stonebullsees und zieht von Gehölz zu Gehölz.\n\nSetzt dem ein Ende! Bringt mir ihr Fell! Ich werde dem Häuptling von Eurer Tat berichten. Aber seid auf der Hut – sie ist gefährlich. Vielleicht trefft Ihr dort draußen auf andere Jäger. Gemeinsam stehen Eure Chancen besser.", t = "Chakuyak"},
    [96137] = {ot = "Besiegt $1oa junge schwarze Verheerer und $2oa schwarze Verheerer und kehrt dann zu Sirra Von'Indi in Dunkelhain zurück, um weitere Informationen zu erhalten.", st = "Ein kleiner Dolch, der der selbst ernannten Waldläuferin Ira gehörte. Sie sorgte in den Wäldern für Sicherheit, indem sie verhinderte, dass die Tiere Reisende angriffen.\n\nNachdem Iras Geist nun immer noch durch die Wälder streift, ist es vielleicht eine unerledigte Angelegenheit für sie, die Worgs zu beseitigen, die im ganzen Wald nach wie vor Opfer fordern.", t = "Iras Dolch"},
    [96139] = {ot = "Durchsucht die Rabenflucht nach Dingen von Interesse und kehrt zu Sirra Von'Indi in Dunkelhain zurück.", st = "In schlimmen Zeiten wie diesen ist es wichtig, nicht nur an unsere Feinde zu denken, sondern auch an unsere Helden. Dunkelhain würde ohne den Mut von Lady Althea oder jenen, die an der Rabenflucht ihr Leben gegeben haben, nicht mehr stehen.\n\nHabt Ihr schon viel über die Rabenflucht gelesen? Nein, natürlich nicht. Ihre Geschichte wurde zusammen mit ihren Menschen ausgelöscht. Selbst meine eindrucksvolle Bibliothek hat nicht viel zum Thema zu bieten.\n\nFalls Ihr doch etwas findet, wäre ich Euch dankbar, wenn Ihr es herbringt. Diese Leute haben es verdient, dass wir sie in Erinnerung behalten.", t = "Die Familie Valor"},
    [96204] = {ot = "Begleitet Lumina Windsinger und helft Ihr, Burg Fenris zu entkommen.", st = "Jetzt, wo ich frei bin, werde ich dafür Sorge tragen, dass diese üblen Kreaturen bereuen, je eine Windformerin zu Gesicht bekommen zu haben.\n\nVerschwinden wir von hier, $C.", t = "Der Zorn der Windformerin"},
    [96390] = {ot = "Tötet $1oa Spione der Dunkeleisenzwerge in Dun Morogh.", st = "Spione der Dunkeleisenzwergen haben Dun Morogh infiltriert. Ich bin mir nicht sicher, warum, aber wir müssen dieses Problem im Keim ersticken, bevor es größer wird.\n\nGeht nach Osten zu Ironbands Truppenlager und tötet die Spione der Dunkeleisenzwerge, die Ihr dort findet.", t = "Erstickt sie im Keim"},
    [96391] = {ot = "Bringt die Dunkeleisenkarte zu Erdseher Farsen in Dun Morogh.", st = "<Die Karte in Eurer Hand zeigt offenbar eine komplexe Reihe von unterirdischen Tunneln und Gängen, die alle an einem Punkt unter Ironforge selbst zusammenzuführen scheinen.\n\nIhr könnt die Runen nicht entziffern, da sie in der hässlichen gezackten Runensprache der Dunkeleisenzwerge geschrieben sind, aber Ihr könnt den Zweck dieser Tunnel erraten. Während Ihr die Karte studiert, erfasst Euch ein Windhauch und Ihr könnt schwach eine Zwergenstimme darin hören. Erdseher Farsen muss hiervon erfahren.>", t = "Karte des Untergrunds"},
    [96392] = {ot = "Sprecht mit Erdseher Farsen und frag ihn, ob er Euch seine Fernsicht leiht, um die Bedrohung der Dunkeleisenzwerge zu beobachten.", st = "Seid gegrüßt, $gmein Freund:meine Freundin;. Mein Name ist Erdseher Farsen und ich besuche Dun Morogh vom Nistgipfel. Auf meiner Reise konnte ich nicht umhin zu bemerk'n, dass wir, nun ja... ein kleines Problem mit den Dunkeleisenzwergen hab'n.\n\nWenn Ihr einen Moment Zeit habt, kann ich Euch zeig'n, was ich meine. Ich habe Magie, die das Problem lös'n sollte.", t = "Farsens Wacht"},
    [96393] = {ot = "Betretet die Halle der Thanen unter der Altstadt von Ironforge und besorgt den Kopf von Durgen Dirgehammer.", st = "Versammelt einige Verbündete und steigt in die Höhlen unter der Altstadt von Ironforge hinab. Betretet dort die Halle der Thanen und dringt bis zu den unteren Gewölben vor. \n\nMein Dunkeleisenzwergisch ist etwas eingerostet, aber ich kann einen Namen entziffern – Durgen Dirgehammer. Wahrscheinlich ist er der Kommandant. Schlagt seinen Kopf ab und bringt ihn zu König Magni Bronzebeard. \n\nOh, und richtet ihm aus, dass sein alter Freund Farsen ihn grüßen lässt!", t = "Eindringlinge in der Altstadt von Ironforge"},
    [96394] = {ot = "Tötet $1oa wütende Erscheinungen und $2oa gepeinigte Seelen, und bettet den Geist von Anvilmar zur Ruhe.", st = "Etwas hat die Gräber unten in der Halle der Thanen gestört, und seltsame Geräusche waren zu hören, die tief aus den Gewölben kamen. Die Geister der Toten haben einen leichten Schlaf, und was auch immer dort unten vor sich geht, scheint sie aufgeschreckt zu haben.\n\nGeht dort hinunter und seht, was Ihr für uns tun könnt. Wenn einer der Toten erwacht ist – nun, dann schickt ihn wieder zurück ins Grab!", t = "Die rastlosen Toten"},
    [96395] = {ot = "Bettet den Geist von Faldrim Anvilmar zur Ruhe und kehrt dann zur geisterhaften Bediensteten in der Halle der Thanen zurück.", st = "Der... Than... Mein mächtiger... Than... Er... muss... ruhen.\n\nBitte... helft ihm... Helft ihm... zu ruhen...\n\nVerzehrt... von... altem... Groll... Keine... Ruhe...", t = "Ein uralter Groll"},
    [96403] = {ot = "Sammelt $1oa zwergische Erbstücke in der Halle der Thanen.", st = "Ihr da, $gAbenteurer:Abenteurerin;... ich brauche Eure Hilfe.\n\nIch bin im Gewölbe herumgeschlichen – äh, ich meine \"patrouilliert\", als ein Trupp Dunkeleisenzwerge mit Maulwurfmaschinen aus der Tiefe kam! ich weiß nicht, was sie hier wollen, aber es gibt wertvolle Beute – äh, ich meine natürlich \"wichtige kulturelle Erbstücke\" da unten! Bitte, bergt alle Relikte dieser Art, die Ihr findet, und bringt sie hierher.\n\nIch versichere Euch, dass jeder Eurer Funde katalogisiert und an seinen rechtmäßigen Ehrenplatz zurückgebracht wird.", t = "Wichtige Erbstücke"},
    [96408] = {ot = "Untersucht das Lager über dem Steinbruch Gol'Bolar.", st = "Letzte Nacht hat einer unserer Bergsteiger ein Lagerfeuer auf einem Hügel im Osten entdeckt. Es scheint sehr hoch zu liegen, mit Blick auf den Steinbruch Gol'Bolar.\n\nEs ist bestimmt nichts, aber es wäre gut, wenn Ihr nachsehen würdet. Wenn sie freundlich gesinnt sind, ist alles gut. Wenn nicht... nun, dann wisst Ihr, was zu tun ist.", t = "Ein Besucher in Dun Morogh"},
    [96604] = {ot = "Setzt Euch an Brakks einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96605] = {ot = "Setzt Euch an Kagas einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96606] = {ot = "Setzt Euch an Lyreenas einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96607] = {ot = "Setzt Euch an Eleanors einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96608] = {ot = "Setzt Euch an Erics einfaches Lagerfeuer, indem Ihr /sitzen ins Chatfenster eingebt, und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", st = "Seid gegrüßt, $C. Ich sehe, dass Ihr den Geist des Abenteuers in Euch tragt. Das ist gut. Die Welt braucht mehr rastlose Seelen wie uns, die nach Ruhm und Reichtum streben.\n\nIhr werdet lernen müssen, Euch in der Wildnis wohlzufühlen, wenn Ihr erfolgreich sein wollt. Ich weiß nicht, wie es um Eure Überlebenskünste bestellt ist, aber ich kann Euch vermutlich das eine oder andere beibringen, wenn Ihr gewillt seid, zu lernen.\n\nSetzt Euch neben das Feuer und macht es Euch gemütlich. Ich werde Euch alles erklären.", t = "Die große weite Welt"},
    [96626] = {ot = "Sprecht mit Tomas in Goldhain, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96627] = {ot = "Sprecht mit Sam Sarsparilla in der Nähe von Goldhain.", st = "$n, Ihr habt bisher Eure Eignung als Beschützer unter Beweis gestellt. Daher beauftrage ich Euch nun mit einer ungewöhnlichen Aufgabe.\n\nIch habe von einem neuen Abenteurer gehört, der sich die Straße runter in Goldhain befindet. Begebt Euch dorthin und findet heraus, was er tut.", t = "Der Abenteurer"},
    [96628] = {ot = "Bringt das Vorratsbündel zu Eric Brighthammer in der Nähe von Kharanos.", st = "Wartet, $n. Ich habe eine weitere Bitte an Euch, bevor Ihr Euch in den Tunnel wagt.\n\nMeine Gebirgsjäger haben von einem Abenteurer berichtet, der gleich vor Kharanos aufgetaucht ist. Würdet Ihr ihm diese Vorräte bringen?", t = "Der Abenteurer"},
    [96629] = {ot = "Sprecht mit Gremlock Pilsnor in Kharanos, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96630] = {ot = "Bringt das Tagebuch zu Lyreena Duskblade in der Nähe von Dolanaar.", st = "<Das schlichte Tagebuch enthält Aufzeichnungen über das Leben und die Abenteuer von jemandem, von dem Ihr noch nie gehört habt.\n\nViele Einträge handeln vom Zelten. Es klingt ziemlich... spaßig.>", t = "Die Abenteurerin"},
    [96634] = {ot = "Sprecht mit Zarrin in Dolanaar, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96638] = {ot = "Sprecht mit Raan Wildwind in der Nähe von Shen'dar.", st = "Mehr und mehr Abenteurer wie Ihr haben nach Ruhm und Reichtum außerhalb der Sicherheit des Thendalhains gesucht. Einer dieser Abenteurer hat sein Lager außerhalb von Shen'dar aufgeschlagen, entlang der Straße, die südwestlich aus dem Thendalhain hinausführt.\n\nSucht ihn auf und seht, welche nützlichen Dinge Ihr von ihm lernen könnt, die Euch auf Euren Reisen behilflich sein könnten.", t = "Der Abenteurer"},
    [96646] = {ot = "Sprecht mit Zerril Softbreeze in Shen'dar, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96652] = {ot = "Bringt das Tagebuch zu Brakk in Klingenhügel.", st = "<Das schlichte Tagebuch enthält Aufzeichnungen über das Leben und die Abenteuer von jemandem, von dem Ihr noch nie gehört habt.\n\nViele Einträge handeln vom Zelten. Es klingt ziemlich... spaßig.>", t = "Der Abenteurer"},
    [96655] = {ot = "Sprecht mit Koch Torka in Klingenhügel, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96656] = {ot = "Sprecht mit Eleanor Shackleton in der Nähe von Brill.", st = "$n, Ihr habt Euch bei Euren bisherigen Anstrengungen gegen den Scharlachroten Kreuzzug als zuverlässig erwiesen. Daher beauftrage ich Euch nun mit einer ungewöhnlichen Aufgabe.\n\nIch habe von einer neuen Abenteurerin gehört, die sich die Straße runter in der Nähe von Brill rumtreibt. Begebt Euch dorthin und findet heraus, was sie da tut.", t = "Der Abenteurer"},
    [96658] = {ot = "Sprecht mit William Pickman in Brill, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96659] = {ot = "Bringt das Vorratsbündel zu Kaga Wildhoof in der Nähe des Dorfs der Bloodhoof.", st = "Wartet, $n. Ich habe eine weitere Bitte an Euch, bevor Ihr uns verlasst.\n\nEs gibt eine Abenteurerin namens Kaga Wildhoof, die ihr Lager außerhalb des Dorfs der Bloodhoof aufgeschlagen hat. Sie hat mir in der Vergangenheit sehr geholfen und jetzt kann ich mich endlich dafür revanchieren. Könnt Ihr ihr bitte diese Vorräte bringen?", t = "Der Abenteurer"},
    [96661] = {ot = "Sprecht mit Pyall Silentstride im Dorf der Bloodhoof, um das Kochen zu erlernen.", st = "Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.", t = "Grundlagen des Zeltens: Kochen"},
    [96779] = {ot = "Findet Lord Tomas innerhalb der Burg Durnholde im Vorgebirge von Hillsbrad und tötet ihn. Kehrt dann zu Myrokos Silentform zurück.", st = "Manchmal, $R, kann ein einzelner Schnitt an der richtigen Stelle einen Gegner auf der Stelle töten. Dasselbe gilt oftmals für Organisationen.\n\nUnsere Agenten haben ein Schlüsselziel in den Rängen des Syndikats ausfindig gemacht: einen Mann namens Lord Tomas.\n\nEr hat in der Burg Durnholde im Vorgebirge von Hillsbrad eine wichtige Rolle inne. Wenn Ihr Ravenholdt zu Diensten sein wollt, dann begebt Euch nach Durnholde und schaltet ihn aus. Je schneller und unauffälliger, desto besser.", t = "Sabotage des Syndikats"},
    [96821] = {ot = "Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon.", st = "Wir sehen dieser Tage immer weniger Reisende aus Klingenhügel. Die Skorpide haben schon immer wenig Spaß gemacht, aber jetzt habe ich gehört, dass Spinnen ihre Nester entlang der Straße bauen.\n\nWenn Eure Reise Euch nach Norden führt, tötet doch unterwegs einige dieser Spinnen. Und dann berichtet in Klingenhügel, dass der Weg wieder etwas sicherer ist.", t = "Nehmt die Beine in die Hand"},
    [96822] = {ot = "Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück.", st = "Wir haben viele tapfere Krieger der Horde verloren, als wir Burg Tiragarde plünderten. Da die Menschen die Ruinen nun verstärkt haben, können wir ihre Überreste nicht einsammeln, um ihren Tod angemessen zu ehren.\n\nBegebt Euch zu den Ruinen um die Burg und sucht nach den Waffen, die von unseren gefallenen Brüdern zurückgelassen wurden. Wir werden sie an einem Ehrenplatz ausstellen.", t = "Für die Ehre"},
    [96825] = {ot = "Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt.", st = "Unser Jäger und Fischer bringen viel würzige Nahrung für unsere Truppen mit – aber sie bekommen nur selten etwas Süßes.\n\nIch habe einen Kaktus gesehen, an dem eine stachelige, schmackhafte Frucht wächst. Aber er wächst nur auf den Hügeln im Westen, wo diese garstigen Stacheleber sich herumtreiben. Bahnt Euch einen Weg durch die Stacheleber und bringt mir einige dieser Früchte. Aber passt auf – sie sind so stachelig wie die Eber!", t = "Diese Frucht beißt zurück"},
    [96873] = {ot = "Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen.", st = "Der Hexendoktor Zalazane hat den Trollen östlich von hier den freien Willen geraubt. Er nutzt grausame Magie, um den Verstand seiner Gefangenen zu beherrschen, aber einer seiner Lieblingstricks ist, sie Anhänger mit bösen Bindezaubern tragen zu lassen.\n\nÜbt Eure Verzauberkunst, indem Ihr diesen Anhängern die Magie entzieht, und bringt mir die Ergebnisse. Aber legt nicht versehentlich einen davon an, wenn Euch Eure Freiheit etwas wert ist!", t = "Ein Dorn im Nacken"},
    [96874] = {ot = "Ug'thok in Orgrimmar möchte, dass Ihr 5 verwitterte Stacheln von Bestien am Donnergrat und 5 raue Schleifsteine für ihn sammelt.", st = "Habt Ihr die riesigen Bestien des Donnergrats gesehen? Ich denke immer, die Stacheln auf ihren Rücken würden sich perfekt zur Herstellung eines mächtigen Axtblatts eignen. Saru hat gelacht, als ich es ihm gesagt habe... aber was weiß der schon!?\n\nAls Teil Eures Schmiedeunterrichts könnt Ihr mir helfen! Bringt mit einige dieser Stacheln, zusammen mit Schleifsteinen, um sie zu schärfen.", t = "Vom Stachel zur Axt"},
    [96875] = {ot = "Kamari in Orgrimmar möchte, dass Ihr 5 raue Echsenhäute von Wildtieren am Donnergrat und 2 geschmeidige leichte Bälge besorgt.", st = "Orgrimmar wächst stetig, $C. Und wenn die Peons neue Tierhäute brauchen, um die Wände und Dächer unserer Neubauten zu verkleiden, kommen sie zu mir!\n\nDie Bälge der Echsen am Donnergrat sind für gewöhnlich zu dick, um Rüstungen daraus herzustellen, aber sie eignen sich hervorragend als Baumaterial. Bringt mir einige dieser Bälge und auch einige leichtere gegerbte Häute. Zeigt mir Eure Fähigkeiten im Umgang mit Leder!", t = "Bestien des Donnergrats"},
    [96876] = {ot = "Bringt den Beutel zu Ukor im Süden von Durotar.", st = "Der Name \"Ukor\" ist grob auf die Lasche des Beutels gestickt.", t = "Ukors verlorener Beutel"},
    [96877] = {ot = "Bringt Halikors Huf nach Orgrimmar.", st = "Der riesige Huf dient als Beweis für Euren Sieg über die mächtige Echse.", t = "Halikors Huf"},
    [96895] = {ot = "Findet das Mitglied der Argentumdämmerung in der Nähe des Eingangs von Undercity.", st = "Ich weiß nicht, ob Ihr es schon gehört habt, aber zwei Abgesandte der Argentumdämmerung sind gerade hier durchgekommen. Ich habe nichts gegen die Argentumdämmerung, aber mir gefällt der Gedanke nicht, dass sie unbeaufsichtigt durch Tirisfal streifen. Es waren beides Verlassene... aber das macht mich nicht weniger nervös.\n\nEiner von ihnen ist gerade auf dem Weg nach Südosten hier vorbeigekommen. In dieser Richtung gibt es eine Gruppe von Geißelkultisten, die am Rand der Stadt rumschnüffeln. Wenn diese beiden von ihnen gehört haben, hätte das zweifellos ihre Aufmerksamkeit erregt.", t = "Der Argentumabgesandte"},
    [96896] = {ot = "Beobachtet das Gespräch zwischen Danitha Morr und Leonid Bartholomew dem Geachteten.", st = "Danitha und ich haben gegen die Geißel gekämpft, als wir Undercity gegen den Angriff von Naxxramas verteidigten. An jenem Tag haben wir viele gute Freunde verloren, darunter auch den Helden, nach dem diese Festung benannt wurde: Garek Bandarion.\n\nEr war vielleicht der erste Verlassene, der wieder gelernt hat, das Licht als Paladin zu führen. Es ermutigt mich zu sehen, dass sein Vermächtnis und sein Potenzial hier in Danitha und ihrer Kohorte weiterleben.\n\nWenn nur der Rest der Verlassenen genauso denken würde...", t = "Für die gerechte Sache"},
    [96897] = {ot = "Tötet $1oa dunkle Neophyten und $2oa dunkle Vollstrecker in Tirisfal.", st = "Die Geißel ist eine Plage für unser Land, und ihre lebenden Diener sind am schlimmsten. Die Menschen von Tirisfal haben schon genug mit den geistlosen Toten und dem Scharlachroten Kreuzzug zu tun. Wenn Ihr etwas Gutes tun wollt, helft mir, diesem Abschaum ein Ende zu bereiten.", t = "Der Kult der Verdammten"},
    [96898] = {ot = "Sammelt $1oa nekrotische Kristallfragmente in Tirisfal.", st = "Es ist noch nicht lange her, dass sich die Zitadelle Naxxramas auf diese Stadt stürzte, fest entschlossen, die Verlassenen auszulöschen. Sowohl die Verlassenen als auch die Argentumdämmerung haben an jenem Tag viel verloren, um die Zukunft der Verlassenen zu sichern.\n\nWährend der Schlacht wurde der große nekrotische Fokussierkristall, der unter Naxxramas hing, zertrümmert und seine Fragmente über dieses ganze Gebiet verstreut. Ich vermute, dass es die Kultisten darauf abgesehen haben. Helft mir, die Fragmente zu bergen und dafür zu sorgen, dass sie nicht in die Hände der Geißel fallen.", t = "Überreste des Krieges"},
    [96899] = {ot = "Trefft Leonid Barthalomew in der Bandarionfestung in Tirisfal.", st = "Ihr habt heute eine große Tat für die Argentumdämmerung vollbracht, und ich danke Euch. Ich weiß nicht, wie vertraut Ihr mit der Bandarionfestung seid, aber mein Kommandant und ich waren auf dem Weg dorthin, um uns mit den Paladinen zu treffen, die dort ansässig sind. Das war allerdings, bevor wir von der Präsenz des Kults der Verdammten erfahren haben.\n\nWenn Ihr mehr über die Argentumdämmerung und unsere Mission erfahren möchtet, sucht meinen Kommandanten in der Bandarionfestung nordwestlich von hier auf. Ich werde hierbleiben, um den Rest dieses Schlamassels aufzuräumen.", t = "Die Bandarionfestung"},
    [96984] = {ot = "Holt den Arkanpartikel für Magus Wordeen Voidglare in Tarrens Mühle aus Dalaran.", st = "Ihr habt vielleicht nicht unser Bestes im Sinn, aber ich werde ein Paar helfende Hände nicht ablehnen. Und wenn Dalaran fällt, nimmt es alles mit sich – auch Eure Undercity.\n\nAlso, Euer Gönner möchte hereinkommen? Gut. Ich werde Euren Schlüssel verzaubern, sodass Ihr die Stadt durch meine Zauberschutze betreten könnt. Sobald Ihr hier seid, trefft mich bei der Violetten Zitadelle, wo all das hier begann. Die Kirin Tor werden zu beschäftigt sein, um Euch aufzuhalten.\n\nPlündert soviel Ihr wollt, aber was auch geschieht, unsere oberste Priorität ist die Abwendung einer Katastrophe.", t = "Das Herz der Störung"},
    [96986] = {ot = "Besiegt Atrexis den Grabritter in Dalaran für Melisara in Tarrens Mühle.", st = "In den Eingeweiden der Magierstadt im Norden gibt es einen Verräter unserer Art. Ein Totenbeschwörer mit verstörenden Fähigkeiten. Er erhebt eine Armee der Untoten, direkt vor den Augen der Kirin Tor.\n\nMir ist das Schicksal der Magierstadt egal, $n, aber dieser Grabritter ist ein Schlag ins Gesicht für alles, wofür wir Verlassenen stehen. Bereitet ihm ein Ende. Zeigt ihm, dass niemand unerreichbar für die Dunkle Fürstin ist.", t = "Der Grabritter"},
    [96987] = {ot = "Holt das Buch \"Die Gründung von Dalaran\" aus Dalaran für Rexxie Copperclutch in der Nähe des Kanalisationseingangs.", st = "Nun, wenn das mal kein gleichgesinnter Unternehmergeist ist. Schleicht Euch in so beschwerlichen Zeiten nach Dalaran hinein? Tz, tz. \n\nIhr seid ganz nach meinem Geschmack, $R!\n\nSolange unsere Magierfreunde hier beschäftigt sind, können wir vielleicht einige \"verlegte\" Schätze finden. Die haben hier ganze Archive voll schmucker arkaner Magi. Wenn Ihr mir den einen oder anderen ihrer geheimen Folianten bringt, könnte ich ihn für gutes Geld verkaufen. Ich teile den Gewinn mit Euch.\n\nHe, seht mich nicht so an. Ihr seid doch selbst nicht gerade für einen netten Ausflug hier. Seid Ihr dabei oder nicht?", t = "Opportunistische Bildung"},
    [96988] = {ot = "Sammelt $1oa gesprungene Wächterkerne in Dalaran für Doktor Martin Felben in Undercity.", st = "Die Belagerung von Dalaran durch ihre eigenen Konstrukte ist die perfekte Gelegenheit, um – sagen wir – einige Proben auszuborgen.\n\nStellt Euch eine Armee von arkanbetriebenen Abscheulichkeiten vor. Die Dunkle Fürstin hätte keine andere Wahl, als meine alchemistischen Fähigkeiten anzuerkennen. Vielleicht ernennt sie mich sogar zum Leiter der Königlichen Apothekervereinigung?\n\nGeht in die Stadt und findet einige Kerne der Konstrukte. Die werden sie nicht freiwillig hergeben, also tut, was Ihr tun müsst.", t = "Quelle der Macht"},
    [97003] = {ot = "Bringt den Kopf von Chol'aruk zu Gur'ak im Brachland.", st = "Ihr da, $C. Ich brauch Eure Hilfe. Es gibt Gerüchte von einer Bestie, die nordwestlich von hier in einer Höhle tief im Dornenhügel haust. Die Grimmhauer nennen sie Chol'aruk oder \"den Verschlinger\". Sie soll fünfmal so groß sein wie ein normaler Stacheleber und einen unstillbaren Blutdurst besitzen. \n\nDie meisten glauben diese Geschichten nicht. Ich schon, denn ich habe schon einmal gegen einen wie ihn gekämpft.\n\nFindet sein Versteck und tötet Chol'aruk. Bringt mir seinen Kopf. Doch ich warne Euch: Seid gut vorbereitet und geht nicht allein.\n\nBlut und Donner, $C.", t = "Chol'aruk der Verschlinger"},
    [97220] = {ot = "Bringt die Torhauslieferung zum Lagerraumeingang in Trias' Käseladen im Handelsdistrikt.", st = "Uns fehlt es diese Woche an Dockarbeitern.\n\nHättet Ihr Lust, unseren Frachtplan ein wenig zu entlasten?\n\nBringt dieses Paket zum Lagerraumeingang des Torhauses. Ihr findet es im zweiten Stock von Trias' Käseladen. Die Herrin Elaine weiß über die Lieferungen Bescheid. Das Torhaus verlangt öfter mal diskretere Zustellungen von Lieferungen, damit die Wachoffiziere feierliche Überraschungen organisieren können.", t = "Philmors Bitte"},
    [97222] = {ot = "Tragt die Torhauslieferung die Treppe in Trias' Laden hoch und stellt sie vor der Tür ab.", st = "Ja, es ist nur eine Treppe. Aber wenn es nur eine so kleine Gefälligkeit ist, sollte es Euch keine Probleme bereiten, die Lieferung selbst zu erledigen!\n\nTrias' Käse ist nicht Teil des Torhauses oder ihrer Vorratslager, aber unsere Gebäude liegen auf einer Höhe.\n\nStellt die Kiste vor die Tür ihrer Vorratskammer. Die Wache wird jemanden für eine normale Abholung schicken. Sie werden sehen, dass die Lieferung da ist, und sie hineintragen, wenn sie auf ihren Posten zurückkehren.", t = "Torhauswaren"},
    [97223] = {ot = "Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin.", st = "Alle Raptor'n, die Ihr hier seht, hab ich selbst ausgebildet. Sie stamm'n aus ganz Kalimdor. Einige der besten sin' Blutkrallenraptoren von den Inseln vor unserer Küste.\n\nEins von den Weibchen, die Blutkrallenmatriarchin, is' besonders wild. Sie hat viele Bewohner von unser'm Dorf getötet un' is' inzwischen zu gefährlich geword'n, um sie weiterhin in der Nähe zu duld'n. Wenn Ihr sie bezwing'n könnt, bringt mir ihre Eier. Wir können die Jungen aufzieh'n. Dann sin' sie unsere Verbündete statt Feinde.", t = "Blutkrallenmatriarchin"},
    [97225] = {ot = "Sammelt $1oa vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin.", st = "Als wir von den Inseln flieh'n musst'n, auf denen jetzt Zalazane und seinesgleichen hausen, ließ'n wir viele wertvolle Götz'n zurück. Sie helf'n uns, mit den Geistern zu kommunizier'n, die wir verehr'n: unseren Loa. Sie sin' von großer Bedeutung für unseren Stamm.\n\nDie Anhänger Zalazanes zeig'n keinerlei Ehrfurcht vor unser'n Loa und hab'n die Götz'n über die größte der Inseln verstreut.\n\nWenn es uns nicht gelingt, sie zurückzuhol'n, wird das schlimme Folgen hab'n. Einen Loa zu beleidig'n, is' eine ernste Angeleg'nheit.\n\nGeht. Findet so viele Loagötz'n wie möglich un' bringt sie mir.", t = "Vergessene Loagötzen"},
    [97234] = {ot = "Bringt das verpackte Lesematerial zur Bibliothek von Stormwind.", st = "Seid Ihr hier, um die tiefere Bedeutung unserer legendären Geschichten zu erörtern? Nein?\n\nNun, wenn Ihr Euch fertig umgesehen habt, könntet Ihr dann das hier für mich in die Bibliothek tragen? Wir tauschen einige unserer weniger beliebten Werke gegen etwas modernere Schriften aus. Ich habe hier eine Liste an Folianten, die der Bibliothekar im Rahmen unserer bestehenden Vereinbarung sicher auftreiben kann.\n\nKostenlose Erfrischungen im Club gehen auf uns, wenn Ihr uns aushelft.", t = "Lesezimmer"},
    [97236] = {ot = "Bringt den Fangzahn von Githyiss zu jemandem in Aldrassil, der sich für das Studium von Spinnen interessiert.", st = "Ein frisches Exemplar von einem Tier dieser Größe ist ein bedeutsamer Fund. Vielleicht hat jemand in Aldrassil daran Interesse, der sich mit dem Studium von Spinnen auskennt.", t = "Fangzahn von Githyiss"},
    [97237] = {ot = "Findet die Lesematerialien, die sich irgendwo in der Bibliothek befinden, und kehrt dann zu Roy Lewells im Park von Stormwind zurück.", st = "Ich habe unser Inventar überprüft, und alle von Mr. Lewells aufgelisteten Werke sind derzeit verfügbar.\n\nIhr müsst sie allerdings selbst aus den Regalen nehmen. Es ist die Pflicht eines Bibliothekars, wachsam zu sein, und deshalb werde ich jetzt meine buchhalterische Aufsicht wieder aufnehmen.\n\nWenn Ihr in Roys Namen mit dem Material zu ihm zurückkehrt, seid Ihr nicht für ihre Rückgabe verantwortlich; seiner Notiz zufolge dient Ihr dem Buchclub als $goffizieller Kurier:offizielle Kurierin;. Darum soll sich ihre Vereinigung selbst kümmern.\n\nEinen schönen Tag noch, $n.", t = "Regalverlesen"},
    [97242] = {ot = "Sammelt Stecklinge vom Rohrkolben und Speergras, das in der Nähe der fließenden Gewässer im Tal der Ehre wächst, und bringt sie zu Kor'geld in Yelmaks Alchimie und Tränke.", st = "Yelmak will nicht, dass sein Lehrling irgendwas kaputtmacht. Oder zumindest noch mehr als ohnehin schon.\n\nEr meinte zu mir, der junge Mischer in Ausbildung sei zu stolz und würde nicht um Hilfe bitten, wenn er sie wirklich braucht. Yelmak will ihn eines seiner speziellen selbstgebrauten Rezepte kosten lassen.\n\nSammelt eine Mischung aus Rohrkolben- und Speergrasstecklingen von den Pflanzen, die rund um das Gewässer im Tal der Ehre wachsen. Ich würde sie ja selbst besorgen, aber wenn ich den Laden verlasse, würde Whuut sicher spitzkriegen, dass wir was mit ihm vorhaben.", t = "Yelmaks Mischmasch"},
    [97243] = {ot = "Bringt die Fackel der schlafenden Flamme zu Olariaan Swiftburn im Schrein der Flammen in im Böenbeerentiefland.", st = "Obwohl wir hier im Reich des Himmelswalls sind, befinden wir uns trotzdem noch auf der Elementarebene. Die Geister aller vier Elemente sprechen zu uns, wenn wir bereit sind, ihnen zuzuhören. Einer von uns Windformern hat eine besonders starke Verbindung zum Element des Feuers. Er ist ein Shen'dorei namens Olariaan Swiftburn.\n\nBringt diese Fackel zu ihm. Er hält sich im Schrein der Flammen im Böenbeerentiefland auf. Ihr findet ihn ganz am Rand der Insel, westlich von Valanaar.", t = "Ruf des Feuers"},
    [97244] = {ot = "Tötet Himmelspriester Faladiel im Böenbeerentiefland und nehmt Faladiels Herz mit.", st = "Es gibt einen Himmelspriester der Al'Aketh namens Faladiel. Einst war er ein Rufer der Flamme und ein treuer Windformer. Wie viele Al'Aketh tauschte er jedoch seine Loyalität gegen Macht, und an seinen Händen klebt nun das Blut seiner früheren Brüder und Schwestern.\n\nIhr findet Himmelspriester Faladiel auf dem Bauernhof nordöstlich von Valanaar, südlich vom Schrein von Akir. Tötet den Verräter und bringt mir sein Herz. Eine grausame Aufgabe zwar, doch leider nötig für das Ritual, das wir durchführen wollen.", t = "Ruf des Feuers"},
    [97245] = {ot = "Findet Kuramaas Zuhause im Shen'darhochland und besiegt den Geist im Kampf. Bringt nach dem Sieg Kuramaas Maske zu Olariaan Swiftburn im Böenbeerentiefland.", st = "Die Bewohner des Shen'darhochlands erzählen von einem uralten Waldgeist namens Kuramaa. Sie behaupten, er würde in einem knorrigen Baumstumpf auf einem Hügel nahe dem Ankerpylon des Hochlands leben.\n\nBegebt Euch ins Hochland und findet diesen Baumstumpf. Klopft mit Eurer Faust gegen die Rinde, und Kuramaa wird erscheinen. Besiegt den Geist im Kampf und bringt mir seine hölzerne Maske.\n\nDoch nehmt Euch in Acht, dieses Wesen kann dem Großteil Eurer Magie mit Leichtigkeit widerstehen. Nur Flammen können es bezwingen.", t = "Ruf des Feuers"},
    [97246] = {ot = "Besucht Borstans Feuergrube und sagt ihm, dass Ihr Migis Mittagessen im Auftrag von Thatog persönlich überbringt.", st = "Mein Sohn Migi treibt sich den ganzen Tag mit seinen Freunden herum. Ich sage ihm immer, er soll sich bei Borstan sein Mittagessen abholen. Ich weiß aber, dass er das fast nie tut, weil er ständig halb verhungert nach Hause kommt. Diese Kinder glauben, dass ihre Spiele wichtiger sind als ihre Körper!\n\nSchaut bitte bei Borstans Feuergrube vorbei und sagt ihm, dass Ihr da seid, um Migis Mittagessen abzuholen. Ihr findet ihn mit Sicherheit beim Rest seiner Freunde hinter der Feste Grommash.\n\nIch muss hier tagsüber meinen Pflichten nachgehen und kann nicht jede seiner Mahlzeiten überwachen.", t = "Mahlzeit oder Spielzeit"},
    [97249] = {ot = "Bringt Migi hinter der Feste Grommash sein Mittagessen.", st = "Da ich nun weiß, dass seine Eltern sich darüber Sorgen machen, wieviel er überhaupt isst, habe ich eine Idee.\n\nSie haben mir das Versprechen abgenommen, nicht jeden Tag das gleiche Essen einzupacken, damit Migi sich nicht zu einseitig ernährt. Aber immer, wenn der Räucherofen voll ist und wir honigglasierte Schweinebauchsandwiches zubereiten, taucht er zum Mittagessen auf. Wir haben damit begonnen, die übriggebliebenen knusprig glasierten Stücke als Topping aufzuheben, die wir dem Essen jeden Tag hinzufügen können.\n\nBringt ihm das hier. Vielleicht taucht er ja früher auf und bringt seine Freunde mit!", t = "Lieblingsessen"},
    [97250] = {ot = "Tötet Soldaten der Allianz, die an der Grenze zu den Marschen von Dustwallow ins Brachland vordringen, und kehrt anschließend zu Grunzer Logmar ins Camp Taurajo zurück.", st = "$uAbenteurer:Abenteurerin;, plant Ihr, in die Marschen von Dustwallow zu reisen? Mir ist zu Ohren gekommen, dass einige Menschensoldaten an der Grenze Stellung bezogen haben und die Wahrzeichen stürzen, die unsere Taurenpfadfinder hinterlassen haben.\n\nAngeblich soll eine beliebte Taverne abgebrannt sein, woraufhin sie, in typischer Allianzmanier, die Schuld direkt der Horde zugeschoben haben! Ich kann nicht sagen, ob an ihrer Behauptung irgendetwas wahr ist, doch ihr Einfall in UNSER Land darf so nicht stehen bleiben.\n\nErst töten, dann nachforschen!", t = "Falsch verurteilt, angemessen vergolten"},
    [97253] = {ot = "Sammelt $1oa Handvoll komplexer Teile vom oberen Piratenlager südlich von Ratchet und kehrt anschließend zurück zu Wrenix dem Jämmerlichen in Ratchet.", st = "Hey, habt Ihr einen Moment?\n\nAlso... Anscheinend hat es keiner von denen, die ich losgeschickt habe, um das Piratenproblem zu beseitigen, lebendig zurück geschafft. Nach fünf oder sechs Versuchen dachte ich mir: \"Was, wenn ich einfach eine Maschine schicke?\" Wie sich aber herausstellt, können Krummsäbel in der Not als Schraubendreher herhalten... Und bevor ich meine Maschine zurückschicken konnte, waren ihre Teile auch schon überall in ihrem Lager verteilt!\n\nIch brauche diese Teile zurück und da es sich dabei um eine schnelle kleine Bergungsmission handelt, sollten Eure Überlebenschance DEUTLICH höher als bei den anderen sein. Was sagt Ihr?", t = "Teile und Stücke"},
    [97257] = {ot = "Wartet, bis Olariaan mit dem Ritual bei der Kohlenpfanne der Opfergabe beginnt, und folgt seinen Anweisungen.\n\nIhr müsst die Ewige Flamme nach Valanaar bringen, bevor die Zeit abläuft.", st = "Nun werden wir das Ritual durchführen.\n\nIch platziere die Materialien auf dem Altar und rufe die Geister des Feuers an. Wenn sie das Opfer annehmen, werden sie erscheinen und die Ewige Flamme entfachen. Haltet dann Eure Fackel an die Flamme und fangt sie ein.\n\nTragt die brennende Fackel nach Valanaar und platziert sie in der Kohlenpfanne der Ewigen Flammen. Ihr müsst Euch beeilen, denn die Flammen der Feuerlande verlöschen hier im Himmelswall schnell.", t = "Ruf des Feuers"},
    [97275] = {ot = "Gebt Whuut Yelmaks Trank.", st = "Whuut ist ein Wunderkind. Das muss man ihm lassen. Aber er verfügt noch nicht über die nötige Erfahrung, Weisheit und Zeit am Rührstab, um zu wissen, wie man alchemistische Prozesse respektiert.\n\nEr verbraucht all unsere seltensten und exotischsten Reagenzien, ohne mal innezuhalten und seine Grundfertigkeiten zu üben und zu verbessern.\n\nGebt ihm diesen Trank, den ich mithilfe einer schnellen Braumethode zubereitet habe. Er wird alle seine Taten noch mal überdenken, wenn er lernt, dass lokale Heilmittel und ein behutsames Vorgehen der erste Schritt zur wahren Beherrschung sind.", t = "Whuut Ding will Weile haben"},
    [97277] = {ot = "Findet das Lager von Grund und Gozwin in den Hügeln im Nordwesten. Bergt Gozwins Mechanikerlogbuch und tötet den Schneeleopardenpirscher.", st = "Oi, ich hatte mich gerade abgewandt und das Wildschwein gegrillt, als ich meinen Kumpel Gozwin um sein Leben schreien hörte!\n\nBis ich mich umgedreht hatte, konnte ich nur noch einen verschwommenen Schemen und Reißzähne erkennen. So riesige Pranken! Ein Schneeleopard schleppte seine Gnomenbeute davon. Ich hab meine Schrotflinte geschnappt und über das Biest geschossen. Es hat ihn losgelassen und ist davongejagt.\n\nZum Glück hat es dem alten Goz nicht mehr als ein paar Kratzer verpasst.\n\nGeht zum Lager in den nordwestlichen Hügeln und holt Gozwins Mechanikerlogbuch zurück. Erledigt auch diesen Schneeleoparden, wenn Ihr ihn seht!", t = "Grund und Gozwin"},
    [97279] = {ot = "Sammelt $1oa zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück.", st = "Bei dem Zustrom von neuen Rekruten wie Euch haben wir Probleme, alle mit Waffen zu versorgen. Unserem Waffenschmied, Kzan, gehen die Übungswaffen aus und ich würde gern sehen, wie Ihr Euch anstellt, um mir ein Bild davon zu machen, womit ich arbeiten muss. Zu Eurem Glück habe ich eine Lösung für beide Probleme.\n\nBergt da draußen sechs zurückgelassene Übungswaffen, während Ihr Eber bekämpft und erste Erfahrungen sammelt. Unsere gescheiterten Rekruten haben sie auf dem Boden liegen lassen. Bringt sie dann zu Kzan, unserem Waffenschmied, im Höhlenbau hinter mir.", t = "Verlorene Waffen"},
    [97281] = {ot = "Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm.", st = "<Vor Euch liegt eine seltsame Kugel mit einer matten Oberfläche. Als Ihr sie aufhebt, scheint ein schwacher elektrischer Strom in ihrem Inneren zu vibrieren. Bei näherer Betrachtung erkennt Ihr, dass ein dunkler Nebel darin wabert. Hin und wieder ist ein kleiner elektrischer Funke zu sehen.\n\nEs ist offensichtlich, dass die Harpyie diesen Gegenstand für einen bestimmten Zweck verwendet hat. Vielleicht könnte Rezlak Interesse daran haben?>", t = "Ein Sturm braut sich zusammen"},
    [97282] = {ot = "Bringt $1oa geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.", st = "\"Rezlak, wenn sich eine Gelegenheit bietet, dann ergreif sie.\" Das ist eine der Weisheiten, die Gazlowe mir beigebracht hat. Und genau das habe ich vor.\n\nDie Kugel hier scheint nicht beschädigt zu sein. Sie wirkt nur, als hätte sie keine Energie mehr. Aber ich hab da eine Idee, wie ich sie wieder auf volle Pulle bringen kann!\n\nIn einer Schlucht westlich von hier gibt es jede Menge Donnerechsen. Ihre Organe speichern eine gewaltige elektrische Ladung – genau das, was ich brauche.\n\nBesorgt mir ein paar dieser Organe!", t = "Elektrisierende Aussichten"},
    [97287] = {ot = "Sprecht mit Erzmagierin Celindra in Dalaran.", st = "Es war klug von Euch, in die Stadt der Magier einzudringen. Doch ich denke, es ist an der Zeit, dass wir zu etwas... diplomatischeren Mitteln greifen.\n\nSo sehr es mich auch schmerzt, es gibt in ganz Azeroth keinen Ort mit größerem Wissen über arkane Magie. Selbst meine brillanten Forschungen verblassen neben der Weisheit, die die Kirin Tor über Jahrhunderte angesammelt haben. Ich finde, es wird höchste Zeit, dass auch wir Zugang zu diesem exklusiven Zirkel erhalten. Findet Ihr nicht auch?\n\nNehmt das Partikel, das Ihr beschafft habt, wieder an Euch. Um es zurückzubekommen, werden sie alles tun. Alles.", t = "Geschickte Verhandlungen"},
    [97288] = {ot = "Bringt den monströsen Kopf zu Apothekermeister Faranell in Undercity.", st = "<Als die Kreatur umfällt, kullert ihr Kopf zu Boden. Es wirkt, als wäre er schon des Öfteren wieder angebracht worden. Die Verbindung scheint mit jedem neuerlichen Anbringen schwächer zu werden.\n\nIrgendjemand in Undercity weiß bestimmt mehr über diese einzigartige Monstrosität.>", t = "Endlose Qual"},
    [97289] = {ot = "Bringt den Kopf des Barons zu Othmars Leiche in Undercity.", st = "Wir fertigen ständig Monstrositätenköpfe, aber dieser hier ist etwas Besonderes. Er gehörte einst einem Großmarschall der Allianz. Einem besonders unsympathischen. Othmar war, glaube ich, sein Name. Die Dunkle Fürstin hatte das Vergnügen, diesen selbst loszuwerden.\n\nOh, was er für Geheimnisse ausplaudern könnte, wenn er sprechen könnte. Kann er ja! Wenn wir ihn nur an einem passenden Körper anbringen.\n\nLos, legt ihn neben die Leiche im Nebenzimmer. Aber macht ihn nicht fest. Noch nicht.", t = "Endlose Qual"},
    [97290] = {ot = "Berichtet Apothekermeister Faranell in Undercity von Euren Erkenntnissen.", st = "Ihr... Monster...\n\nWarum sollte... ich Euch helfen...\n\nVerschwindet...", t = "Endlose Qual"},
    [97291] = {ot = "Holt eine giftige Schädelkappe von Tawny Grisette im Handwerksviertel, Blasenkraut in der Nähe des Kräuterkundelehrers und eine Essenz der Pein vom Giftverkäufer im Schurkenviertel für Meisterapotheker Faranell in Undercity.", st = "Nachdem der Kopf wieder angebracht ist, müssen wir ihn an den Willen der Dunklen Fürstin binden. Das sollte kein Problem sein. Nach den ganzen Prügeln, die es eingesteckt hat, hat dieses Biest kaum noch Hirn übrig.\n\nWir müssen es nur motivieren.\n\nBringt mir eine giftige Schädelkappe von Miss Grisette im Handwerksviertel. Oh, und etwas Blasenkraut von unseren hiesigen Kräuterkundelehrern, den Alliestars. Sie schulden mir was, also nehmt es Euch einfach. Und zuletzt ein wenig Essenz der Pein. Jeder beliebige Giftverkäufer sollte sowas haben.\n\nWir haben einen Trank zu brauen!", t = "Endlose Qual"},
    [97292] = {ot = "Spritzt das zischende Serum für Meisterapotheker Faranell in das System über Othmars Leiche.", st = "Ich habe ein köstliches Serum zusammengemischt, das unser neuer Gast sicherlich... stimulierend finden wird.\n\nNehmt das. Gießt es in die Leitungen über ihm. Mal sehen, ob wir ihn davon überzeugen können, dass Loyalität uns gegenüber zu seinem Besten wäre.\n\nUnd versucht, nichts zu verschütten. Ich kann mir keinen neuen Assistenten leisten.", t = "Endlose Qual"},
    [97326] = {ot = "Bringt $1oa glatte Felsen zu Thra hinter der Feste Grommash.", st = "Hey! Ihr habt Zeit und könntet uns weiterhelfen! Ich erkenne das an der Art, wie Ihr lächelt, während Ihr uns bei unserem Spiel zuschaut.\n\nDieser Ort hinter der Feste Grommash ist schön, weil wir hier genug Platz für unsere Figuren haben. Leider ist es echt blöd, dass wir nicht genug Felsen als Ersatz für Stühle oder Tische haben.\n\nIhr seid doch groß und stark... Könntet Ihr nicht ein paar mittelgroße Felsen für uns anschleppen, die glatt genug zum Sitzen sind, falls wir mal eine Pause brauchen?", t = "Felsen zum Faulenzen"},
    [97485] = {ot = "Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf.\n\nFügt die Gegenstände zusammen und streut das Räucherwerk von der Anhöhe der Jäger.", st = "Der Segen von An'she sei mit Euch.\n\nWir Tauren pflegen die Tradition, Räucherwerk mit den Winden zu verstreuen und ich hatte gehofft, dass Ihr diese Tradition mit uns ehren wollt.\n\nDas Räucherwerk müsst Ihr selbst herstellen, indem Ihr Kräuter von Nida, Zedernzweige von Nata, Sehnenschnur von Mahi auf der mittleren Anhöhe und zeremoniellen Feuerstein und Zunder von Naal auf der oberen Anhöhe erwerbt. Habt Ihr alles gesammelt, so fügt die Gegenstände zusammen und streut sie von der südlichen Klippe der Anhöhe der Jäger.\n\nEine Matte sowie Räucherwerk findet Ihr bei der Ritualstätte.", t = "Traditionen von Thunder Bluff"},
    [97538] = {ot = "Tah Winterhoof in Thunder Bluff möchte $1oa Mirkkrautsamenkapseln vom Mirkfallonsee.", st = "Seid gegrüßt. Dürfte ich Euch um einen Gefallen bitten? Mir sind gerade die roten Pigmente für meine Farben ausgegangen und ich suche jemanden mit jüngeren Hufen, der für mich die lange Reise ins Steinkrallengebirge antritt.\n\nIn der Mitte des Gebirgspasses dort liegt ein großer, kreisrunder See... der Mirkfallonsee. In seinem Wasser wächst eine einzigartige Pflanze, das Mirkkraut. Seine Samenkapseln nehmen beim Trocknen eine leuchtend rote Farbe an. Sammelt für mich die Samenkapseln dieser Pflanze, dann werde ich Euch für Eure Mühen reich entlohnen.", t = "Pigmente für Farben"},
    [97558] = {ot = "Bringt Shelene Rhobart $1oa Nachtsaugerflügelmembranen, $2oa Schattenhundbälge und $3oa Häute eines Murlocs der Finsterflossen.", st = "Ein Aspekt des Untodes, über den niemand spricht, ist die Frage, was geschieht, wenn wir verletzt werden. Wie heilt die Haut eines Untoten?\n\nDie Antwort lautet: gar nicht.\n\nUnser Dasein ist ein Fluch, $n. Um weiterexistieren zu können, müssen wir uns an den Lebenden bedienen.\n\nWerden wir verletzt, müssen wir die Haut ersetzen – meist durch Tierhäute. Da sich für unterschiedliche Körperpartien unterschiedlich dicke Häute eignen, benötigen wir eine möglichst große Auswahl.\n\nBringt mir Flügelmembranen von Nachtsaugern, Bälge von Schattenhunden und die Haut eines Murlocs der Finsterflossen!", t = "Häute, Bälge, Membranen"},
    [97891] = {ot = "Bringt den instabilen Trank zu Doktor Martin Felben im Apothekarium, bevor die Zeit abläuft.", st = "Ihr da! Schnell, Ihr müsst diesen Trank über den Schleimkanal zu Doktor Martin Felben im Apothekarium bringen!\n\nEr ist nur sehr sehr begrenzt haltbar und ich kann nicht selbst gehen... meine Knie klappern und springen raus, wenn ich versuche, zu rennen.\n\nAnscheinend ein weiterer wunderbarer Nebeneffekt des Untodes.\n\nAber wir vergeuden Zeit! Hier, nehmt das und zischt los!\n\n<Alessandro macht eine scheuchende Geste.>", t = "Zügige Tranklieferung"},
    [97899] = {ot = "Geht nach Orgrimmar und sprecht mit Whuut, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Aha, Ihr wollt Euch also als $gAlchimist:Alchimistin; in der Herstellung von Tränken und Gebräuen versuchen. Das wird Euch auf Euren Reisen bestimmt nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Manabrunnen für Euer Lager bauen könnt. Bald werden alle möglichen Heiler und Zauberwirker angerannt kommen, um sich an Eurem Brunnen zu erfrischen.", t = "Grundlagen des Zeltens: Alchimie"},
    [97900] = {ot = "Geht nach Klingenhügel und sprecht mit Dwukk, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also dazu entschieden, $gSchmied:Schmiedin; zu werden. Eine sehr gute Wahl, denn so bleiben Eure Klingen immer scharf.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Schleifstein für Euer Lager bauen könnt. Wenn Ihr den Schleifstein aufstellt, stehen bald alle Krieger und Schurken aus der Gegend bei Euch Schlange, um ihre Waffen zu schärfen.", t = "Grundlagen des Zeltens: Schmiedekunst"},
    [97901] = {ot = "Geht nach Orgrimmar und sprecht mit Jhag, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Verzauberer machen alles besser und sind in jedem Lager draußen in der Wildnis willkommen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt. Unterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [97902] = {ot = "Geht nach Klingenhügel und sprecht mit Mukdrak, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Als $gIngenieur:Ingenieurin; könnt Ihr allerlei Bauteile, Bots und Bomben basteln, egal, ob zum Vergnügen oder für den Profit.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Materialbot für Euer Lager bauen könnt. Dieser hilfreiche Automat stockt Eure Vorräte auf, sodass Euch und Euren Freunden nie die Materialien für Zauber ausgehen.", t = "Grundlagen des Zeltens: Ingenieurskunst"},
    [97903] = {ot = "Geht nach Klingenhügel und sprecht mit Rawrk, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ihr habt Euch also für Erste Hilfe entschieden? Als $C ist das eine ehrbare Wahl... und auch eine pragmatische.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Verbandtasche für Euer Lager herstellen könnt. Bei Abenteurern stehen Verletzungen an der Tagesordnung, und wenn Ihr in Eurem Lager Heilung anbietet, könntet Ihr damit sogar Leben retten.", t = "Grundlagen des Zeltens: Erste Hilfe"},
    [97904] = {ot = "Geht nach Sen'jin und sprecht mit Lau'Tiki, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ob Ihr es glaubt oder nicht, Eure Fähigkeiten als $gAngler:Anglerin; können für Euer Lager durchaus nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fischglas für Euer Lager herstellen könnt. Mit diesem Schmuckstück könnt Ihr Euch selbst und anderen Abenteurern ein wenig Freude bereiten. Denn fröhliche Abenteurer sind starke Abenteurer und ich bin mir sicher, dass sich das auch in Euren Kampffähigkeiten niederschlagen wird.", t = "Grundlagen des Zeltens: Angeln"},
    [97905] = {ot = "Geht nach Orgrimmar und sprecht mit Jandi, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [97906] = {ot = "Geht nach Orgrimmar und sprecht mit Karolek, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
    [97907] = {ot = "Geht nach Klingenhügel und sprecht mit Krunn, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.", t = "Grundlagen des Zeltens: Bergbau"},
    [97908] = {ot = "Geht nach Orgrimmar und sprecht mit Thuwd, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Kunst, erlegten Tieren Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.", t = "Grundlagen des Zeltens: Kürschnerei"},
    [97914] = {ot = "Bringt Thundris' Brief zu Baros Alexston in Stormwind.\n\nThundris hat ein Schiff in Auberdine erwähnt, das Euch dorthin bringen kann.", st = "Auberdine ist ein bescheidener Ort, $C. Ihr werdet seinen Namen nicht im Geäst von Darnassus hören. Die meisten erinnern sich nur an jene blühenden Städte, die die große Teilung uns genommen hat... Ameth'Aran, Bashal'Aran und... Lathar'Lazal.\n\nUnd doch bleibt Auberdine in ihrem Schatten.\n\nIch wünsche, dass unsere Arbeit hier Anerkennung findet. Ein neues Schiff verbindet uns mit dem Königreich Stormwind und bringt Leben und Vorräte an unsere Küsten. Ich bitte Euch, geht für die nächste Überfahrt an Bord und bringt diesen Brief zu einem Menschen namens Baros Alexston.\n\nVerbreitet die Kunde von unserer Heimat.", t = "Neue Horizonte"},
    [97915] = {ot = "Geht zum Wald von Elwynn in der Nähe von Stormwind und sprecht mit Alchimist Mallory, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Aha, Ihr wollt Euch also als $gAlchimist:Alchimistin; in der Herstellung von Tränken und Gebräuen versuchen. Das wird Euch auf Euren Reisen bestimmt nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Manabrunnen für Euer Lager bauen könnt. Bald werden alle möglichen Heiler und Zauberwirker angerannt kommen, um sich an Eurem Brunnen zu erfrischen.", t = "Grundlagen des Zeltens: Alchimie"},
    [97916] = {ot = "Geht nach Goldhain und sprecht mit Schmied Argus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also dazu entschieden, $gSchmied:Schmiedin; zu werden. Eine sehr gute Wahl, denn so bleiben Eure Klingen immer scharf.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Schleifstein für Euer Lager bauen könnt. Wenn Ihr den Schleifstein aufstellt, stehen bald alle Krieger und Schurken aus der Gegend bei Euch Schlange, um ihre Waffen zu schärfen.", t = "Grundlagen des Zeltens: Schmiedekunst"},
    [97917] = {ot = "Geht nach Stormwind und sprecht mit Betty Quin, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Verzauberer machen alles besser und sind in jedem Lager draußen in der Wildnis willkommen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt. Unterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [97918] = {ot = "Geht nach Stormwind und sprecht mit Sprite Jumpsprocket, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Als $gIngenieur:Ingenieurin; könnt Ihr allerlei Bauteile, Bots und Bomben basteln, egal, ob zum Vergnügen oder für den Profit.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Materialbot für Euer Lager bauen könnt. Dieser hilfreiche Automat stockt Eure Vorräte auf, sodass Euch und Euren Freunden nie die Materialien für Zauber ausgehen.", t = "Grundlagen des Zeltens: Ingenieurskunst"},
    [97919] = {ot = "Geht nach Goldhain und sprecht mit Michelle Belle, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ihr habt Euch also für Erste Hilfe entschieden? Als $C ist das eine ehrbare Wahl... und auch eine pragmatische.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Verbandtasche für Euer Lager herstellen könnt. Bei Abenteurern stehen Verletzungen an der Tagesordnung, und wenn Ihr in Eurem Lager Heilung anbietet, könntet Ihr damit sogar Leben retten.", t = "Grundlagen des Zeltens: Erste Hilfe"},
    [97920] = {ot = "Sprecht mit Lee Brown in der Nähe von Goldhain, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ob Ihr es glaubt oder nicht, Eure Fähigkeiten als $gAngler:Anglerin; können für Euer Lager durchaus nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fischglas für Euer Lager herstellen könnt. Mit diesem Schmuckstück könnt Ihr Euch selbst und anderen Abenteurern ein wenig Freude bereiten. Denn fröhliche Abenteurer sind starke Abenteurer und ich bin mir sicher, dass sich das auch in Euren Kampffähigkeiten niederschlagen wird.", t = "Grundlagen des Zeltens: Angeln"},
    [97921] = {ot = "Sprecht mit der Kräuterkundigen Pomeroy im Wald von Elwynn, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [97922] = {ot = "Geht nach Goldhain und sprecht mit Adele Fielder, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
    [97923] = {ot = "Sprecht mit Gelman Stonehand in Stormwind, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.", t = "Grundlagen des Zeltens: Bergbau"},
    [97924] = {ot = "Geht nach Goldhain und sprecht mit Helene Peltskinner, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Kunst, erlegten Tieren Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.", t = "Grundlagen des Zeltens: Kürschnerei"},
    [97925] = {ot = "Geht zum Holzfällerlager des Osttals im Wald von Elwynn und sprecht mit Eldrin, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [97927] = {ot = "Geht nach Thunder Bluff und sprecht mit Kray, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Aha, Ihr wollt Euch also als $gAlchimist:Alchimistin; in der Herstellung von Tränken und Gebräuen versuchen. Das wird Euch auf Euren Reisen bestimmt nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Manabrunnen für Euer Lager bauen könnt. Bald werden alle möglichen Heiler und Zauberwirker angerannt kommen, um sich an Eurem Brunnen zu erfrischen.", t = "Grundlagen des Zeltens: Alchimie"},
