    [97944] = {ot = "Sprecht mit Malorne Bladeleaf in Dolanaar, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [97946] = {ot = "Sprecht mit Nadyia Maneweaver auf der Straße von Dolanaar nach Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
    [97948] = {ot = "Sprecht mit Kurdram Stonehammer in Auberdine, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.", t = "Grundlagen des Zeltens: Bergbau"},
    [97949] = {ot = "Sprecht mit Radnaal Maneweaver auf der Straße von Dolanaar nach Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Kunst, erlegten Tieren Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.", t = "Grundlagen des Zeltens: Kürschnerei"},
    [97950] = {ot = "Sprecht mit Trianna in Darnassus, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [97951] = {ot = "Geht nach Brill und sprecht mit Carolai Anise, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Aha, Ihr wollt Euch also als $gAlchimist:Alchimistin; in der Herstellung von Tränken und Gebräuen versuchen. Das wird Euch auf Euren Reisen bestimmt nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Manabrunnen für Euer Lager bauen könnt. Bald werden alle möglichen Heiler und Zauberwirker angerannt kommen, um sich an Eurem Brunnen zu erfrischen.", t = "Grundlagen des Zeltens: Alchimie"},
    [97952] = {ot = "Geht nach Undercity und sprecht mit Basil Frye, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also dazu entschieden, $gSchmied:Schmiedin; zu werden. Eine sehr gute Wahl, denn so bleiben Eure Klingen immer scharf.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Schleifstein für Euer Lager bauen könnt. Wenn Ihr den Schleifstein aufstellt, stehen bald alle Krieger und Schurken aus der Gegend bei Euch Schlange, um ihre Waffen zu schärfen.", t = "Grundlagen des Zeltens: Schmiedekunst"},
    [97953] = {ot = "Geht nach Brill und sprecht mit Vance Undergloom, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Verzauberer machen alles besser und sind in jedem Lager draußen in der Wildnis willkommen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt. Unterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [97954] = {ot = "Geht nach Undercity und sprecht mit Graham Van Talen, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Als $gIngenieur:Ingenieurin; könnt Ihr allerlei Bauteile, Bots und Bomben basteln, egal, ob zum Vergnügen oder für den Profit.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Materialbot für Euer Lager bauen könnt. Dieser hilfreiche Automat stockt Eure Vorräte auf, sodass Euch und Euren Freunden nie die Materialien für Zauber ausgehen.", t = "Grundlagen des Zeltens: Ingenieurskunst"},
    [97955] = {ot = "Geht nach Brill und sprecht mit Schwester Neela, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ihr habt Euch also für Erste Hilfe entschieden? Als $C ist das eine ehrbare Wahl... und auch eine pragmatische.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Verbandtasche für Euer Lager herstellen könnt. Bei Abenteurern stehen Verletzungen an der Tagesordnung, und wenn Ihr in Eurem Lager Heilung anbietet, könntet Ihr damit sogar Leben retten.", t = "Grundlagen des Zeltens: Erste Hilfe"},
    [97956] = {ot = "Geht nach Brill und sprecht mit Clyde Kellen, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ob Ihr es glaubt oder nicht, Eure Fähigkeiten als $gAngler:Anglerin; können für Euer Lager durchaus nützlich sein.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fischglas für Euer Lager herstellen könnt. Mit diesem Schmuckstück könnt Ihr Euch selbst und anderen Abenteurern ein wenig Freude bereiten. Denn fröhliche Abenteurer sind starke Abenteurer und ich bin mir sicher, dass sich das auch in Euren Kampffähigkeiten niederschlagen wird.", t = "Grundlagen des Zeltens: Angeln"},
    [97957] = {ot = "Geht nach Brill und sprecht mit Faruza, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [97958] = {ot = "Sprecht mit Shelene Rhobart auf der Straße von Brill nach Undercity, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $C. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
