    [97968] = {ot = "Geht nach Valanaar und sprecht mit Syriel Nightrain, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Sieht aus, als hättet Ihr Euch etwas Wissen in Kräuterkunde angeeignet. Blumen pflücken ist nicht bloß ein Zeitvertreib, es kann auch sehr nützlich sein... und profitabel.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine Räucherkerze für Euer Lager herstellen könnt. Gute Laune ist wichtig, um Heiler und Zauberwirker bei der Stange zu halten, und eine Räucherkerze kann allen, die Magie einsetzen, einen Schub geben.", t = "Grundlagen des Zeltens: Kräuterkunde"},
    [97969] = {ot = "Geht nach Shen'dar und sprecht mit Indari Sunseam, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ah, Ihr habt Euch also für Lederverarbeitung entschieden. Schön für Euch, $c. Ich glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Zelt anfertigt, das Euch an heißen Tagen Abkühlung verschafft und an Regentagen trocken hält.\n\nMit einem soliden Zelt über dem Kopf wird es Euch leichtfallen, alles andere zu bekommen, was Ihr braucht, um auf Euren Reisen immer auf Zack zu bleiben.", t = "Grundlagen des Zeltens: Lederverarbeitung"},
    [97970] = {ot = "Geht nach Shen'dar und sprecht mit Messana Crestwind, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann. wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager, werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.", t = "Grundlagen des Zeltens: Bergbau"},
    [97971] = {ot = "Geht nach Shen'dar und sprecht mit Mendalass Tattermend, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Kunst, erlegten Bestien Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben, und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.", t = "Grundlagen des Zeltens: Kürschnerei"},
    [97972] = {ot = "Geht nach Shen'dar und sprecht mit Taleen Shimmerthread, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [97973] = {ot = "Geht nach Shen'dar und sprecht mit Taleen Shimmerthread, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Die Schneiderei ist eine überraschend effektive Handwerkskunst, und ich bin sicher, sie wird Euch einigen Nutzen bringen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr ein Fraktionsbanner für Euer Lager anfertigt, sofern Ihr die Fertigkeit dazu habt. Motivation und Kampfmoral sind enorm wichtig für den Erfolg auf dem Schlachtfeld, und ein inspirierendes Banner sorgt dafür, dass Ihr mit vollem Einsatz bei der Sache bleibt.", t = "Grundlagen des Zeltens: Schneiderei"},
    [97977] = {ot = "Sammelt $1oa Totems der Knarzklauen und bringt sie zu Tarindrella.", st = "Die Knarzklauenfurbolgs würden sich nicht einfach so gegen ihre alten Verbündeten wenden. Wir müssen mehr über ihre Notlage herausfinden.\n\nSucht in ihren verlassenen Heimstätten nach Totems. Wenn welche das Chaos ihres Aufbruchs überstanden haben, könnten ihre Gravuren uns vielleicht Aufschluss darüber geben, was hier passiert ist.\n\nIhr findet ihre Lager entlang des westlichen Talrands, aber die Grell und Grellkin haben sie vielleicht darüber hinaus verstreut.", t = "Ruf der Natur"},
    [97979] = {ot = "Wirkt Elunes Licht und Schattenhaftigkeit.", st = "Ihr seid $gein:eine; Kaldorei - ein Kind der Sterne - und Ihr habt ein Geburtsrecht geerbt, wie es in dieser Welt kein zweites gibt. Elunes Gnade erhellt unsere Stärken, lenkt unsere Klingen in die Herzen unserer Feinde und verbirgt uns wie der Mond das Antlitz der Sonne.\n\nUnsere lange Wacht findet nach der Verteidigung des Hyjal ein Ende und wir haben uns einer Allianz mit anderen angeschlossen... die Ihr zu gegebener Zeit kennenlernen werdet. Vorerst ruht Ihr im Geäst Teldrassils.\n\nZeigt die Gaben von Mutter Mond und erfreut Euch an ihrem Segen.", t = "Das Geschenk der Göttin"},
    [98013] = {ot = "Tötet für Arbal im Hain der Uralten $1oa Myrmidonen der Sturmschuppen, $2oa Zauberinnen der Sturmschuppen und $3oa Krieger der Sturmschuppen.", st = "Wappnet Euch für Euren Weg in die Ruinen, $gjunger Freund:junge Freundin;. Dort wird Euch niemand freies Geleit gewähren.\n\nZahlreiche verfluchte Hochgeborene, heute als Naga bekannt, durchstreifen die einst prachtvolle Stadt. Reist nach Nordosten und vertreibt sie aus diesem Land.\n\nVon dem, was sie einst waren, ist nichts mehr geblieben. Sollten sie dem Twilight-Hammer dienen, werden sie den Wäldern, die ihnen einst Zuflucht boten, nur weiteres Leid bringen.\n\nNach Krieg steht ihnen der Sinn, $C. Dann sollen sie Krieg bekommen.", t = "Wachsende Streitmacht"},
    [98021] = {ot = "Meldet Euch bei Gryan Starkmantel auf der Späherkuppe in Westfall.", st = "Wollt Ihr damit anfangen, Gutes in unserer Welt zu tun? Dann solltet Ihr Euch bei einem Mann namens Gryan Stoutmantle melden. Ihr findet ihn südlich von hier, in Westfall, in einer Siedlung mit dem Namen Späherkuppe. Sein Volk braucht Hilfe.\n\nNachdem Ihr aus einer anderen Existenzebene hierher gereist seid, erscheinen die Probleme, die unsere Lande plagen, vielleicht unbedeutend. Doch seid gewiss, Eure Hilfe bedeutet sehr viel für die Leute, die von diesen Problemen betroffen sind, und Ihr selbst werdet an Euren Aufgaben wachsen.\n\nViel Glück, $gAbenteurer:Abenteurerin;!", t = "Reise zur Späherkuppe"},
    [98024] = {ot = "Meldet Euch bei Thork in Crossroads im Brachland.", st = "Nachdem Ihr aus der Elementarebene hierher gereist seid, mögen die Probleme, die unsere Lande plagen, vielleicht unbedeutend erscheinen. Doch seid versichert, die Gefahren, denen sich die Horde stellen muss, sind mehr als real, und wenn Ihr Euren Dienst überlebt, werdet Ihr umso eindrucksvoller daraus hervorgehen.\n\nWollt ihr damit anfangen, Gutes in unserer Welt zu tun? Dann reist nach Südwesten, in die weiten Ebenen, die als das Brachland bekannt sind. Dort findet Ihr eine Siedlung, die \"Crossroads\" genannt wird. Die stolzen Einwohner dieser Siedlung können jede Hilfe gebrauchen.\n\nGeht mit Ehre, $gAbenteurer:Abenteurerin;!", t = "Reise nach Crossroads"},
    [98025] = {ot = "Findet und tötet Jai'vhanel. Die schwarze Eule wurde zuletzt nördlich der Ruinen von Ameth'Aran, am Fuß der Berge, gesichtet. Bringt zum Beweis ihres Todes eine ihrer Federn zu Schildwache Glynda Nal'Shea in Auberdine.", st = "Achtung!\n\nEine Belohnung wird ausgesetzt für den Tod der Eule Jai'vhanel, auch bekannt als \"die Schwertfeder\".\n\nBedauerlicherweise ist die Eule dem Wahnsinn verfallen und greift Reisende auf der Straße nahe Auberdine an.\n\nZuletzt wurde Jai'vhanel nördlich der Ruinen von Ameth'Aran, am Fuß der Berge, gesichtet. Bringt zum Beweis ihres Todes eine ihrer pechschwarzen Federn zurück.\n\nDie Belohnung kann bei Schildwache Glynda Nal'Shea in Auberdine abgeholt werden.\n\nGezeichnet: Der Dorfrat von Auberdine", t = "GEUSCHT: Jai'vhanel"},
    [98027] = {ot = "Bringt die Mondsichelhalskette zu Maliynn in Astranaar.", st = "<Die silberne Halskette schimmert sanft in Euren Händen. Der kleine Halbmond ähnelt den Symbolen, die Ihr bereits bei den Nachtelfen gesehen habt.\n\nAls Ihr die Halskette umdreht, entdeckt Ihr eine kleine Inschrift: \"Alor'lormah, Maliynn\". Vielleicht gehört sie Maliynn in Astranaar?>", t = "Leuchtende Mondsichelhalskette"},
    [98042] = {ot = "Erbeutet ein unvergleichliches Auge von einem Jünger oder Schläger des Twilight-Hammers an der Meistergleve in Dunkelküste und findet in Auberdine jemanden, der bereit ist, es an sich zu nehmen.", st = "<Als Ihr die einzelne Seite aus dem Twilight-Folianten reißt, erfüllt eine unheilvolle Stimme ungebeten Eure Gedanken.>\n\nSie sind gescheitert.\n\nIhr werdet der Vergessenheit anheimfallen.\n\nDas gewonnene Auge wird verloren gehen.", t = "Ein Blick in den Abgrund"},
    [98046] = {ot = "Bringt das ausgelaugte Gefäß zu Lariia im Tempel des Mondes in Darnassus.", st = "<Erzdruide Fandral Staghelms Augen werden schmal.>\n\nIhr seid noch hier?\n\nNehmt die Phiole und geht mir aus den Augen, $C. Es ist offensichtlich, dass meine Antworten nicht in den Wassern zu finden sind, so wie zuvor.\n\nVielleicht kann eine der Priesterinnen im Tempel des Mondes im Süden sich darum kümmern.\n\n<Fandral wendet sich ab und schenkt Euch keine Beachtung mehr.>\n\nIch muss woanders suchen, wenn das funktionieren soll...", t = "Krone der Erde"},
    [98065] = {ot = "Bringt die Mondbrunnenüberreste zu Tyrande Whisperwind im Tempel des Mondes in Darnassus.", st = "Ihr müsst das sofort zu Tyrande bringen! Ich werde es für Euch in ein etwas angemesseneres Gefäß umfüllen.\n\nSeid unbesorgt. Die Hohepriesterin von Elune ist entschlossen, aber freundlich. Sie beschützt alle, die nach Darnassus kommen, und bringt allen das Licht unserer Göttin.\n\nSie wird dieses heilige Wasser dankbar entgegennehmen. Ihr findet sie direkt über uns.", t = "Krone der Erde"},
    [98067] = {ot = "Stellt für Schildwache Dalia Sunblade im Tempel des Mondes von Darnassus Wächtereulen am Eingang zu den Tiefen der Burg Cenarius, der Bank von Darnassus, dem Gasthaus auf der Terrasse der Handwerker und am Stadttor auf.", st = "General Feathermoon achtet darauf, dass alle Wächter Zeit finden, zu Elune zu beten. Eine wahre Jägerin führt nicht allein die Klinge, sondern verlässt sich ebenso auf die Gaben der Göttin, um ihre Feinde zu besiegen.\n\nIhr könnt mich bei meinen täglichen Pflichten unterstützen. Platziert Wächtereulen in der Stadt: zunächst an den Tunneln, die im Norden in die Tiefen der Burg Cenarius führen, dann bei der Bank im Stadtzentrum, am Gasthaus auf der Terrasse der Handwerker im Nordosten und schließlich am Stadttor. Die Wachen werden Euch dabei behilflich sein.\n\nEtwas geht in Teldrassil vor sich... Wir müssen wachsam bleiben.", t = "Die Augen der Schildwache"},
    [98069] = {ot = "Bringt 8 gestohlene Vorräte vom Freiwindposten zu Jandia im Freiwindposten.", st = "Diese elenden Harpyien! Sie haben die letzte Karawane angegriffen, die ich angeheuert hatte, um Vorräte zum Freiwindposten zu bringen. Für den Augenblick haben wir genug Vorräte, aber sie werden bald ausgehen.\n\nIch bin mir nicht sicher, was die Harpyien mit den zusätzlichen Vorräten anstellen wollen, aber ich wäre Euch dankbar, wenn Ihr sie für mich zurückholen würdet. Sie haben sich westlich von hier eingenistet. Ihr findet sie sowohl am Fuße der Klippen als auch in einer Höhle oben am Rand.", t = "Gestohlene Vorräte vom Freiwindposten"},
    [98070] = {ot = "Tötet $1oa kreischende Harpyien, $2oa kreischende Wildfedern und $3oa kreischende Windruferinnen.", st = "Im Kreischenden Canyon lebt eine Gruppe einheimischer Harpyien, die für ihre Wildheit und ihre taktischen Überfälle bekannt sind. Sie haben die letzten paar Versorgungskarawanen überfallen, die mutig genug waren, hier durchzureisen.\n\nIch befürchte, wenn nicht bald jemand etwas unternimmt, werden es keine Karawanen mehr wagen, die Reise zum Freiwindposten anzutreten.\n\nGeht und erschlagt so viele dieser Harpyien, wie Ihr könnt. Kehrt zu mir zurück, wenn Ihr fertig seid, und ich werde Euch für Eure Mühe gut entlohnen.", t = "Ausgekreischt"},
    [98093] = {ot = "Sulhasa im südlichen Brachland möchte, dass Ihr $1oa Sturmechsen und $2oa Fleischreißerpirscher in der Gegend beseitigt, damit sie sicher von dem Baum herunterkommen kann.", st = "Ich bin so froh, dass Ihr mich gesehen habt!\n\nDas Wetter war heute Morgen so schön, also bin ich von Camp Taurajo die Goldene Straße entlangspaziert. Als ich umkehren wollte, konnte ich nicht. Ein Rudel Hyänen kreiste mich ein und Sturmechsen versperrten meinen einzigen Fluchtweg.\n\nDa bin ich auf diesen Baum geklettert und zu dieser Stunde treiben sich hier zu viele Feinde herum, als dass ich übers offene Feld nach Hause laufen könnte.\n\nWürdet Ihr diese Sturmechsen und Fleischreißerpirscher für mich erledigen?", t = "Das Feld säubern"},
    [98094] = {ot = "Hochexekutorin Darthalia möchte, dass Ihr Todespirscher Masoj südlich von Tarrens Mühle außerhalb von Dun Garok aktualisierte Befehle überbringt.", st = "Nun, da wir Euch die Lieferung kritischer Informationen an unsere Spione vor Ort anvertrauen können, habe ich noch eine Aufgabe für Euch.\n\nBringt das hier zu Todespirscher Masoj fast direkt südlich von uns. Er wird mehr für Euch haben, sobald Ihr ihm das hier überbracht habt. Er ist auf erhöhtem Gelände nördlich des fauligen Weinguts stationiert, das Nethander-Siedlung genannt wird.\n\nUnser Plan, die Kontrolle über diese Lande zu übernehmen, nimmt immer weiter Gestalt an.", t = "Späherunterstützung"},
    [98095] = {ot = "Todespirscher Masoj möchte, dass Ihr drei Phiolen des Apothekariums auf Gipfeln rund um das Vorgebirge von Hillsbrad platziert und dann zu ihm zurückkehrt.", st = "Unser Oberkommando schleust strategische Truppen mithilfe von Fledermausreitern ein. Schlüsselpunkte rund um das Vorgebirge haben ihre Signalfeuer verloren.\n\nNehmt diese Phiolen. Entkorkt sie an drei Orten: den Hügeln, die an Dun Garok angrenzen, dem Plateau mit Blick auf die Festung Durnholde und am Grat der Landzunge über der Stadt Hillsbrad. Die Dämpfe, die dabei austreten, werden auf die Sinne der Fledermaus wie ein Stimmstab wirken und sie erneut zu den gewünschten Übergabepunkten locken.\n\nHaltet nach zerbrochenen leeren Phiolen Ausschau und frischt unsere Markierungen auf.", t = "Nützliche Vorteile"},
    [98189] = {ot = "Bringt die Menethil-Statuette zu Hauptmann Stoutfist in der Burg Menethil.", st = "Meine Güte, sie ist... sie ist wunderschön!\n\nDie Blind Princess sollte sie zum Hafen von Menethil bringen, bevor das Unheil seinen Lauf nahm! Wir waren so nah dran.\n\nIch glaube, sie sollte von Hauptmann Stoutfist in der Burg Menethil direkt hinter uns gegengezeichnet werden. Warum bringt Ihr diese ehrenvolle Aufgabe nicht zu Ende?", t = "Die Statue zurückbringen"},
    [98190] = {ot = "Bringt Hochlord Bolvar Fordragon in Burg Stormwind die Menethi-Statuette.", st = "Ihr solltet das hier umgehend nach Stormwind bringen. Ich bin zwar stolz darauf, dass diese Burg und ihr Hafen den Namen von König Terenas Menethil II tragen, aber wir sind ein ruhiger Hafen in einem sehr unangenehmen Sturm an Feinden. Es ist hier nicht sicher.\n\nGanz besonders die Dragonmaw würden viel dafür geben, so etwas zu erbeuten... und mich graust es bei der Vorstellung, was sie damit anstellen würden.\n\nMacht Euch in dieser Angelegenheit nicht die Mühe, auf die Hierarchie Rücksicht zu nehmen. Wendet Euch damit direkt an Hochlord Fordragon. Er weiß, wo man sie am besten aufbewahrt.", t = "Ein Freund der Familie"},
    [98191] = {ot = "Bringt Lord Grayson Shadowbreaker in der Kathedrale des Lichts die Menethil-Statuette.", st = "König Terenas war ein guter Mann. Ein frommer Mann. Von seinem Volk geliebt und der wahre Grund, warum es diese Allianz überhaupt gibt.\n\nDie Ironie ist, dass er auch bescheiden war: Er hasste diese Art von Ehrenmal, und deshalb existieren nur so wenige davon. Und von diesen haben noch weniger Lordaerons Untergang überlebt.\n\nWie es scheint, hat sich das Licht in dieser Statuette gesammelt. Sie sollte am besten in der Kathedrale des Lichts auf dem Kathedralenplatz im Zentrum der Stadt aufbewahrt werden. Bringt sie zur sicheren Verwahrung zu Lord Grayson Shadowbreaker.", t = "Ein Freund der Familie"},
    [98197] = {ot = "Bergt für Valstag Ironjaw $1oa Holz aus Khaz Modan und $2oa Eisen aus Khaz Modan aus dem Hafen von Menethil.", st = "Dieser Hafen wurde ursprünglich von der alten Horde als Ausgangspunkt für ihre Invasion auf Hillsbrad gebaut. Dadurch haben sie Lordaerons Verteidigungen komplett umgangen!\n\nSo viele haben ihr Leben gelassen...\n\nWas das Ganze noch schlimmer macht, ist die Tatsache, dass diese Flotte mit den Ressourcen erbaut wurde, die sie aus Khaz Modan gestohlen hatten!\n\nIm Hafen befinden sich noch viele Überreste, nachdem Admiral Proudmoore die Unholde vertrieben und diesen Ort für die Allianz erbaut hat. Wir brauchen sie, um die Verteidigungen der Stadt gegen die Bedrohung durch die Dragonmaw zu stärken.", t = "Kriegsbeute"},
    [98219] = {ot = "Sprecht mit Lieutenant Farren Orinelle in Southshore im Vorgebirge von Hillsbrad.", st = "Danke noch mal, dass Ihr die Statuette sicher überbracht habt, $n.\n\nIch könnte bei etwas anderem Eure Hilfe gebrauchen. Es gibt da ein Mitglied der Stadtwache, das nach Southshore in Vorgebirge von Hillsbrad versetzt wurde.\n\nSein Vater war ein Freund von mir, und ich streite zwar nicht ab, dass er die Lektion gebrauchen kann... Aber ich möchte trotzdem, dass er im Leben weiterkommt. Er würde sicher von jemandem wie Euch profitieren, der ihm unter die Arme greifen kann.\n\nEs gibt da ein Boot, das Euch vom Hafen von Menethil aus dorthin bringen kann, falls Ihr wieder dort vorbeikommt.", t = "Der beschämte Lieutenant"},
    [98245] = {ot = "Sammelt $1oa Scharfzahnschneidezähne für Howin Kindfeather.", st = "Ich weiß ja nicht, wen ich mehr hasse: die verdammten Dunkeleisenzwerge, die Dragonmaw oder die Drachen, die sie geritten haben.\n\n<Howin spuckt aus.>\n\nIch will die Dinge in Ordnung bringen. Aber dafür brauchen wir Vorräte.\n\nDiese Welpenschuppen werden uns gegen Drachenfeuer schützen, aber sie sind echt schwer zusammenzuweben.\n\nDie Scharfzahnraptoren am Raptorgrat im Nordosten und der Salzgischtschlucht im Nordwesten sind nach ihren spitzen Beißerchen benannt. Die sollten ohne Probleme durch die Schuppen kommen.\n\nBringt mir eine Handvoll ihrer Schneidezähne.", t = "Scharfzahnschneiderei"},
    [98246] = {ot = "Sammelt $1oa perfekte Scharfzahneier für Howin Kindfeather.", st = "Ich brauche Eier, damit mein Plan funktioniert. Bassbeak muss sich erst mal den Bauch vollschlagen. Es ist nicht meine Art, mich auf den Rücken eines schlecht gelaunten Greifen zu setzen.\n\nSie müssen perfekt sein, ohne Risse oder so.\n\nHolt Euch welche von den Scharfzahnraptoren, deren Dotter sind so groß wie die Birne eines Gnoms. Ihr findet sie am Raptorgrat im Nordosten und der Salzgischtschlucht im Nordwesten.\n\nBesorgt mir ein rundes Dutzend, damit sollten wir auf der sicheren Seite sein.", t = "Harte Zeiten"},
    [98251] = {ot = "Tötet $1oa Schattenhornhirsch und $2oa Ashenvalebär und kehrt zu Va'xug Firefure nordwestlich des Fallenskysees zurück.", st = "Graaah!\n\nIch bin so wütend! Sie sagen, Ashenvale wäre leicht zu durchqueren! Für wen? Die Biester? Die Vögel?\n\nIm einen Moment pflücke ich ein Kraut, im nächsten bin ich schon in dieser Kluft gefangen. Muss ich wirklich den halben Wald umrunden, um dort wieder herauszukommen, wo ich vor nur wenigen Augenblicken stand?\n\nWenn ich diese Laune habe, werden meine Zauber unberechenbar und benehmen sich... anders.\n\nKönntet Ihr die Wildtiere der näheren Umgebung etwas ausdünnen? Selbst ihre dämlichen Hufe gehen mir auf die Nerven. Ich verabscheue diesen verfluchten Wald.", t = "Keine Rückkehr"},
    [98252] = {ot = "Zeigt Vax'ugs Auge von Kilrogg den Weg zurück zur Hauptstraße nach Ashenvale.", st = "Zeigt meinem Auge von Kilrogg den Weg aus dieser Kluft und zurück zur Straße nach Ashenvale. Bleibt in Bewegung und ich folge nach, sobald ich einen klaren Pfad erkenne.\n\nIch bleibe hier. Einer von uns sollte auf unsere Habseligkeiten aufpassen. Wenn Ihr Euch verirrt, kann ich Euch mithilfe des Auges zurückführen. Ich lasse nicht zu, dass wir beide blind in diesem feindseligen Wald umherirren.\n\nIch kann den Kanal für vier Minuten aufrechterhalten. Nicht länger. Erreicht die Straße, bevor die Vision abbricht, oder kehrt zu mir zurück für einen erneuten Versuch.", t = "Ein Leerenpfad"},
    [98282] = {ot = "Sammelt für Caitlin Grassman im Hafen von Menethil eine intakte Pirscherdrüse im Thelgenfelsen.", st = "Bestimmte alchimistische Rezepte benötigen Zutaten von, nun ja, sehr gefährlichen Orten. Und dabei handelt es sich oftmals nur um grundlegende Kräuter! Die anderen Zutaten sind noch schlimmer zu beschaffen!\n\nIch muss noch mehr Gegengift herstellen, bevor ich hier wieder wegkann. Ich schwöre, alles in diesem Sumpf ist giftig. Als wenn das Gift die Gegend selbst durchsetzen würde!\n\nKönnt Ihr mir helfen? Ich brauche eine Giftdrüse von den Spinnen im Thelgenfelsen südöstlich von hier. Sie muss aber intakt sein, sonst verliert sie zu viel Gift, bevor Ihr hier ankommt. Tut mir leid!", t = "Alchimistische Gefahren"},
    [98284] = {ot = "Geht nach Shen'dar und sprecht mit Nasalanna Windsinger, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Verzauberer machen alles besser und sind in jedem Lager draußen in der Wildnis willkommen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt. Unterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [98285] = {ot = "Sprecht mit dem seltsamen Einsiedler im Schattenwindwald, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Ingenieure sind besonders erfinderische Leute, und wenn man allein in der Wildnis ist, ist es immer gut, seine Fähigkeiten einsetzen zu können. Kein gutes Lager kommt ohne ein paar nützliche Konstruktionen aus!\n\nJa, kommt wieder vorbei, wenn Ihr ein bisschen Ingenieurserfahrung gesammelt habt, dann zeige ich Euch, wie man etwas ganz Besonderes baut!", t = "Grundlagen des Zeltens: Ingenieurskunst"},
    [98286] = {ot = "Geht nach Shen'dar und sprecht mit Nasalanna Windsinger, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", st = "Verzauberer machen alles besser und sind in jedem Lager draußen in der Wildnis willkommen.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr eine verzauberte Laute für Euer Lager herstellen könnt. Unterhaltung in der Freizeit ist immer wichtig, und dieses bisschen Magie kann Euch dabei helfen, Euch auf die verschiedensten Herausforderungen vorzubereiten, wenn Ihr Euch wieder auf den Weg macht, so staubig er auch sein möge.", t = "Grundlagen des Zeltens: Verzauberkunst"},
    [98299] = {ot = "Tötet $1oa kränkliche Flüchtlinge und $2oa hagere Flüchtlinge für Dalar Dawnweaver am Grabmal.", st = "Wenn wir eine Sache mit Gewissheit sagen können, dann ist es, dass Arugal für die Worgen im Silberwald die Verantwortung trägt... sei es aufgrund seiner eigenen Machenschaften oder nicht. Aber wir wissen nicht, wie es sich ausbreitet.\n\nWährend ich nach einem Weg suche, den Fluch zu bannen, ist es unsere oberste Priorität, ihn einzudämmen. Verlassene scheinen immun, doch eine große Gruppe Menschen haben sich am Greymane-Wall versammelt.\n\nGeht dorthin und tötet diese Geflohenen, ehe sie ebenfalls zu Arugals Dienern werden können. Und versucht, nicht gebissen zu werden, $R.", t = "Die Ausbreitung eindämmen"},
    [98319] = {ot = "Findet Gebirgsjäger Cornelius im Graufelsbau für Gebirgsjägerin Gretchen.", st = "Als ob die Trollprobleme nicht schon reichen würden, wimmelt es in den Bergen inzwischen nur so von Wendigos! Normalerweise bleiben sie in ihren Höhlen, aber inzwischen vermehren sie sich wie die Karnickel. Jetzt haben sie sich auch noch im Graufelsbau nördlich von hier eingenistet.\n\nWenn Whitebeard seinen Bericht fertigkriegen will, müssen wir zuerst meinen Partner Cornelius finden. Der Hohlkopf hat sich mal wieder zu früh in den Kampf gestürzt. Mutig, aber dumm.\n\nGeht in die Höhle und seht nach, wo er steckt. Und wenn Ihr schon dort seid, könnt Ihr auch gleich ein paar der Viecher erledigen.", t = "Sichert den Pass"},
    [98321] = {ot = "Sammelt Flintfires Lieferungen ($1oa Stück) im Graufelsbau für Tongus Flintfire in Kharanos.", st = "Hoho! $uEin:Eine:r; $R, $uder:die:r; sich nicht scheut, sich die Hände schmutzig zu machen!\n\nFalls Ihr Arbeit sucht: Im Moment fehlt's mir leider an Nachschub. Unsere zuverlässigste Erzquelle wurde von Wendigos überrannt, und die Höhle mussten wir aufgeben. Die Bergleute mussten Hals über Kopf fliehen und alles zurücklassen!\n\nWie wär's, wenn Ihr Euch im Graufelsbau westlich von hier mal umseht? Vielleicht findet Ihr ein paar unserer verlorenen Lieferungen. Das würde uns eine Menge Ärger ersparen.", t = "Flintfires Lieferung"},
    [98322] = {ot = "Seht westlich von Kharanos nach Gebirgsjägerin Gretchen.", st = "In dunklen Höhlen herumzukraxeln ist was für Abenteurer. Ich schreib bloß die Berichte und schick sie nach Ironforge.\n\nJetzt ist es nur so, dass einer meiner Trupps vermisst wird, also nix mit Bericht! Ich hatte Gebirgsjäger losgeschickt, damit sie sich mal um das Wendigo-Problem da draußen kümmern, aber habe seitdem nichts von ihnen gehört.\n\nWenn Ihr sowieso unterwegs seid, schaut doch mal westlich von Kharanos nach Gebirgsjägerin Gretchen. Ich häng mit meinem Bericht hinterher!", t = "Sichert den Pass"},
    [98323] = {ot = "Bringt Gebirgsjägerin Gretchens Bericht zu Senir Whitebeard in Kharanos.", st = "Ich hoff, Ihr habt da drin wenigstens ein paar von den Biestern zur Strecke gebracht. Schade um Cornelius.\n\nNach allem, was Ihr erzählt habt, bleibt wohl nur festzuhalten, dass die Höhle verloren ist. Whitebeard wird das gar nicht gern hören, aber ich schick bestimmt niemanden mehr in diese Todesfalle.\n\nRichtet ihm das ruhig aus, $n. Ich rühr mich hier nicht vom Fleck, bis der Pass wieder sicher ist.", t = "Sichert den Pass"},
    [98326] = {ot = "Erschlagt Eisheuler und bringt Gretta Ganter in Brewnall den Sack mit Fischen.", st = "Habt Ihr eine Ahnung, wie schwer das Angeln auf einem zugefrorenen See ist? Mein armer Mann Paxton sitzt seit Tagen draußen auf dem Eis und wir haben keinen einzigen Sack Fisch zusammenbekommen.\n\nNa ja, das heißt, EINEN hatten wir. Bis dieser verflixte Wendigo mich überfallen und unseren Fang mitgenommen hat! Es wird Wochen dauern, den Rückstand aufzuholen, äh, aufzuangeln. Und das auch nur, wenn dieser Krawallmacher von Eisheuler die Fische nicht längst verscheucht hat.\n\nTut uns den Gefallen und holt den Sack zurück, ja? Der sabbernde Kerl hockt irgendwo tief im Graufelsbau im Südosten.", t = "Eisheuler"},
    [98340] = {ot = "Sprecht mit Dendrite Starblaze in Nighthaven in Moonglade.", st = "Anscheinend seid Ihr bereit für den nächsten Schritt auf Eurer Reise, $gjunger Druide:junge Druidin;. Dendrite Starblaze hat nach Euch verlangt. Er möchte, dass Ihr ihn erneut in Moonglade aufsucht.\n\nIhr habt bereits gelernt, mithilfe der Magie nach Moonglade zu reisen, also solltet Ihr Euch sofort auf den Weg machen können, wenn Ihr das wünscht. Wenn Ihr Eure Druidenausbildung fortsetzen wollt, würde ich vorschlagen, dass Ihr bald aufbrecht.", t = "Der große Katzengeist"},
    [98341] = {ot = "Sucht den Avatar von Saeyleenan im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der windgetragenen Katze mitzuteilen hat.", st = "Ein Geist aus Eurer Heimat ist vor Kurzem hier aufgetaucht und bat mich, Euch zu ihm zu führen. Dieser windgetragene Katzengeist ist gekommen, Euch als Mentor zur Seite zu stehen und Euch zu lehren, auf Zephras seine Katzengestalt anzunehmen.\n\nAlle Druiden erlangen irgendwann dieses Wissen, doch anscheinend ist die Form in Eurer Heimat eine andere. Wenn Ihr die Katzenform des Geistes annehmen möchtet, müsst Ihr zunächst unsere Prüfung bestehen.\n\nDer Geist wartet im Südteil von Moonglade, südlich von den beiden Brücken.", t = "Der Große windgetragene Katzengeist"},
    [98342] = {ot = "Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum großen Katzengeist zurück.", st = "Um Euch meinen Geist zu eigen zu machen, werdet Ihr mehr als ein paar Worte brauchen. Um meine Gestalt zu verstehen und zu respektieren, müsst Ihr beweisen, dass Ihr nicht nur Gerissenheit und Verstohlenheit verkörpert, sondern auch Wildheit, solltet Ihr in Bedrängnis gebracht werden.\n\nIn den Grabhügeln gleich östlich von hier befinden sich drei Relikte meiner Gunst, die Ihr beschaffen müsst. Sie werden von mächtigen, wütenden Geistern bewacht, die Euch angreifen werden, sobald sie Euch erblicken. Eine Statue beim Eingang wird Euch mit vorübergehender Verstohlenheit segnen, sodass Ihr an ihnen vorbeikommt.\n\nBringt diese Relikte zurück zu mir. Wir werden sehen, ob Ihr bereit seid, meine Gestalt anzunehmen.", t = "Der große Katzengeist"},
    [98362] = {ot = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.", st = "Nun ist es an der Zeit, dass sich unsere Wege erneut trennen, mein Kind, denn die Anwendung Eures neu erworbenen Wissens führt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Anscheinend hat Euer Lehrer, Turak Runetotem, in Euch $einen würdigen Schüler:eine würdige Schülerin; gefunden. Ich sehe dasselbe in Euch. Beherzigt seinen Rat und schon bald werdet Ihr Euch den großen Katzengeist zu eigen machen und seine Gestalt annehmen können.\n\nKehrt dorthin zurück, wo Ihr hergekommen seid. Wenn die Zeit reif ist, werden wir uns wiedersehen.", t = "Nach Thunder Bluff"},
    [98386] = {ot = "Tötet $1oa große Taranteln und zerstört $2oa Taranteleier in Althers Mühle für Großknecht Oslow im Rotkammgebirge.", st = "Orcs, Gnolle, Murlocs. Alles scheint darauf aus zu sein, mich daran zu hindern, diese Brücke rechtzeitig fertigzustellen. Jetzt haben wir Nachricht erhalten, dass sich Taranteln in unserem Sägewerk eingenistet haben!\n\nWenn Ihr Euch etwas dazuverdienen wollt, würdet Ihr vielleicht bei Althers Mühle im Osten vorbeischauen und Euch um unser Spinnenproblem kümmern? Wenn ich guten Gewissens keine Arbeiter hinschicken kann, um Lieferungen abzuholen, ist sie so gut wie nutzlos für mich.\n\nOh, und wenn Ihr den alten Alther seht, dann sagt ihm, dass er mir was dafür schuldet, dass ich hinter ihm herräume.", t = "Althers Mühle"},
    [98387] = {ot = "Bringt $1oa gestohlene Waffen und $2oa Blackrockvorräte nach Seenhain zu Marshal Marris.", st = "Ohne Waffen kann man keinen Krieg führen.\n\nAuch wenn die Blackrock-Orcs in dieses Land eindringen, sind ihre frechen Angriffe dennoch verwundbar.\n\nReist nach Südosten unter die Burg Steinwacht, findet ihre Lager und kümmert Euch um ihre Waffen und Vorräte.\n\nWollen wir doch mal sehen, wie viel Ärger sie uns machen können, wenn sie kein Kriegsmaterial mehr haben.", t = "Die Blockade der Blackrock"},
    [98389] = {ot = "Befreit $1oa eingesponnene Opfer im Nachtwebergrund für Aramis Hammerhand in Deathknell.", st = "Seid gegrüßt, $C. Ja, ich bin ein Paladin. Nicht einmal der Tod kann das Licht aufhalten.\n\nDas hat meinesgleichen mit allen Verlassenen gemeinsam... wir haben das überwunden, was die Lebenden als ihr Ende betrachten. Aber selbst einige unserer Leute fürchten uns; sie argwöhnen, dass wir sie als eine Art Monstrosität niederstrecken werden.\n\nIn Wahrheit haben wir eine komplexe Beziehung zum Untod, aber wir sind nicht hier, um unserem eigenen Volk zu schaden. Helft mir, das den anderen zu zeigen. Reist zum Nachtwebergrund im Nordwesten und befreit die frisch wiedererweckten Narren, die von den Spinnen dort gefangen wurden.", t = "Ein Licht in der Dunkelheit"},
    [98391] = {ot = "Sprecht mit Schwester Aquinne in Darnassus.", st = "Seid gesegnet, $C. Die Schwesternschaft von Elune ist seit tausenden von Jahren eine standfeste Säule der Gesellschaft der Kaldorei.\n\nNoch vor der großen Teilung, noch vor dem Krieg der Ahnen und durch die lange Wacht hindurch haben wir unser Volk durch die Dunkelheit geführt und geheilt. Dies ist unsere Pflicht, dies ist der Anspruch der göttlichen Mondmutter.\n\nNun benötigen wir Eure Hilfe bei einer Sache allerhöchster Wichtigkeit. Schwester Aquinne harrt Eurer Ankunft in Darnassus.", t = "Die Schwesternschaft von Elune"},
    [98392] = {ot = "Sammelt Hasskreischs Amulett, Windmeisterin Gaedress' Amulett und Hexenmutter Arysas Amulett für Schildwache Arynia Cloudsbreak auf der Lichtung des Orakels.", st = "Diese Gürtel... seht Euch das Leder genau an, $n. Seht Ihr die Befleckung, die durch die Fasern verläuft?\n\nIch habe einen Verdacht zu seinem Ursprung, aber ich brauche weitere Beweise, um sicher zu sein.\n\nBegebt Euch erneut zu den Nestern der Harpyien im Westen und erledigt ihre Anführerinnen. Wenn ihre Amulette von derselben Dunkelheit befleckt sind wie diese Gürtel, haben wir unsere Antwort.", t = "Dunkel auf der Lichtung"},
    [98393] = {ot = "Sprecht mit Dendrite Starblaze in Nighthaven in Moonglade.", st = "Anscheinend seid Ihr bereit für den nächsten Schritt auf Eurer Reise, $gjunger Druide:junge Druidin;. Dendrite Starblaze hat nach Euch verlangt. Er möchte, dass Ihr ihn erneut in Moonglade aufsucht.\n\nIhr habt bereits gelernt, mithilfe der Magie nach Moonglade zu reisen, also solltet Ihr Euch sofort auf den Weg machen können, wenn Ihr das wünscht. Wenn Ihr Eure Druidenausbildung fortsetzen wollt, würde ich vorschlagen, dass Ihr bald aufbrecht.", t = "Der große Katzengeist"},
    [98394] = {ot = "Sucht den großen Katzengeist im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der Katze mitzuteilen hat.", st = "Im südlichen Teil von Moonglade lebt auf einem Hügel, der die Brücke überblickt, ein weises und gerissenes Wesen, das wir den großen Katzengeist nennen.\n\nÄhnlich wie der große Bärengeist ist dieser Geist denjenigen Druiden ein Lehrer und Mentor, die die Katzengestalt annehmen wollten. Alle Druiden bitten ihn irgendwann um Rat, und wenn Ihr die Gestalt einer Katze annehmen wollt, dann werdet Ihr das auch.\n\nGeht, trefft Euch mit dem großen Katzengeist und lernt, was er Euch beibringen will.", t = "Der große Katzengeist"},
    [98396] = {ot = "Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum großen Katzengeist zurück.", st = "Um Euch meinen Geist zu eigen zu machen, werdet Ihr mehr als ein paar Worte brauchen. Um meine Gestalt zu verstehen und zu respektieren, müsst Ihr beweisen, dass Ihr nicht nur Gerissenheit und Verstohlenheit verkörpert, sondern auch Wildheit, solltet Ihr in Bedrängnis gebracht werden.\n\nIn den Grabhügeln gleich östlich von hier befinden sich drei Relikte meiner Gunst, die Ihr beschaffen müsst. Sie werden von mächtigen, wütenden Geistern bewacht, die Euch angreifen werden, sobald sie Euch erblicken. Eine Statue beim Eingang wird Euch mit vorübergehender Verstohlenheit segnen, sodass Ihr an ihnen vorbeikommt.\n\nBringt diese Relikte zurück zu mir. Wir werden sehen, ob Ihr bereit seid, meine Gestalt anzunehmen.", t = "Der große Katzengeist"},
    [98397] = {ot = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius.", st = "Nun ist es an der Zeit, dass sich unsere Wege erneut trennen, mein Kind, denn die Anwendung Eures neu erworbenen Wissens führt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Anscheinend hat Euer Lehrer, Mathrengyl Bearwalker, in Euch $geinen würdigen Schüler:eine würdige Schülerin; gefunden. Ich sehe dasselbe in Euch. Beherzigt seinen Rat, und schon bald werdet Ihr Euch den großen Katzengeist zu eigen machen und seine Gestalt annehmen können.\n\nKehrt dorthin zurück, wo Ihr hergekommen seid. Wenn die Zeit reif ist, werden wir uns wiedersehen.", t = "Auf nach Darnassus"},
    [98398] = {ot = "Findet die Orakelbaumrinde in der Nähe, um seine Nachricht zu vernehmen.", st = "Ich bin beeindruckt, was Ihr in so kurzer Zeit alles bewerkstelligt habt, $n. Ich würde Euch am liebsten bitten, hier zu bleiben und mir bei meinen Pflichten zu helfen... aber tief in meinem Herzen weiß ich, dass größere Aufgaben auf Euch warten.$b$bMir ist aufgefallen, dass der Orakelbaum einen Teil seiner Rinde abgestoßen hat. Zweifellos hat er eine Aufgabe, die er erledigt haben möchte. Ihr solltet mit ihm sprechen.", t = "Der Orakelbaum"},
    [98403] = {ot = "Tötet $1oa besudelte Waldweber und bringt Tallonkai Swiftroot das ausgewachsene Teufelsmoos von Xethorr dem Verschlagenen.", st = "Lord Melenas hat nicht allein gehandelt, sondern auf Geheiß eines Anderen. Xethorr der Verschlagene ist sein Name. Er hat offenbar die auf Teldrassil heimischen Spinnen verderbt, um ihr Gift für einen unheilvollen Plan zu missbrauchen.\n\nSein Domizil liegt nordwestlich von hier tief im Wald, in einer Gegend, die als die Kluft bekannt ist. Lasst Vorsicht walten und bringt Verbündete mit, denn Xethorr ist ein nicht zu unterschätzender Gegner.\n\nVernichtet seine Brut und bringt mir alles, das uns mehr über die Machenschaften des Satyrs verrät.", t = "Krankhafter Hass"},
    [98404] = {ot = "Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum Avatar von Saeyleenan zurück.", st = "Um Euch meinen Geist zu eigen zu machen, werdet Ihr eine Prüfung bestehen müssen. Um meine Form zu verstehen und zu respektieren, müsst Ihr beweisen, dass Ihr nicht nur Gerissenheit und Verstohlenheit verkörpert, sondern auch Wildheit, solltet Ihr in Bedrängnis gebracht werden.\n\nIn Grabhügeln gleich östlich von hier befinden sich drei Reliquien, die Ihr beschaffen müsst. Sie werden von mächtigen, wütenden Geistern bewacht, die Euch angreifen werden, sobald sie Euch erblicken. Eine Statue beim Eingang wird Euch mit vorübergehender Verstohlenheit segnen, sodass Ihr an ihnen vorbeikommt.\n\nBringt diese Relikte zu mir zurück, um die Druidenprüfung dieser Lande zu bestehen.", t = "Der Große windgetragene Katzengeist"},
    [98405] = {ot = "Sucht den großen Katzengeist im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der Katze mitzuteilen hat.", st = "Im südlichen Teil von Moonglade lebt auf einem Hügel, der die Brücke überblickt, ein weises und gerissenes Wesen, das wir den großen Katzengeist nennen.\n\nÄhnlich wie der große Bärengeist ist dieser Geist denjenigen Druiden ein Lehrer und Mentor, die die Katzengestalt annehmen wollten. Alle Druiden bitten ihn irgendwann um Rat, und wenn Ihr die Gestalt einer Katze annehmen wollt, dann werdet Ihr das auch.\n\nGeht, trefft Euch mit dem großen Katzengeist und lernt, was er Euch beibringen will.", t = "Der große Katzengeist"},
    [98407] = {ot = "Sammelt $1oa Stachelhalsbänder von Hauer der Rotkammgnolle für Deputy Feldon in der Nähe von Seenhain.", st = "Wenn die Gnolle inzwischen dreist genug sind, so nah an Menschen ihre Lager aufzuschlagen, dann ist nicht abzusehen, wie weit sie noch gehen werden. Wir müssen sie abschrecken.\n\nDiese Biester sind kaum organisiert, aber sie scheinen vor allem Stärke zu respektieren. Wenn wir es schaffen, die Schlimmsten von ihnen zu töten und uns vielleicht ein paar ihrer Trophäen zu nehmen, dann können wir diesen Gnollen in Erinnerung rufen, warum sie in den Hügeln bleiben sollten, wo sie hingehören.\n\nSolltet Ihr einige ihrer Hauer sehen, bringt mir ihre Halsbänder. Das sollte sie lehren, die Allianz zu fürchten.", t = "Machtdemonstration"},
    [98417] = {ot = "Maseara Herbstmond möchte, dass Ihr westlich von Forest Song unter den Satyrnaardämonen sucht. Meldet bei Eurer Rückkehr alle Hinweise auf ihren Mann Kurothel.", st = "Als unser Schicksal uns im Moment unser größten Verwundbarkeit miteinander verband, ereilte unsere Dörfer ein großes Unglück. Satyrn schändeten unsere Tempel, ihre gottlose Berührung entweihte heilige Zweige und die Unschuldigen wurden gnadenlos abgeschlachtet.\n\nKurothel wurde von Zorn übermannt. Die Druiden tragen den Kampf zu den Satyrn, und er ist ihnen gefolgt.\n\nUnsere Verbindung besteht weiter. Ich spüre meinen Mann, im Westen, innerhalb dieser Wälder. Bitte, kehrt mit Neuigkeiten über sein Schicksal zu mir zurück.", t = "Auf dem Pfad der Rache"},
    [98418] = {ot = "Tötet $1oa Schurken von Xavian, $1oa Teufelsanbeter von Xavian, $1oa Verräter von Xavian und $1oa Höllenrufer von Xavian.\nKehrt anschließend zu Maseara Herbstmond in Forest Song zurück.", st = "Kurothel hatte Sichtungen von sogenannten Wolfsmännern erwähnt. Dieses Rudel treibt sich nun in großer Anzahl in unserem Wald herum. Als wir das letzte Mal miteinander sprachen, strebten die Druiden den Austausch mit jenen der Bestien an, die ihre animalischen Instinkte auf gewisse Weise zu beherrschen vermochten.\n\nSeine geschriebene Worte zeigen einen dunkleren Kampf. Wenn wir irgendetwas tun können, damit wir IHN wiedersehen, dann wird die Beseitigung der dämonischen Bedrohung, die ihn zu dieser feurigen Verwandlung treibt, seiner gepeinigten Seele sicher Linderung verschaffen.\n\nTötet die Xavian, $n.", t = "Geteilte Wut"},
    [98423] = {ot = "Bringt das Abkommen des Einvernehmens zu Magni Bronzebeard in Ironforge.", st = "Im Inneren der Kammer findet Ihr eine Tafel, auf der die Bedingungen des Friedensvertrages zwischen den Klans der Bronzebeard- und Wildhammerzwerge festgehalten sind. Sie scheint aus der Zeit kurz nach dem Krieg der Drei Hämmer zu stammen und ist zweifelsohne ein wertvolles Stück Zwergengeschichte. Der König von Ironforge hätte bestimmt Interesse an diesem Artefakt.", t = "Das Abkommen des Einvernehmens"},
    [98424] = {ot = "Sammelt die übrigen Seiten von Vorsteher Fizsprockets Notizbuch in der Mine der Venture Co. und bringt sie zu Morin Cloudstalker am Dorf der Bloodhoof.", st = "Einige besonders abgenutzte Seiten stecken, sorgfältig gefaltet, in Fizsprockets Brusttasche.\n\nSie enthalten offenbar wichtige Informationen über die Venture Co. und ihre Machenschaften in dieser Region. Bevor Ihr zu Morin Cloudstalker zurückkehrt, solltet Ihr nach den restlichen Seiten suchen.", t = "Fizsprockets Notizen"},
    [98427] = {ot = "Bringt den Mechanoroderschlüssel zu Morin Cloudstalker am Dorf der Bloodhoof.", st = "Auf einer der Seiten ist die Rede von einem Schredder... Davon habe ich auf meinen Reisen bereits gehört. Diese Maschinen können einen Wald in einem Bruchteil der Zeit niederreißen, die Axt und Muskelkraft dafür benötigen.\n\nGanze Haine, seit Jahrtausenden Zuflucht der Kinder der Erdenmutter, verschwinden innerhalb weniger Tage.\n\nDas werden wir in unserer Heimat nicht zulassen. Nicht so nah an dem Ort, an dem unsere Jüngsten ihre ersten Schritte machen.\n\n$n, ich muss Euch bitten, Verbündete um Euch zu scharen, in die Mine im Nordosten zurückzukehren und dafür zu sorgen, dass diese Maschine keinen einzigen Baum mehr fällt.", t = "Schluss damit!"},
    [98430] = {ot = "Helft Perith Stormhoof bei der Flucht aus dem Bleichmähnenfels und meldet Cairne Bloodhoof in Thunder Bluff, dass er in Sicherheit ist.", st = "Seid gegrüßt, $C. Was führt Euch an diesen Ort der Dunkelheit und Gewalt?\n\nHäuptling Cairne Bloodhoof hat mich ursprünglich entsandt, um mit den Gnollen Kontakt aufzunehmen, die sich hier niedergelassen haben. Über den eigentlichen Auftrag darf ich jedoch nicht sprechen. So ist es bei den Langläufern, den Kundschaftern des Häuptlings.\n\nAlles, was Ihr wissen müsst, ist dies: Unsere Friedensbemühungen wurden mit Gewalt erwidert. Wenn Ihr mir nicht helft zu entkommen, werde ich den Gnollen heute Nacht wohl als Mahl dienen.\n\nWerdet Ihr mir helfen?", t = "Die Langläufer"},
    [98435] = {ot = "Bringt Thunderhorns Bericht zu Erzdruide Hamuul Runentotem in Thunder Bluff.", st = "Unsere Ältesten in Thunder Bluff müssen erfahren, welche Fortschritte wir dank Eurer Hilfe erzielt haben.\n\nBitte bringt diesen Bericht zu Erzdruide Hamuul Runentotem in Thunder Bluff. Ihr findet ihn auf der Anhöhe der Ältesten im Osten der Stadt. Nehmt den Aufzug hinauf ins Zentrum der Stadt und überquert anschließend die Brücken.", t = "Thunderhorns Bericht"},
    [98461] = {ot = "Bringt Hollees Nachricht zu Tarrel Rockweaver nahe des Hafens von Menethil im Sumpfland.", st = "Wenn Ihr Auberdine ohnehin verlasst, könntet Ihr mir einen Gefallen tun!\n\nMein lieber Freund Tarrel und ich sind zusammen zur Schule gegangen. Ach, er war schon damals ein echtes Naturtalent, wenn es um Ausgrabungen ging! Nach unserem Abschluss trennten sich unsere Wege: Er ging ins Sumpfland, mich verschlug es an die Dunkelküste.\n\n<Hollee seufzt und zieht die Stirn kraus.>\n\nNa ja, und seine Frau... Merrin.\n\nAch, was soll's, ich mache das jetzt trotzdem. Falls Ihr ins Sumpfland kommt, seht bitte nach, ob es ihm gut geht. Und... würdet Ihr ihm das hier geben? Wahrscheinlich ist er in der Nähe des Hafens von Menethil. Von hier fährt sogar ein Schiff direkt dorthin.", t = "Unerwiderte Liebe"},
    [98512] = {ot = "Tötet 10 Auftragsmörder der Al'Aketh im Shen'darhochland.", st = "He, Ihr da, $gFremder:Fremde;! Geht in Deckung und seid leise. Wir sind nicht allein.\n\nIch war auf Patrouille nahe der Grenze, als mir auffiel, dass sich dort oben am Hang, bei dem Haus im Norden, mehrere Al'Aketh herumtreiben. Ich weiß nicht, was sie dort wollen, aber sie führen sicher nichts Gutes im Schilde.\n\nWenn Ihr Euch nützlich machen wollt, geht hinein und schaltet sie aus. Ich warte hier und halte Euch den Rücken frei.", t = "Auftragsmörder der Al'Aketh"},
    [98545] = {ot = "Bringt den versiegelten Brief zu Glix Xizzix in Undercity.", st = "Da Ihr schon mal hier seid, möchte ich Euch bitten, diesen Brief einem alten Freund von mir in Undercity zu überbringen. Ich würde ihn ja selbst zustellen, aber ich habe eine... sagen wir... bewegte Vergangenheit mit der Dunklen Fürstin. Es ist besser, wenn eine neutrale Person die Übergabe übernimmt.\n\nSucht nach einem Goblin namens Glix Xizzix im Handelsviertel von Undercity. Ich bin sicher, er wird Euch für Eure Mühe entschädigen.\n\n<Leonid gluckert, als er Euch den Brief reicht.>", t = "Leonids Brief"},
    [98574] = {ot = "Lest das geheiligte Memorandum und sprecht mit Branstock Khalder in Anvilmar.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Geheiligtes Memorandum"},
    [98575] = {ot = "Lest die besudelte Tafel und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen.", st = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.$B$BIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet sie lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", t = "Besudelte Tafel"},
    [98576] = {ot = "Lest das Glyphenpergament und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", st = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, $n.$B$BLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von Magierlehrerin Mai'ah. Sie möchte mit Euch reden, wenn Ihr bereit seid.", t = "Glyphenpergament"},
    [98581] = {ot = "Lest die archaische Rune und sprecht mit Teo Hammerstorm in Anvilmar.", st = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Diese Inschriften tragen die Handschrift der Wildhämmer, also schätze ich mal, sie kommt vom Schamanenlehrer Teo Hammerstorm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", t = "Archaische Rune"},
    [98601] = {ot = "Lest die geweihte Schriftrolle und sprecht mit Aramis Hammerhand in der Kirche von Deathknell.", st = "Während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Sie ist vom Gestank des Lichts nur so durchdrungen, also nehme ich an, dass sie für einen Paladin wie Euch von einiger Bedeutung ist.\n\nLest sie, bevor Ihr wieder loszieht. Aber bitte, tretet zurück, während Ihr es tut. Paladine machen mich sehr nervös.", t = "Ein schwieriger Pfad"},
    [98731] = {ot = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", st = "Nun, da Ihr meinen Segen erhalten habt, kehrt zu Dendrite zurück. Er wird Euch weitere Anweisungen geben. Ich hoffe sehr, dass wir uns eines Tages wiedersehen.\n\nMögen die Schatten Euch für immer verbergen und Eure Gegner leichte Beute für Eure Krallen sein, $gjunger Freund:junge Freundin;.", t = "Segen des großen Katzengeistes"},
    [98738] = {ot = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", st = "Nun, da Ihr meinen Segen erhalten habt, kehrt zu Dendrite zurück. Er wird Euch weitere Anweisungen geben.\n\nLeider kann ich Euch im Moment nicht mehr viel beibringen. Ich hoffe sehr, dass Ihr mich eines Tages wieder in Zephras besucht. Ich spüre großes Potenzial in Euch, $gjunger Shen'dorei:junge Shen'dorei;.\n\nMögen die Schatten Euch für immer verbergen und Eure Gegner leichte Beute für Eure Krallen sein.", t = "Segen des großen windgetragenen Katzengeistes"},
    [98739] = {ot = "Sprecht mit Dendrite.", st = "Nun, da Ihr meinen Segen erhalten habt, kehrt zu Dendrite zurück. Er wird Euch weitere Anweisungen geben. Ich hoffe sehr, dass wir uns eines Tages wiedersehen.\n\nMögen die Schatten Euch für immer verbergen und Eure Gegner leichte Beute für Eure Krallen sein, $gjunger Freund:junge Freundin;.", t = "Segen des großen Katzengeistes"},
    [98815] = {ot = "Kehrt mit $1oa Dickichtraptorbälgen bei dem Gerber James Halloran im Hafen von Menethil zurück.", st = "Im Hochland gibt es Ruinen irgendwelcher Art, deren Geheimnisse gerade von einem Expeditionsteam erforscht werden. Soweit ich weiß, gibt es dort eine ganz eigene Tierwelt und wilde Bestien, die in diesem bergigen Feuchtgebiet lauern. Wie wäre es, wenn Ihr Euch mit ein paar gut ausgerüsteten Freunden dorthin aufmacht und wir einen Tauschhandel vereinbaren?\n\nUnd stellt Euch bloß nicht an wie ein Balg! Ich will ihre Bälge! Bringt mir die Bälge von vier Dickichtraptoren. Ich werde einen Tausch für Euch aushandeln, damit es sich für Euch lohnt.", t = "Hochlandbälge"},
    [98823] = {ot = "Bringt das Relikt der Titanen zu Muln Earthfury beim Himmelsschauerplateau im Nordwesten von Mulgore.", st = "Das ist ein wahrlich faszinierendes Objekt.\n\nEs weist Anzeichen dafür auf, dass es weit mehr ist als nur eine einfache Schnitzerei oder Skulptur.\n\nAuch wenn unsere Ältesten vielleicht Interesse daran haben, dieses Artefakt zu begutachten, ist es doch der Irdene Ring, der über die größte Weisheit hinsichtlich unserer verschütteten Ruinen und vergessenen Länder verfügt. Sucht Muln Earthfury auf. Angesichts der Tragweite dessen, was Ihr bei Euch tragt, solltet Ihr ihn direkt ansprechen.\n\nIhr findet ihn und andere Älteste des Irdenen Rings beim Himmelsschauerplateau im Nordwesten von Mulgore.", t = "Irdenes Echo"},
    [98824] = {ot = "Bringt das Relikt der Titanen zu Hochforscher Magellas in der Halle der Forscher in Ironforge.", st = "Angesichts der titanartigen Inschriften auf seinen Oberflächen kommt nur die Halle der Forscher in Ironforge als geeigneter Verwahrungsort dafür in Frage\n\nIch würde mir wünschen, dass Euer Name dann im historischen Katalog vermerkt wird: \"Entdeckt von $n! Beglaubigt durch Ausgrabungsleiter Whelgar...\" Ah, ich fange gerade an, zu schwelgen.\n\nHochforscher Magellas wird Euch empfangen und angesichts der außergewöhnlichen Natur Eures Mitbringsels sicherlich äußerst dankbar sein, solltet Ihr entscheiden, es dem Museum zu spenden.\n\nEin toller Fund!", t = "Prähistorisches Prisma"},
    [99046] = {ot = "Begebt Euch auf die Suche nach Schildwache Eralya Leafshadow auf der Straße in Richtung der Lichtung des Orakels.", st = "Der Rat des Waldes hat vor einiger Zeit eine kleine Gruppe Schildwachen zum Orakelbaum entsandt. Der Baum übermittelt unseren Ältesten Botschaften, und es ist unsere Aufgabe, diese sicher nach Darnassus zu bringen\n\nMir wurde mitgeteilt, dass unsere letzte Botin noch nicht eingetroffen ist. Die Häufigkeit der Nachrichten des Orakels schwankt, doch diesmal hat es ungewöhnlich lange gedauert.\n\nBitte macht Euch auf zur Straße nach Westen zur Lichtung des Orakels und sucht nach ihr. Eralya Leafshadow war an der Reihe, doch sie befindet sich noch in der Ausbildung. Möge Elune Euch leiten.", t = "Die verlorene Botin"},
    [99047] = {ot = "Sucht für Schildwache Eralya Leafshadow Hilfe bei Byancie in Dolanaar.", st = "Meine Schwestern und ich... wurden entsandt... Orakelbaum...\n\nBaum... Botschaft. Ich... Harpyien... überall...\n\n<Eralya hustet Blut, das Gesicht von Schmerz verzerrt.>\n\nIch habe vielleicht nicht mehr lange... niemand kommt. Bitte... Byancie... in Dolanaar...", t = "Noch nicht tot"},
    [99048] = {ot = "Findet Heglan Shadeeye nördlich von Burg Tiragarde.", st = "Ein Mitglied der Shattered-Hand, einer Gruppe von eher... verdeckt agierenden Kämpfern, beobachtete Burg Tiragarde aus der Ferne. Plötzlich kamen keine Berichte mehr von ihr.\n\nIch bezweifle, dass die Menschen sie gefangen haben könnten, daher mache ich mir Sorgen, dass etwas Gefährlicheres dahintersteckt. Versucht bitte, sie zu finden. Hoffentlich sind die Nachrichten einfach nur verspätet.", t = "Hand vermisst"},
    [99049] = {ot = "Findet Hinweise darauf, was Heglan Shadeeye angegriffen hat.", st = "Die Umgebung ist verwüstet und zeigt deutliche Spuren eines Gefechts. Was auch immer Heglan überfallen hat, es ist nicht unversehrt davongekommen. Wahrscheinlich gibt es in der Nähe Hinweise darauf, was hier geschehen ist.\n\nOrgnil wird sicher jeden Beweis sehen wollen, den die Angreifer hinterlassen haben.", t = "Bedrohung von unten"},
    [99050] = {ot = "Beschafft $1oa taubedeckte Peitscherwedel, eine leere Phiole und erfrischendes Quellwasser für Byancie in Dolanaar.", st = "Ich brauche Eure Hilfe, um die Zutaten zu beschaffen, die ich benötige, um die Krankheit lange genug aufzuhalten, damit Eralya es bis hierher zurückschafft, um sich weiter behandeln zu lassen.\n\nGlücklicherweise ist unsere Heimat noch immer reich an Ressourcen und kann uns in Zeiten der Not versorgen.\n\nDie Hauptzutat sind taubedeckte Peitscherwedel. Ihr findet sie rund um den Al'Amethsee direkt südlich von hier oder am Wellspringsee und seinem Fluss im Nordwesten.\n\nZudem benötige ich eine leere Phiole und etwas Quellwasser. Beides kann man hier in der Stadt kaufen oder tauschen.", t = "Gaben des Großen Baums"},
    [99051] = {ot = "Sammelt $1oa Nagastachelflossen ein.", st = "Es ist nicht das erste Mal, dass uns diese Schlangen Ärger bereiten. Man muss ihnen klarmachen, dass ihre Anwesenheit hier nicht geduldet wird.\n\nFindet heraus, wo ihre Späher ihr Lager aufschlagen, und tötet sie. Bringt mir ihre Flossen als Beweis. Wir müssen schnell handeln, damit sie es verstehen.", t = "Bedrohung von unten"},
    [99052] = {ot = "Tötet den Meeresriesen an der Nordküste von Durotar und bringt einen Beweis für Euren Erfolg zurück.", st = "Einer meiner Späher hat berichtet, dass ein Meeresriese diesen Nagas hierher gefolgt ist. Ich weiß nicht, ob sie ihn möglicherweise absichtlich mitgebracht haben, aber er ist auf jeden Fall gefährlich.\n\nEr ist noch jung, aber er könnte einen unaufmerksamen Orc trotzdem im Handumdrehen in zwei Hälften reißen. Er muss beseitigt werden. Aber ich würde Euch raten, Euch Hilfe für diesen Auftrag zu holen.", t = "Bedrohung von unten"},
    [99053] = {ot = "Helft Schildwache Lynessa Duskblossom vom Grabhügel von Ban'ethil zu entkommen und berichtet dann Schildwache Kyra Starsong in Dolanaar, dass sie in Sicherheit ist.", st = "Meine Gebete wurden erhört! Ich bin Euch sehr dankbar, dass Ihr Euch den Weg hierher gebahnt habt.\n\nIch wurde vom Orakelbaum hierher gesandt, um den schlummernden Druiden hier eine Botschaft zu überbringen. Aber dieser Ort wurde komplett von Furbolgs überrannt! Sie haben mich überwältigt, bevor ich weglaufen konnte, und mich hierher gebracht. Ich fürchte, ich werde ihre nächste Mahlzeit sein.\n\nIch weiß nicht, wie es Euch geht, aber ich verabscheue diesen Ort. Unter der Erde haben die Kaldorei nichts zu suchen.", t = "Flucht aus Ban'ethil"},
    [99073] = {ot = "Bringt die Peitscherwassersalbe zu Schildwache Eralya Leafshadow an der Straße zum Orakelbaum.", st = "Die Salbe ist fertig. Bringt sie schnell zu Eralya.\n\nIch weiß nicht, ob sie sie heilen kann. Die Fäulnis breitet sich rasch aus und wird immer stärker, je weiter sie vordringt.\n\nZumindest wird sie ihr Leiden lindern. Und allein schon dafür solltet Ihr Euch beeilen.", t = "Leidlinderung"},
    [99079] = {ot = "Findet Langläuferin Malah Longwind östlich des Dorfes der Bloodhoof, nahe Mulgore.", st = "Die Langläufer sind die vertrauenswürdigsten Späher unseres Volkes. Obwohl ihre Loyalität allein dem Oberhäuptling gilt, bittet der junge Baine sie manchmal um Hilfe.\n\nDies ist ein solcher Fall. Die Langläuferin Malah wurde nahe unserer östlichen Grenze entsandt und kehrte gestern Abend nach drei Tagen nicht zurück. In solchen Fällen ist es unsere Pflicht, uns von ihrem Wohlergehen zu überzeugen.\n\nIch muss gewährleisten, dass das Dorf sicher bleibt. Beweist Euch und macht Euch auf die Suche nach Malah. Ihr könnt sie an ihrem Stirnband und ihrem mit Federn verzierten Stab erkennen, den Erkennungszeichen der Langläufer.", t = "Langläuferin Malah"},
    [99080] = {ot = "Tötet $1oa Zentauren der Galak und $2oa Kundschafter der Galak und bringt den Kopf von Herak dem Plünderer zu Baine Bloodhoof.", st = "Hört meine Worte: Wir werden den Zentauren nicht einmal einen einzigen Grashalm überlassen.\n\nBegebt Euch sofort zu ihrem Lager, bevor sie sich ausgeruht haben und die Gelegenheit bekommen, in unser Dorf einzufallen. Tötet sie alle. Stellt sicher, dass keiner ins Brachland entkommt, um dort weitere Verstärkung zu holen.\n\nWenn Ihr den Anführer dieser vermeintlichen Räuberbande findet, bringt mir seinen Kopf, damit er anderen als Warnung diene, die es wagen, unser Heimatland zu betreten.", t = "Vertreibt sie"},
    [99081] = {ot = "Bringt den Bericht von Langläuferin Malah zu Kriegerheld Wildrunner im Dorf der Bloodhoof.", st = "In der Richtung, aus der die Pfeile in Malahs Rücken gekommen sein dürften, erblickt Ihr etwas, das wie ein neues Zentaurenlager aussieht. Dort herrscht reges Treiben, was darauf hindeutet, dass sich ein kleiner Raubzug seinen Weg nach Mulgore gebahnt hat.\n\nDie Langläuferin hält in ihrer immer noch geballten Hand einen Bericht. Kriegerheld Wildrunner wird wissen wollen, was Malah widerfahren ist. Und wer ihre Mörder sind.", t = "Schwieriges Unterfangen"},
    [99082] = {ot = "Ersucht in Thunder Bluff um eine Audienz beim Oberhäuptling Cairne Bloodhoof.", st = "Die Tapferkeit, mit der Ihr Euer Volk verteidigt habt, verdient Anerkennung. Begebt Euch nach Thunder Bluff im Nordwesten, unserer mächtigen Stadt, deren Schatten uns in den wärmeren Monaten Erfrischung spendet, und bittet meinen Vater um eine Audienz.\n\nEr war es, der gemeinsam mit dem jungen Kriegshäuptling Thrall den Angriff anführte, um diese Ebenen zurückzuerobern und die Zentauren ein für alle Mal zu vertreiben. Als Oberhäuptling wird er Euch großzügig dafür belohnen, dass Ihr dazu beigetragen habt, dass seine Tapferkeit gewürdigt wird.\n\nUm zum Oberhäuptling auf der zentralen Anhöhe zu gelangen, müsst Ihr den Aufzug verwenden.", t = "Der Oberhäuptling"},
    [99101] = {ot = "Bringt den Bericht von Langläuferin Malah zu Baine Bloodhoof.", st = "Baine Bloodhoof ist der Anführer unseres Dorfes. Er muss sofort von diesem Übergriff erfahren.\n\nBringt ihm den Bericht von Langläuferin Malah. Ihr findet ihn im Zentrum der Stadt.\n\nSchnell! Ihr dürft keine Zeit verschwenden!", t = "Unser uralter Feind"},
    [99108] = {ot = "Besiegt 3 andere Spielercharaktere in Duellen oder Novizenkrieger für Tang Stonehoof.", st = "Seid gegrüßt, $C. Auch wenn Ihr $ukein Krieger:keine Kriegerin; seid und ich Euch diesen Pfad nicht lehren kann, bedeutet das nicht, dass Ihr nicht trotzdem von meinen Unterweisungen profitieren könnt.\n\nVor Euch liegt die Arena. Dort spielt es keine Rolle, wen Ihr Mutter nennt oder ob Ihr Schwert oder Bogen führt. Alle sind gleich, und alle lernen im Kampf, ihre Hörner zu spitzen.\n\nWerdet Ihr unsere Domäne betreten und unsere Wege auf eigene Faust erlernen? Ihr könnt gegen jeden dieser Novizen oder jeden anderen Gegner antreten, der willens ist. Mich kümmert nicht, wen Ihr auswählen werdet.", t = "Sparringskampf"},
    [99123] = {ot = "Helft Pal'juh, aus der Kolkarklippe zu entkommen, und berichtet anschließend Meister Vornal in Sen'jin davon.", st = "Ich bin alleine losgezogen, um die Klippe etwas auszukundschaften. Leider ist mir gerade im falschen Moment die Magie ausgegangen und nun stecke ich hier fest.\n\nWenn Ihr mir zur Flucht verhelfen könntet, wäre ich Euch überaus dankbar.", t = "Verloren in den Schatten"},
    [99127] = {ot = "Überprüft die Fischfallen im Kristallsee.", st = "Die Fische wollen heute einfach nicht beißen. Irgendetwas stimmt nicht mit ihnen. Es sind nicht nur die Haken, die leer bleiben. Ich hab hier auch noch keine einzige Sardine schwimmen sehen.\n\nLee hier hat über Nacht ein paar Fallen aufgestellt. Schaut bitte nach, ob wir wenigstens dort etwas fangen konnten. Und lasst mich wissen, wenn Ihr irgendetwas merkwürdiges seht.", t = "Schlechtes Netz"},
    [99128] = {ot = "Tötet die Murlocs am Kristallsee.", st = "Das kann nur das Werk von diesen Murlocs auf der anderen Seite des Sees sein. Diese ekelhaften kleinen Viecher haben ein grauenhaftes Temperament und die passenden Zähne noch dazu.\n\nWenn wir nichts dagegen tun, gibt es in diesem See bald gar keine Fische mehr. Ihr würdet mir einen riesigen Gefallen tun, wenn Ihr sie etwas ausmerzen könntet.", t = "Eine schleimige Bedrohung"},
    [99129] = {ot = "Sprecht mit Remy \"Zweifach\" über Jasons Murlocprobleme.", st = "Remy hat letztens von Murlocs gesprochen... Ich bin mir ziemlich sicher, dass er die kleinen Plagegeister genauso hasst wie ich.\n\nVielleicht hat er ein paar Ideen, wie wir die Viecher in Zukunft von meinen Fischen fernhalten können. Ich möchte Euch darum bitten, ihm einen Besuch abzustatten und mit ihm zu reden. Fragt ihn, ob ihm etwas zu der Sache einfällt.", t = "Ein Problem, ein Mann, eine Lösung"},
    [99130] = {ot = "Sammelt die Zutaten für den Murloc-Köder.", st = "Ich habe da ein paar Ideen, wie wir gegen die Murlocs vorgehen können. Und eine dieser Ideen hilft im gleichen Zug sogar noch anderen.\n\nEs gibt da ein Kraut, dass sich oft auf Bauernhöfen finden lässt. Es heißt Dämmerkraut und seine Blüten sind in hohen Dosen für die meisten Tiere giftig. Wenn wir aus der Pflanze einen Köder für die Murlocs herstellen, können wir diesen Kreaturen vielleicht beibringen, Abstand zu halten.\n\nUnd im gleichen Zug werden die Felder einiger Bauern gejätet. Es gibt nur Gewinner... nur Gewinner.", t = "Ein verlockendes Angebot"},
    [99131] = {ot = "Kehrt zu Jason Mathers zurück.", st = "Sagt Mathers, dass er den Köder später bei mir abholen kann. Ich gebe ihm dann einen Abriss darüber, wie man ihn richtig einsetzt.\n\nHoffentlich kann er bald wieder Fisch verkaufen. Und hoffentlich haben wir bald weniger Murlocs auf dieser Welt.", t = "Ein Köder für Erfolg"},
    [99134] = {ot = "Bestraft $1oa Todeswachen für Exekutor Zygand.", st = "Ihr seid nicht Teil der Todeswache und hattet dementsprechend noch keine Gelegenheit, mich zu enttäuschen.\n\nAls Belohnung für Euren vergleichsweisen Mangel an Inkompetenz werdet Ihr jene strafen, die dieses Talent zur Genüge zur Schau gestellt haben.\n\nBeeilt Euch... $n war Euer Name, richtig? ... sonst landet Ihr auf meiner Liste als Belohnung für jemand anderen.", t = "Disziplin"},
    [99141] = {ot = "Besorgt die Berichte von Todeswache Dillinger, Todeswache Kristof und Gordo für Exekutor Zygand.", st = "Seid Euch sicher, $C... die Dunkle Fürstin erwartet, dass ihr Wille perfekt ausgeführt wird. Als Exekutor ist es meine Pflicht, dafür zu sorgen.\n\nIch warte seit geraumer Zeit auf Berichte mehrerer meiner Todeswachen. Ich muss wohl nicht erwähnen, dass meine Geduld am Ende ist. Besorgt ihre Berichte und bringt sie mir im Namen der Dunklen Fürstin.\n\nIhr findet Todeswache Dillinger beim Friedhof westlich von hier. Todeswache Kristof ist beim Außenposten östlich von hier stationiert. Und schaut nach der Monstrosität Gordo. Er läuft westlich in der Nähe des Stillwassertümpels umher.", t = "Geduld"},
    [99142] = {ot = "Sammelt $1oa Grabkräuter und bringt sie zu Jungapotheker Holland.", st = "Wenn Ihr nach Osten geht, in Richtung von Balnirs Bauernhof, hätte ich noch mehr für Euch zu tun. Heutzutage ist es so schwer, gute Hilfe zu finden, wie Eure Begegnung mit Gordo ganz klar aufzeigt.\n\nWährend ich Verdammniskraut sammle, nehme ich einige kleinere alchemische Modifikationen vor und pflanze es wieder auf dem Bauernhof an, um meine ultimative Kreation anzubauen. Ich nenne es Grabkraut und es soll der Vorbote meines glorreichen Schicksals sein.\n\nBehaltet die Geißel in der Umgebung im Auge, wenn Ihr dort seid. Es scheint als würde das Kraut sie... anziehen. Interessant.", t = "Grabkraut"},
    [99143] = {ot = "Sammelt $1oa Stücke glänzenden Plunder von dem Murloclager in der Nähe.", st = "Diese Fischmenschen müssen wie echte Fische denken, oder? Was bedeutet, dass sie auch mögen, was Fische mögen!\n\nWenn Ihr ihren Plunder durchwühlt und mir alles bringt, was einen guten Köder abgeben könnte, werde ich Euch dafür entlohnen.", t = "Glitschiger Glitzerkram"},
    [99144] = {ot = "Helft Bareth Dämmerstein, aus dem Außenposten der Kreuzzügler zu entkommen, und berichtet Shari Stilwell in Brill von seiner Unversehrtheit.", st = "Das Licht segne Euch dafür, dass Ihr mich gefunden habt. Ich war auf meinem Weg von der Bandarionfestung, um Shari Stilwell in Brill eine Nachricht zu überbringen, als diese Monster mich gefangen nahmen. Sie führen das Licht mit einem Hass im Herzen, der die Überreste meines Bluts zum Kochen bringt. Das widerspricht allem, wofür ich meditiere... allem, das ich zu beschützen versuche!\n\n<Bareth Dämmerstein richtet sich auf.>\n\nIch weiß, dass sich viele nach wie vor an meinesgleichen stören, aber ich versichere Euch, dass meine Intentionen gut sind. Wenn Ihr mir helfen würdet, von hier zu fliehen, wäre ich Euch ewig dankbar.", t = "Auf der Suche nach Sicherheit"},
    [99152] = {ot = "Sammelt $1oa schwach leuchtende Knochen für Hilda die Brecherin.", st = "Während die Befleckten im Schattental im Südwesten definitiv ein Problem sind, dürfen wir nicht zulassen, dass die Keller unter der Stadt zu einer gewaltigen Geißelmeute gegen die Bandarionfestung heranwächst.\n\nIch muss dafür sorgen, dass diese Rekruten kampfbereit sind, sollte es dazu kommen. Ihr hingegen bekommt die Schnelleinweisung.\n\nReist unter das Schattental und bergt einige ihrer elendigen Knochen, damit wir sie weiter erforschen können. Ich brauche welche, die nach wie vor etwas von der ursprünglichen Reanimierungsmagie enthalten... die sollten leuchten.", t = "Wie oben, so auch unten"},
    [99153] = {ot = "Findet das versteckte Kristallfragment unter Schattental für Ephram Barbaro.", st = "He, Ihr da! In unseren Reihen sprechen sich die Dinge schnell rum. Ich habe von der Sache mit den Kultisten bei den Überresten der Schlacht gegen Naxxramas gehört.\n\nDas Problem ist nur, dass einer der Kultisten mit einem Stück des Fokussierkristalls entkommen ist. Und das scheint noch etwas Saft zu haben. Unsere beste Vermutung ist, dass er sich irgendwo unter dem Schattental befindet. Entweder lässt der Kristall sie auferstehen oder er macht sie stärker... und wir wollen keins von beidem.\n\nFindet den Kristall, bevor die Sache aus dem Ruder läuft.", t = "Das Eine, das entkam"},
    [99156] = {ot = "Bringt Reißers Herz zu Todeswache Linnea.", st = "Verdammt nochmal! Während Ihr auf Patrouille wart, kam ein neuer Bericht rein. Es wurde eine abtrünnige Monstrosität gesichtet, die im östlichen Teil von Tirisfal umherwandert, in der Nähe des Giftwebertals.\n\nDa ist irgendetwas faul an der Sache. Monstrositäten schlüpfen nicht einfach unbemerkt durch das Bollwerk.\n\nBehaltet das Ganze für Euch und sprecht nur bei Bedarf darüber. So oder so, eine solche Kreatur wird sich nicht ganz so einfach fällen lassen. Ihr solltet also Verbündete mitbringen, wenn Ihr nicht als dessen nächstes Mahl enden wollt.\n\nKümmert Euch darum, dann sollt Ihr angemessen entlohnt werden. Bringt mir das Herz der Monstrosität als Beweis für Eure Tat.", t = "Patrouille zur Rückendeckung"},
    [99158] = {ot = "Bringt die Kiste mit Kerzen zu Vater Gavin in der Nebelfichtenzuflucht.", st = "Hier in den Bergen gibt es einen Priester, der einer Organisation namens Argentumdämmerung angehört. Es handelt sich bei ihnen um eine heilige Gruppe, die es sich zum Ziel gemacht hat, alles Unheilige und Unnatürliche zu vernichten.\n\nVater Gavin gehört allerdings eher zu jenen unter ihnen, der anderen hilft und Heilung anbietet, statt zur Waffe zu greifen. Er hat ein altes Gebäude hergerichtet, das nun als Rastort für Reisende dient und Nebelfichtenzuflucht genannt wird. Ich habe eine Lieferung heiliger Kerzen für ihn. Könntet Ihr sie ihm bringen, wenn Ihr in die Richtung geht?", t = "Dämmerung in den Bergen"},
    [99159] = {ot = "Sammelt $1oa Stücke Feuerholz.", st = "Mein Ofen steht jederzeit bereit, um allen frierenden Seele etwas Wärme zu spenden, doch ich würde Euch gerne um Hilfe bitten, wenn es Euch nichts ausmacht.\n\nIch brauche mehr Feuerholz. Normalerweise würde ich mich selbst darum kümmern, doch ich bin gerade anderweitig beschäftigt.", t = "Auf der Suche nach Wärme"},
    [99160] = {ot = "Zerstört $1oa kleine Eiselementare.", st = "Euch sind vermutlich bereits die Elementare in der Umgebung aufgefallen. Vor ein paar Tagen hat sich eine Lawine aus Fels und Eis gelöst und ist nach unten gekracht, weshalb die Elemente nun ganz aufgebracht sind.\n\nDiese gefrorenen Berge sind für gewöhnliche Zwerge so schon heimtückisch genug, auch ohne fleischgewordene Elemente. Ich bin kein Kämpfer mehr... und mit jedem Geist, den Ihr zur Ruhe bettet, würden die Wege deutlich sicherer werden.", t = "Raufreifraserei"},
    [99161] = {ot = "Tötet Avala und bergt seinen Kern.", st = "Mir ist aufgefallen, dass der erste Elementar, der nach dem Bergrutsch erschien, größer als die anderen war. Und allem Anschein nach ist er auch der Ursprung gelegentlicher Wetterwechsel und anderer kleinerer Lawinen.\n\nIch habe ihn 'Avala' getauft. Wenn Ihr ihn ebenfalls zur Ruhe betten könntet und mir seinen Kern als Beweis bringt, werde ich Euch entlohnen.", t = "Raufreifraserei"},
    [99162] = {ot = "Sammelt die Gewehre von gefallenen Gebirgsjägern.", st = "Selbst die Gebirgsjäger von Ironforge müssen auf sich acht geben, wenn sie durch die Gipfel von Dun Morogh reisen. Schneefall und Eis bereiten unerfahrenen Mitgliedern oft ein jähes Ende.\n\nNach einem Bergrutsch versuche ich normalerweise, nach Zeichen von Überlebenden oder etwaigen Opfern zu suchen... während ich zum Licht bete, dass es nichts zu finden gibt. Doch jetzt, da die Elemente so aufgebracht sind, habe ich mich nicht allzu weit raus gewagt. Wenn Ihr Ausschau nach vermissten Gebirgsjägern halten könntet und mir ihre Gewehre bringt, werde ich sie nach Ironforge senden.", t = "Heimtückische Kälte"},
    [99260] = {ot = "Sprecht mit Elaadrin Evengale in Valanaar.", st = "Ich hatte den Auftrag, bei den Menhiren der Warte wichtige Daten über den Fluss der elementaren Energie zu sammeln. Diese Daten sind entscheidend für unsere Pläne, sicher zwischen dem Himmelswall und Azeroth zu reisen. Ohne diese Daten für unsere Berechnungen werden unsere Versuche scheitern, unsere Himmelsseglerschiffe durch die Elementarebene zu steuern.\n\nDie Daten sind inzwischen wohl verloren und ich bin nicht in der Verfassung, sie erneut zu sammeln. Ich habe dem obersten Magister von Eurer Rolle bei meiner Rettung berichtet, und er möchte erneut mit Euch sprechen.", t = "Fillions Mission"},
  },
})
end)
